var CW={"INTJ": {"sweet": ["Knows the answer before you ask", "Plans six months ahead", "The one to call in a crisis", "Spots wasted effort instantly", "Unshakable inner compass"], "mild": ["Brain meeting always in session", "Optimizes every walking route", "Freezes at surprise invites"], "spicy": ["Wonders what small talk is for", "Mentally leaves bad meetings", "Wins arguments with cold logic", "Itches to fix your plans"], "love": ["Slow and careful to fall", "Plans the future without asking", "Affection in secret code", "Fiercely loyal once decided", "Backs your dreams for real", "Keeps every promise", "Quietly preps anniversaries", "Texts only the key points", "Scouts the date route first", "Confesses after running the odds", "Goes silent around a crush", "Shuts down fights with logic", "Treats exes as old data", "Will never admit jealousy"]}, "INTP": {"sweet": ["Endlessly curious mind", "Catches flaws nobody sees", "Ignores titles, sees people", "Explains things clearly and deeply", "Surprises everyone with wild ideas"], "mild": ["Googling random stuff at 3am", "Replies late, lost in thought", "Messy room, perfect mental map"], "spicy": ["Ears close on boring topics", "Deadline mode starts at midnight", "Won't budge if the logic holds", "Can't let a sloppy explanation go"], "love": ["Struggles to put feelings in words", "Remembers everything you said", "Late-night calls over fancy dates", "Guards alone time fiercely", "Accepts your quirks completely", "Seriously solves your problems", "Loves freely, never clingy", "Leaves you on read for 3 days", "Analyzes why they like you", "Dates at bookstores or museums", "Keeps missing the moment to confess", "Accidentally forgets anniversaries", "Explains who's right mid-fight", "Sweet talk in a robot voice"]}, "ENTJ": {"sweet": ["Decisive and reassuring", "Leads the team to victory", "Maps the road to any goal", "Always follows through", "Leads by example"], "mild": ["Schedules weekends by the minute", "Makes trip itineraries unasked", "Ends up running every party"], "spicy": ["Just get to the point", "Truly cannot wait", "Fastest critic in the room", "Schedules rest like a task"], "love": ["All in for the one they love", "Perfectionist date planner", "Terrible at being babied", "Brings up the future early", "Fiercely protective of their partner", "Genuinely proud of your growth", "Fixes your problems on the spot", "Confesses first, with confidence", "Books anniversary dinners early", "Texts are strictly business", "Runs the show even on dates", "Rushes fights to a conclusion", "Sets KPIs for the relationship", "Breakups? Clean and swift"]}, "ENTP": {"sweet": ["Ideas multiply in conversation", "Makes any room more fun", "Breaks the ice in one line", "First to try new things", "Loves a good debate with anyone"], "mild": ["Derails every conversation", "New hobby every three months", "Always testing a new app"], "spicy": ["Argues just for sport", "Great starter, weak finisher", "Hunts for loopholes", "Promises on a whim, regrets later"], "love": ["Enjoys the chase a little too much", "Bored by boring partners", "Teases the one they like", "Never a dull moment together", "Every date feels brand new", "Makes your stories even better", "Genius at cheering you up", "Roasting you is their love language", "Reply speed depends on mood", "Even confessions sound like jokes", "Changes date plans on a whim", "Treats fights as fun debates", "Still friends with every ex", "Cools off the moment you chase"]}, "INFJ": {"sweet": ["Reads you without a word", "Quietly holds your true feelings", "A silent source of support", "Rare friend for deep talks", "Always chooses kind words"], "mild": ["Replays the day before bed", "Drained by crowds", "Surprisingly detailed journals"], "spicy": ["The sudden door slam", "Smiles, sees right through you", "Impossibly high standards for self", "Quietly drifts from toxic people"], "love": ["Forever searching for the one", "Overreads their partner's mind", "Slow to open up", "Loves deeply and for long", "Notices your tiniest changes", "Your emotional anchor", "Every word feels warm", "Rewrites texts again and again", "The listener on dates", "Senses a breakup first", "Remembers every special date", "Sees through lies instantly", "Sky-high standards for the one", "Vanishes when pushed too far"]}, "INFP": {"sweet": ["Feels others' pain deeply", "True to themselves", "Kindness at just the right warmth", "Eyes light up about passions", "Notices little joys"], "mild": ["Inner story always playing", "Plays one song a hundred times", "Best weekend: never leaving home"], "spicy": ["Motivation switch gone missing", "An hour drafting one text", "Whole day lost to daydreams", "Remembers every hurt for years"], "love": ["Daydreams run ahead of the romance", "One word makes or breaks the day", "Devoted to the one they love", "Would confess in a love letter", "Embraces all of you", "Wishes your happiness above all", "Cherishes tiny anniversaries", "Overthinks every reply for hours", "Freezes up around a crush", "Every love song is about you", "Gets wistful at goodbyes", "Romanticizes their exes", "Cries alone after a fight", "Reality never matches the dream"]}, "ENFJ": {"sweet": ["Sees the best in everyone", "Brings everyone together", "First to check on someone sad", "Leaves you feeling energized", "Truly happy for others' growth"], "mild": ["Official birthday surprise planner", "Always reading the group's mood", "Advice calls that last for hours"], "spicy": ["Can't stop helping", "Calendar full from never saying no", "Exhausted by own expectations", "Puts everyone else first, always"], "love": ["Gives too much for a partner", "Never forgets an anniversary", "Your dream's biggest fan", "Holds back to avoid being disliked", "Praises you more than anyone", "Always in tune with your feelings", "Gets close with your family", "Goes all out on surprises", "Always replies so politely", "First to apologize after fights", "Your date wishes come first", "Tries to coach their partner", "Still gives their ex advice", "Expects love back in equal measure"]}, "ENFP": {"sweet": ["Lights up any room", "Makes friends in seconds", "Believes in your potential", "Spreads excitement everywhere", "Goes all in on passions"], "mild": ["Phone notes full of ideas", "Plans a trip on a whim", "Conversation jumps everywhere"], "spicy": ["Quick to heat, quick to cool", "Overbooked into burnout", "Leaves cleanup to future self", "Wild emotional rollercoaster"], "love": ["Falls in love in a heartbeat", "Crushes are painfully obvious", "Panics when texts stop", "Makes every day fun", "Every day's a festival together", "Says how they feel, full volume", "Dreams your dreams with you", "Triple-texts, then some", "Confesses on pure impulse", "Date plans decided same day", "Tells friends all about you", "Jealousy is written all over them", "Bounces to the next love fast", "Bolts when things get clingy"]}, "ISTJ": {"sweet": ["Always keeps promises", "Steady, tireless effort", "Flawless with every task", "Trusted more than anyone", "Spots tiny mistakes instantly"], "mild": ["Up at the same time daily", "Reads the whole manual", "Same place, same order"], "spicy": ["Plan changes ruin the mood", "No precedent, no action", "Shuts people down with facts", "World-class inflexibility"], "love": ["Anniversaries marked on the calendar", "Shows love through actions", "Scouts date spots in advance", "Too shy for sweet talk", "Always on time, without fail", "Remembers your birthday wishes", "Zero chance of cheating", "Sets the date budget ahead", "Short, to-the-point texts", "Confesses by the book", "Sticks to the same restaurant", "Secretly hates surprises", "Wins fights with cold facts", "Logistics over romance"]}, "ISFJ": {"sweet": ["Master of quiet thoughtfulness", "Remembers everyone's favorites", "Calming to be around", "Quietly supports everyone", "Kindly notices small changes"], "mild": ["Always carries band-aids", "Can't say no to a favor", "Keeps every old letter"], "spicy": ["Real feelings kept in storage", "Bottles it up, then explodes", "Up all night overthinking", "Too polite for own good"], "love": ["Tends to give too much", "Notices you're sick first", "Jealous but never shows it", "Loyal once they fall", "Remembers all your favorites", "Drops off snacks on rough days", "Honors even tiny promises", "Overthinks replies after reading", "Works around your schedule", "Real feelings go to friends only", "Saves every anniversary photo", "Cries suddenly at the limit", "Drags up the past in fights", "Takes six months to move on"]}, "ESTJ": {"sweet": ["The reliable organizer", "The reliable planning machine", "Unmatched sense of duty", "Genius at planning", "Always steps up in a crisis"], "mild": ["Always ends up planning the party", "Lives for the to-do list", "Can't stand people running late"], "spicy": ["Bulldozes with being right", "Can't hide the urge to boss", "Annoyed by inefficiency", "Catchphrase: that's not normal"], "love": ["Dates with the future in mind", "Flawless date plans", "Secretly bad at being babied", "Takes the lead in love too", "Protects what they commit to", "First to show up in a crisis", "Meets the parents early", "Strict about meeting times", "Texts lead with the conclusion", "Confesses in plain words", "Runs your plans on a spreadsheet", "Fights turn into lectures", "Critiques your planning", "Efficiency over romance"]}, "ESFJ": {"sweet": ["Genius at warming up a room", "Remembers everyone's birthday", "Can't ignore someone in need", "Master connector of people", "Lifts everyone with a smile"], "mild": ["Center of every group chat", "Goes all out on host gifts", "Sends everyone the photos"], "spicy": ["Impressive gossip network", "Sulks without compliments", "Called a people-pleaser", "Caretaking gone overboard"], "love": ["All out for anniversaries", "Spoils the one they love", "Anxious over slow replies", "Cares what friends think", "Close with your whole family", "Good-morning texts every day", "Calls right away on bad days", "Celebrates monthly anniversaries", "Shows you off to friends", "Wants matching everything", "Plans birthdays a month ahead", "Left on read? Total meltdown", "Expects love in return", "Knows what their ex is up to"]}, "ISTP": {"sweet": ["Cool under any trouble", "Handy, can fix anything", "There when it matters", "Gets it done the shortest way", "Totally self-sufficient"], "mild": ["Builds without the manual", "Tunes out boring talk", "Tool collection keeps growing"], "spicy": ["Replies with just \"yeah\"", "Texts only when necessary", "Won't move unless in the mood", "Vanishes without warning"], "love": ["Runs from clingy partners", "Shows love in quiet actions", "Comfortable silence together", "Texts rarely, even in love", "Fixes broken stuff instantly", "Your go-to in a crisis", "Silently carries your bags", "Texts back with just a sticker", "Dates with zero plan", "Needs alone time, even in love", "Tends to forget anniversaries", "Ghosts heavy conversations", "Even breakups are low-key", "Says yes with just \"sure\""]}, "ISFP": {"sweet": ["Effortlessly great taste", "Kind to everyone", "Quietly there for you", "Lives by their own colors", "Sensitive to beauty"], "mild": ["Splurges on cute little things", "Lazy days at home are best", "Plans by mood"], "spicy": ["Pretends deadlines don't exist", "Quietly escapes the hard stuff", "Disappears instead of speaking up", "Moody as a cat"], "love": ["Goes quiet around a crush", "Would confess in a letter", "Waits to be asked out", "Happy just being together", "Takes on your tastes", "Speaks love through little gifts", "Your presence is enough", "Secretly fears you hate them", "Rewrites every text twice", "Loops your favorite songs", "Dates at cozy cafés", "Quietly vanishes after fights", "Hurt but never says so", "Can cool off on a whim"]}, "ESTP": {"sweet": ["Unbeatable go-getter", "Thrives under pressure", "Never boring to be around", "Acts the moment they decide", "Makes friends anywhere"], "mild": ["Leaves on a whim", "First in line at new spots", "Exaggerates the punchline"], "spicy": ["Planning skills on vacation", "Next challenge over reflection", "Gets bored at light speed", "Blurts first, regrets later"], "love": ["Makes the first move fast", "Wants thrilling dates", "Loves playing games", "Loves the chase", "Your boredom-proof date", "Rushes in when you're in trouble", "Wears their heart openly", "Gets close on the first date", "Vibes over plans", "Rather meet up than text", "Blurts out confessions", "Loses interest once they win", "Bounces back the day after fights", "Hangs out with exes casually"]}, "ESFP": {"sweet": ["Lights up the room by being there", "Master entertainer", "Up for anything, always", "Instant friends with anyone", "Expert at living in the moment"], "mild": ["Camera roll full of selfies", "Calendar always packed", "First to grab the karaoke mic"], "spicy": ["Memories over savings", "Homework panic the night before", "Bored? Straight to the phone", "Seems to listen, doesn't"], "love": ["All in once they fall", "An open book about romance", "Loves surprises", "Gets lonely, texts a lot", "Makes you laugh every time", "Says \"I like you\" daily", "Throws epic anniversaries", "Camera roll full of dates", "Brings you into the friend group", "Makes up right after fights", "Gets louder around a crush", "Lonely? Call spam incoming", "Falls hard and fast", "No budget cap on anniversaries"]}};
var KT={"ENFJ>INTJ": {"title": "You quietly map out a detailed future with people at its heart.", "body": "Imagining what could be and planning a clear path toward it — that's your core, in both temperament and character. On top of that, you have the energy you get from being with people and the depth you find alone, the kindness to sense how others feel and the calm to decide by logic. You can build a plan for everyone alone in a quiet room, then present it with more passion than anyone.", "say": "\"I've already mapped out the whole flow. …Just tell me if everyone can keep up without strain.\"", "do": "You work late into the night on the team's long-term plan, then share it the next morning with a personal note for each member.", "worry": "The more efficient the idea, the more you worry it leaves someone's feelings behind, and you can't commit. Some days you want to see everyone, some days no one, and the swing throws even you off.", "karai": "Your five-year plan is flawless. Your plans for this weekend? Still blank."}, "ENFJ>INTP": {"title": "You have the warmth to lift people up and a mind that thinks things all the way through.", "body": "Trusting your hunches and seeing possibilities — that's the same in your temperament and your character. Beyond that, you have almost every pair: energy from people and from deep solo thinking, a heart that values feelings and a mind that follows logic, the skill to plan ahead and the ease to go with the flow. When someone comes to you for advice, you cheer them up — and before you know it, you've taken the whole problem apart to see how it works.", "say": "\"That sounds really hard. …By the way, mind if I sketch out how it got this way?\"", "do": "On the way home after hearing a friend's troubles, you come up with three possible fixes and quietly message them the next day.", "worry": "Wanting to help others and wanting to chase your own interests pull equally hard, so you're torn over how to spend your time. You can't move until your thoughts settle, yet you keep picturing the faces of the people waiting on you.", "karai": "Encouraging words for others come out in a second. Your own replies? Left to sit for three days."}, "ENFJ>ENTJ": {"title": "You lead people's passion with clear, steady decisions.", "body": "Getting energy from people, picturing what's ahead, and planning your way forward — those are the same in your temperament and your character. On top of that, you can sense each person's feelings and also make clean, logical calls. You set the goal and pull everyone along, yet you stop to check on anyone falling behind. You're a leader people rely on, with warmth always mixed into your firmness.", "say": "\"The deadline is Friday — that part's not moving. …But if anyone's struggling, tell me now.\"", "do": "After wrapping up a meeting with a crisp decision, you send a private thank-you only to the person who seemed down.", "worry": "Even after making the right call, you lie awake wondering if someone got hurt. When you need to be tough, one look at their face and you soften your words.", "karai": "You boosted everyone's morale — but the math on your own exhaustion doesn't add up."}, "ENFJ>ENTP": {"title": "You have a caring heart and a sharp mind that cuts in with fresh ideas.", "body": "Coming alive around people and looking toward new possibilities — that's the same in your temperament and your character. Beyond that, you have both a heart that values feelings and a mind that tests the logic, and both a knack for careful planning and the freedom to act on a whim. While you get a discussion buzzing, you slip in an idea no one else thought of — and shape it so everyone can get on board.", "say": "\"Wouldn't it be fun to flip that idea around? …Oh, in a way where nobody loses out, of course.\"", "do": "A casual chat sparks a new project, and you've split up the roles before the conversation ends.", "worry": "You want to push your idea forward, but you also understand why others object, and that puts on the brakes. The moment you make a plan, a more interesting way pops up and you can't settle.", "karai": "The one who got the debate going is the first to wander off on a tangent."}, "ENFJ>INFJ": {"title": "You put your care for people to work in lively rooms and quiet ones alike.", "body": "Picturing possibilities, valuing people's feelings, and planning your way forward — that's your core, in both temperament and character. On top of that, you have both the energy you get from people and the ability to settle your heart alone. In front of a crowd you lift everyone up, and one-on-one you listen closely, putting into words feelings the other person hadn't even noticed yet.", "say": "\"Let's all talk it through! …Oh, but first, can I hear just what you think?\"", "do": "After hosting an event with a big smile, you ride the train home alone, replaying what people said to you that day.", "worry": "The days you help the most are the days you come home completely drained. You take in someone's worries so deeply that your own heart grows heavy too.", "karai": "You can read every tiny shift in other people's hearts, yet you miss your own battery level."}, "ENFJ>INFP": {"title": "You have a warmth that lights up others and a heart that tends its own feelings with care.", "body": "Trusting your intuition and putting feelings first — that's your core, in both temperament and character. Beyond that, you have both the energy you get from people and the depth you find alone, and both the skill to plan ahead and the ease to follow your mood and the flow. When you act for someone else, you're amazingly driven; when it's about you, you can wait patiently until your heart says, \"This is it.\"", "say": "\"I think that's wonderful! …I'm going to check in with my own feelings for a bit, too.\"", "do": "You cheer on a friend's dream and even help plan it, while your own dream stays tucked safely in your journal.", "worry": "Living up to others' hopes and staying true to your own heart both matter, and when you can't choose, you freeze. Even with a plan, on days your heart isn't in it you can't start — and then you blame yourself.", "karai": "You push everyone else forward with all your strength, but your own back? \"Still getting ready.\""}, "ENFJ>ENFJ": {"title": "You've grown your gift for bringing out the best in people, straight and true.", "body": "The temperament you were born with and the character you've grown through experience are the same type. Your belief in people's potential, your way of standing by their feelings, and your knack for getting everyone facing the same direction have grown steadily without wavering. Because your sense of self is so clear, you shine where you can help — and where you can't see how people respond, you tend to lose energy without knowing why.", "say": "\"It's okay, you can do this. Let's do it together!\"", "do": "At a gathering full of strangers, you end up introducing everyone to each other, and by the time you leave, you've started a group chat.", "worry": "When people count on you, you take on everything, and your time for yourself quietly disappears. If the mood around you clouds over even a little, you wonder if it's your fault.", "karai": "You wish so hard for everyone's happiness that you forget to save a slice for yourself."}, "ENFJ>ENFP": {"title": "You can turn your passion for people into solid plans — or let it spread out freely.", "body": "Getting energy from people, trusting your intuition, and deciding with your heart — that's your core, in both temperament and character. On top of that, you have both the skill to plan your way forward and the flexibility to adjust as things change. You plan something fun, invite everyone, and laugh your way through the surprises on the day, so the world of the people around you naturally grows bigger.", "say": "\"I've pulled together everyone's schedules for next month! …Oh, but what if we suddenly feel like going to the beach that day?\"", "do": "You carefully build a trip itinerary — then deliberately write in, \"Open time: decide on the spot.\"", "worry": "Wanting people to have fun, you pack the schedule full, and suddenly there's no free time left for you. The gap between days you want everything in order and days you don't want to decide anything leaves even you confused.", "karai": "On the \"let's just wing it\" trip, guess who did the most research? You."}, "ENFJ>ISTJ": {"title": "You turn your warmth for people into steady support, one reliable step at a time.", "body": "Planning ahead and seeing things through — that's your core, in both temperament and character. Beyond that, you have both the energy you get from people and the focus you find alone, both an eye for future possibilities and a solid habit of building on facts, and both the kindness to read feelings and the fairness to decide by logic. People often see you as \"the precise one,\" but that precision is always about making sure no one gets stuck.", "say": "\"Please follow these steps as written. …Oh, and I'll check in with the new person myself.\"", "do": "You finish a flawless handover document, then add handwritten notes only where the reader might trip up.", "worry": "Wanting people to follow the rules clashes with not wanting to blame them, so you rewrite your reminder over and over. You want to see people, but if you're not fully prepared, you're tired before you even meet.", "karai": "You're trying to add \"being considerate\" to the manual, too."}, "ENFJ>ISFJ": {"title": "You share your caring nature with both bright cheer and careful attention.", "body": "Valuing people's feelings and planning your way forward — that's your core, in both temperament and character. On top of that, you have both the energy you get from people and the calm you find alone, and both a feel for future possibilities and a careful habit of checking the facts in front of you. In front of everyone you're the bright cheerleader, and behind the scenes you remember each person's tastes and even how they're feeling — your thoughtfulness reaches everywhere.", "say": "\"Let's all do our best! …Also, Sam was coughing a bit yesterday, so I brought some throat drops.\"", "do": "You take on planning a farewell party and pick the restaurant by recalling the guest of honor's favorite foods from years of conversations.", "worry": "Helping others never feels like a burden, but somehow your own plans always end up last. Some days you want to talk about big dreams, yet you stop yourself with \"I need to be realistic.\"", "karai": "Everyone's special days are in your planner. Your own birthday? You remember it when someone tells you."}, "ENFJ>ESTJ": {"title": "You move things steadily forward with energy that lifts people up.", "body": "Getting energy from people and planning your way forward — that's the same in your temperament and your character. Beyond that, you have both the imagination to picture what's ahead and the drive to act on facts, and both the kindness to stand by people's feelings and the fairness to decide by logic. You set clear goals and steps to get everyone moving, and you truly notice who worked hard and say so — so even though you're strict, people are glad to follow you.", "say": "\"We're hitting this number by the end of the month, no matter what. …And last week's slides were really clear — thank you.\"", "do": "You update the progress chart every morning, adding a word of praise whenever you spot a team member's small win.", "worry": "Every time someone breaks the rules, you wear yourself down deciding whether to call it out or put their feelings first. The more you push forward with reality, the more it feels like you're drifting from the dreams you once had.", "karai": "You manage the team's schedule to the minute, but your own break is \"if there's time.\""}, "ENFJ>ESFJ": {"title": "You can turn your care for people toward the future and toward everyday life alike.", "body": "Getting energy from people, valuing feelings, and planning your way forward — that's your core, in both temperament and character. On top of that, you have both a feel for possibilities no one can see yet and a steady respect for past experience and facts. You dream up everyone's future together while also minding today's snacks and seating, so at any gathering you're the center of that sense of ease.", "say": "\"Let's do something even bigger next year! …For now — did everyone actually eat lunch?\"", "do": "You volunteer for the local festival, pitching new ideas while carefully passing on last year's tricks that worked.", "worry": "You want everyone to be happy so much that one unhappy face keeps your heart from resting. You feel pulled between wanting to try new things and wanting to protect the ways that work.", "karai": "By the time you've handed out plates to everyone, your own food has gone cold."}, "ENFJ>ISTP": {"title": "You pair cool, capable skill with a real warmth for people.", "body": "You're a calm, hands-on type who doesn't say much and quickly solves the problem in front of you. You also carry a deep warmth that wants people to grow and wants to cheer them on. So even as a person of few words, you can't leave someone struggling alone. You have both the kindness to help quietly and the fire for a heartfelt word when it really counts.", "say": "\"It's no big deal. …But I think you can do even more.\"", "do": "You quietly fix a junior's mistake without a word, and later just say, \"You were on the right track.\"", "worry": "You really want to encourage people, but putting it into words feels awkward, so you let actions do the talking. Sometimes you do so much for others that your own time runs out.", "karai": "You act all cool, but you're secretly keeping a diary of your junior's growth."}, "ENFJ>ISFP": {"title": "You can show your kindness through words and through your own sense of beauty.", "body": "Deciding with care for people's feelings — that's your core, in both temperament and character. Beyond that, you have both the energy you get from people and the fullness you find in time alone, both a feel for future possibilities and a sense that savors the beauty right in front of you, and both the skill to plan and the softness to go with your mood. Encouraging words for everyone, a small handmade gift slipped in quietly — you offer both naturally.", "say": "\"Everyone's feelings came through, I promise. …Oh, doesn't this flower's color look like today's sky?\"", "do": "You organize a group card for a friend's birthday and quietly tuck in a little something you picked out on your own.", "worry": "The more you plan to meet others' expectations, the more your heart lags behind. You love lively gatherings, but afterward you need quiet time alone to recharge.", "karai": "You're the first to notice how others feel, and the last to notice you're tired."}, "ENFJ>ESTP": {"title": "You bring the energy that fires people up and the drive to jump into action on the spot.", "body": "Getting energy from people — that's your core, in both temperament and character. On top of that, you have both the power to picture possibilities and the grip to handle what's real right now, both the kindness to read feelings and the clarity to make clean, logical calls, and both the skill to plan ahead and the push to move on momentum. After you've talked about everyone's dreams and got them excited, you're the first to dive in and clear the way.", "say": "\"This is going to help everyone, I'm sure of it! …Okay, I'm calling them before I overthink it.\"", "do": "The moment after hearing a friend's problem, you're already contacting someone you know who could fix it.", "worry": "After deciding on impulse, you look back wondering whether you left anyone behind. Wanting to plan carefully and wanting to move right now fight it out, and you end up thinking on the run.", "karai": "Nobody thinks harder about people's feelings than you — you just move so fast nobody can keep up."}, "ENFJ>ESFP": {"title": "You warm people with your care and spread it through the fun of the moment.", "body": "Getting energy from people and deciding with care for feelings — that's your core, in both temperament and character. Beyond that, you have both the power to picture what's ahead and the knack for savoring this very moment, and both the skill to plan and the ability to roll with things and enjoy them. You truly cheer on everyone's future while making the present ridiculously fun, so the people around you can't help smiling.", "say": "\"Let's make all your dreams come true! …But for today, let's just have a blast!\"", "do": "You plan a get-together to cheer on a friend's big challenge, and on the day you forget all about running it and have the most fun of anyone.", "worry": "You want to protect the fun, but thinking about the future suddenly makes you anxious. You get so caught up in making others happy that what you really feel gets pushed aside.", "karai": "You're passionate about everyone's life plans, but you look the other way when it comes to your own wallet."}, "ENFP>INTJ": {"title": "You take your overflowing ideas and quietly turn them into detailed plans on your own.", "body": "Trusting flashes of insight and possibilities — that's your core, in both temperament and character. Beyond that, you have both the energy you get from people and the depth you find alone, both a heart that values feelings and a mind that decides by logic, and both the freedom to move on a whim and the steadiness to plan ahead. You don't let an exciting idea stay just a dream — you quietly draw it all the way out into a blueprint.", "say": "\"This is going to be so fun! …So I made it into a three-step plan.\"", "do": "A hobby you picked up on a whim turns into something you've researched inside and out — complete with a how-to guide you wrote yourself.", "worry": "Ideas come in a second, but trying to make the plan perfect means it takes a while to get started. The gap between days you want to hang out with everyone and days you don't want anyone around can confuse the people close to you.", "karai": "Five seconds after a great idea hits, you've already counted three flaws in it."}, "ENFP>INTP": {"title": "You deepen your sparks of insight through curiosity about people and a love of logic.", "body": "Trusting your hunches and adapting flexibly as things change — that's your core, in both temperament and character. On top of that, you have both the energy you get from people and the depth you find in solo thinking, and both a heart that values feelings and a mind that follows logic. Whatever catches your interest, you can blow it up with friends in a burst of excitement or dig alone into how it works deep down — you're curiosity in human form.", "say": "\"Hey, isn't this interesting? …Wait, hang on — let me think about why it's interesting.\"", "do": "A question that pops up while talking with a friend has you researching alone until the middle of the night.", "worry": "Your interests keep jumping, so it's hard to feel you've ever finished anything. After saying what's logically right, you worry you may have left the other person's feelings behind.", "karai": "You've opened so many search tabs that you've forgotten what you wanted to know in the first place."}, "ENFP>ENTJ": {"title": "You pull exciting dreams into reality without hesitation.", "body": "Getting energy from people and trusting your intuition — that's the same in your temperament and your character. Beyond that, you have both a heart that values feelings and a mind that decides by logic, and both the ease to adapt on the spot and the drive to plan your way forward. You talk about dreams that get everyone excited, then turn them straight into goals and steps and lead the way — a leader who brings both fun and results.", "say": "\"This would be so much fun if we all did it! …So, deadline's the end of next month. Let's assign roles.\"", "do": "An idea that took off over drinks with friends is a proposal and schedule in everyone's inbox by the next morning.", "worry": "The harder you push for results, the fewer happy faces you seem to see, and that gets you down. You're pulled between sticking to the plan and taking a more interesting detour.", "karai": "You keep saying \"let's just have fun,\" yet you're the one chasing the numbers hardest."}, "ENFP>ENTP": {"title": "You polish your ideas with both heart and logic.", "body": "How fast you spot something interesting — that's your core, in both temperament and character. On top of that, you have both the ability to sense people's feelings and the ability to reason things through. You don't just come up with ideas — you can ask yourself both \"Who will this make happy?\" and \"Will this actually work?\"", "say": "\"That's fun! …But wait, there might be a hole in it.\"", "do": "Halfway through giving a friend advice, you're suddenly offering three ways to improve things.", "worry": "After winning an argument, you picture the other person's face and feel down. Every time, you're torn over whether to lead with being right or being kind.", "karai": "After you win the argument, the one who takes the most damage is usually you."}, "ENFP>INFJ": {"title": "You grow your caring insights into a quiet, steady belief.", "body": "Picturing possibilities and deciding with care for people's feelings — that's your core, in both temperament and character. Beyond that, you have both the energy you get from people and the ability to settle your heart alone, and both the freedom to follow your whims and the steadiness to plan ahead. You open up to anyone in no time, and deep down you've been nurturing a wish to help others as a goal that doesn't waver.", "say": "\"Wow, that's lovely! …Hey, what does it mean to you?\"", "do": "In the middle of a fun chat, you remember something the other person let slip, and a few days later you quietly check on them.", "worry": "You want to act on your ideas right away, but you stop to ask, \"Is this really right?\" You love being with people, but when you get too involved, you need time alone afterward.", "karai": "You can make friends with anyone, but your heart's door has a triple lock."}, "ENFP>INFP": {"title": "You can nurture what moves your heart, out loud or in quiet.", "body": "Trusting your intuition, valuing feelings, and moving freely where your heart leads — that's your core, in both temperament and character. On top of that, you have both the energy you get from people and the depth you find in time alone. You can dream big with friends or pour your feelings into a journal or something you make alone, so you're really good at getting what you feel across to others.", "say": "\"Hey, hey, listen! …Oh wait, I can't put it into words yet — can I write it down first?\"", "do": "Heading home after a big group hangout, you put in your earbuds and jot down the day's best moments.", "worry": "Your wish to see people and your wish to be alone rise and fall in big waves, so sometimes a plan starts to feel heavy right after you make it. You love so many things, yet you move on to the next before any of them take shape.", "karai": "When someone invites you, you say \"I'm in!\" right away — then regret it alone the night before."}, "ENFP>ENFJ": {"title": "You spread your excitement to others and turn it into everyone's strength.", "body": "Getting energy from people, trusting your intuition, and deciding with your heart — that's your core, in both temperament and character. On top of that, you have both the freedom to move as things unfold and the drive to plan and follow through. You share a fun idea, get people on board, and then take responsibility for pulling it all together, so before you know it you're at the center of the circle.", "say": "\"If we all do this, it'll be so much fun! …Okay, I'll be the one to organize it.\"", "do": "A surprise you thought of on a whim happens that very day, after you've lined up everyone's schedules.", "worry": "The more you're given the lead, the less time you have to act on a whim. You care so much about doing your part that even on off days you force a smile.", "karai": "You say you want to live free, but you're always the one running the group calendar."}, "ENFP>ENFP": {"title": "You've let your gift for finding joy grow freely.", "body": "The temperament you were born with and the character you've grown through experience are the same type. Your excitement for new things, your belief in people's potential, and your way of widening your world wherever your heart leads have grown steadily without wavering. Because your sense of self is so clear, you shine brighter than anyone where you're free to move — and in places full of rules and routine, your energy tends to fade without you knowing why.", "say": "\"Wait, what's that? Sounds fun — let's go!\"", "do": "You get off at a station you've never been to, make friends with someone at a shop you happen to walk into, and come home with their number.", "worry": "You love starting things, but you tend to blame yourself for getting bored before you finish. You may seem lively, but sometimes a passing comment hurts you deeply.", "karai": "A hundred things on your bucket list. Three checked off."}, "ENFP>ISTJ": {"title": "You bring a free-spirited spark to a steady, reliable everyday life.", "body": "You do what's decided with precision and keep your promises — a sincere, dependable person. You also have a curiosity that gets excited about new possibilities and loves having fun with others. So even in your usual work, a little playfulness or a fresh twist shows through. You're so proper, yet surprisingly fun to talk to.", "say": "\"Let's follow the steps. …Oh, by the way, I came up with something really fun lately.\"", "do": "You take the same route to work every day, but on days off you head out on a whim to towns you've never seen.", "worry": "You get everything done properly, but when every day feels the same, something starts to feel missing. You want to try out your ideas, but \"What if it fails?\" makes you overly careful.", "karai": "Taking meeting notes with a serious face — and three new project ideas in the margins."}, "ENFP>ISFJ": {"title": "You bring your bright ideas to people with careful, thoughtful attention.", "body": "Deciding with care for people's feelings — that's your core, in both temperament and character. On top of that, you have both the energy you get from people and the calm you find alone, both an eye for new possibilities and a careful habit of checking the facts in front of you, and both the freedom to move lightly and the loyalty to keep what you've decided. Even when a fun idea hits, you check \"Is everyone okay with this?\" before you move — that's how kind you are.", "say": "\"Hey, want to have a picnic sometime? …I already looked up a backup spot in case it rains.\"", "do": "You're tempted to pick a bold gift for a friend, but in the end you carefully choose something they'll really use.", "worry": "Part of you wants to jump into something new, but worrying about causing others trouble keeps you from taking the first step. When people ask for help you say yes, and your own fun gets pushed back.", "karai": "You say \"I want an adventure for once\" — while ordering your usual at your usual place."}, "ENFP>ESTJ": {"title": "You keep things running smoothly with a brightness that pulls people in.", "body": "Getting energy from people — that's your core, in both temperament and character. Beyond that, you have both the imagination to picture possibilities and the drive to act on facts, both a heart that values feelings and a mind that decides by logic, and both the freedom to move lightly and the steadiness to stick to the plan. You set the steps and lead everyone, while slipping in bits of playfulness to brighten the room — a fun kind of organizer.", "say": "\"We meet at nine — no one's late, please! …And for lunch, let's all go try somewhere new.\"", "do": "You lay out exactly how the work will go, then sneak a little quiz into every weekly team meeting.", "worry": "The more responsibility you're given, the more you feel you're forgetting the fun of acting on a whim. After pointing out a rule, you can't stop worrying whether the other person is feeling down.", "karai": "Five minutes after saying \"let's play it by ear,\" you're handing out a step-by-step guide."}, "ENFP>ESFJ": {"title": "With a heart full of excitement, you warmly support everyone's everyday life.", "body": "Getting energy from people and deciding with care for feelings — that's your core, in both temperament and character. On top of that, you have both a feel that's moved by new possibilities and a steady respect for familiar ways and experience, and both the freedom to move lightly and the loyalty to keep what you've decided. You come up with new plans everyone can enjoy, and on the day you look after every detail so no one is left stuck — the host everyone can count on.", "say": "\"Let's do something a little different for this year's holiday party! …Oh, and of course I'll handle the seating and food.\"", "do": "At a class get-together you suggest a new game, and afterward you send photos and updates to the friends who couldn't make it.", "worry": "You want everyone to be happy so much that if a new idea gets a lukewarm response, you pull it right back. Wanting adventure and wanting to protect your usual comfort both matter, and you're torn.", "karai": "You planned a surprise, then got so nervous you checked with the guest of honor first."}, "ENFP>ISTP": {"title": "You pair a spark of inspiration with the cool focus to work things out with your hands.", "body": "Adapting flexibly to whatever's happening — that's your core, in both temperament and character. Beyond that, you have both the energy you get from people and the focus you find alone, both a feel for possibilities and an eye for the facts in front of you, and both a heart that values feelings and a mind that judges by logic. You try out ideas right away, and if they don't work, you calmly find the cause and fix it — like a nimble experimenter.", "say": "\"Wouldn't it be cool if we did it like this? …Eh, we'll find out if we try.\"", "do": "You find a fun gadget online and take it apart to see how it works before ever reading the manual.", "worry": "Your wish to have fun with people and your wish to work quietly alone come in big waves, and you worry people will think you're antisocial. Showing how you feel through actions is easier than saying it, so you're often misunderstood.", "karai": "You truly feel for people's problems — yet all that comes out of your mouth is solutions."}, "ENFP>ISFP": {"title": "You can share what moves you, both with others and with yourself.", "body": "Valuing feelings and moving freely where your heart leads — that's your core, in both temperament and character. On top of that, you have both the energy you get from people and the fullness you find in time alone, and both an imagination for what hasn't happened yet and a sense that savors the colors, sounds, and textures right in front of you. Laughing together in a lively crowd or quietly making something you love on your own — you truly enjoy both.", "say": "\"Hey, look at this view! …Actually, let's not say anything. I just want to look for a while.\"", "do": "On a fun trip with friends, you slip away for a moment on your own to take a photo of flowers by the road.", "worry": "Wanting to connect with people and wanting to keep your own pace are both strong, so every time you turn down an invite you feel a little low. You love so many things, but when someone asks about your future goals, you're stuck for an answer.", "karai": "Everyone's smiling in your group photos, but most of your camera roll is sky and cats."}, "ENFP>ESTP": {"title": "With ideas and drive, you're off the moment inspiration strikes.", "body": "Getting energy from people and adapting flexibly in the moment — that's your core, in both temperament and character. Beyond that, you have both the imagination to picture possibilities and a feel for grabbing what's real right now, and both a heart that values feelings and the clarity to make clean, logical calls. You dive into anything that looks fun before anyone else and can size up the pros and cons on the spot, so people see you as \"the one who always makes something happen.\"", "say": "\"Wait, we could go right now! …Though that place is pricey — let's try somewhere else.\"", "do": "The moment you hear a friend has no weekend plans, you've invited them and booked train tickets for a day trip.", "worry": "After deciding on impulse, you worry you may have left someone's feelings behind. While you chase the fun, your prep for what's ahead always ends up last-minute.", "karai": "On days you go out \"just for a bit,\" you usually end up catching the last train home."}, "ENFP>ESFP": {"title": "With an excited heart, you enjoy this very moment to the fullest.", "body": "Getting energy from people, valuing feelings, and adapting flexibly in the moment — that's your core, in both temperament and character. On top of that, you have both the imagination to picture what hasn't happened yet and a sense that soaks up the fun right in front of you. You make people laugh with big, dreamy talk while fully enjoying today's food and scenery, so the days of those around you get a little brighter.", "say": "\"Let's travel around the world someday! …For now, let's go get those crepes!\"", "do": "Heading home after a big talk about the future, you get pulled straight into a festival you happen to spot.", "worry": "There are so many fun things that before you know it, you're short on both money and time. Because you seem so lively, people don't notice when you're feeling down.", "karai": "Your dreams for the future are huge — but tomorrow's breakfast is still undecided."}, "INFJ>INTJ": {"title": "You read people's hearts and build the future with clear logic.", "body": "Thinking things through on your own and planning ahead is the core your temperament and character share. On top of that, you have both a feel for how people are feeling and a knack for putting things together logically. When you plan, you can ask \"Who does this help?\" and \"Will this really work?\" at the same time, so people quietly come to rely on you.", "say": "\"The logic holds up. …But I'd like to think for a moment about how they'll feel.\"", "do": "The night before a meeting, you fill a notebook with answers to every objection—and kind ways to say them.", "worry": "You can see the right answer, but you spend so long on how to say it that you speak up too late. And after you choose the efficient path, you keep thinking about the people you left behind.", "karai": "You've planned five years ahead, but you still haven't replied about tomorrow's dinner."}, "INFJ>INTP": {"title": "Deep kindness and a free, curious mind—you have both.", "body": "Going deep in your alone time and looking for meaning no one can see is something your temperament and character share. On top of that, you have the warmth to stay close to people's feelings, the curiosity to dig into anything with logic, and both the foresight to plan ahead and the lightness to rethink on the spot. When someone brings you a problem, you take in their feelings—and somehow end up taking the whole problem apart, too.", "say": "\"That sounds really hard. …So, why do you think it happened?\"", "do": "You start looking something up before bed, and three hours later you're reading articles in a totally unrelated field.", "worry": "You want to help people, but thinking gets so fun that you stop actually doing. Right after making a plan, you think of a better way and want to start over.", "karai": "You can explain the meaning of life, but your laundry is still sitting in the dryer."}, "INFJ>ENTJ": {"title": "You turn quiet insight into the power to move people.", "body": "Seeing ahead and turning decisions into results is the core your temperament and character share. Layered on top are the power to think deeply alone and to lead from the front, and the power to sense feelings and to decide with logic. While you pull a team toward a goal, you still notice who's pushing too hard and who's holding back what they want to say.", "say": "\"Okay, Friday is the deadline. …Oh, Sam, have you been tired lately?\"", "do": "You fit the team's goals onto one sheet—and write in what each member is good at.", "worry": "The more you take on the leader role, the less time you have to think alone. When you need to be firm, their face pops into your head, and later you blame yourself.", "karai": "You make sure everyone else gets their days off, but yours are always \"someday.\""}, "INFJ>ENTP": {"title": "You feel people's hearts while opening new paths.", "body": "Valuing sparks and possibilities is something your temperament and character share. On top of that, your range is wide: quiet thinking and thinking out loud with others, a heart that cares about feelings and a mind that tightens the logic, the power to plan and the lightness to go with the flow. You can get a debate buzzing and still check that no one walked away feeling beaten.", "say": "\"What if we flip it around? …Oh, sorry if that came out harsh.\"", "do": "You get a new idea from small talk, run with it on the spot, then go home and rework the plan alone.", "worry": "Ideas flow when you're with people, but you crash once you get home. Every time, the urge to act on a whim wrestles with the urge to make a solid plan.", "karai": "Unbeatable in conversation—then a very long solo review meeting on the way home."}, "INFJ>INFJ": {"title": "You've grown your gift for sensing the unseen, straight and true.", "body": "Your born temperament and the character you grew through experience are the same type. Your power to quietly sense what lies deep in people's hearts and the meaning behind things, and to move step by step toward an ideal, has grown without wavering. Because you know clearly what matters to you, you shine where that is understood—and where it isn't, you tend to wear out without knowing why.", "say": "\"Don't push yourself. Whenever you feel like talking, I'm here.\"", "do": "You notice a friend is down before they say a word, and quietly hand them their favorite snack.", "worry": "You pick up on others' feelings so much that you notice your own tiredness late. Your ideals are high, so the gap with reality can leave you feeling low on your own.", "karai": "You can read everyone's mind—except the part where you're running on empty."}, "INFJ>INFP": {"title": "You grow quiet ideals wherever your heart leads.", "body": "Recharging alone and valuing intuition and people's feelings is the core your temperament and character share. On top of that, you have both the power to plan ahead and move steadily and the flexibility to follow your mood and the moment. You carry a big goal in your heart, yet you also treasure the people and places you find on detours—and they become seeds for your next goal.", "say": "\"I want to do this by next year. …Well, if I change my mind along the way, that's fine too.\"", "do": "You buy a beautiful planner and start writing plans; by day three it's a diary and a sketchbook.", "worry": "When you can't stick to a plan, you feel like a failure. But a packed schedule makes it hard to breathe, so you keep searching for the right balance.", "karai": "Making the plan is the most fun part of the plan."}, "INFJ>ENFJ": {"title": "You stay close to people's hearts and lead everyone forward.", "body": "An eye for possibilities, and a way of moving forward with a plan while caring about feelings—your temperament and character share both. Layered on top are the power to think quietly alone and the power to brighten a room full of people. In front of everyone you enjoy bringing the group together, and back home you replay the day's conversations alone, thinking about what to do next time.", "say": "\"Thanks so much for coming today, everyone! …Later, I'd love to hear how it was for each of you.\"", "do": "You plan a group get-together, then send each person a thank-you message afterward.", "worry": "You love helping people, but suddenly you have no time alone at all. It's hard to balance being relied on with wanting to be left alone for a while.", "karai": "You recharge everyone else's heart, but always leave your own charger at home."}, "INFJ>ENFP": {"title": "Deep care and wide curiosity—you bring people together.", "body": "Trusting your intuition and caring about people's feelings is the core your temperament and character share. On top of that, you have the power to think deeply in quiet and a bright sparkle in a crowd, plus the foresight to plan and the lightness to follow a sudden idea. You can open up to someone new right away and still catch the feelings behind their words.", "say": "\"Wait, that's amazing! Let's do it! …Oh, but first, give me a little time to think.\"", "do": "You hit it off with someone on a trip and swap contacts, then soak in the afterglow alone on the train home.", "worry": "The more fun the day, the harder the tiredness hits at night. The things you want to do keep piling up; you want to give each one your all, yet they all feel half-done.", "karai": "You answer every invite with \"I'm in!\"—and you're the one hesitating most on the morning of."}, "INFJ>ISTJ": {"title": "You build deep insight up with solid steps.", "body": "Thinking calmly on your own and moving with a plan is something your temperament and character share. On top of that, you can both sense the meaning behind things and check the facts one by one, and you have both a heart that reads feelings and a calm mind that decides with logic. Thoughtful care shows through your precise work, so people often say, \"If you're on it, I can relax.\"", "say": "\"The steps are fine as they are. …I'll just add a note here for the new folks.\"", "do": "You write a precise manual and attach a handwritten note at the end: \"Ask me anytime if you get stuck.\"", "worry": "You often get caught between following the rules and making room for the person in front of you. The future is on your mind, but without solid grounds you can't move, so your thoughts go in circles.", "karai": "You add people's feelings to the checklist, so it gets longer every time."}, "INFJ>ISFJ": {"title": "You turn deep care into steady, everyday help.", "body": "Recharging alone and moving with a plan while caring about feelings is the core your temperament and character share. Layered on top are the imagination to picture what's ahead and what it means, and the steadiness to rely on past experience and the facts in front of you. You hold big ideals in your heart while never skipping the small daily acts of care—a kindness with both feet on the ground.", "say": "\"Things are about to get busy, so I'm getting ready now. …Here, I packed you lunch.\"", "do": "When a friend moves, you make a schedule for the day—and bring work gloves and drinks for everyone.", "worry": "Picturing the future makes you anxious, so you prepare far more than you need to. With all the planning for others, your own wants tend to get pushed back.", "karai": "You've already perfectly prepared for problems that haven't happened yet."}, "INFJ>ESTJ": {"title": "You keep things running, with a caring eye.", "body": "Making a plan and seeing your decisions through is something your temperament and character share. On top of that, you have the power to think quietly and to act briskly in front of others, the imagination to picture possibilities and a respect for facts, and a heart that reads feelings alongside a calm mind that decides with logic. While you use rules to keep things in order, you still check that those rules aren't making anyone suffer.", "say": "\"I need you to meet the deadline. …But if you're struggling, tell me early, okay?\"", "do": "You write a proposal to fix how things run at work, and add its purpose at the end: \"So everyone can go home on time.\"", "worry": "The more you lead the group, the less time you have to sort out your thoughts alone. After giving clear directions, you lie awake wondering if you said too much.", "karai": "Your reason for fixing the system is usually \"so nobody ends up in tears.\""}, "INFJ>ESFJ": {"title": "You sense people's feelings and make a place for everyone.", "body": "Caring about people's feelings and moving with an eye on what's ahead is the core your temperament and character share. Layered on top are the power to let your imagination roam alone and to jump in and warm up a crowd, and an eye for meaning together with an honest love of everyday life. At gatherings you make sure everyone's having a good time, and you notice even small changes in each person.", "say": "\"Tea and snacks are all set! …Hey, you've seemed down for a while—is something up?\"", "do": "You plan a birthday party down to the seating, then run through the flow again and again in your head so the guest of honor won't feel awkward.", "worry": "You love seeing people happy, so you do too much, and your battery dies the moment you're alone. Trying to protect the mood, you sometimes miss your chance to say what you think.", "karai": "Fill up on everyone's \"thank you,\" then collapse alone at home—that's your daily routine."}, "INFJ>ISTP": {"title": "With a kind eye, you fix the problem in front of you fast.", "body": "Recharging alone and quietly watching how things are is something your temperament and character share. On top of that, you have the imagination to sense meaning and the hands-on skill to check things yourself, a heart for people and a cool eye for how things work, and the foresight to plan along with the lightness to act on the spot. You may not say much, but when someone's in trouble, your hands get moving and you just fix it.", "say": "\"Let me see—probably right here. …Fixed. Now you can use it without worrying.\"", "do": "You quietly fix a friend's broken bike and, while you're at it, casually ask, \"So how've you been?\"", "worry": "You show care through actions more than words, so your kindness doesn't always come across. You're torn between thinking long-term and focusing only on what you can do right now.", "karai": "First to show up with a toolbox, but \"Are you okay?\" never quite makes it out."}, "INFJ>ISFP": {"title": "You pour deep care into the beauty of this moment.", "body": "Treasuring quiet time alone and putting people's feelings first is the core your temperament and character share. Layered on top are the power to look at what's ahead and what it means, a feel for the colors and textures right in front of you, and both foresight and a softness that follows your mood. You may be quiet with words, but you can show how you feel through a small gift or gesture.", "say": "\"These flowers made me think of you. …I just kind of wanted you to feel better.\"", "do": "You choose a seasonal postcard for a friend who's feeling down and send it with a short note.", "worry": "You know you should think about the future, but you want to honor how you feel now, so you can't decide. You feel others' pain easily, and one sad news story can weigh on you all day.", "karai": "You spend your whole day off picking out a gift to cheer someone else up."}, "INFJ>ESTP": {"title": "Bold moves and deep care, side by side.", "body": "You read the flow of the moment and move fast—you're a person of action. You also have a thoughtful side that quietly senses how people feel and thinks deeply about what things mean. So even when you seem to act on impulse, you're actually watching the people around you closely. You have both lightness and depth.", "say": "\"Let's just go! …They've seemed down lately, so I want to invite them.\"", "do": "You take a sudden trip on a whim, and on the way back you're the one listening most deeply to your friend's worries.", "worry": "Being on the move is fun, but once you're alone, something someone said won't leave your head. People tend to see you as easygoing, and it feels like they don't get how deeply you really think.", "karai": "You look like you just go with the vibe, but you've been thinking about the reason for that vibe for three days."}, "INFJ>ESFP": {"title": "You care about people and enjoy today to the fullest.", "body": "Deciding with people's feelings in mind is the core your temperament and character share. On top of that, you have the power to think deeply alone and to liven up a crowd, the imagination to see meaning and the ability to savor this moment, and the power to plan along with the lightness to ride the flow. Even at the center of a lively party, you notice who's been left out and invite them in.", "say": "\"Today is so much fun! …Hey, let's go get the one standing off to the side.\"", "do": "You were the most excited one at the party, but on the way home you wonder alone, \"Did she have a good time?\"", "worry": "After giving your all to a fun time, your heart can't keep up without some time alone. The wish to enjoy now and the wish to prepare for the future take turns showing up.", "karai": "The moment you get home, you power off right along with your phone."}, "INFP>INTJ": {"title": "You turn gentle ideals into reality with careful plans.", "body": "Going deep in your alone time and picturing possibilities no one sees yet is something your temperament and character share. On top of that, you have both a heart that stays true to what you care about and a mind that decides step by step, and both a softness that enjoys the flow and the power to plan ahead. You don't let the ideal in your heart stay a dream—you break it into steps and make it real.", "say": "\"With this plan, we can get there in three years. …But if it stops being fun, let's rethink it.\"", "do": "You turn your favorite story's world into timelines and maps, and your notes end up thicker than the story itself.", "worry": "The more efficiently you move, the more you stop and ask, \"Is my heart actually happy with this?\" Even for choices you want to make with feeling, you catch yourself hunting for the \"right\" reason.", "karai": "You've made a spreadsheet to score how much things spark joy."}, "INFP>INTP": {"title": "You deepen a rich imagination with both feeling and logic.", "body": "Loving alone time, valuing sparks of inspiration, and moving freely with your interests is the core your temperament and character share. On top of that, you have both a heart that cares about your own and others' feelings and a mind that thinks things through logically. Once you start talking about something you love, you can't stop—and you can explain its charm both the way you felt it and the way it works.", "say": "\"This song just makes me cry. …I think it's because the chord changes right here.\"", "do": "After a movie moves you, you stay up past midnight writing notes on why it moved you.", "worry": "You can't settle until you can explain with logic what you felt. And sometimes you think so hard that you miss the moment to simply enjoy it.", "karai": "While you analyze why you were moved, the feeling quietly leaves the room."}, "INFP>ENTJ": {"title": "You lead from the front to bring a hidden ideal to life.", "body": "Picturing possibilities no one sees yet is something your temperament and character share. On top of that, you have the power to nurture your feelings alone and to lead in front of people, a heart that values feelings and a mind that decides with logic, and the flexibility to adapt along with the drive to plan and finish. While you move a team toward a goal, you can fill that goal with a reason you truly care about.", "say": "\"We hit the goal by the end of the month. …And honestly, I really love this project.\"", "do": "You lay out the numbers clearly, but the first page of your slides is a passionate \"why I want to do this.\"", "worry": "The more you take on the leader role, the less time you get to lose yourself in what you love. After a tough call, you keep wondering whether you went against what you care about.", "karai": "Instant decisions in every meeting, thirty minutes to choose dinner."}, "INFP>ENTP": {"title": "With a gentle touch, you keep new ideas spreading.", "body": "Trusting your sparks and moving freely with the situation is the core your temperament and character share. Layered on top are the power to let your imagination grow alone and to expand ideas by talking with people, and a heart that cares about feelings alongside a mind that sharpens the logic. You toss out sharp opinions with a joke, and still make sure no one in the room got hurt.", "say": "\"What if we flipped it? …Oh, I don't mean your idea is bad or anything.\"", "do": "You come up with a new game while chatting with friends, then go home and secretly build out all the details alone.", "worry": "When a debate gets fun and you say too much, you stew all night about how they felt. You often feel there isn't enough time for either fun with people or daydreaming alone.", "karai": "Every sharp comeback comes with a quiet little \"just kidding.\""}, "INFP>INFJ": {"title": "You grow a gentle imagination with an eye on what's ahead.", "body": "Settling your heart in alone time and valuing intuition and people's feelings is the core your temperament and character share. On top of that, you have both the softness to follow your feelings and the power to see ahead and move steadily. You treasure a sudden idea, keep it warm, and take your time growing it into something that helps people.", "say": "\"I just have a feeling this one's better. …So I'll get it ready by next month.\"", "do": "For a hobby you started on a whim, you've somehow filled your planner with a whole year of practice plans.", "worry": "Caught between wanting freedom and wanting things settled, you make plans and then erase them. Trying to meet others' expectations, you can overpack your plans and leave your own heart behind.", "karai": "Even your \"do whatever I feel like\" day is neatly on the schedule."}, "INFP>INFP": {"title": "You've grown your true colors and gentle imagination, straight and true.", "body": "Your born temperament and the character you grew through experience are the same type. Treasuring what moves your heart, staying close to others' pain, and shaping your thoughts in your own words and ways—this power has grown in you without wavering. Because you know clearly what matters to you, you flourish where it's accepted, and in places that don't fit, you tend to lose energy without knowing why.", "say": "\"I think that's really lovely. …I can't quite explain it, but it's just, you know, nice.\"", "do": "When you find a view you love, you stop, take a photo, and save it with a few words.", "worry": "If you keep doing things that don't fit your heart, you wear down without knowing why. The harder you try to fit in, the easier it is to lose sight of what you loved.", "karai": "The story in your head is past volume ten, but cleaning your room hasn't gotten past page one."}, "INFP>ENFJ": {"title": "You share gentle ideals and move forward together.", "body": "Valuing sparks and deciding with people's feelings in mind is the core your temperament and character share. Layered on top are the power to nurture your feelings alone and to lead within a group, and the softness to follow your heart along with the power to plan ahead. You put what you care about into words, share it with everyone, and make it real together.", "say": "\"If we do it together, it'll be amazing! …I've already made the schedule.\"", "do": "You gather friends to plan a small event, and between tasks you hide away in a café to write down how you feel.", "worry": "While you keep cheering others on, your alone time to settle your feelings disappears. The more you lock in plans to meet everyone's expectations, the less free your heart feels.", "karai": "You cheer on everyone's dreams at full volume, but your voice gets tiny when it's your own."}, "INFP>ENFP": {"title": "You can spread your overflowing imagination, alone or with others.", "body": "Trusting your sparks, valuing feelings, and going with the flow is the core your temperament and character share. On top of that, you have both the power to deepen your imagination alone and the power to get energized by being with people. After making everyone laugh at a lively gathering, you can relive the day like a story on a quiet night.", "say": "\"Let's all go, it'll be so fun! …Oh, but I kind of want to walk home alone after.\"", "do": "After a whole day out with friends, you put in your earbuds on the train home and look for a song that fits the day.", "worry": "You love seeing people, but after too much of it, you suddenly don't want to talk to anyone. You can't predict that wave yourself, and after turning down an invite you feel guilty.", "karai": "The number of people you've told \"Let's hang out soon!\" far outnumbers the free days on your calendar."}, "INFP>ISTJ": {"title": "You give shape to a gentle imagination with solid steps.", "body": "Recharging alone and quietly turning things over in your mind is something your temperament and character share. On top of that, you have a sense that pictures what isn't seen yet and the steadiness to stack up facts one by one, a heart that reads feelings and a calm mind that decides with logic, and a free-flowing softness along with the power to finish a plan. People often see you as \"the precise one,\" but kindness and an eye for beauty show up in the small details of your work.", "say": "\"I'll check and get back to you. …Also, could I change the colors on this document a little?\"", "do": "You make a flawless how-to guide and put a little drawing on the last page.", "worry": "You get everything done properly, yet sometimes feel empty: \"Is this what I wanted to do?\" Even to start something you love, you find yourself needing a reason and a plan.", "karai": "You've put a deadline on your dreams and keep rushing yourself."}, "INFP>ISFJ": {"title": "You turn a gentle imagination into steady everyday care.", "body": "Settling your heart in alone time and deciding with feelings in mind is the core your temperament and character share. Layered on top are a sense that pictures what isn't seen yet and a steadiness that relies on experience and facts, and the softness to follow your mood along with the power to plan ahead. You remember the tastes and schedules of the people close to you, and add your own little touch.", "say": "\"Everything's ready for tomorrow. …I also made you this, like a good-luck charm.\"", "do": "You neatly write the family's plans on the calendar and doodle little pictures in the margins.", "worry": "In days full of set tasks, the time for things you love keeps shrinking. You're glad to be useful, yet sometimes you wonder, \"What did I actually want to do?\"", "karai": "You never forget anyone's anniversary, but you push back the deadline on your own dream every year."}, "INFP>ESTJ": {"title": "Firm follow-through and a soft heart, side by side.", "body": "You set up the steps and see things through to the end—someone people trust to keep things running. You also have a sensitive side that needs time alone to settle and wants to quietly protect what matters to you. That's why your \"let's do it right\" isn't coldness; it's sincerity that protects what's important. Your firmness and your kindness come from the same place.", "say": "\"Let's meet the deadline. …But if anyone's pushing too hard, please tell me.\"", "do": "At work you give crisp directions, and at home you sink alone into the music and books you love.", "worry": "The more people rely on you to lead, the more you push your own feelings aside. After saying what's right, you remember the other person's face and feel low.", "karai": "A tough-as-nails meeting leader who cries at heartwarming videos on the way home."}, "INFP>ESFJ": {"title": "With kindness for others, you hold up everyone's days.", "body": "Deciding with people's feelings in mind is the core your temperament and character share. On top of that, you have the power to let your imagination grow alone and to warm up a group, a sense that values sparks and an honest care for everyday life, and the softness to follow your mood along with a knack for organizing. While you make sure everyone's comfortable, you quietly mix in your own playful touch.", "say": "\"The seats and food are all set! …And I've got a little surprise planned, too.\"", "do": "You smoothly organize a welcome party at work, and handmake a message card for each new person.", "worry": "The more you try to meet everyone's expectations, the less time you have to daydream alone. You care so much about harmony that doing what you love starts to feel \"selfish.\"", "karai": "You collect everyone's \"That was fun!\" and feel satisfied—then push your own fun to next month."}, "INFP>ISTP": {"title": "You give shape to a gentle sense with skillful hands.", "body": "Recharging alone and moving freely with the situation is the core your temperament and character share. Layered on top are the imagination to picture what doesn't exist yet and the hands-on skill to check things yourself, and a heart that values feelings alongside a cool eye for how things work. As you quietly make something, you fill it with your own special touches and kindness for whoever will use it.", "say": "\"This just needs one screw. …And while I was at it, I painted it a color you'd like.\"", "do": "You repair an old piece of furniture yourself, repaint it in your favorite color, and love it more than before.", "worry": "Putting feelings into words is hard for you, so your kindness can come off as blunt. Even when you try to be purely logical, your hands stop if your heart isn't on board.", "karai": "You say \"It's nothing,\" but you remembered their favorite color and finished it in exactly that."}, "INFP>ISFP": {"title": "You savor both your imagined worlds and the beauty in front of you.", "body": "Treasuring alone time, putting feelings first, and going with the flow is the core your temperament and character share. On top of that, you have both an imagination that pictures what isn't seen yet and a sense that enjoys the colors, sounds, and textures right in front of you, just as they are. Whatever moves your heart, you can turn into a story in your head or something you make with your hands.", "say": "\"This sunset is beautiful. …It feels like the start of a story.\"", "do": "You bring home stones and leaves from a trip, line them up in a little box, and give each one a name from the memory.", "worry": "You love so many things, but you're not sure how to connect them to your future. You don't like clashing with people, so you quietly swallow what you want to say.", "karai": "You can't throw out a single keepsake, and your drawer is already a small museum."}, "INFP>ESTP": {"title": "With a gentle heart, you dive right in.", "body": "Moving flexibly with the situation is the core your temperament and character share. On top of that, you have the power to grow your imagination alone and to move with energy among people, an inspired sense and a firm grip on the reality in front of you, and a heart that values feelings alongside a cool eye for pros and cons. You give a hesitant friend a push and jump in together, and still check on how they feel afterward.", "say": "\"Don't overthink it, let's just try! …But if you hate it, tell me right away.\"", "do": "On a whim you leave on a solo trip that same day, and end up talking late into the night with someone you met there.", "worry": "After acting on momentum, once you're alone you wonder, \"Did that hurt anyone?\" Because people see you as up for anything, it's hard to say you want a quiet day.", "karai": "Bungee jumping? Decided instantly. Flagging down a server? Five minutes."}, "INFP>ESFP": {"title": "With a gentle sense, you enjoy this moment with everyone.", "body": "Valuing people's feelings and going with the flow is the core your temperament and character share. Layered on top are the power to sink into your imagined world alone and to brighten a group, and a sense that values sparks along with the ability to savor the fun in front of you. As you go around telling everyone about great food and fun places, you find a story of your own in each one.", "say": "\"I just know you'll all love this place! …Doesn't it feel kind of like a secret hideout?\"", "do": "For a friend's birthday, you start a handmade message album on a whim and finish it just in time.", "worry": "You pack in so many fun plans that you run short of alone time to settle your heart. Trying so hard to keep the mood bright, you sometimes can't let people see when you're sad.", "karai": "All smiles in front of everyone, then sad songs and big feelings on the train home."}, "ENTJ>INTJ": {"title": "You finish big goals with quiet, steady focus.", "body": "Seeing far ahead, deciding with clear logic, and moving forward with a plan sit at your core, in both your temperament and your character. On top of that, you have the drive to move a room full of people and the focus to think things through deeply on your own. You set the direction with confidence in the meeting, then go home and polish the plan one more time. Your strength is that you can lead out front and refine in quiet, and switch between the two.", "say": "\"Let's go with this direction. …I'll sleep on the details and send them tomorrow.\"", "do": "After pulling the whole group dinner together, you hold a one-person review session on the train home.", "worry": "The more you're asked to lead, the less time you get to think alone. You're glad to be relied on, but you also want quiet time, and balancing the two takes energy every time.", "karai": "You say \"Leave it to me,\" then quietly carry it all yourself until midnight."}, "ENTJ>INTP": {"title": "You have both the power to decide and the power to question.", "body": "Trusting your flashes of insight and thinking things through logically: that's your core, in both your temperament and your character. Beyond that, you can gather people and drive toward a goal, and also take a system apart slowly on your own. You can stick to a plan, and you're flexible enough to rethink it midway. You reach conclusions fast, yet you can still stop and ask, \"But is that really true?\" You move freely between speed and depth.", "say": "\"Okay, it's decided. …Wait, actually, it'd be more fun to rethink the whole premise.\"", "do": "You're the toughest critic of your own plan, picking it apart and rebuilding it.", "worry": "You want to decide quickly, but the more you think, the more answers you see, and you stall. You want time leading people and time thinking alone, so when your schedule gets too packed, you run out of breath.", "karai": "The conclusion was ready ages ago, but testing it got so fun that you're late handing it in."}, "ENTJ>ENTJ": {"title": "You've built your own road to your goals, without hesitation.", "body": "Your temperament, the nature you were born with, and your character, the nature that grew through experience, are the same type. Working with people, seeing ahead, thinking things through, and following through on what you decide: these strengths have grown steadily, without wavering. Once you can see the goal, the steps fall into place on their own, and before you know it you're the one organizing everything. Because you know so clearly how you work best, places with no goal, or where nothing ever gets decided, can wear you out in ways you can't quite explain.", "say": "\"So where's the goal? Let's work backward from there.\"", "do": "You set goals even for your days off, and keep an eye on your completion rate.", "worry": "When you move at your own pace, you only notice later that others couldn't keep up. You look for meaning even in rest, so it's hard to truly let go.", "karai": "You say \"Let's take it easy,\" while drawing up a plan for taking it easy."}, "ENTJ>ENTP": {"title": "You can set the path, and rebuild it along the way.", "body": "Getting energy from people and thinking with both insight and logic: that's your core, in both your temperament and your character. Added to that, you can plan ahead and follow through neatly, and also go with the flow in the moment. You're good at making plans, and just as good at enjoying it when things don't go to plan. Your strength is that you never move the goal, but you'll redesign the route as many times as it takes.", "say": "\"The deadline is Friday. No exceptions. …So, can I change the whole approach?\"", "do": "You write a tidy meeting agenda, then launch a whole new project out of the small talk on the day.", "worry": "You want to stick to what you decided, and you want to try a more interesting road, both at the same time. You worry that changing course so often is wearing people out.", "karai": "You prepared three backup plans, then went with a fourth that wasn't any of them."}, "ENTJ>INFJ": {"title": "You see far ahead, and make a path for people's hearts too.", "body": "Picturing future possibilities and moving forward with a clear plan: that's your core, in both your temperament and your character. Layered on top, you can lead a group and think deeply alone, decide by logic and read how people feel. You don't just talk about ideals; you map out the steps to get there, and you notice anyone who might be left behind. You guide people with a quiet kind of strength.", "say": "\"Let's make this our goal. …Is everyone okay? Nobody pushing too hard?\"", "do": "While a younger coworker talks to you about their future, you're quietly drafting their five-year plan in your head.", "worry": "Even when you know the right direction, you can't say it if someone might get hurt. You wear yourself out thinking about others' feelings, and only recover once you're alone.", "karai": "You fit everyone's happiness into the plan. The only thing missing is breathing room for you."}, "ENTJ>INFP": {"title": "You have the heart to dream big and the power to make it happen.", "body": "Your heart is drawn to possibilities no one can see yet: that's your core, in both your temperament and your character. On top of that, you can rally people and get results, and also nurse your own feelings in quiet. You have the drive to decide and push ahead, and the softness to take an honest detour when your heart asks for one. You don't leave dreams as dreams; you shape them in a way you truly believe in. Your passion and your kindness come from the same place.", "say": "\"We have to do this project. …But I want it in a form I truly believe in.\"", "do": "After pulling people in with your passion, you fight hard to protect some alone time to settle your feelings.", "worry": "Wanting results and wanting it to feel right in your heart don't easily point the same way. After leading a group, you need more time alone than you expected.", "karai": "You have a plan to change the world, but today's laundry is still waiting for the right mood."}, "ENTJ>ENFJ": {"title": "You lead with strength, and with warmth on top.", "body": "Getting energy from people and moving ahead with foresight and a plan: that's your core, in both your temperament and your character. Alongside that, you can judge things with clear logic and also care about each person's feelings. You state the team's goal clearly, and you still notice when someone's mood shifts. You're the kind of leader who won't give up on results or on people.", "say": "\"Let's hit this target this month! …So, has anyone been feeling down lately?\"", "do": "You run the meeting tightly, then check in privately with the person who barely spoke.", "worry": "When you should be firm, you picture how the other person feels and soften your words too much. Trying to move everyone forward, you end up being the one running around the most.", "karai": "You're so busy watching everyone else grow that your own goals keep getting pushed back."}, "ENTJ>ENFP": {"title": "You can carry excitement all the way to the finish line.", "body": "Being with people energizes you, and ideas and possibilities light you up: that's your core, in both your temperament and your character. Layered on top, you decide with both logic and heart, and you can stick to a plan or follow your mood. You pull people in with a sudden idea, then wrap it up with real results at the end. With fun and follow-through, you brighten everyone around you.", "say": "\"This is going to be so much fun! …Okay, let's split up the roles and set a deadline.\"", "do": "You start planning a surprise party on a whim, and before you know it you've made a schedule and a budget sheet.", "worry": "You want to keep starting fun things, but you also want to finish everything you start, so life gets busy. When someone just needs you to listen, you bring up efficiency first and regret it later.", "karai": "The one who said \"Let's keep it chill\" is running the whole thing most seriously."}, "ENTJ>ISTJ": {"title": "You build big visions step by solid step.", "body": "Deciding with logic and moving ahead with foresight: that's your core, in both your temperament and your character. Added to that, you can rally people and work quietly alone, see future possibilities and check facts one by one. Even while aiming high, you never neglect the numbers and steps right in front of you. You're a dependable doer with both drive and steadiness.", "say": "\"We're aiming for number one in the country. …First, show me all of last month's data.\"", "do": "After talking about your dream, you open a spreadsheet and work out exactly what it'll cost.", "worry": "Wanting to try something new and wanting the safe method pull against each other, so decisions take time. After leading for a while, you start missing quiet time to just work.", "karai": "Even for an adventure, you won't leave until the manual is finished."}, "ENTJ>ISFJ": {"title": "You see the big picture, and take good care of the people close to you.", "body": "Planning ahead and seeing things through: that's your core, in both your temperament and your character. Beyond that, you can stand in front and support from behind, look far ahead and value the facts in front of you, decide by logic and stay close to people's feelings. You read the big flow while noticing the small troubles of the people near you. Strength and kindness live side by side in you, naturally.", "say": "\"Let's get this far by next year. …Oh, but first, are you feeling okay?\"", "do": "While drawing up the team's yearly plan, you add everyone's birthday to the calendar.", "worry": "Even when you want to lead, your care for others comes first and you step back. The harder you try to do your part well, the more your own rest gets pushed aside.", "karai": "You can see the company's future clearly, but not how many vacation days you have left."}, "ENTJ>ESTJ": {"title": "You move a team with a vision of the future and a feel for the real work.", "body": "Getting energy from people, deciding with logic, and moving ahead with a plan: that's your core, in both your temperament and your character. Alongside that, you can picture possibilities no one has seen yet and lean on past experience and facts. You set new goals and also check, with a hands-on eye, whether they'll actually work. Your way of doing things is neither a fantasy nor just following old habits.", "say": "\"Here's where I want us in three years. …So, let's decide what to say at tomorrow's morning meeting.\"", "do": "When you pitch a new project, you bring three past examples that worked.", "worry": "You want to change things, and you want to protect what's already working, so drawing the line is hard. You use your own tidy standards as the benchmark and expect others to move at your speed.", "karai": "You say \"Do it your own way,\" but you've already decided the format for handing it in."}, "ENTJ>ESFJ": {"title": "You can plan a place where everyone belongs.", "body": "Getting energy from people and moving ahead neatly with a plan: that's your core, in both your temperament and your character. Layered on top, you can picture what's ahead and value what's real right now, decide by logic and care for how people feel. You set big goals and still create a mood where everyone can work happily. You're a reliable caretaker who protects both results and good vibes.", "say": "\"Let's ride this momentum all the way! …Oh, and there's tea and snacks ready for everyone.\"", "do": "You plan the event down to the minute, and on the day you go around thanking every single person.", "worry": "When you need results, the wish not to upset anyone shows up. You love being relied on, take on too much, and suddenly your calendar is packed.", "karai": "You planned everyone's seats, and forgot to save one for yourself."}, "ENTJ>ISTP": {"title": "You knock out big goals lightly, with skill and clever fixes.", "body": "Thinking things through and deciding with logic: that's your core, in both your temperament and your character. Beyond that, you can lead people and work quietly with your hands, see far ahead and grab the facts in front of you, stick to a plan and adjust lightly to the situation. Once the goal is set, you skip the fussy steps, pick \"the best move I can make right now,\" and get results fast.", "say": "\"The goal is set. …How? I'll mess around with it first and figure it out.\"", "do": "After announcing the team's goal, you quietly start building a prototype by yourself.", "worry": "Wanting to plan ahead and wanting to act on the spot take turns, so even you find your pace hard to read. When you're put in charge of a group, you miss working alone with your hands.", "karai": "It's written all over your face: fixing it yourself would be faster than this long meeting."}, "ENTJ>ISFP": {"title": "You're gentle and sensitive, with the strength to move straight ahead.", "body": "You're a calm, sensitive person who values your own pace and feelings. You also have the strength to set a goal, lead people, and push things forward. So when something matters and you can't let it go, you act with surprising clarity. You have both softness and a strong backbone.", "say": "\"Either is fine with me. …Oh, but this one thing, I'd like to do my way.\"", "do": "Usually you're the listener, but when it counts, you suddenly lay out the plan and get everyone moving.", "worry": "You want things to stay peaceful, but when things drag on, you get quietly irritated. You hold back what you want to say for too long, then sometimes say it too strongly all at once.", "karai": "Inside your \"Anything's fine,\" there are three conditions you won't budge on."}, "ENTJ>ESTP": {"title": "You map out the winning move, then nail it on the spot.", "body": "Getting energy from people and deciding quickly with logic: that's your core, in both your temperament and your character. Added to that, you can plan far ahead and also seize the chance right in front of you. You build a long-range strategy, yet when the moment comes, your body moves before your head does. You're a person of action who shines brightest when it really counts.", "say": "\"Here's the strategy. …Eh, we'll improvise the rest once we're there!\"", "do": "You set a rough route for the trip, then keep changing the details on the day depending on the crowds.", "worry": "You want to read ahead and move, but you jump at whatever's fun right now and the plan gets pushed back. Putting speed first, you skip the small checks and regret it later.", "karai": "Three days after making a long-term plan, you're already off on a whole new gamble."}, "ENTJ>ESFP": {"title": "You liven up the room, and still get everyone to the goal.", "body": "The more you're with people, the more energy you get: that's your core, in both your temperament and your character. On top of that, you can plan ahead and enjoy the moment, decide by logic and sense how people feel. You build a team that's always laughing, and you still deliver real results. Fun and follow-through are both strengths that brighten everyone around you.", "say": "\"Let's have a blast today! …Oh, and we meet at 8 tomorrow. Don't be late.\"", "do": "You keep the after-party lively while quietly starting to talk about the next goal.", "worry": "You want to enjoy the moment, but part of your mind is always on the next step. Because you care about everyone's feelings, a hard thing you had to say tends to stay with you.", "karai": "You make plans on a whim, then carry them out more precisely than anyone, and everyone's shocked."}, "ENTP>INTJ": {"title": "You turn flashes of inspiration into a solid blueprint.", "body": "Possibilities excite you, and you think things through logically: that's your core, in both your temperament and your character. Layered on top, you can grow ideas by talking with people and refine them deeply alone, act on a whim and plan far ahead. Your ideas don't just overflow; you can build them into a long plan and see it through. You have both a wide range of ideas and the reliability to finish them.", "say": "\"Wouldn't it be fun to think about it backward? …Okay, I'll sort out the steps through next month.\"", "do": "You take an idea from casual chat, go home, and turn it into a full proposal overnight.", "worry": "You want to grow ideas by talking, but if you talk too much you get tired and want to be alone. Torn between trying things right away and planning properly first, you're often slow to start.", "karai": "The plan in your head is perfect, but you go ahead without explaining it to anyone and surprise them all."}, "ENTP>INTP": {"title": "You toss ideas around with people, then deepen them alone.", "body": "Trusting your insights, thinking with logic, and moving flexibly with the situation: that's your core, in both your temperament and your character. On top of that, talking with people energizes you, and so does thinking things through alone. In a discussion you keep widening the topic, and on the way home you quietly take the idea apart. Your strength is moving back and forth between widening and digging deep.", "say": "\"Tell me more about that! …Actually, let me think about it on my own for a bit.\"", "do": "On the way home from a lively dinner, you jot down notes alone, continuing the day's debate.", "worry": "There's a big gap between days you want to talk and days you don't want to see anyone, so planning your schedule is tricky. Thinking is so much fun that you sometimes feel satisfied before you've actually done anything.", "karai": "On days with no one to debate, you argue with online articles in your head."}, "ENTP>ENTJ": {"title": "You take a sudden idea all the way to results.", "body": "Getting energy from people and thinking with insight and logic: that's your core, in both your temperament and your character. Beyond that, you can move flexibly with the flow and also plan ahead and follow through. You toss out a fun idea in a meeting, and before long you've already assigned owners and deadlines. Coming up with ideas and pulling them together, you can do both on your own, and people count on that.", "say": "\"How about something like this? …Okay, decided. Prototype by next week.\"", "do": "You turn an idea from small talk into a project that same day and start gathering people.", "worry": "Wanting to try new ideas and wanting to keep the plan clash, and sometimes you get tied up by your own rules. Because you move with so much momentum, you're slow to notice people who can't keep up.", "karai": "For something you \"just kind of tried,\" the report is suspiciously impressive."}, "ENTP>ENTP": {"title": "You got here by always chasing what's interesting.", "body": "Your temperament, the nature you were born with, and your character, the nature that grew through experience, are the same type. Growing ideas by talking with people and flipping the obvious upside down: these strengths have grown steadily, without wavering. When you meet something new or a question with no right answer, your eyes light up. Because your style is so clear, places full of fixed routine tasks can drain your energy before you even know why.", "say": "\"Okay, but what if we just stopped doing all of it?\"", "do": "Every new hobby comes with a full set of gear, and three months later you're talking about the next one.", "worry": "You're great at starting, but you tend to blame yourself for getting bored of keeping it going. When a dull place drains you, it's usually not your fault. It's just not the right place for you.", "karai": "Once the debate heats up, you forget you started out on the other side."}, "ENTP>INFJ": {"title": "With your insight, you gently light up other people's futures.", "body": "Picturing possibilities no one can see yet: that's your core, in both your temperament and your character. Layered on top, you can grow ideas through conversation and reflect deeply alone, think with logic and read feelings, move lightly and plan ahead. You can offer a sharp idea in a way that reaches the other person's heart. With your mind and your kindness, you give people a push forward.", "say": "\"You could also look at it this way. …Which one matters most to you?\"", "do": "While listening to a friend's worries, you put into words what they really feel, before they've even noticed it themselves.", "worry": "Even when you think of something interesting, you hold back, wondering if it might hurt someone. Because you take others' feelings in so deeply, you need lots of alone time to recover.", "karai": "You give brilliant life advice to others, but for yourself it's just \"Eh, it'll work out.\""}, "ENTP>INFP": {"title": "You add a kind heart to your free-flowing ideas.", "body": "Valuing your insights and moving flexibly with the situation: that's your core, in both your temperament and your character. Added to that, you can get lively with people and let your imagination grow alone, sharpen things with logic and treasure feelings. You don't just come up with fun ideas; you fill them with the wish to help someone. Humor and warmth blend in you naturally.", "say": "\"That's so funny! …But the person it's about might feel a little sad.\"", "do": "After getting lost in a debate with everyone, you go home and write something like a story, all alone.", "worry": "Even when your head agrees, you can't move if your heart isn't on board. After a lively time with people, you look back alone and wonder if your words hurt anyone.", "karai": "The margins of your notebook hold equal parts brilliant ideas, doodles, and feelings you never said out loud."}, "ENTP>ENFJ": {"title": "With fun ideas, you bring everyone's hearts together.", "body": "Getting energy from people and being moved by possibilities: that's your core, in both your temperament and your character. Layered on top, you can think with logic and care about feelings, move lightly in the moment and plan ahead. You fire up the room with ideas and still lay out a path everyone can get on board with. With your ideas and your gift for bringing people together, you help others feel hopeful.", "say": "\"Wouldn't this be fun? …I'll set it up so everyone actually wants to do it.\"", "do": "You pitch a new project with a smile, and quietly talk one-on-one beforehand with anyone who might object.", "worry": "Even when you want to make a sharp point, you sometimes swallow it, thinking about the mood and the other person's feelings. The more you take on the role of bringing everyone together, the less time you have to freely try out your ideas.", "karai": "After taking in everyone's opinions, your original idea is nowhere to be found."}, "ENTP>ENFP": {"title": "You spread the fun with both logic and heart.", "body": "Getting energy from people and moving lightly on your insights: that's your core, in both your temperament and your character. On top of that, you can test ideas with logic and stay close to people's feelings. You have a sharp mind that enjoys a debate and a wish to make people smile, so people naturally gather when you talk. You're lively, quick-witted, and well loved.", "say": "\"Isn't that logic a little off? …I mean, I totally get how you feel, though.\"", "do": "A new game pops into your head mid-chat, and you rework the rules so everyone can enjoy it.", "worry": "You want to say clearly what you think is right, but picturing someone's disappointed face puts on the brakes. Your interests keep shifting and you also value your friendships, so there's never enough time.", "karai": "Five minutes after saying \"Let's think about this calmly,\" you're the most fired-up person in the room."}, "ENTP>ISTJ": {"title": "You turn bold ideas into reality, step by solid step.", "body": "Thinking things through and judging with logic: that's your core, in both your temperament and your character. Beyond that, you can grow ideas by talking and work steadily alone, look at possibilities and check the facts, move flexibly in the moment and follow a plan reliably. Your strength is that you don't let ideas end as talk; you break them into steps and make them real.", "say": "\"Wouldn't it be fun to do it this way? …First, let's check the past records.\"", "do": "Even when you think of a new way to do something, you test it small first and put the results in a table.", "worry": "You want to try new things and you want to keep the reliable way, so it's hard to choose. When you're the rule-keeper for too long, you miss having chances to share ideas.", "karai": "You test your wildest ideas with the most boring steps of anyone."}, "ENTP>ISFJ": {"title": "You're quietly supportive, with ideas that break the usual mold.", "body": "You're a kind supporter who looks out for others and carefully handles what's been decided. You also have a curiosity that questions the obvious and wants to find new ways. So while doing things \"the usual way,\" you're quietly thinking up a better one. You bring both a sense of calm and a spark of inspiration.", "say": "\"The usual way is fine. …Though I was thinking this might make it a little easier.\"", "do": "You finish the task you were asked to do perfectly, and you've also built a system so anyone can do it easily next time.", "worry": "You're good at going along with others, but when the same thing repeats too long, part of you gets bored. Even with a good idea, you sometimes can't bring it up because of the mood in the room.", "karai": "While saying \"Oh, I'm nobody,\" you're holding the boldest improvement plan in the room."}, "ENTP>ESTJ": {"title": "You can make new ideas run smoothly in the real world.", "body": "Getting energy from people and deciding with logic: that's your core, in both your temperament and your character. Added to that, you can chase new ideas and rely on experience and facts, move flexibly and move with a plan. One moment you pitch an out-there idea, the next you've nailed down the steps and who does what. You're a hands-on leader with both ideas and the power to make them happen.", "say": "\"Why don't we just shake this up? …Okay, let's decide who's on it and the deadline right now.\"", "do": "You switch the usual meeting to \"Let's do it standing up today,\" and still end it right on time.", "worry": "Because you know why rules matter, it's hard to balance that with wanting to try new things. When you're the one in charge, you put being right first and can come across as harsh.", "karai": "You say \"Let's break the mold,\" then write a step-by-step guide for breaking it."}, "ENTP>ESFJ": {"title": "With lively ideas, you make everyone's days more fun.", "body": "The more you're with people, the more energy you get: that's your core, in both your temperament and your character. Beyond that, you can dream up new possibilities and treasure everyday life, think with logic and care about feelings, move lightly in the moment and faithfully keep what you've decided. You can shape a fun idea into something everyone will love. You're at the center of the circle, warming up the room.", "say": "\"Wouldn't this be fun? …Don't worry, I'll work around everyone's schedules.\"", "do": "You bring a small new twist to every get-together, and you also keep perfect track of who's coming and who's paid.", "worry": "Even when a cheeky comeback pops into your head, you swallow it for the other person's sake. You love doing things for others, so it's hard to find time to try your own ideas.", "karai": "The one who pitched the silliest idea is also the one cleaning up most carefully."}, "ENTP>ISTP": {"title": "With logic and a light touch, you get through any problem.", "body": "Thinking things through and moving flexibly with the situation: that's your core, in both your temperament and your character. Layered on top, you can grow ideas by talking and work quietly alone, see future possibilities and grab the facts in front of you. You don't just talk about ideas; you get your hands on them and test them right away. When people are stuck, they count on you for both your words and your hands.", "say": "\"In theory, it should work. …Well, let's just try it.\"", "do": "When you buy a new appliance, you try every button before reading the manual.", "worry": "Your mood swings between wanting to debate and wanting to work without talking to anyone, so people may think you're moody. You go back and forth between wanting to expand ideas and wanting to deal only with what's solid in front of you.", "karai": "You said \"I'll explain later,\" and it's already fixed."}, "ENTP>ISFP": {"title": "With a free spirit, you enjoy both your ideas and your senses.", "body": "Moving flexibly with the situation and wanting to stay free: that's your core, in both your temperament and your character. Added to that, you can get lively with people and enjoy quiet time alone, imagine possibilities and savor what's in front of you, think with logic and treasure feelings. You enjoy things with your mind, and savor them with your heart and body. Both are your own way of having fun.", "say": "\"Wouldn't it be fun to do it like this? …But right now, I just want to look at this view.\"", "do": "An idea from chatting with friends turns into a little handmade piece you make alone at home.", "worry": "Even when you want to say something sharp, thinking of the other person's feelings makes you hesitate. You love getting lively with people, but without time alone, you tire quickly.", "karai": "Your motto is \"keep the calendar open,\" yet you've already bookmarked every exhibit you're curious about."}, "ENTP>ESTP": {"title": "With ideas and action, you never miss a chance.", "body": "Getting energy from people, thinking with logic, and going with the flow: that's your core, in both your temperament and your character. On top of that, you can dream up possibilities that don't exist yet and quickly grasp what's real in front of you. When you get a fun idea, you've already found where and how to test it. Fast at thinking and fast at moving, you're a dependable doer.", "say": "\"This could be a new business! …Okay, let's go see the place right now.\"", "do": "You come up with an idea on a trip and try it out on the locals right there.", "worry": "You want to chase both future possibilities and present fun, so your schedule is always packed. Since you think while moving, you move on before looking back, and tend to repeat the same mistakes.", "karai": "By the time you say \"Let's be careful,\" you've already taken the first step."}, "ENTP>ESFP": {"title": "With brilliant ideas, you make the whole moment fun.", "body": "Getting energy from people and moving lightly with the flow: that's your core, in both your temperament and your character. Layered on top, you can dream up new possibilities and savor the fun right in front of you, think with logic and sense people's feelings. You spin fun games out of casual chat one after another, and get everyone around you smiling. Wherever you are, the place lights up.", "say": "\"Hey, I just had a great idea! …If everyone's in, let's do it right now.\"", "do": "When rain cancels the plans, you turn it on the spot into a game night at home and get everyone excited.", "worry": "You want to protect the fun, but when you spot a contradiction, you can't help pointing it out. Because you're sensitive to people's feelings, you remember the moment the room went cold for a long time.", "karai": "The one who said \"Just for fun\" is having the most serious fun of all."}, "INTJ>INTJ": {"title": "Someone who has steadily grown a quiet power to see ahead.", "body": "Your temperament and your character share the same shape. Thinking quietly on your own, reading many moves ahead, and building a clean, efficient path — that's your core. Because you rarely doubt your direction, you get remarkable results in places that make sense to you. In places full of rules with no clear reason, your energy quietly drains away.", "say": "\"Bottom line: that's going to cause problems in three months.\"", "do": "Before the meeting even starts, you've already prepared answers to the questions on the last page of the handout.", "worry": "You tend to skip the explanation, so people call you \"cold\" or say they \"can't tell what you're thinking.\" Choosing words so others understand takes more time than you'd expect.", "karai": "The plan in your head is flawless. Too bad you're the only person on Earth who can read it."}, "INTJ>INTP": {"title": "Someone who can redraw the map of the future as many times as it takes.", "body": "Thinking deeply on your own and seeing how things really work — that's your core, in both your temperament and your character. On top of that, you have both the drive to set a route to the goal and the flexibility to enjoy a detour when something new turns up. You're good at making a solid plan, and just as good at tearing it up and rebuilding it midway. That's why a stuck problem only gets more interesting for you.", "say": "\"I've already worked out the steps. …But wouldn't this other way be more fun?\"", "do": "After making a travel itinerary, you can't stop researching and end up knowing more about the place's history than anyone.", "worry": "The drive to decide and the urge to keep thinking kick in at the same time, so you suddenly add new ideas right before the deadline. Torn between wanting to finish and knowing it could still be better, you freeze in front of the submit button.", "karai": "Your folder has five files named \"final.\""}, "INTJ>ENTJ": {"title": "Someone who turns plans into action by bringing people along.", "body": "Seeing ahead, laying out a clear path, and moving once you decide — your temperament and character share that. Beyond it, you have both the power to think things through quietly on your own and the power to step up in front of people and pull things together. You plan your strategy alone before the meeting, then confidently lead the way when it counts. Since you can handle both the quiet prep and the lively execution, you turn what's handed to you into results fast.", "say": "\"I've set the direction. Okay, let's hand out the roles from here.\"", "do": "You take charge in meetings, then walk home alone with earbuds in, replaying how it all went.", "worry": "You're great at moving people, but afterward you're wiped out and don't want to talk to anyone. The more people lean on you, the less time you get to think alone.", "karai": "The nights after you've led the team are the nights every notification gets switched off."}, "INTJ>ENTP": {"title": "Someone who tosses ideas around with others while keeping an eye on the horizon.", "body": "Trusting your flashes of insight and thinking things through logically — those you share. On top of that, you have both the power to boil ideas down alone and the power to grow them in conversation, plus both the drive to stick to a set path and the lightness to change direction on the spot. A casual idea from chatting with friends somehow turns into a step-by-step plan. In a good way, the line between play and serious work is thin for you.", "say": "\"That could actually work! …Wait, if we think three years out, it's stronger if we build it like this.\"", "do": "A joke at a group dinner sparks a new project idea, and by the next morning you've sketched out the proposal on your own.", "worry": "The more fun the conversation, the more ideas pile up — and sorting them out lands on you alone. The urge to expand and the urge to narrow down show up on the same day.", "karai": "The one who opened the can of worms and the one cleaning it up? Usually both you."}, "INTJ>INFJ": {"title": "Someone who sees even people's feelings and quietly paves the way.", "body": "Recharging in time alone, reading where things are headed, and moving forward with a clear outlook — that's your core in both temperament and character. On top of that, you have both the power to check what's right through logic and the power to take people's feelings to heart. You can look for \"the way that works best\" and \"the way that hurts no one\" at the same time, so people often quietly turn to you for advice.", "say": "\"Logically, this is the right answer. …But thinking about how they'll feel, I want to say it differently.\"", "do": "When you need to give a younger coworker feedback, you decide what to say in one night — and spend three days on how to say it.", "worry": "Wanting to say what's right and not wanting to hurt anyone overlap, so you often swallow your words. Because you understand so much, you end up carrying other people's worries too.", "karai": "You read other people's feelings three moves ahead, and forget to read your own."}, "INTJ>INFP": {"title": "Someone who protects their ideals in a way that makes sense.", "body": "Treasuring time to think alone and being drawn to possibilities no one can see yet — those you share. Beyond that, you have both the power to move forward with logic and a clear outlook, and the softness to go with the flow while honoring your own feelings and values. You'll pour plans and reasoning into what you love, but you just can't move for things that don't touch your heart. That honesty is your strength.", "say": "\"My head is on board. …But my heart isn't quite ready to go yet.\"", "do": "You make a perfect schedule for your creative hobby, then start a different piece depending on your mood that day.", "worry": "You know in your head that you \"should,\" but your feelings can't keep up, and you're quick to blame yourself. Balancing the wish to stick to the plan with the wish to protect your heart's pace quietly wears you out.", "karai": "Your life plan is mapped out decade by decade. Tomorrow's schedule? Still blank."}, "INTJ>ENFJ": {"title": "Someone who sees far ahead and gives people a push forward.", "body": "Seeing ahead through intuition and moving once you decide — your temperament and character share that. On top of it, you have both deep solo thinking and the warmth to brighten a room, both calm logic and a kindness that reads feelings. In front of everyone you're the cheerful encourager, while behind the scenes you've mapped out how to win. You carry warm care for people and cool foresight together.", "say": "\"You've totally got this! …And I've narrowed what we need to do by next week down to three things.\"", "do": "You cheer on a friend's dream with all your heart, then go home and research the road to making it happen.", "worry": "Because you're good at encouraging others, you keep smiling and taking things on even when you're running low. After lively times, you rarely get enough quiet time alone to recover.", "karai": "At everyone's future-planning meeting, somehow there's never an agenda item for you."}, "INTJ>ENFP": {"title": "Someone who adds the colors of people and feelings to a quiet blueprint.", "body": "Getting excited about possibilities no one can see yet — that's your core in both temperament and character. Beyond that, you have both sides of everything: thinking things through alone and diving into a crowd, calm logic and warm empathy, careful planning and riding the moment. You naturally switch between a wide social life and deep thinking, depending on the scene.", "say": "\"Ooh, that sounds fun, I'm in! …By the way, I think this part of the plan has a hole.\"", "do": "You bond with someone new over their big dream, then jot down its weak spots on the train home.", "worry": "The gap between days you want to be around people and days you want to think alone is big, so even you aren't sure how to fill your calendar. Sometimes you tire yourself out by coolly reviewing the choices you made on impulse.", "karai": "Life of the party and chair of the post-party review committee — both you."}, "INTJ>ISTJ": {"title": "Someone who builds big ideas step by solid step.", "body": "Recharging alone, thinking logically, and moving forward as planned — those you share. On top of that, you have both the power to imagine what could be and the steadiness to check facts and past experience one by one. You don't just come up with new ways no one has tried; you also look into \"how did it go last time?\" before acting. That's why you rarely make big mistakes with what you're trusted to do.", "say": "\"Let's switch to the new system. But first, let's check last year's numbers again.\"", "do": "Before buying a new appliance, you picture how you'll use it for years to come while comparing a hundred reviews.", "worry": "Because you check so carefully, it can take a while to turn ideas into reality. The wish to bet on possibilities and the wish to pick the sure thing are quietly playing tug-of-war.", "karai": "You test the bridge before crossing — then hand in a proposal to improve it."}, "INTJ>ISFJ": {"title": "Someone who sees ahead and quietly supports the people around them.", "body": "Recharging alone, seeing ahead, and moving steadily forward — your temperament and character share that. On top of that, you have both the power to imagine possibilities and the power to value the facts in front of you, both calm logic and kindness toward others. You notice before someone runs into trouble and quietly take care of it without a word. Those small, thoughtful touches hold both your foresight and your care.", "say": "\"I brought a spare, just in case. …Oh, and a jacket, since I figured you'd be cold.\"", "do": "You plan next month's event earlier than anyone, with notes on what each guest likes.", "worry": "Because you act before anyone asks, people start to take it for granted. Caught between wanting efficiency and wanting to go along with others, you tend to put your own time last.", "karai": "You clear away everyone's \"uh-oh\" in advance, and never tell anyone your own."}, "INTJ>ESTJ": {"title": "Someone who takes a well-made plan and runs it reliably on the ground.", "body": "Deciding with logic and moving forward as planned — that's your core in both temperament and character. On top of that, you have both the power to read ahead alone and the power to give directions in front of people, both intuition that maps the route and facts that keep your footing firm. You can single-handedly connect the ideal on paper with the reality on the ground. That's why you're often asked to get stalled things moving again.", "say": "\"Here's the goal. So this week, let's make sure these three things get done.\"", "do": "You spot wasted work at your job, design a new process, and hand it out to everyone the next day.", "worry": "Because you can already see the right answer in your head, other people's slowness can get on your nerves. When you're leading people for a long stretch, your alone time for thinking keeps shrinking.", "karai": "\"Let's decide together,\" you say — with the answer already in your pocket."}, "INTJ>ESFJ": {"title": "Someone who quietly reads ahead to make a place for everyone.", "body": "Moving things forward with a clear outlook — your temperament and character share that. Beyond it, you have both sides of everything: thinking alone and getting energy from people, imagining possibilities and valuing the facts in front of you, deciding by logic and caring about feelings. You can brighten the mood and also design how the whole thing runs smoothly. You're a reassuring person to have in charge.", "say": "\"I worked out where everyone's sitting! …I put people who'll get along next to each other.\"", "do": "You plan a friend's birthday party with a minute-by-minute timeline, while checking in with every single guest.", "worry": "You love doing things for others, but before you know it, there's almost no time left to think on your own. Going along with everyone's feelings, you sometimes miss the chance to say what you think.", "karai": "The moment you agree to organize, you've already planned the after-party and the after-after-party."}, "INTJ>ISTP": {"title": "Someone who thinks far ahead and checks it with their own hands.", "body": "Recharging alone and thinking things through logically — that's your core in both temperament and character. On top of that, you have both the power to see ahead and make plans, and the lightness to act on the spot based on the facts in front of you. You take the systems you've worked out in your head and test them by simply trying them. You don't stop at theory — you make things that actually work.", "say": "\"It should work like this. …Well, guess we'll know once we try it.\"", "do": "You glance at the furniture instructions once, end up assembling it by instinct, and still get it done.", "worry": "The wish to make long plans and the wish to just handle what's in front of you take turns, so your follow-through comes in waves. If you're not into something, you just can't get your hands to move.", "karai": "You spend more time fiddling with the tools in front of you than drawing the blueprint for the future."}, "INTJ>ISFP": {"title": "Someone who wraps sharp foresight in a gentle sensitivity.", "body": "Recharging in time alone — your temperament and character share that. Beyond it, you have both sides of everything: imagining future possibilities and savoring what you sense right now, deciding by logic and valuing feelings, making plans and going with the flow. You see through things calmly, yet never let go of the beautiful, comfortable things around you. You have strong, quiet standards.", "say": "\"On paper, this one's the better deal. …But I just like this color more.\"", "do": "You redo your room according to plan, then rethink everything to match the one little item you fell in love with.", "worry": "When the logical path and the path that feels right split, either choice leaves a little snag afterward. It's hard to put your preferences into words, so when someone asks you to explain, you go quiet.", "karai": "You can list ten rational reasons, and still decide with \"because I like it.\""}, "INTJ>ESTP": {"title": "Someone with a forward-thinking mind who can enjoy the moment.", "body": "Thinking things through logically — that's your core in both temperament and character. On top of that, you have it all: thinking deeply alone and moving around among people, seeing possibilities and grabbing the facts in front of you, making plans and acting on the spot. To others it looks like you jumped in on impulse, but in a corner of your mind you've already worked out how to win.", "say": "\"Let's just go! …Oh, I already looked up the last train home.\"", "do": "You head out on a whim, and somehow end up guiding everyone along the most efficient route.", "worry": "The swing between days you want to move and have fun and days you want to sink into thought is big, so you overbook and wear yourself out. Afterward, you replay the calls you made in the moment and grade yourself.", "karai": "You say \"it'll work out\" — and you've already got the steps to make it work out."}, "INTJ>ESFP": {"title": "Someone who keeps one calm eye open in the middle of the fun.", "body": "You're a people person who enjoys the moment and lights up the room. You also have a calm side that looks ahead and quietly pieces things together on your own. That's why you can gently steer things so the fun keeps going. Even while you're laughing, part of you is taking in the whole picture.", "say": "\"Let's have the best time today! …And let's pick a date now so we can do this again.\"", "do": "You were laughing at the center of the party, yet you're the first to figure out the cleanup plan and get moving.", "worry": "The more fun the lively times are, the more alone time you need afterward to think. People see you as the bright one, so it's hard to share the deep things on your mind.", "karai": "The loudest one at the party is the quietest one on the way home."}, "INTP>INTJ": {"title": "Someone who turns a curious mystery into a plan with a goal.", "body": "Going deep in time alone and trying to see how things work — that's your core in both temperament and character. On top of that, you have both the freedom to follow your interests wherever they go and the power to plan ahead and see things through. Research that started with \"I wonder why\" ends up in a genuinely useful form. You can turn curiosity into results.", "say": "\"I really want to know why this happens. …Okay, let's have a conclusion by next month.\"", "do": "A random question sends you researching, and you finish with an easy-to-read diagram you made just for yourself.", "worry": "Wanting to think freely and wanting to wrap things up neatly collide, so you struggle to decide where to draw the line. Even after making a plan, a new question pulls your heart its way.", "karai": "Even your side-quest research has a firm deadline."}, "INTP>INTP": {"title": "Someone who has always kept \"I wonder why\" close.", "body": "Your temperament and your character share the same shape. You love thinking on your own, and your urge to know how things work never stops. That curiosity has been your steady core since you were a kid. You do great where you're free to think, but where you're expected to just follow without asking why, you tend to wear out without knowing the reason.", "say": "\"Wait, hold on — why is it like that in the first place?\"", "do": "You start looking up one thing before bed, and the next thing you know, it's light outside.", "worry": "Thinking is so fun that getting started often gets pushed back. It's all finished in your head, but to others it looks like you're \"doing nothing.\"", "karai": "From your search history alone, no one could ever guess who you are."}, "INTP>ENTJ": {"title": "Someone who makes free-flowing ideas real by getting people moving.", "body": "Trusting your flashes of insight and thinking logically — those you share. On top of that, you have both the power to dig into ideas alone and the power to pull people together, both the freedom to wander and the drive to set a goal and go. When you want to test a system you've thought up, you gather people, set up the steps, and actually run it. You can turn the experiments in your head into something real in front of everyone.", "say": "\"I came up with a good system. Let's assign roles and test it by next week.\"", "do": "Starting from something you looked into for fun, you somehow end up redesigning how your club is run.", "worry": "When you keep leading people, you lose your time to think freely and start feeling boxed in. Rushing to the right answer, you sometimes cut off your own ideas halfway.", "karai": "Five minutes after saying \"let's all think about it,\" you're announcing the conclusion."}, "INTP>ENTP": {"title": "Someone who grows the experiments in their head through conversation.", "body": "Trusting your insight, thinking logically, and moving flexibly with the flow — that's your core in both temperament and character. On top of that, you have both the power to think deeply alone and the power to expand ideas by talking with others. You take ideas you've quietly been warming up, test them in a good debate, and polish them further. Time alone and time with people both feed your thinking.", "say": "\"I've been thinking about this a while — what do you think happens if we flip it?\"", "do": "You come up with a theory while chatting with friends, then go home and test it alone until the middle of the night.", "worry": "Talking is fun in the moment, but once you get home you're suddenly drained and don't want to hear from anyone. You come up with so many ideas that you move on before any of them is finished.", "karai": "Starting debates: expert. Ending them: still researching."}, "INTP>INFJ": {"title": "Someone who gently delivers answers they've checked with logic.", "body": "Recharging in time alone and valuing possibilities no one can see yet — those you share. Beyond that, you have both the power to test what's right through logic and the power to care for people's feelings, both the freedom to think openly and the drive to plan and move forward. You calmly untangle people's worries while carefully choosing words that are easy for them to hear. People quietly rely on you as someone to talk to.", "say": "\"I think this is probably why. …But you don't have to decide anything right now, okay?\"", "do": "While listening to a friend's problem, you sort out the causes in your head, then quietly hand them a note with a next step.", "worry": "The more you think about others' feelings, the more you hesitate to share your honest opinion. Wanting to think freely and wanting to reach a clear answer overlap, so you tend to carry worries for a long time.", "karai": "You solve other people's problems overnight, and leave your own to sit for three years."}, "INTP>INFP": {"title": "Someone who deepens their own world by thinking and feeling.", "body": "Treasuring time alone, imagining possibilities, and moving gently with the flow — that's your core in both temperament and character. On top of that, you have both the power to think things through logically and the power to honor your own feelings and values. You can explain in your own words even why you love what you love, so your passions have both depth and warmth.", "say": "\"There are three reasons I love this. …No, honestly, the main one is it just makes me cry.\"", "do": "You write a long review of your favorite movie, mixing analysis and passion, that nobody asked for.", "worry": "You keep turning over feelings that logic can't settle. Torn between being right and being kind, you're often slow to reply.", "karai": "You sort out your feelings at the length of a research paper."}, "INTP>ENFJ": {"title": "Someone who can turn deep thinking into words that lift people up.", "body": "Trusting your insight and valuing possibilities no one can see yet — your temperament and character share that. On top of it, you have both thinking alone and drawing energy from people, both checking with logic and valuing feelings, both thinking freely and planning ahead to move things forward. You cheerfully give people a push in front of everyone, and your words are backed by careful thought.", "say": "\"You can totally do this! …I've got the reasons too — want to hear them?\"", "do": "Before meeting a younger friend who wants advice, you spend the night before sorting out their situation on your own.", "worry": "Because encouraging people is fun, you tend to cut into the time you need to think alone. Torn between answering someone's feelings and calmly checking what's right, you struggle to find the words.", "karai": "In public, everyone's head cheerleader. At home, a quiet lone researcher."}, "INTP>ENFP": {"title": "Someone whose curiosity keeps growing with every new person they meet.", "body": "Getting excited about unseen possibilities and moving lightly with the flow — that's your core in both temperament and character. Beyond that, you have both the power to think deeply alone and the power to jump into a crowd, both checking with logic and staying close to feelings. When you meet an interesting person or topic, your heart and mind start moving at once. You're curiosity in human form.", "say": "\"That's amazing! …So wait, how does that actually work?\"", "do": "At an event you've never been to, you make friends with the person next to you and grill them about how their job works.", "worry": "Your interests keep shifting, so the things you start often stall halfway. On nights after a fun time with people, the lack of alone time catches up with you.", "karai": "Your bookshelf holds one half-filled notebook for every obsession."}, "INTP>ISTJ": {"title": "Someone who solves free-roaming questions with solid steps.", "body": "Recharging alone and thinking logically — your temperament and character share that. On top of that, you have both the power to imagine possibilities freely and the power to check facts one by one, both flexibility with the flow and the steadiness to keep your commitments. You don't stop at a hunch; you gather evidence before you conclude. At work you're serious and trusted, while new questions are always running in your head.", "say": "\"I'll follow the rules. …But can I look into why the process is set up this way?\"", "do": "You get your routine tasks done perfectly, and in your spare time you look up where those tasks came from.", "worry": "Wanting to keep the rules and wanting to think more freely collide, so you often feel boxed in. There's so much to check before saying an idea out loud that the moment passes.", "karai": "When you hear \"there's no precedent,\" you object — and get a little excited."}, "INTP>ISFJ": {"title": "Someone with a sharp eye who quietly supports others.", "body": "Recharging in time alone — your temperament and character share that. Beyond it, you have both sides of everything: imagining possibilities and valuing the facts in front of you, thinking logically and caring for others, moving freely and keeping your commitments. You're quick to notice small changes in the people around you, quietly think about why, and then gently lend a hand.", "say": "\"You've seemed a bit down lately. …I think you're not sleeping enough. Here, this tea helps you sleep.\"", "do": "You notice a change in a friend's health, look into the cause, and casually hand them something that helps.", "worry": "When you're going along with others a lot, you lose time to think at your own pace and get tired. Even when logic says otherwise, you keep it to yourself out of consideration.", "karai": "Thoughtfulness toward others: 100 points. Explaining your own feelings: always handed in blank."}, "INTP>ESTJ": {"title": "Someone who takes a bright idea and runs it tightly in practice.", "body": "Thinking logically and deciding by reason — that's your core in both temperament and character. On top of it, you have both thinking alone and pulling people together, both imagining possibilities and grounding yourself in facts, both the freedom to experiment and the drive to see things through. You can turn new ideas into rules and steps that everyone can actually use.", "say": "\"This is the least wasteful process. …But I'll come back next month with a better one.\"", "do": "You set up a system at work and get everyone to follow it, while secretly testing an improved version yourself.", "worry": "When you keep leading people, you lose time to let your thoughts roam and start to feel stifled. You make the rules, yet sometimes you're the one who feels most cramped by them.", "karai": "The person who writes the most rules is the one who questions them the most."}, "INTP>ESFJ": {"title": "Someone who brings people together and never stops thinking.", "body": "You're a natural organizer who looks out for everyone's feelings and puts people at ease. You also have a strong drive to dig into how things work and why, on your own. Even while going along with others, you keep asking yourself, \"why does it work this way?\" That calm, clear thinking is why your care for people always hits the mark.", "say": "\"What matters most is that everyone feels good about it. …By the way, it's faster if we do it like this.\"", "do": "After pulling off a group dinner perfectly as the organizer, you go home and start researching something totally unrelated.", "worry": "You don't mind doing things for others, but when your time to think alone disappears, you suddenly run out of breathing room. After going along with everyone, you lose track of \"wait, what did I actually think?\"", "karai": "Nodding along with a smile — while counting the holes in their logic."}, "INTP>ISTP": {"title": "Someone who checks what they've figured out with their own hands.", "body": "Recharging alone, thinking logically, and moving flexibly with the flow — that's your core in both temperament and character. On top of that, you have both the power to imagine possibilities freely and the power to check the facts and how things feel in your hands. Once you think \"it's probably like this,\" you try it right away. Going back and forth between thinking and testing, you get closer to the heart of things.", "say": "\"In theory, it's like this. …But it'd be faster to just take it apart.\"", "do": "You buy a gadget that caught your eye and take it apart before using it — stopping just short of the point of no return.", "worry": "You focus amazingly well on what interests you, and can't bring yourself to touch what doesn't. Explaining your thinking feels like a hassle, so people often misunderstand you.", "karai": "You grab the screwdriver before the manual."}, "INTP>ISFP": {"title": "Someone who protects their own pace by thinking and feeling.", "body": "Recharging in time alone and moving gently with the flow — that's your core in both temperament and character. Beyond that, you have both imagining possibilities and savoring what you sense right now, both thinking logically and valuing feelings. With the things you love, your interest in how they work and the stirrings of your heart work together. You're quiet, but your tastes are clear.", "say": "\"Why does this color combo feel so calming? …Eh, if I like it, that's enough.\"", "do": "You keep going back to your favorite café, watching how they brew the coffee and trying it yourself at home.", "worry": "There are times you want to reason things out and times you just want to feel, so your feelings are hard to explain. When someone rushes you, both your thoughts and your feelings freeze.", "karai": "Inside your \"just because\" are a hundred reasons only you know."}, "INTP>ESTP": {"title": "Someone who moves before thinking, and thinks while moving.", "body": "Thinking logically and adapting flexibly in the moment — that's your core in both temperament and character. On top of it, you have both thinking deeply alone and moving around among people, both imagining possibilities and grabbing the facts in front of you. When an idea hits, you try it first; if it doesn't work, you pause right away and rethink how it works. You switch between action and analysis very fast.", "say": "\"Let's just try it! …Oh, I think I just figured out why that failed.\"", "do": "You start a new game with friends, and after just a few rounds you've found the winning pattern.", "worry": "Spending long stretches on the move with others leaves you short on time to gather your thoughts alone. Sometimes you rethink things you decided in the moment and start second-guessing.", "karai": "First to jump in, first to crack the strategy."}, "INTP>ESFP": {"title": "Someone who finds every day interesting with a free mind and a bright heart.", "body": "Moving flexibly with the flow and not getting tied down by rules — that's your core in both temperament and character. Beyond that, you have both thinking alone and shining among people, both imagining possibilities and enjoying the now, both thinking logically and valuing feelings. Even in the middle of laughing with everyone, you suddenly wonder, \"why is this happening?\" Fun and curiosity live side by side in you.", "say": "\"This is so much fun! …Hey, why do you think everyone got so hyped?\"", "do": "On the way home after hanging out, you drift into thinking about why today was so fun.", "worry": "You need both the fun of being with people and the fun of thinking alone, so planning your schedule is tricky. After riding the vibe of the moment, you're puzzled by how suddenly you want quiet.", "karai": "The one having the most fun is now the one philosophizing hardest on the way home."}, "ESTJ>INTJ": {"title": "A planner who can map the road to faraway goals.", "body": "Thinking things through logically and moving forward with a clear view ahead is your core, in both your temperament and your character. On top of that, you have both the power to jump into a group and get things moving, and the power to think deeply on your own. You have the care to check the facts in front of you and the imagination to picture a future that doesn't exist yet. You're someone who can write \"next week's to-do list\" and \"the five-year plan\" in the same notebook.", "say": "\"Okay, so that's who's doing what. …By the way, do you think this job will even exist in three years?\"", "do": "After handing everyone a role in the meeting, you're sketching a new system by yourself on the train home.", "worry": "After leading in front of people, you need more alone time than you expect. Choosing between what's solid right now and the ideal further ahead can make decisions take a while.", "karai": "You've got a ten-year plan, but still no idea what's for dinner tonight."}, "ESTJ>INTP": {"title": "Someone with both solid follow-through and a mind that thinks things all the way through.", "body": "Making decisions with clear logic is your core, in both your temperament and your character. On top of that, you have the drive to lead everyone through the steps, and the urge to dig into \"why does it work this way?\" on your own. You understand why rules matter—and you also enjoy questioning them and rebuilding them. That's why you're a great fit for slowly making old ways of doing things better.", "say": "\"Deadline's Friday. …Wait, actually—wouldn't it be faster to flip this whole process around?\"", "do": "You follow the manual step by step, while filling its margins with notes on \"a better way.\"", "worry": "The wish to reach a conclusion fast clashes with the feeling that you haven't thought it through yet, and it frustrates even you. Your days out with people and your days holed up alone feel so different that planning your schedule gets tricky.", "karai": "While you were redesigning the system, the deadline for the actual task passed."}, "ESTJ>ENTJ": {"title": "Someone who moves today's reality and the big vision at the same time.", "body": "Getting energy from people, deciding with clear logic, and moving ahead with a view of what's coming is your core, in both your temperament and your character. Alongside that, you have the steadiness to value solid facts and past examples, and the spark to bet on new possibilities. When you're put in charge, you can fold a safe plan and a bold challenge into one proposal. You can switch between caution and daring depending on the moment.", "say": "\"Here's how last year's numbers look. …So this year, let's be bold and change the whole approach.\"", "do": "For a neighborhood event, you perfect the usual schedule—then quietly slip in one brand-new idea.", "worry": "Torn between the comfort of doing what worked before and the urge to change things in a big way, you rerun the numbers again and again before deciding. Others seem slow to you, so you tend to take everything on yourself.", "karai": "You say \"let's decide together,\" but the conclusion slide is already made."}, "ESTJ>ENTP": {"title": "Someone who brings a breeze of fresh ideas to steady progress.", "body": "Getting energy from people and deciding with clear logic is your core, in both your temperament and your character. On top of that, you can build plans on solid facts, and you're light enough on your feet to change direction with a sudden idea. In discussions, you toss out ideas that surprise everyone, then pin it all down to \"So who's doing what, and by when?\" Fun and reliability live side by side in the same conversation.", "say": "\"I love that idea! …So let's lock in the budget and deadline right now.\"", "do": "You plan a trip down to the detail, then swap out half the stops after a tip you heard from a local.", "worry": "The wish to stick with what you decided and the wish to try something new take turns, so your own plan keeps wavering. When people ask \"So which is it?\" you get a little stuck.", "karai": "You've got three proposals going, and you've cheated on every one of them with the next idea."}, "ESTJ>INFJ": {"title": "A dependable organizer who also sees deep into people's hearts.", "body": "Setting a course and moving forward steadily is your core, in both your temperament and your character. Along with that, you have it all: the drive to lead and the depth to think quietly alone, an eye for facts and an eye for what's ahead, the power to decide with logic and the heart to read people's feelings. At work you look like the schedule person, but you're actually noticing who's pushing themselves too hard, and where.", "say": "\"We'll go with this schedule. …Also, has anyone seemed down lately?\"", "do": "While putting together a progress chart, you add a sticky note with a personal word for each team member.", "worry": "You worry that an efficient decision might have hurt someone, and replay it many times afterward. The more you take on roles that keep you surrounded by people, the less time you have to reset on your own.", "karai": "You can worry about everyone—but you're the very last to notice you're tired."}, "ESTJ>INFP": {"title": "Someone who carries a quiet ideal all the way to something real.", "body": "You like thinking on your own and holding on to what your heart says is good. But you don't let those ideals stay dreams. Once you decide to act, you also have the drive to make a plan, set deadlines, and bring people in to make it real. It starts with kindness and ends with getting it done. Being both a dreamer and a doer—that's your strength.", "say": "\"I really think this is going to be something great. …Okay, let's get this far by next Friday.\"", "do": "A hobby you started just because you loved it has somehow turned into a full-on project with a spreadsheet and deadlines.", "worry": "You want to honor your feelings, yet you catch yourself measuring yourself by efficiency and results. The more you love something, the harder you try to do it \"properly\"—and the more it wears you out.", "karai": "You were talking about your dream, and three minutes later it has owners and deadlines."}, "ESTJ>ENFJ": {"title": "Someone who puts warm hopes into the plans that move people.", "body": "Getting energy from people and moving forward with a plan is your core, in both your temperament and your character. On top of that, you have both a straight-ahead way of judging by facts and logic, and a heart that cares about people's feelings and growth. Put in charge of a club or team, you plan the practice menu down to the detail—and you also have words ready to lift each person up. Even in your strictness, there's always faith in the other person.", "say": "\"Today's drills go in this order. …I really believe you all can do it.\"", "do": "When coaching a junior, you hand them a step-by-step guide—along with a letter listing three things they're great at.", "worry": "The wish to say what's right clashes with the wish not to hurt anyone, so choosing your words takes time. The harder you try to live up to everyone's expectations, the fewer places you have to admit you're struggling.", "karai": "Even your words of encouragement are prepared right on schedule."}, "ESTJ>ENFP": {"title": "Someone who can have fun freely, on a solid foundation.", "body": "Getting more energized the more you're around people is your core, in both your temperament and your character. On top of that, you have it all: the steadiness to check the facts and the spark to find new possibilities, the power to decide with logic and the heart that values feelings, the knack for planning and the ease to enjoy the moment. At events you're at the center of the laughter—and before you know it, you're also directing the cleanup.", "say": "\"Let's all go, it'll be so much fun! …Oh, I'll send the meeting time and what to bring later.\"", "do": "A hobby group you started on a whim somehow has proper rules and an attendance sheet.", "worry": "Caught between jumping at fun things and wanting to keep your commitments, you feel a little tug of regret whichever you choose. After going with your mood, you sometimes blame yourself for not being more careful.", "karai": "You say you want to live free—while making a schedule for your free time."}, "ESTJ>ISTJ": {"title": "Someone who can run a solid process by leading people or by working alone.", "body": "Relying on facts, deciding with clear logic, and moving forward with a view ahead is your core, in both your temperament and your character. On top of that, you have both the power to stand in front and take charge, and the power to quietly finish things on your own. At work, you explain the steps to everyone—then finish your own part, accurately, before anyone else. Whether it's a busy room or a quiet one, your work is the same quality.", "say": "\"That's the process. Any questions? …If not, I'll get started.\"", "do": "You assign moving-day jobs to the whole family, then pack up the bookshelf by yourself without asking anyone for help.", "worry": "You're glad to be trusted with bringing people together, but afterward you're wiped out and want to be alone. You sometimes worry whether people can keep up with how thorough you are.", "karai": "\"It's faster if I just do it myself\" has become your catchphrase."}, "ESTJ>ISFJ": {"title": "Someone who quietly supports people with careful planning.", "body": "Valuing facts and experience and moving forward with a plan is your core, in both your temperament and your character. Layered on top, you have the power to get things moving in front of people and the power to tidy things up carefully alone, a straightforward way of judging by logic and a gentle way of standing by people's feelings. At family events, you're the one who sets the schedule—and also the one who remembers Grandma's favorite dish.", "say": "\"We're meeting at the station at ten. …Oh, and I saved Grandma the window seat.\"", "do": "Making the seating chart for a family gathering, you quietly make sure people who don't get along aren't side by side.", "worry": "Even when you should speak up, you think of the other person's feelings and swallow your words—then later think, \"I should've said it.\" When people keep relying on you, your own rest keeps getting pushed back.", "karai": "You have notes on everyone's favorites, but go blank when someone asks for yours."}, "ESTJ>ESTJ": {"title": "Someone who has grown, straight and true, the power to decide, drive, and deliver.", "body": "Your temperament and character are the same, so your power to turn plans into reality is your steady core. You connect with people, check the facts, decide with clear logic, and move forward step by step. All of this comes so naturally that people rely on you without a second thought. Because your way of doing things is so clear, you get big results in places that suit you—and in places that don't, you get worn down without quite knowing why.", "say": "\"Okay, let's decide. Who's doing what, and by when?\"", "do": "For a family trip, you print an itinerary with times down to the minute and hand everyone a copy.", "worry": "When others move slowly, you end up taking everything on yourself. Sometimes you say what you think is right, it comes across as harsh, and you feel down.", "karai": "Even your day off has somehow turned into \"today's tasks.\""}, "ESTJ>ESFJ": {"title": "Someone whose brisk efficiency comes with real kindness.", "body": "Getting energy from people, valuing facts, and moving forward with a plan is your core, in both your temperament and your character. On top of that, you have both a straightforward way of deciding by logic and a heart that cares how everyone feels. Organizing a group dinner, you stick to the budget and time—and still arrange a little gift for whoever couldn't come. You're organized without ever seeming cold, and that's thanks to this kindness.", "say": "\"It's $25 a person, two hours max. …So, did we already order the farewell flowers for Sam?\"", "do": "After making a fair duty roster at work, you quietly swap shifts with someone who looks unwell.", "worry": "You want to make a fair, logical call, but when someone looks disappointed you can't settle on it. You pay so much attention to everyone that you only notice how tired you are once it's over.", "karai": "Strict about the rules—and the softest of all on anyone in trouble."}, "ESTJ>ISTP": {"title": "Someone who can both plan the steps and fix things with their own hands.", "body": "Relying on facts and deciding with clear logic is your core, in both your temperament and your character. On top of that, you have the power to lead a plan in front of people and the power to quietly work with your hands alone, the comfort of deciding ahead and the ease of handling things on the spot. When trouble hits, you're giving everyone directions—and somehow you've already got a tool in your hand. You solve problems with both your words and your hands.", "say": "\"Just follow the steps on this sheet. …Eh, if something breaks, we'll figure it out then.\"", "do": "Putting furniture together, you read the instructions carefully—then switch to your own way halfway and finish faster.", "worry": "You want a plan, but you also don't want to be tied down, so every time you add something to your calendar you hesitate a little. After leading a group, you go quiet and just want to tinker with something by yourself.", "karai": "You do read the manual. You just never tell anyone you did."}, "ESTJ>ISFP": {"title": "Someone with soft, personal tastes inside a well-organized life.", "body": "Valuing the facts and the feel of things in front of you is your core, in both your temperament and your character. On top of that, you have the power to move among people and the power to savor time alone, to decide by logic and to choose by feeling, to make a plan and to go with your mood. You may be all business at work, but on your days off you take your time caring for favorite dishes and plants. That careful touch shows up in both.", "say": "\"I'll have that done by tomorrow morning. …Oh, this coffee cup is such a nice color.\"", "do": "In your balcony garden, you keep a watering log—while puzzling forever over which flower colors go together.", "worry": "Switching between quick, decisive moments and slow moments to just feel things, all in one day, tires you out. You tell yourself \"I need to do this properly\" even about things you love, and the fun fades a little.", "karai": "Even during your relaxing time, you're counting exactly how many minutes you rested."}, "ESTJ>ESTP": {"title": "Someone who can follow a set path and also win in the moment.", "body": "Getting energy from people, looking at facts, and deciding with logic is your core, in both your temperament and your character. On top of that, you have both the power to plan far ahead and the quick reflexes to change your moves as things unfold. In sports, you'd work out the game plan in detail beforehand, then read the other side during the game and pick the best play on the spot. It's because you prepared that you can make bold changes.", "say": "\"This is our game plan. …But if they switch it up, we'll adjust then.\"", "do": "You make a shopping list for the barbecue, then spot a sale at the store and change the whole menu.", "worry": "Between wanting things to go to plan and wanting to act the moment an idea hits, you end up breaking your own plans. When people say \"Was there any point in planning?\" it stings a little.", "karai": "You're fast at making schedules—and even faster at rewriting them."}, "ESTJ>ESFP": {"title": "A dependable rock who also knows how to make things fun.", "body": "Getting energy from people and valuing what's real in front of you is your core, in both your temperament and your character. On top of that, you have both the power to decide by logic and stick to the plan, and the brightness to read the room and make it fun. At a family birthday party, you run every bit of the prep—and on the day, you're the one singing the loudest. Your seriousness and your cheer both come alive in the same place.", "say": "\"Decorations done by three! …Hey, want to try making something out of these balloons?\"", "do": "After neatly splitting up the cleaning jobs, you put on music and get everyone dancing while you tidy up.", "worry": "The more you try to meet your responsibilities, the less room you have to be one of the people having fun. Choosing between making everyone happy and keeping things on track means the more fun the event, the more on edge you are.", "karai": "You play both hype person and MC, then totally burn out on the way home."}, "ESFJ>INTJ": {"title": "Someone who builds the road ahead with a caring heart and a forward-thinking mind.", "body": "Setting a course and moving forward steadily is your core, in both your temperament and your character. Layered on top, you have the warmth to bring a group together and the power to think deeply alone, an eye that values the facts in front of you and an eye that pictures future possibilities, a heart that reads feelings and a mind that decides by logic. You may look cool at first, but every plan you make has a touch of \"so no one gets left in a bind.\"", "say": "\"This is the most efficient way. …But I'll back you up until you get used to it.\"", "do": "While mapping out your family's future plans in a spreadsheet, you also make sure everyone's birthdays are on it.", "worry": "After you reach the logically right answer, you worry it might leave someone feeling lonely. Your days swing between wanting people and wanting to think alone, and you feel a little guilty every time you turn down an invite.", "karai": "Right after a cool-headed analysis, you check your phone three times to see how they reacted."}, "ESFJ>INTP": {"title": "Someone who uses answers worked out alone to help others.", "body": "You love quietly digging into ideas on your own, like an explorer of how things work. You also have a warmth that treasures the people around you and makes sure everyone feels at ease. That's why your thinking never ends in self-satisfaction—it always heads toward \"Will this help someone?\" Your sharp mind and your kindness are truly connected.", "say": "\"Logically, it works out like this… as long as it doesn't cause anyone trouble, that is.\"", "do": "Hearing that nobody can sort out a schedule, you quietly work out the best combination and then casually share it.", "worry": "You need your time to think alone, yet you can't say no when people count on you. After giving the right answer, some nights you can't sleep, wondering if you hurt the other person.", "karai": "That thing you said you \"don't care about\"? You're the one who's cared about it the longest."}, "ESFJ>ENTJ": {"title": "Someone who keeps the team close while pushing hard toward the goal.", "body": "Getting energy from people and moving forward with a plan is your core, in both your temperament and your character. On top of that, you have both the steadiness to value experience and facts and the vision to look far ahead, the heart to think of others' feelings and the power to decide by logic. Leading a team, you set big goals—and still remember everyone's birthday. You care about the numbers and the faces just as much.", "say": "\"This quarter, we're growing sales to here. …Oh, but first, let's all go grab lunch.\"", "do": "While drafting the plan for a big project, you've already booked the place for the wrap party.", "worry": "You want to settle things quickly, but if someone looks unhappy you can't push it through, and later you wish you'd been clearer. Chasing both results and being liked wears you out.", "karai": "Tough on targets, yet you spend an hour picking out snacks for the team."}, "ESFJ>ENTP": {"title": "Someone who keeps everyone entertained while firing off new ideas.", "body": "Getting more energized the more you're around people is your core, in both your temperament and your character. On top of that, you have it all: the steadiness to value experience and the spark of new ideas, kindness that honors feelings and a mind that thinks in logic, the knack for planning and the ease of switching gears on the spot. In discussions, you put everyone at ease while casually offering an idea nobody else thought of.", "say": "\"Great work, everyone! …Hey, I've got kind of a weird idea—can I run it by you?\"", "do": "Organizing a class reunion, you stick to the usual program—and somehow add a quiz contest.", "worry": "Torn between wanting to share your idea and not wanting to spoil the mood, you hesitate over when to speak up. Debates get so fun that after winning one, you lie awake worrying about the other person.", "karai": "You start arguing for their sake, and halfway through you're just enjoying the debate."}, "ESFJ>INFJ": {"title": "Someone who stays close to people's hearts and pictures their happiness down the road.", "body": "Valuing people's feelings and moving forward with a plan is your core, in both your temperament and your character. On top of that, you have both the power to draw energy from being with people and the power to quietly settle your heart alone, an eye for the facts in front of you and an eye that pictures someone's future. When a friend comes to you for advice, you help in practical ways—while also thinking, \"What would it take for this person to be smiling five years from now?\"", "say": "\"For now, let's go together tomorrow. …I really think there's a place out there that suits you even better.\"", "do": "Helping a friend with a job change, you gather job listings for them—and hand them a handwritten note of encouragement too.", "worry": "Because you want so much to help, you carry other people's worries as if they were your own. You love lively gatherings, yet you're puzzled by how suddenly you want to be alone once they end.", "karai": "You think so carefully about other people's futures, but your own next week is still blank."}, "ESFJ>INFP": {"title": "Someone with gentle thoughtfulness and a precious world all their own.", "body": "Deciding with people's feelings in mind is your core, in both your temperament and your character. Layered on top, you have the power to move within a group and the power to deepen your feelings alone, the steadiness of trusting experience and a sensitivity that lets your imagination grow, the knack for keeping things on track and the ease of going where your heart leads. You take good care of everyone, while holding close a precious dream you haven't shown anyone.", "say": "\"I made lunch for everyone. …While we eat, there's something I'd love to talk to you about.\"", "do": "After carefully managing the family schedule, you write long entries in your journal alone at night.", "worry": "When what others expect of you drifts a little from what you care about, it hurts whichever you choose. After going along with others, your feelings can't catch up unless you get some time alone.", "karai": "You tell everyone \"Do whatever you like,\" but can't say it to yourself."}, "ESFJ>ENFJ": {"title": "Someone who carries the smiles around them far into the future.", "body": "Getting energy from people, deciding with feelings in mind, and moving forward with a plan is your core, in both your temperament and your character. On top of that, you have both the steadiness to value the facts and experience right in front of you, and the power to believe in and picture the potential of people and things. In community activities, you run the yearly events with care—while thinking, \"What will it take for people to still gather in this town ten years from now?\"", "say": "\"Thanks for helping with the festival again this year! …Next year, I'd love to do something where the kids are the stars.\"", "do": "Taking on a role in the neighborhood kids' club, you organize last year's records while also writing a proposal for something new.", "worry": "You're so happy to do things for others that before you know it, you've taken on too many roles. Because you want so badly to meet everyone's expectations, you're hard on yourself when things don't go well.", "karai": "\"Don't overdo it\" is your catchphrase—yet you're the one overdoing it most."}, "ESFJ>ENFP": {"title": "Someone who cherishes people and adds new fun to every day.", "body": "Getting energy from people and deciding with feelings in mind is your core, in both your temperament and your character. Layered on top, you have the steadiness that comes from experience and excitement for new possibilities, the power to stick to a plan and the freedom to follow your whims. When friends get together, you've booked the usual spot—and on the way home you're already planting the next good time: \"Want to try that place next time?\"", "say": "\"I booked our usual place! …Oh, but did you know a new café opened by the station?\"", "do": "You keep up with every yearly tradition, and each time slip in one new game that surprises the family.", "worry": "Ideas keep popping up, but you also care about your responsibilities, so both end up feeling half-done. Trying too hard to make everyone happy, you push back the things you were looking forward to.", "karai": "Your planner is neatly written, but choosing the stickers for it takes the longest."}, "ESFJ>ISTJ": {"title": "Someone with real thoughtfulness and a meticulous way of working.", "body": "Valuing facts and experience and moving forward with a plan is your core, in both your temperament and your character. On top of that, you have both the brightness that warms a group and the focus to work quietly on your own, a heart that values feelings and a mind that judges by logic. At work you're trusted for your accuracy—and you're also the first to notice someone who's struggling and check in on them.", "say": "\"The documents are checked. …More importantly, you look pale—are you getting enough sleep?\"", "do": "After filing your expenses exactly by the rules, you quietly leave a throat lozenge on a coworker's desk.", "worry": "When following the rules clashes with helping the person in front of you, you agonize over it alone for a long time. You value your relationships, yet without quiet time alone you can't shake off the tiredness.", "karai": "People call you strict about the rules, but you're actually the easiest to sway with feelings."}, "ESFJ>ISFJ": {"title": "Someone who can support people both out loud and behind the scenes.", "body": "Relying on facts and experience, valuing people's feelings, and moving forward with a plan is your core, in both your temperament and your character. On top of that, you have both the power to light up when you're with people and the power to carefully set things in order alone. In front of everyone you keep things running with a smile, and behind the scenes you've handled all the little preparations without anyone noticing. You're a natural both in the spotlight and in a supporting role.", "say": "\"Thanks so much for coming, everyone! …Oh, if anyone's cold, I've got blankets ready.\"", "do": "Cheerfully hosting a welcome party at work, you've already asked the new hire which foods they don't like and adjusted the menu.", "worry": "Doing things for others has become so normal that you're slow to notice when you're tired. You're not good at saying no, and favors quietly pile up.", "karai": "You remember every single \"thank you\"—but can't remember the last day you took off."}, "ESFJ>ESTJ": {"title": "Someone who keeps things moving firmly while caring for everyone.", "body": "Getting energy from people, valuing facts, and moving forward with a plan is your core, in both your temperament and your character. On top of that, you have both a heart that values people's feelings and a straightforward way of deciding by logic. As a PTA officer, you'd end the meeting right on time—and afterward quietly check in with someone who didn't get a chance to speak. Your power to decide and your power to care always work side by side.", "say": "\"Then we'll go with this plan. …You were about to say something earlier, weren't you? I'd love to hear it.\"", "do": "After dividing up the housework fairly, you take over for whoever's worn out—\"just for today.\"", "worry": "After making the right call, you worry whether it hurt anyone. Depending on who you're talking to, you go back and forth between speaking frankly and speaking gently.", "karai": "Five minutes after a stern talk, you're running out to buy their favorite snack."}, "ESFJ>ESFJ": {"title": "Someone who has grown their gift for caring about people, straight and true.", "body": "Your temperament and character are the same, so caring about the people around you is your steady core. You get energy from people, learn from experience, and act in a thoughtful, organized way while honoring how others feel. With that natural thoughtfulness, you've warmed up every place you've been and brought people together. Because your way of being is so clear, you shine where you're appreciated—and wear down more than most in cold places.", "say": "\"Has everyone eaten? Let me know if you need more.\"", "do": "You have every friend's birthday on your calendar and never miss sending a message each year.", "worry": "Because you're so sensitive to how people react, even a slightly cold moment stays on your mind all day. Often, what tires you out isn't your own weakness—it's being somewhere your kindness doesn't come back to you.", "karai": "You remember everyone's favorite drink, and forget to order your own."}, "ESFJ>ISTP": {"title": "Someone with the care to bring people together and the knack for quietly fixing things alone.", "body": "Valuing the facts and experience in front of you is your core, in both your temperament and your character. On top of that, you have it all: the brightness that warms a group and the focus to work with your hands alone, a heart that stands by people and a mind that thinks in logic, the comfort of deciding ahead and the ease of handling things on the spot. When a friend is in trouble, before offering comforting words, you've already started fixing their broken bike.", "say": "\"You okay? …Here, let me see. I think if I adjust this bit, it'll work.\"", "do": "You were chatting with everyone at a family gathering, and suddenly you're alone in the kitchen fixing a leaky faucet.", "worry": "Wanting to be close to people and wanting to do your own thing take turns, so even you can't predict your mood swings. Putting feelings into words feels awkward, so you worry whether what you showed through actions came across.", "karai": "When someone says \"thank you,\" you get shy and change the subject to tools."}, "ESFJ>ISFP": {"title": "Someone with gentle thoughtfulness and a comfort zone all their own.", "body": "Valuing what's real in front of you and deciding with people's feelings in mind is your core, in both your temperament and your character. On top of that, you have both the brightness to move among people and the calm to savor time alone, the knack for keeping things on track and the ease of moving with your mood. You're great at looking after everyone, and you also treasure time surrounded by your favorite scents and music more than anything.", "say": "\"Everything's ready, so don't worry. …Once it's over, I'm going to sneak off for a little tea by myself.\"", "do": "When you invite friends over, you plan the menu well in advance—but pick the table flowers on the day, by mood.", "worry": "Going along with others, there are moments when you lose track of what you even like. You want to plan things properly, but if you're not in the mood that day you can't get moving, and you blame yourself.", "karai": "Your plans for others are packed; your plans for yourself are \"if I feel like it.\""}, "ESFJ>ESTP": {"title": "Someone who cares about everyone and moves fast when it really counts.", "body": "Getting energy from people and valuing the facts in front of you is your core, in both your temperament and your character. Layered on top, you have a heart that values people's feelings and a no-nonsense way of deciding by logic, the power to make plans and the quick reflexes to read the flow and act. When trouble hits on a trip, you calm everyone down and find another way to get there right away.", "say": "\"Everyone okay? …Right, if the trains are stopped, let's call two cabs. Now.\"", "do": "You'd been preparing an event step by step, then saw the rain on the day and switched to an indoor venue right away.", "worry": "Wanting to act out of kindness clashes with wanting to decide quickly and efficiently, so you're careful your words don't come out harsh. You go back and forth between keeping the plan or changing it on the spot, and it lingers a bit even after you decide.", "karai": "While worrying about everyone, you're secretly itching to move on to the next thing."}, "ESFJ>ESFP": {"title": "Someone who cares for everyone and enjoys the moment to the fullest.", "body": "Getting energy from people, valuing what's real in front of you, and deciding with your heart is your core, in both your temperament and your character. On top of that, you have both the power to plan ahead and the lightness to go with the mood and have fun. When hanging out with friends, you've handled the bookings and messages—and on the day, you're the one suggesting a spontaneous detour and laughing the hardest.", "say": "\"I booked the restaurant for six! …But before that, want to stop by that crêpe place?\"", "do": "At your kid's sports day, you've got the lunch and picnic blanket perfectly ready—and you're also the loudest one cheering.", "worry": "Torn between wanting to prepare properly and wanting to enjoy the moment, you feel a little unsettled whichever you pick. You put everyone else's fun first so much that only later do you realize you didn't get your own fill.", "karai": "You're the organizer, yet you're having the most fun—and almost leave without settling the bill."}, "ISTJ>INTJ": {"title": "Someone with both steady groundwork and a mind that looks ahead.", "body": "Taking time to think on your own, deciding with clear logic, and moving forward with the big picture in view — this is your core, in both your temperament and your character. On top of that, you have the steadiness to check facts and experience one by one, and the power to imagine possibilities that haven't taken shape yet. You can study past records closely and still picture where things will be years from now, so you really shine when you're trusted with long-term plans.", "say": "\"Here's how last year's numbers looked. …So three years from now, I'd like things to be different.\"", "do": "You've kept years of household budgets, and built your own plan from them all the way to retirement.", "worry": "Deciding whether to stick with the usual way or switch to something new can take you a long time. With caution and foresight both at work, your head is always a little busy.", "karai": "Your plan for the next ten years is flawless. Tonight's dinner? Still undecided."}, "ISTJ>INTP": {"title": "Someone who values clear logic and still keeps the freedom to think.", "body": "Recharging in time alone and judging things by logic — this is your core, the same in your temperament and your character. Beyond that, you have both: the solid habit of stacking up facts and the curiosity to chase a spark, the discipline to follow set steps and the flexibility to rethink on the spot. You research carefully before you act, yet along the way you wander off to a new question and come back with an answer no one expected.", "say": "\"Yes, these steps are correct. …But why are we doing them this way in the first place?\"", "do": "You meant to read the manual line by line, and somehow you're now researching how the whole product works.", "worry": "Wanting to follow the rules and wanting to try a better way can collide, and your hands stop. Thinking is so fun that the panic tends to hit right before the deadline.", "karai": "Your research detours run so long it takes five minutes to remember what you were looking up."}, "ISTJ>ENTJ": {"title": "Someone with quiet reliability and the drive to lead others.", "body": "Deciding with clear logic and moving things forward with a plan in view — this is your core, in both your temperament and your character. On top of that, you have the calm to focus and recharge alone and the energy to get a room moving, an eye for solid facts and the vision to set big goals. In meetings you've read the materials more closely than anyone, and in the end you're the one who says, \"Okay, here's how we'll do it\" — and takes charge.", "say": "\"I've checked every number. …So next term, let's aim much higher.\"", "do": "You fire up the team around a shared goal, then go home and quietly update the progress chart by yourself.", "worry": "Because people see you as dependable, your own time to rest alone keeps getting pushed back. You also go back and forth between playing it safe and going bold.", "karai": "The person who said \"Let's all work on this together\" is the one carrying the most alone."}, "ISTJ>ENTP": {"title": "Someone who tests new ideas, one after another, on solid ground.", "body": "Thinking things through with logic before deciding — this is your core, the same in your temperament and your character. Beyond that, you have both sides of almost everything: the calm you find alone and the energy you get from talking with people, a careful trust in facts and ideas that open up possibilities, the steadiness to follow a plan and the lightness to change course on the spot. You keep pitching fresh projects while quietly double-checking that nothing has slipped through the cracks.", "say": "\"What about this? Isn't it fun? …Oh, and I already worked out the budget.\"", "do": "An idea pops up in casual chat, and by that night you've put it in a spreadsheet to see if it can actually work.", "worry": "You come up with so much that it's tiring to narrow down what to commit to. The gap between days you love a lively crowd and days you don't want to talk to anyone is big, and it throws even you off.", "karai": "You start a debate on purpose, then spend the walk home fact-checking your own arguments."}, "ISTJ>INFJ": {"title": "Someone who stands by others' feelings with sincere, careful steps.", "body": "Settling your heart in time alone and moving forward with a plan in view — this is your core, in both your temperament and your character. On top of that, you have the steadiness to check facts and the sense to feel the meaning beneath things, the calm of logic and the kindness that cares about how others feel. When someone comes to you for advice, you first sort out the situation carefully, then gently shed light on what they truly want deep down.", "say": "\"Okay, I understand the situation. …So, what do you want to do?\"", "do": "While listening to a friend's problem, you're mapping out the steps to solve it and the order of the words you'll say, both at once.", "worry": "When the right answer and the kind answer aren't the same, choosing between them can keep you up at night. You prepare so much for others that sharing your own feelings gets pushed to last.", "karai": "You're great at tidying up other people's hearts, but yours is covered in sticky notes."}, "ISTJ>INFP": {"title": "Someone with firm footing who still listens to their heart.", "body": "Recharging in time alone — this is your core, the same in your temperament and your character. Beyond that, you have both: steadiness that trusts experience and a rich imagination, calm logic and kindness that values feelings, sincerity that keeps plans and softness that goes with the flow. You get your to-dos done properly, and when something moves your heart, you pour yourself into it completely. Yours is a quiet kind of passion.", "say": "\"I'll finish everything I need to. …But this one thing, I just can't let go of.\"", "do": "You write in your journal at the same time every day, and now and then slip in a poem no one will ever see.", "worry": "\"I should do this properly\" and \"I want to do it my way\" come up at the same moment, and you can't fully commit to either. On days when your head agrees but your heart won't follow, you tend to blame yourself.", "karai": "You say you want to live freely — in a plan that runs three pages."}, "ISTJ>ENFJ": {"title": "Someone who warmly brings people together with solid planning.", "body": "Planning ahead and following through properly — this is your core, in both your temperament and your character. On top of that, you have the calm to focus alone and the brightness to shine among people, an eye that checks facts and a heart that believes in possibilities, cool-headed logic and the kindness to sense how others feel. You're great at cheering people on and helping them move forward, and your words are backed by real research and preparation.", "say": "\"Don't worry, you can do this. …Oh, and here's a note with the steps, just in case.\"", "do": "You give a heartfelt welcome speech for the new team members, then balance the dinner bill down to the last cent.", "worry": "The harder you try to meet everyone's hopes, the less quiet time you get alone. It's also easy to get stuck on where to draw the line between putting feelings first and sticking to the rules.", "karai": "You're amazing at encouraging others, but the only pep talk you give yourself is \"Not good enough yet.\""}, "ISTJ>ENFP": {"title": "Someone who turns free ideas into something real that lasts.", "body": "You're full of sparks, love having fun with people, and bring bright ideas to the table. You also have the sincerity to keep your word and build up something solid, step by step. That's why your ideas don't stay just ideas: you start things joyfully and actually keep them going. People around you often find you surprisingly dependable.", "say": "\"This is going to be so fun, trust me! …I'll just check my notes from last time, though.\"", "do": "You jumped into a new hobby on a whim, and somehow you're the one who's kept it up the longest, every single week.", "worry": "New things excite you, but when change keeps coming, tiredness hits suddenly. After acting on impulse, you sometimes scold yourself with \"I should've been more careful.\"", "karai": "You say you decided \"just for fun,\" yet your prep afterward is the most thorough of anyone's."}, "ISTJ>ISTJ": {"title": "Someone who has steadily grown the strength to see things through.", "body": "The temperament you were born with and the character you've grown share the same type. Keeping promises, checking facts one by one, and seeing what you've decided all the way through — that sincerity has grown straight and true since childhood. Because your strengths are so clear, you do your best work where steps and procedures matter, and you can feel worn out, without knowing why, in places where everything is decided on a whim.", "say": "\"Let me check the notes from last time, and I'll get back to you.\"", "do": "You arrive ten minutes early to meet up, and you've already looked up the train home.", "worry": "Sudden changes of plan or vague instructions, one after another, wear you out badly. That tiredness usually isn't a weakness in you; it comes from being stuck with a way of working that doesn't fit you.", "karai": "The moment someone says \"Just play it by ear,\" you start writing a manual for it."}, "ISTJ>ISFJ": {"title": "Someone who supports the everyday lives around them with care and precision.", "body": "Recharging in time alone, trusting experience and facts, and moving forward with a plan in view — this is your core, in both your temperament and your character. On top of that, you have both the logic to judge things fairly and the warmth to care about how people feel. Your work is accurate and complete, and you quietly lend a hand to anyone who's struggling, so at work and at home people say, \"It's such a relief when you're around.\"", "say": "\"One of the dates on this form was off. …Oh, I went ahead and fixed it for you.\"", "do": "You keep the team schedule perfectly accurate, and quietly lighten the load for anyone who seems unwell.", "worry": "When something true needs to be said, worry about hurting someone can make you swallow your words. As you take on every request properly, your own breathing room slowly disappears.", "karai": "You fix other people's mistakes so quietly that they never find out they made one."}, "ISTJ>ESTJ": {"title": "Someone who rallies people and moves them forward with solid planning.", "body": "Trusting facts, deciding with logic, and sticking to the plan — this is your core, in both your temperament and your character. On top of that, you have both the calm to recharge slowly on your own and the power to stand up in front of people and get everyone moving. You prepare for meetings quietly by yourself, then run the real thing with confidence, so people rely on you: \"If they're in charge, it'll all work out.\"", "say": "\"Today we'll cover these three things. …Afterward, I'll need a little quiet time to sort my thoughts.\"", "do": "You run the neighborhood event without a hitch, then go home and write down what to improve in a notebook, without talking to anyone.", "worry": "The more people count on you, the more you're out in front, and your quiet time alone keeps shrinking. On days you've been too strict with someone careless, you quietly reflect on it later.", "karai": "You tell everyone \"Rest is part of the job,\" but there's not a single day off on your own calendar."}, "ISTJ>ESFJ": {"title": "Someone who adds human warmth to well-organized plans.", "body": "Valuing experience and facts and moving forward with a plan in view — this is your core, in both your temperament and your character. On top of that, you have the calm to think quietly alone and the brightness that comes alive around people, cool-headed logic and caring warmth. When planning a get-together, you nail down the schedule and budget, and still pay close attention so that every single person feels at ease.", "say": "\"The plan for the day is final. …Oh, and Sam doesn't do spicy food, right?\"", "do": "At a family gathering, you make a seating chart so the relatives who don't get along won't end up side by side.", "worry": "While looking after everyone, your time alone vanishes, and suddenly you're drained. You also get caught between wanting people to follow the rules and not wanting to blame anyone.", "karai": "You know everyone's food likes and dislikes, but when someone asks what you want to eat, you can't answer."}, "ISTJ>ISTP": {"title": "Someone with both steady methods and quick, flexible responses.", "body": "Valuing time alone, relying on facts, and thinking things through logically — this is your core, in both your temperament and your character. On top of that, you have both the ability to plan ahead and move steadily, and the ability to read the moment and change your approach. When trouble hits, you stay calm, fix it fast with whatever's at hand, and then set things up so it won't happen again.", "say": "\"That'll do for now — it's fixed. …I'll update the instructions so it doesn't happen again.\"", "do": "You quickly fix a broken piece of furniture with your own tools, and order spare parts that same night.", "worry": "Some days you want to stick to the plan, and some days you want to go with your mood, so even you find your pace hard to read. You don't like being tied down by rules, yet without any, you feel uneasy.", "karai": "You say \"It'll work out somehow,\" while carrying a backup for your backup."}, "ISTJ>ISFP": {"title": "Someone whose careful handiwork carries a gentle, artistic touch.", "body": "Recharging in time alone and treasuring the facts and textures right in front of you — this is your core, in both your temperament and your character. On top of that, you have cool-headed logic and kindness that values feelings, sincerity that keeps plans and softness that follows the moment. When you cook or make things by hand, you follow exact amounts and steps, and still naturally add your own taste and a feel for the season.", "say": "\"I made it just like the recipe. …But it's cold today, so I added a little ginger.\"", "do": "You clean your room on the same day every week, without fail, and finish by setting out a single seasonal flower.", "worry": "\"I should do this properly\" and \"I want to go at my own pace\" both live in you, and some days you feel stuck in between. Putting your feelings into words isn't easy, and it's frustrating when they don't come across.", "karai": "Even on the days off you meant to spend lazily, your schedule fills up with laundry and grocery plans."}, "ISTJ>ESTP": {"title": "Someone who can both jump into action and prepare with care.", "body": "Relying on the facts in front of you and judging with logic — this is your core, in both your temperament and your character. On top of that, you have the calm to prepare on your own and the drive to dive in among people, the caution to stick to a plan and the agility to switch gears in a flash. When it counts, you're the first to move, and your call is backed by the experience and research you've built up all along.", "say": "\"Okay, let's go right now! …Oh, and I already checked a rainy-day route, just in case.\"", "do": "At a barbecue you and your friends threw together on a whim, you somehow showed up with a first-aid kit and extra charcoal.", "worry": "Wanting to just go for it and wanting to prepare so nothing goes wrong can collide, and you get tired before you've even decided. After a lively time with others, you're thrown off if you don't get some quiet time alone.", "karai": "You say \"Momentum is everything,\" but you've checked in advance how to build the momentum."}, "ISTJ>ESFP": {"title": "Someone with steady footing who enjoys the here and now.", "body": "Valuing the facts in front of you and what you've actually experienced — this is your core, in both your temperament and your character. Beyond that, you have both: the calm you find alone and the brightness that lights up a crowd, cool-headed logic and kindness that values feelings, sincerity that keeps plans and the lightness to enjoy the moment. You liven things up, yet you keep track of what matters, like what time to head home and who owes what, so people feel safe having fun with you.", "say": "\"Today is so much fun! …Okay, the last train is at 11:12, so we should start heading out.\"", "do": "You were the life of the karaoke party, yet ten minutes before the end you'd already split the bill for everyone.", "worry": "The more fun you've had, the more you need time alone afterward, and the size of that gap surprises even you. You want to just enjoy yourself, but you can't help thinking ahead and weighing the costs.", "karai": "You were the wildest one there, and on the way home you're already checking tomorrow's schedule."}, "ISFJ>INTJ": {"title": "Someone with gentle thoughtfulness and a clear eye on the future.", "body": "Settling your heart in time alone and moving steadily with a plan in view — this is your core, in both your temperament and your character. On top of that, you have an eye for the facts and experience close at hand and the power to picture possibilities not yet visible, the kindness to sense others' feelings and the ability to judge calmly with logic. Because you care about people, you can quietly make long-range plans so that they won't struggle years from now.", "say": "\"With that plan, I think you'll hit trouble in six months. …I don't want things to get hard for you, so I'm saying it now.\"", "do": "You remember every family member's birthday, and you've made a chart of anniversaries and savings for the next ten years.", "worry": "Even when you're sure your view is right, thinking about the other person's feelings means it takes you a while to say it. You think so far ahead that you can miss the fun right in front of you.", "karai": "You spend three days rewording one tough-love comment into the gentlest version possible."}, "ISFJ>INTP": {"title": "Someone with warm thoughtfulness and a free, curious mind.", "body": "Recharging in time alone — this is your core, the same in your temperament and your character. Beyond that, you have both: steadiness that trusts experience and curiosity that chases new ideas, kindness toward others and the cool logic to think things all the way through, the habit of preparing properly and the flexibility to rethink when a new thought strikes. You start researching because you want to help someone, and before you know it, you understand how it works better than anyone.", "say": "\"You seemed stuck, so I looked into it. …By the way, the way this works is really fascinating.\"", "do": "You set out to fix a friend's glitchy laptop, and you're still digging into the cause at midnight.", "worry": "Sometimes you hold back an answer you reasoned out, worried it might hurt someone. When you get absorbed in thinking, you forget the errand you were asked to do, and feel down about it later.", "karai": "The research you started for someone else has quietly turned into your new hobby."}, "ISFJ>ENTJ": {"title": "Someone with a caring heart who leads from the front.", "body": "Planning ahead and following through properly — this is your core, in both your temperament and your character. On top of that, you have the calm to settle things quietly alone and the drive to stand in front, an eye that values the facts close at hand and the vision to set big goals, kindness that looks out for others and the strength to decide with logic. Even after making a tough call, you can casually check in with each person afterward. You're a leader who really looks after people.", "say": "\"This is the direction we're going. I'm open to input. …Oh, and thanks for staying late yesterday.\"", "do": "You give clear directions in the meeting, then hand out snacks to anyone who looks tired afterward.", "worry": "After saying clearly what needs to be decided, you worry alone: \"Did that sound too harsh?\" The more you take the lead, the less quiet time you get to rest.", "karai": "The same night you gave orders like a pro, you're holding a review meeting in bed about how you said them."}, "ISFJ>ENTP": {"title": "Someone whose bold ideas grow from kindness toward others.", "body": "You question the usual way of doing things, love dreaming up new approaches, and think fast. You also have the kindness to quietly support the people close to you and to keep your promises. That's why your debates and ideas aren't about tearing things down; they're about making life easier for someone. Even while chatting up a storm, you're still keeping an eye on how everyone is doing.", "say": "\"What if we flipped that assumption? Wouldn't that be fun? …Oh, but if you're tired, we can do it another time.\"", "do": "After pitching a bold idea in a meeting, you quietly help out the person who's swamped with preparing the slides.", "worry": "Speaking your mind is fun in the moment, but afterward you replay it again and again: \"Did I go too far?\" You swing between wanting to try new things and wanting to keep the comfort of what you know.", "karai": "Even in full debate mode, you never forget to check the other person's face."}, "ISFJ>INFJ": {"title": "Someone who gently cares and even pictures others' futures.", "body": "Settling your heart in time alone, valuing people's feelings, and moving forward with a plan in view — this is your core, in both your temperament and your character. On top of that, you have both the ability to notice small, real changes right in front of you and the sense to feel the deeper meaning and possibilities behind things. You quickly notice when someone is struggling, and you think about how they can move forward from here, staying gently by their side.", "say": "\"You've seemed a bit down lately. …Let's take our time and think about what you want next, together.\"", "do": "After listening to a friend, you pick out a book that might suit them and hand it over with a handwritten note.", "worry": "Because you think so deeply about others, you end up carrying their worries as if they were your own. When you feel the gap between ideals and reality, it seems like your own failing, and you get down.", "karai": "You can advise someone on their life ten years out, but you can't decide on your own plans for this weekend."}, "ISFJ>INFP": {"title": "Someone who spreads kindness with free imagination.", "body": "Recharging in time alone and making decisions with feelings in mind — this is your core, in both your temperament and your character. On top of that, you have steadiness that values experience and facts and the imagination to picture what doesn't exist yet, the ability to plan and follow through and the softness to move with your heart. You care deeply about people, and you can put that care into your own personal form, like a letter or something you've made.", "say": "\"I'll have everything ready. …And I also wrote you a letter, from the heart.\"", "do": "You get the birthday present ready early, then the day before, a sudden idea has you adding a handmade card.", "worry": "It's easy to get stuck between wanting to do things properly for others and wanting to pour yourself into what moves your heart. Small words can hurt you easily, and you keep it all inside without telling anyone.", "karai": "Your planner is packed with plans, and every bit of empty space is filled with doodles."}, "ISFJ>ENFJ": {"title": "Someone who guides people forward with fine-tuned care.", "body": "Valuing others' feelings and moving forward with a plan in view — this is your core, in both your temperament and your character. On top of that, you have the calm to recharge quietly alone and the brightness that comes alive among people, the sharp eye to notice the facts in front of you and the wide view that believes in people's potential. You notice the small changes in each person while showing everyone where to head together, so people naturally ask you to take the lead.", "say": "\"Let's all give it a try together! …Oh, you seemed worn out yesterday. Are you okay today?\"", "do": "You talk passionately about the club's goals, then message each person who couldn't make it to fill them in on the day.", "worry": "The more you do for everyone, the less quiet time you have alone, and by the time you notice, you're completely exhausted. You want so much to meet expectations that saying \"I can't\" is hard for you.", "karai": "You take perfect care of everyone's feelings, and you're always the very last to notice you're tired."}, "ISFJ>ENFP": {"title": "Someone with kindness at the core who connects with people brightly and freely.", "body": "Making decisions with people's feelings in mind — this is your core, in both your temperament and your character. Beyond that, you have both: the calm you find alone and the energy to have fun with others, steadiness that trusts experience and the freedom to chase a spark, sincerity that keeps plans and the lightness to enjoy the flow of the moment. You invite people on a whim and create happy times, while quietly making sure no one gets left behind.", "say": "\"Hey, how about a picnic with everyone? …Oh, I'll think of a backup spot in case it rains.\"", "do": "You start a new hobby in the heat of excitement, and make a practice schedule so you'll keep it up.", "worry": "The gap between days you want to be around people and days you don't want to see anyone is big, and others easily misunderstand you. You swing between wanting to dive into new things and wanting the comfort of familiar places.", "karai": "It was supposed to be a spur-of-the-moment invite, but you're the one doing the most careful planning."}, "ISFJ>ISTJ": {"title": "Someone who turns care into something real through solid rules.", "body": "Recharging in time alone, trusting experience and facts, and planning things out properly — this is your core, in both your temperament and your character. On top of that, you have both the kindness to sense how others feel and the cool head to judge fairly with logic. You stick to rules and promises firmly, and still explain the reasons carefully so others can accept them, so people feel warmth even in your strictness.", "say": "\"Please keep to the deadline. …If you're not feeling well, let me know early and we'll adjust.\"", "do": "You write up the workplace rules properly, and make a separate, easy-to-follow illustrated version for new hires.", "worry": "In moments when you have to decide fairly, picturing someone's disappointed face makes you hesitate. After pointing out a problem, you keep wondering whether you went too far.", "karai": "You're strict about the rules, but the moment someone's in trouble, you start drafting the exception process yourself."}, "ISFJ>ISFJ": {"title": "Someone who has grown the strength to support others, straight and true.", "body": "The temperament you were born with and the character you've grown through experience share the same type. The kindness to notice changes in people and quietly reach out a hand has grown steadily since you were a child. Because your strengths are so clear, you do your best in places that fit you, and in places that don't, you can get tired without knowing why.", "say": "\"Are you okay? Want me to take care of that for you?\"", "do": "You remember everyone's favorites, so each person gets a different treat when you bring snacks.", "worry": "You can't say no when asked, and before you know it, your own plans have slid to the very end of the line. More often than not, the cause of your tiredness isn't you; it's an environment that doesn't fit.", "karai": "You remember everyone's birthday, but forget your own days off."}, "ISFJ>ESTJ": {"title": "Someone who turns a caring nature into dependable action.", "body": "Valuing experience and facts and moving things forward with a plan in view — this is your core, in both your temperament and your character. On top of that, you have the calm to recharge quietly alone and the ability to stand up and bring people together, the kindness to care about feelings and the clear judgment to decide with logic. You run things in your community or workplace briskly, and still take each person's circumstances into account.", "say": "\"That settles who does what. …Oh, if you have little kids, just the morning is fine.\"", "do": "You run the school parents' meeting smoothly, then drop off the handouts at the homes of people who couldn't come.", "worry": "The more briskly you decide, the more you worry people might think you're harsh. As you take on more roles people rely on, your time to rest alone disappears, and tiredness hits all at once.", "karai": "You tell everyone \"Don't overdo it,\" then sign yourself up for two shifts."}, "ISFJ>ESFJ": {"title": "Someone who connects people with gentle thoughtfulness.", "body": "Relying on experience, deciding with feelings in mind, and moving forward with a clear plan — this is your core, in both your temperament and your character. On top of that, you have both the ability to settle your heart quietly alone and the ability to warm up a room full of people. At gatherings, you naturally become the one looking after everyone, and a little downtime at home is all it takes to recharge.", "say": "\"I'm so happy you all came! …I'll go grab more tea.\"", "do": "You volunteer to organize the class reunion and prepare everything yourself, from RSVPs to name tags on the day.", "worry": "You love seeing people, but when plans pile up, you suddenly don't want to talk to anyone. That switch can confuse you, and sometimes you wonder, \"Am I just bad with people?\"", "karai": "As the organizer, you looked after everyone more than anyone did, and didn't eat a single bite yourself."}, "ISFJ>ISTP": {"title": "Someone who quietly solves problems with kind, skillful hands.", "body": "Recharging in time alone and treasuring the facts and textures right in front of you — this is your core, in both your temperament and your character. On top of that, you have kindness that thinks of others and the ability to think calmly with logic, the habit of preparing properly and the ability to respond nimbly on the spot. You may not say much, but when someone's in trouble, your hands get to work and the problem is fixed before anyone knows it. You're someone people can count on.", "say": "\"Here, let me see that. …There, it's fixed. Let me know if anything else comes up.\"", "do": "You fix a friend's bike chain right on the side of the road, and check the brakes while you're at it.", "worry": "Your hands move before your words do, so your kindness doesn't always come across. Caught between sticking to the plan and going with your mood, you can easily lose your own pace.", "karai": "\"It was nothing,\" you say, while carrying three different tools for the repair."}, "ISFJ>ISFP": {"title": "Someone who shares kindness in a natural, easygoing way.", "body": "Settling your heart in time alone, valuing the facts in front of you, and deciding with feelings in mind — this is your core, in both your temperament and your character. On top of that, you have both the ability to prepare ahead and follow through and the ability to move softly with your mood and the flow of the moment. Without getting stuck on how things \"should\" be done, you can gently reach out to the people close to you in the way that suits them best.", "say": "\"Let's go shopping as planned today. …But it's so nice out — want to take a little detour?\"", "do": "Visiting a sick friend, you bring the gift you'd planned plus a single flower you spotted on the way.", "worry": "Because you often go along with others, it's easy to put what you want last. Even when you've made a plan, you feel a bit unsettled if it doesn't match your mood that day.", "karai": "You say \"Anything's fine,\" but you already know exactly which place you want to go."}, "ISFJ>ESTP": {"title": "Someone with a caring nature and the drive to act on the spot.", "body": "Valuing the facts in front of you and real experience — this is your core, in both your temperament and your character. Beyond that, you have both: the calm you find alone and the drive to dive in among people, kindness toward others and the ability to make clear-cut calls, careful preparation and the speed to act in the moment. When trouble hits, you're the first to rush in and get moving, and afterward you stay right beside anyone who's feeling down.", "say": "\"Don't worry, I'm on it — leave it to me! …So, are you hurt? Need some water?\"", "do": "Helping a friend move, you carry the heaviest boxes of anyone, and still remember what everyone likes to drink.", "worry": "After charging ahead, you start wondering if you put a burden on someone, and you mull it over alone. When the lively times go on and on, you suddenly want to be by yourself.", "karai": "You threw yourself into it harder than anyone, then went home wondering, \"Was I too pushy?\""}, "ISFJ>ESFP": {"title": "Someone who makes people smile with kindness and cheer.", "body": "Valuing the facts in front of you and deciding with feelings in mind — this is your core, in both your temperament and your character. On top of that, you have the calm to recharge quietly alone and the brightness that shines in a crowd, careful preparation and the lightness to enjoy the moment. You get everyone laughing and having fun, and you still notice the person sitting quietly in the corner and say hello. You're a truly warm person.", "say": "\"Let's have the best time today! …Oh, is it cold over there? I've got a blanket.\"", "do": "You lead the fun at the party, with bandages and stomach medicine tucked secretly in your bag.", "worry": "You want so much for everyone to have fun that when the mood dips even a little, it feels like your fault. The more you've laughed in a day, the more you need time alone that night to shake off the tiredness.", "karai": "The one who partied hardest is in the taxi home, checking that nobody left anything behind."}, "ESTP>INTJ": {"title": "You read the winning path while on the move, and plan many steps ahead.", "body": "Deciding things with clear logic is your core, in both your temperament and your character. On top of that, you get energy from jumping in with people and also from quietly thinking things through alone. You can grab the facts in front of you and read the possibilities ahead. You can move lightly in the moment and also stick with a long plan. You take what you learn out in the field and turn it into a strategy that looks years ahead.", "say": "\"I'll just go check it out first. …When I'm back, I'll turn it into a three-year plan.\"", "do": "On the way home from a free trial at a new gym, you've already mapped out six months of workouts in your head.", "worry": "You want to act and you want to plan, both strongly, so sometimes you can't decide when to start. Being with people is fun, but if you don't get time alone to think afterward, the tiredness doesn't go away.", "karai": "You say \"I just went with my gut,\" but everyone knows you'd already planned three moves ahead."}, "ESTP>INTP": {"title": "You use both street-smart instinct and a mind that thinks things all the way through.", "body": "Thinking with logic and moving flexibly with the situation are your core, in both your temperament and your character. Added to that, you recharge both by hanging out with people and by sinking into your thoughts alone. You trust the facts you can touch, and you're curious about the \"why\" behind how things work. You're the kind of person who takes apart a broken gadget and ends up talking about how it works all night.", "say": "\"Let's just open it up. …Oh, wait, this mechanism is actually really cool.\"", "do": "On a trip with friends, you skip the famous local food because you can't stop staring at how an old water wheel works.", "worry": "You go out the moment someone invites you, then feel drained on the way home because you didn't get enough time alone. You love thinking so much that sometimes you're satisfied with the idea in your head before you even start.", "karai": "You head out \"to have fun\" and spend the whole time figuring out how something works."}, "ESTP>ENTJ": {"title": "You take the path you opened with sheer momentum and grow it into a big plan.", "body": "Getting energy from people and deciding with logic are the same in your temperament and your character. Added to that, you can grab the facts in front of you fast and also picture what's possible ahead. You can react on the spot and also work backward from the goal to set up the steps. You're the one at the front of the team putting out fires, while quietly getting the next move ready.", "say": "\"So three of us can move right now. …And next year, let's take this nationwide.\"", "do": "When someone suddenly can't make it, you're the first to fill the gap, and by that night you've proposed a system so it never happens again.", "worry": "The more you look ahead, the harder it is to resist jumping at the fun thing right in front of you. Other people's pace can feel slow, so you end up pulling everyone along by yourself.", "karai": "By the time you say \"Let's decide together,\" you've already decided."}, "ESTP>ENTP": {"title": "You turn real-world experience into one new idea after another.", "body": "Getting energy from people, thinking with logic, and moving with the situation are your core, in both your temperament and your character. On top of that, you can stand firmly on solid facts and also look toward things no one has tried yet. You think about \"what will actually happen\" and \"how could this be more fun\" at the same time. That's why you're the one with the most ideas in any meeting.", "say": "\"Last time we did this, it really brought people in. …But what if we flipped it? Wouldn't that be even better?\"", "do": "For the school festival, you pull out last year's sales records and pitch three brand-new ideas.", "worry": "You want to try every idea you have, so you end up with too many things started. When a debate gets heated, you win the argument and then feel a little awkward.", "karai": "Your \"I was just thinking…\" usually lasts about thirty minutes."}, "ESTP>INFJ": {"title": "You can turn deep insight into action without hesitating.", "body": "Day to day, you're a thoughtful person who looks closely at what's in people's hearts and what things really mean. But once you see it, you don't stop there. The moment you feel \"now,\" your body moves, with lightness and nerve. You're not just a thinker, and not just a doer. You see what matters before others notice, and take the first step while everyone else is still unsure.", "say": "\"I just have a feeling they're having a hard time. …Okay, I'm going to go see them now.\"", "do": "After thinking about a job change for weeks, you wake up one morning, decide \"today's the day,\" and get moving that same day.", "worry": "You want to think things through and you want to act right away, both at once, so sometimes neither feels finished. You see people's feelings so clearly that you're worn out after you act.", "karai": "You say \"I want to think it over carefully,\" but you've usually already signed up."}, "ESTP>INFP": {"title": "You move lightly and quickly, carrying a gentle heart with you.", "body": "Moving flexibly with the situation is your core, in both your temperament and your character. Added to that, you get energy from people and also from quietly holding your feelings close. You trust solid facts and you love to imagine. You can decide calmly with logic, and you care deeply about feelings. You act the moment an idea hits, yet there's always \"for someone\" or \"for something I care about\" behind it.", "say": "\"I can go right now! …I just don't want to do anything she'd hate, though.\"", "do": "The same day you hear a friend is struggling, you buy what they need and drop it off at their door.", "worry": "You can act boldly, but when you do something that doesn't fit your heart, it slowly starts to hurt later. On days you've spent going along with others, you need time alone to settle your feelings.", "karai": "You say \"It didn't mean anything,\" but what you do usually means a lot."}, "ESTP>ENFJ": {"title": "You have in-the-moment drive and an eye for helping people grow.", "body": "Getting energy from people is your core, in both your temperament and your character. Added to that, you can see facts quickly and also believe in what people and things could become. You decide calmly with logic and care warmly about feelings. You can react on the spot and also plan ahead to keep things moving. On a team, you brighten the mood and still keep an eye on how each person is growing.", "say": "\"Let's go all out at practice today! …And after, let's talk one-on-one.\"", "do": "You turn a younger teammate's mistake into a laugh on the spot, then later quietly share a tip to get it right.", "worry": "The more you act for everyone else, the more your own wishes get pushed back. Even when you want to decide quickly, you wait for others' feelings, and your decision gets delayed.", "karai": "You give advice to everyone and have no one to go to yourself."}, "ESTP>ENFP": {"title": "You use real action to spread new ideas and bring people together.", "body": "Getting energy from people and moving lightly with the situation are the same in your temperament and your character. On top of that, you trust the facts in front of you and get excited about what hasn't happened yet. You decide calmly with logic and care warmly about feelings. You don't just talk about ideas. You say \"Let's try it tomorrow\" and actually get people together.", "say": "\"That would be so much fun! …Okay, I'll lock in the place and the headcount.\"", "do": "Someone at dinner says \"We should take a trip sometime,\" and by the next morning you've made a group chat with dates.", "worry": "There's so much fun stuff that your schedule and energy are always stretched to the limit. Even when you want to decide with logic, you picture someone's disappointed face and hesitate.", "karai": "You don't allow \"someday,\" so your friends' jokes usually come true."}, "ESTP>ISTJ": {"title": "You have both quick thinking and steady, honest reliability.", "body": "Relying on facts and experience and deciding with logic are your core, in both your temperament and your character. Added to that, you get energy from people and also recharge calmly alone. You can adapt on the spot and also follow the steps you've set. Usually you're the dependable one who respects the rules, but when it counts, you're the fastest to decide and move.", "say": "\"Let's follow the plan. …But if it rains, we switch to the backup right away.\"", "do": "You take the same train every morning, but the second there's a delay, you've already found the fastest way around.", "worry": "You want to prepare properly, but when every day is the same, you get restless. After a lively time with people, you can't relax until you've quietly tidied up alone.", "karai": "You say \"Let's stick to the plan,\" but you're the best at improvising."}, "ESTP>ISFJ": {"title": "You quietly support the people around you, ready to jump in at any moment.", "body": "Relying on the facts and experience in front of you is your core, in both your temperament and your character. On top of that, you get energy from people and also feel calm in time alone. You decide calmly with logic and stay gentle with people's feelings. You can move lightly in the moment and also build things up with care. When you see someone in trouble, your hands move before your words, and you sort it out smoothly.", "say": "\"I'll carry that. …Oh, and I got tomorrow's stuff ready too.\"", "do": "Helping a friend move, you carry the heaviest boxes and still bring drinks and snacks for everyone.", "worry": "Because you can help people so quickly, your schedule fills up with favors before you know it. Even on days you want to fully relax, you feel you should stay on top of things and hesitate to rest.", "karai": "Your catchphrase is \"It was nothing,\" but it's usually quite a lot."}, "ESTP>ESTJ": {"title": "You turn your speed in the field into systems that really work.", "body": "Getting energy from people, valuing facts, and deciding with logic are your core, in both your temperament and your character. Added to that, you can move right away with the situation and also plan ahead and see things through. When trouble hits, you deal with it on the spot, and afterward you set up the rules for \"next time, let's do it this way.\" You're a leader who shines on the ground.", "say": "\"I'll go handle it. …When I'm back, let's rewrite the manual.\"", "do": "You plan a barbecue down to the last detail, and the moment it rains, you switch everyone to a covered spot.", "worry": "Sometimes you want people to follow the rules, and sometimes you want to move without caring about rules at all, and switching between the two wears you out. You move things along so briskly that you worry people find you \"a little scary.\"", "karai": "The first person to break the rules you made is probably you."}, "ESTP>ESFJ": {"title": "You use your energy to make a place where everyone belongs.", "body": "Getting energy from people and valuing what's real in front of you are the same in your temperament and your character. On top of that, you make clean, logical calls and also pay close attention to people's feelings. You can move lightly in the moment and also prepare ahead so no one is left stuck. At gatherings, you're both the life of the party and the host, and by the end you know everyone's face and name.", "say": "\"Okay, cheers! …Oh, do you guys over there have enough to drink?\"", "do": "At the neighborhood festival, you quickly settle prices with the stalls, then spend the rest of the day playing with the kids.", "worry": "Even when you want to say something clearly, you sometimes hold it in because you don't want to spoil the mood. When you put everyone's needs first, you run out of room to enjoy yourself.", "karai": "Whenever you organize the dinner, you're the one who barely eats."}, "ESTP>ISTP": {"title": "You have both quick, hands-on instinct and quiet focus.", "body": "Relying on facts, thinking with logic, and moving flexibly are your core, in both your temperament and your character. Added to that, you get energy from being with people and also recharge by getting absorbed in something on your own. You love going out with friends, but you also feel full tinkering alone with your bike or guitar. You're someone with real skill in your hands.", "say": "\"Let's all go sometime. …Actually, I'll check it out by myself first.\"", "do": "At camp, you quietly get the fire going on the first try, then become the loudest one there.", "worry": "There's a big gap between days you love being surrounded by people and days you don't want anyone to talk to you, which can confuse those around you. You find it a bit hard to explain your ups and downs.", "karai": "For someone who \"likes being alone,\" you sure show up whenever you're invited."}, "ESTP>ISFP": {"title": "You move with bold energy and a soft, gentle sense of beauty.", "body": "Valuing the facts and feelings in front of you, and moving lightly with the situation, are your core, in both your temperament and your character. Added to that, you get energy from people and also from losing yourself in what you love alone. You can make clean, logical calls and also treasure your feelings and tastes. Wherever you dive in on impulse, you come back having found something beautiful no one else noticed.", "say": "\"Let's go see! …Wow, this sunset. Hold on, let me take a picture.\"", "do": "You wander into a vintage shop on a whim, become friends with the staff, and leave with a one-of-a-kind piece.", "worry": "Even when you want to stay cool about something, your likes and dislikes show on your face. After a fun time with people, you can't settle down without time alone doing what you love.", "karai": "You seem to do everything on impulse, but you never compromise on the taste of your stuff."}, "ESTP>ESTP": {"title": "You've opened up every situation with a fast first step.", "body": "Your temperament and your character are the same type. You move before you overthink, catch the flow of the moment, and never miss the key chance. That strength has grown steadily since you were a child. Because you know so clearly who you are, you shine in places full of change, and in places where you just have to wait, you can wear down without knowing why.", "say": "\"Hesitating is a waste of time. Let's go.\"", "do": "When you get lost on a trip, you skip the map, ask a local, and come away with a restaurant tip too.", "worry": "Thinking ahead gets pushed back, and deadlines or important paperwork give you a scare. When dull days drag on, your energy drops and you can't tell why.", "karai": "Your \"later\" usually means the morning it's due."}, "ESTP>ESFP": {"title": "You have calm judgment and a friendly warmth that lights up the room.", "body": "Getting energy from people, enjoying what's real in front of you, and moving with the moment are your core, in both your temperament and your character. On top of that, you can quickly weigh the pros and cons with logic and also warm up the room by caring about people's feelings. You keep the fun going while calmly reading the flow in the back of your mind, and when it matters, you take charge in a snap.", "say": "\"Yes, let's have fun! …But let's figure out the last train home first.\"", "do": "At a friend's surprise birthday, you're the most excited one there, and you still split the bill down to the last cent on the spot.", "worry": "You don't want to break the happy mood, so you wrap what needs saying in a joke. After you say something straight, you worry you might have hurt the other person.", "karai": "You were the wildest one there, and on the way home you can list every lesson from the night."}, "ESFP>INTJ": {"title": "You can add cheer that makes people smile to a careful, detailed plan.", "body": "Day to day, you're a calm strategist who's good at looking ahead and planning with logic. But deep down, there's a sunny side that loves this very moment and brightens everyone around you. So your plans aren't just right, they're actually fun. You map out the path with a cool head and bring people along with a warm smile.", "say": "\"Here's how I set up the whole flow. …And I made time at the end for all of us to celebrate.\"", "do": "You plan a trip down to the minute, slip in one \"free time, no plans\" slot, and that's when you have the most fun.", "worry": "You want to get things done efficiently and you want to enjoy the mood of the moment, so you can't decide how to spend your day off. After a fun time with people, you lose your rhythm if you don't get quiet time alone to reset.", "karai": "The most important item on your perfect schedule is probably \"the after-party.\""}, "ESFP>INTP": {"title": "You use both a friendly, open heart and a mind that thinks deeply.", "body": "Moving flexibly with the situation is your core, in both your temperament and your character. Added to that, you get energy from people and also from getting lost in thought alone. You enjoy the moment with all your senses and love digging into how things work. You care warmly about feelings and can sort things out calmly with logic. In the middle of a fun chat, you're the one who suddenly asks, \"Wait, why does that happen?\"", "say": "\"This shop is so cute! …Hey, why does this layout make me want to buy stuff?\"", "do": "At an amusement park, you enjoy the rides while endlessly thinking about how the lines move.", "worry": "You love talking with people, but when you get caught up in thought, you forget to reply to messages. Even when feelings matter most, you answer with logic and regret it later.", "karai": "Your reply to \"That was fun!\" tends to be \"Yeah, the mechanics were interesting.\""}, "ESFP>ENTJ": {"title": "You use your sunny energy to lead everyone toward big goals.", "body": "Getting energy from people is your core, in both your temperament and your character. On top of that, you savor the fun right in front of you and also picture what's possible ahead. You care warmly about feelings and decide calmly with logic. You can go with the flow and also work backward from the goal. Even when you set a high target, people somehow follow with a smile. You're a leader who's easy to be around.", "say": "\"Our goal is 1.5 times last year! …If we hit it, we're all going out for barbecue.\"", "do": "After firmly setting the numbers in a meeting, you hand out snacks to every member.", "worry": "The more you want results, the more you worry about someone's feelings after you speak harshly. When your head is full of future plans, you lose the room to enjoy what's in front of you.", "karai": "You say \"Let's have fun with it,\" but you've even set targets for the fun."}, "ESFP>ENTP": {"title": "You use your cheerful vibe to keep growing new ideas.", "body": "Getting energy from people and moving lightly with the moment are the same in your temperament and your character. Added to that, you enjoy the present with all your senses and dream up things that don't exist yet. You care warmly about feelings and dig in sharply with logic. While making everyone laugh, you turn the conversation into a plan with \"What if we did it like this? Wouldn't that be more fun?\"", "say": "\"Ooh, that sounds fun! …But wait, if we did it the other way, it might be even better.\"", "do": "While getting ready for a friend's birthday party, you keep adding ideas until it's turned into a small event.", "worry": "You jump at every fun idea, and half-finished things pile up. After a heated debate, you check people's faces, worried you went too far.", "karai": "Somehow, every idea you pitch as a joke ends up actually happening."}, "ESFP>INFJ": {"title": "You have both a bright side that entertains people and the depth to see into their hearts.", "body": "Deciding with care for people's feelings is your core, in both your temperament and your character. Added to that, you get energy from people and also settle your heart quietly alone. You enjoy the fun in front of you and can read the meaning behind things. You can go with the flow and also look ahead and prepare. Even while enjoying a lively crowd, you're the first to notice who looks lonely.", "say": "\"Let's all take a picture! …Wait, Sam's not in it. Come over here!\"", "do": "On the way home from a fun get-together, you think, \"They seemed worried about something,\" and quietly send a message the next day.", "worry": "You love seeing people, but afterward your heart feels more tired than you expected. You read people's feelings so deeply that you worry about things that haven't even happened.", "karai": "The days you laugh the loudest are the days you think the hardest."}, "ESFP>INFP": {"title": "You savor the present and treasure the feelings in your heart.", "body": "Caring about feelings and moving flexibly with the situation are your core, in both your temperament and your character. On top of that, you get energy from people and also from quietly holding your feelings close. You can sense the beauty and fun right in front of you, and imagine what can't be seen yet. After a fun day out with friends, you can tuck that day's scenery away in your heart like a little poem.", "say": "\"Today was so much fun! …I kind of want to remember the color of this sky forever.\"", "do": "After a trip, you make an album and add a few short words to each photo, one by one.", "worry": "Time with friends and time alone in your imagination both matter to you, so you swing between overbooking and hiding away. You can't always put what you care about into words, and that's frustrating.", "karai": "You say \"I just go with the flow,\" but you're more stubborn about what you like than anyone."}, "ESFP>ENFJ": {"title": "You enjoy the moment and give people a warm push forward.", "body": "Getting energy from people and deciding with care for feelings are your core, in both your temperament and your character. Added to that, you enjoy this very moment and believe in what people can become. You can ride the flow and also look ahead and guide everyone. When a friend says \"I want to try this,\" you get excited with them, and before you know it, you've planned how to support them.", "say": "\"That's such a great idea! …So let's try it once by next month. I'll help.\"", "do": "You rush to a younger friend's performance with flowers, and afterward you help them think about their next goal.", "worry": "You love being helpful, so you can't say no, and your schedule gets packed. The more you plan for everyone else, the less time you have to just enjoy yourself.", "karai": "Your schedule for cheering on other people's dreams is perfect. Your own dream? \"Someday.\""}, "ESFP>ENFP": {"title": "You chase both the fun in front of you and ideas that keep growing.", "body": "Getting energy from people, caring about feelings, and moving with the moment are your core, in both your temperament and your character. On top of that, you can fully enjoy the present with all your senses and also picture a future that doesn't exist yet, thinking \"wouldn't that be lovely.\" You treasure today's fun and still find the excitement beyond it, so you brighten the days of everyone around you.", "say": "\"This cake is so good! …Hey, want to open a shop together someday?\"", "do": "Halfway through a café-hopping day, you come up with a small event just for your group and invite your friends on the spot.", "worry": "The fun things and things you want to try keep piling up, and your body and time can't keep up. You want to reach for both today's fun and tomorrow's dreams, so narrowing it down to one is hard.", "karai": "Your \"someday\" list is already longer than one lifetime."}, "ESFP>ISTJ": {"title": "You put your friendly cheer to work with steady, solid effort.", "body": "Relying on facts and experience is your core, in both your temperament and your character. Added to that, you get energy from people and also calm down alone. You care warmly about feelings and decide calmly with logic. You can enjoy the moment and also move forward steadily, step by step. At work, people count on you as \"the reliable one,\" and on breaks you're the one making everyone laugh.", "say": "\"I'll finish the documents today. …After that, want to check out the new bakery?\"", "do": "You write careful handover notes, then add a handwritten line at the end: \"Ask me anytime if you get stuck.\"", "worry": "The better you do, the more people rely on you, and you get fewer chances to just goof around. After you decide based on what's right, you wonder if you left someone's feelings behind.", "karai": "Your face says serious work. Your mind is mostly on weekend plans."}, "ESFP>ISFJ": {"title": "You support the everyday lives of those around you with bright, thoughtful care.", "body": "Valuing what's real in front of you and deciding with care for people's feelings are your core, in both your temperament and your character. Added to that, you get energy from people and also feel relief in time alone. You can enjoy the moment lightly and also prepare ahead with steady care. At gatherings, you're the one keeping the fun going, and you've already prepared everything to match everyone's tastes.", "say": "\"Let's go all out tonight! …Oh, Alex can't really drink, so I got some juice too.\"", "do": "At a house party, you laugh the most, and as people leave, you hand each one a little bag of treats.", "worry": "You want so much to make people happy that you put too much into preparing, and you're exhausted by the day itself. After a fun time, you need to rest quietly alone to get your energy back.", "karai": "Everyone's gifts are perfect, but you forgot to get one for yourself."}, "ESFP>ESTJ": {"title": "You make things fun and still move them forward properly.", "body": "Getting energy from people and valuing what's real in front of you are the same in your temperament and your character. Added to that, you have the brightness to liven up any moment and the sense of responsibility to plan things and see them through. When asked to organize a group dinner, you get the place and budget perfect, and then you're the one having the most fun on the night.", "say": "\"Okay, we meet at 7. …So, where are we going after?\"", "do": "You make a detailed trip guide, then find an interesting shop when you get there and change the whole plan.", "worry": "The more people rely on you as \"so dependable,\" the less time you get to just play. You want to stick to what you decided and you also want to enjoy the moment, so days off can be the most tiring.", "karai": "Your schedule is perfect. You just forgot to pencil in time for your own fun."}, "ESFP>ESFJ": {"title": "You enjoy the moment and take good care of everyone's circle.", "body": "Getting energy from people and caring about what's real and how people feel are your core, in both your temperament and your character. On top of that, you can go with the fun of the moment and also look ahead to prepare so no one is left stuck. For events and celebrations, you take on both the planning and the caring, and on the day, you truly enjoy it too. You're a host people can count on.", "say": "\"Okay, that's the plan for the day! …But if something looks fun, we can change it, right?\"", "do": "You carefully handle the guest list and venue for a class reunion, then get the most excited sharing old memories on the day.", "worry": "You make rules so everyone can have a good time, but on the day itself, you want to go with the flow. The more you try to meet people's expectations, the harder it gets to say you're tired.", "karai": "You're great at telling others \"Don't push yourself.\" You just can't say it to yourself."}, "ESFP>ISTP": {"title": "You have both a bright, friendly warmth and quiet skill.", "body": "Valuing the facts and feelings in front of you and moving lightly with the situation are your core, in both your temperament and your character. Added to that, you get energy from people and also from quietly focusing on something alone. You care warmly about feelings and can make clean, logical calls. You love laughing with everyone, but you also feel quietly full when you're lost in cooking or making something alone.", "say": "\"Ooh, that looks fun, I'm in! …Here, let me see. It's faster if you do it like this.\"", "do": "When a friend's bike gets a flat, you crack jokes while fixing it in no time.", "worry": "Wanting to be kind and wanting to keep things simple bump into each other, and you're not sure how to say things. After a run of lively days, a day comes when you suddenly don't want to talk to anyone.", "karai": "When someone says \"You can do anything!\" you get shy and change the subject right away."}, "ESFP>ISFP": {"title": "You love entertaining people and treasure your own sense of beauty.", "body": "Sensing the beauty and fun in front of you, caring about feelings, and moving flexibly are your core, in both your temperament and your character. On top of that, you light up around people and also fill your heart by losing yourself in what you love alone. Laughing with friends out and about, and being surrounded by your favorite music or art in your room, are both things your days can't do without.", "say": "\"Let's all go! …Oh, but I might want to walk home alone, nice and slow.\"", "do": "After a lively group dinner, you stop by a park at night on your own and walk home listening to your favorite songs.", "worry": "Invitations make you happy, so you say yes too often and later run short of time for yourself. You use so much energy keeping the mood bright that you miss the chance to talk about what you love.", "karai": "You look so social, but you've firmly booked your \"alone time\" too."}, "ESFP>ESTP": {"title": "You have a kind heart for people and the cool head to spot the key moment.", "body": "Getting energy from people, enjoying what's real in front of you, and moving with the moment are your core, in both your temperament and your character. Added to that, you can warm up the room by caring about feelings and also quickly decide by weighing the pros and cons with logic. You laugh with everyone, and the moment trouble hits, you're the fastest to calmly fix it. You're the fun one people can count on.", "say": "\"It's fine, it's fine! …Okay, let's grab a table at another place while we can.\"", "do": "When the hotel booking falls through on a trip, you keep everyone laughing while you call around and find another place.", "worry": "After making a practical decision, you keep replaying how the other person might have felt. You often decide on impulse, so checking the small details gets pushed back.", "karai": "You're so sensitive to people's feelings, and so clueless about what's in your wallet."}, "ESFP>ESFP": {"title": "You've grown your gift for lighting up any room, straight and true.", "body": "Your temperament and your character are the same type. Your gift for enjoying the moment with others and brightening everyone's mood has grown steadily since you were little. Because you know so clearly who you are, you come alive in places full of connection, and in places where you work alone in silence, you can lose your spark without knowing why.", "say": "\"We're here anyway, so let's enjoy it!\"", "do": "Even at a gathering full of strangers, you end up laughing in the middle of it all and go home with a bunch of new contacts.", "worry": "While you put fun first, money and future plans can slip. When you feel low, it's often not because you're weak, but because you've been too far from people.", "karai": "The night you say \"This month I'm really saving money,\" you usually buy something."}, "ISTP>INTJ": {"title": "Someone who grows hands-on answers into long-term plans.", "body": "Recharging in time alone to think, and deciding things by clear logic — that's your core, in both your temperament and your character. On top of that, you have both the lightness to touch and test things for real, and the power to see years ahead and map out a path. Something you tried on a whim often turns out to be part of a bigger plan. You move forward by going back and forth between small experiments and a long blueprint.", "say": "\"Let's just build one and see. …And how we'll use it three years from now? Already decided.\"", "do": "You tinker with tools on the weekend to build a prototype, then spend weeknight evenings putting it into a spreadsheet and planning the next upgrade.", "worry": "The more you plan ahead, the more the fun of just trying things on the spot seems to fade. Some days you freeze, torn between sticking to the plan and following the idea that just hit you.", "karai": "Line one of your ten-year plan is usually \"just mess with it first.\""}, "ISTP>INTP": {"title": "Someone who takes systems apart with both hands and head.", "body": "Getting your energy back from time alone, thinking things through logically, and moving freely without being tied down by rules — these are the same in your temperament and your character. Added to that, you can both handle real things in front of you to see how they work, and imagine theories and possibilities no one can see yet. Put a broken machine in front of you, and you start thinking about how to fix it and \"why was it built like this in the first place?\" at the same time.", "say": "\"Take this screw out and it'll work. …Actually, there was a totally different way to build this, right?\"", "do": "You start fixing a home appliance and end up researching the history of how it works until midnight.", "worry": "Your thoughts spread so wide that by the time you start using your hands, your interest has already moved on. The moment you understand something, you're satisfied — and you often forget to explain it to anyone.", "karai": "You say \"Ah, got it,\" and then explain absolutely nothing to anyone."}, "ISTP>ENTJ": {"title": "Someone who leads big goals with quiet skill.", "body": "Deciding things by clear logic is your core, in both your temperament and your character. On top of that, you have both sides of several things: quietly sharpening your skills alone and gathering people to lead them, an eye for the facts in front of you and an eye for what's ahead, lightness on your feet and a talent for planning. In meetings you lay out the direction with confidence, while quietly handling the hardest job yourself.", "say": "\"This is the direction. Everyone, follow me. …Oh, and this part? I'll take care of it tonight.\"", "do": "After finishing the team's plan, you head out to the site alone to check the real thing with your own eyes.", "worry": "When you're stuck in the leader role for a while, you lose your time to work alone with your hands, and your battery suddenly dies. Even when you know handing things off is faster, you can't shake the feeling that doing it yourself is safer.", "karai": "Your instructions are brilliant, but it usually ends with \"Never mind, I'll just do it myself.\""}, "ISTP>ENTP": {"title": "Someone who finds new paths with busy hands and a quick tongue.", "body": "Thinking logically and adapting flexibly to the moment are the same in your temperament and your character. On top of that, you have both the focus to test how things work on your own and the energy to spin out idea after idea while talking with people. You can also see both solid, touchable facts and possibilities that haven't taken shape yet — so you never stop at \"all talk\" or \"all doing.\"", "say": "\"Wouldn't it be fun if we did it like this? …No, wait — let me build one first, then we'll talk.\"", "do": "An idea that got everyone excited in casual chat? By that night, you've turned it into something real, on your own.", "worry": "Talking with people lights your fire, but too much of it wears you out and makes you want to hide at home. Your hands can never keep up with how many ideas you have.", "karai": "Your count of \"I just thought of something fun\" and your count of finished things don't match. At all."}, "ISTP>INFJ": {"title": "Someone who calmly looks out for where people are headed.", "body": "Building up your strength in time alone is the same in your temperament and your character. Beyond that, you have both sides of three things: an eye that sees facts as they are and one that reads what they'll mean later, deciding by logic and caring about people's feelings, moving lightly and planning ahead. You don't talk much, yet you have what someone needs ready before they even get stuck. That's your quiet way of helping.", "say": "\"I figured this would be a problem next month. …So, here — already fixed it.\"", "do": "While listening to someone's problem, you build a solution in your head, and the next day you quietly hand them the tools they need.", "worry": "You think so much about the other person's feelings that you hesitate to give the logical answer. While worrying about the future, you let the task in front of you slide, and it disappoints you.", "karai": "Your kindness is so fast that people miss their chance to say thank you. Every single time."}, "ISTP>INFP": {"title": "Someone whose skilled hands give shape to the scenes in their heart.", "body": "Recharging in time alone and doing things your own way rather than by the rules are the same in your temperament and your character. Added to that, you have both the precise skill to handle things and the imagination to picture worlds that don't exist yet, plus both cool logic and a gentle heart for feelings. You get passionate talking about a work you love, yet your hands stay perfectly calm when you make things. That mix gives everything you create its own special flavor.", "say": "\"This color kind of makes me want to cry. …Anyway, if you're painting it, this brush size is best.\"", "do": "When a keepsake breaks, before you even feel sad you're looking up how to fix it — and you give it back stronger than before.", "worry": "When you choose with your heart, the logic doesn't catch up later, and that leaves you uneasy. You're not good at putting what you care about into words, so it often never reaches the people around you.", "karai": "The hand that just wiped away your happy tears is already holding a tool."}, "ISTP>ENFJ": {"title": "Someone who cheers people on — and quietly gets to work with their own hands.", "body": "You're a warm leader who believes in people's potential and brings everyone together with encouragement. You also have a craftsman's side that loves working quietly with your hands and solving the actual problem in front of you. That's why you don't stop at words — you can really lend a hand to someone who's struggling. You have both a warm heart and calm, skilled hands.", "say": "\"You've all got this! …And that broken bit over there? I'll fix it.\"", "do": "After giving the team a pep talk, you stay behind in the empty room, quietly finishing the fiddly work.", "worry": "Since you're often out in front of people, you don't get enough quiet time to lose yourself in something alone. You're the one who puts feelings into words for others, yet your own feelings are hard to say.", "karai": "After a fiery speech, what you really want is to go fiddle with your tools alone."}, "ISTP>ENFP": {"title": "Someone who shares their curiosity with people and tools alike.", "body": "Moving lightly with the flow of the moment is your core, in both your temperament and your character. On top of that, you have both sides of three things: focusing alone to check things and getting fired up with people, an eye for solid facts and an eye for widening possibilities, cool logic and a warm heart for feelings. One minute you're chatting away, the next you've gone quiet and started building something. That switch is part of your charm, too.", "say": "\"Wait, that's amazing! Let's do it! …Hold on, let me check if we have enough materials.\"", "do": "On a camping trip you're the most excited one there — and somehow you end up handling the campfire and all the gear repairs.", "worry": "After a fun chat you suddenly want to be alone, and people worry, \"Are you mad?\" You want to do so many things that you often move on before finishing one.", "karai": "That plan you started on a whim? You're doing all the behind-the-scenes work for it. Alone."}, "ISTP>ISTJ": {"title": "Someone who keeps sharpening solid skills with steady routines.", "body": "Recharging alone, relying on facts, and deciding by logic are the same in your temperament and your character. On top of that, you have both the ability to adapt on the fly and the ability to follow set steps carefully. Normally you move forward reliably, right on schedule — but the moment trouble hits, you can close the manual and respond to what's actually happening.", "say": "\"We'll start at ten, as planned. …Well, if something breaks, I'll just fix it on the spot.\"", "do": "Your toolbox is perfectly organized, yet when you're out you cleverly make do with whatever's at hand.", "worry": "You're good at following rules, but in places with too many of them you suddenly can't breathe. You can't find the balance between doing things properly and doing them your way, so your days off end up either packed or totally empty.", "karai": "You're trying very hard to stick to a schedule that literally says \"be flexible.\""}, "ISTP>ISFJ": {"title": "Someone whose handy skills support everyone's daily life.", "body": "Recharging in time alone and relying on facts and experience are the same in your temperament and your character. On top of that, you have both cool logic and a gentle heart for others' feelings, both quick, light action and careful preparation. If someone in your family gets a flat bike tire, you fix it without a word — and tidy up where the pump goes while you're at it. You show care with your hands more than with words.", "say": "\"It's getting cold, so take this. …Oh, let me fix that zipper real quick.\"", "do": "You handle little problems at work before anyone asks, and leave a small note so the next person won't get confused.", "worry": "Because you handle requests so easily, you can never find a reason to say no. Caught between wanting to get things done fast and wanting to put others first, your own time keeps shrinking.", "karai": "You can fix everyone else's stuff, but your own exhaustion stays unrepaired."}, "ISTP>ESTJ": {"title": "Someone with hands-on skill and the power to bring people together.", "body": "Relying on facts and deciding by logic is your core, in both your temperament and your character. On top of that, you have both the focus to hone your skills alone and the drive to stand in front and organize people, plus both flexible, in-the-moment action and the ability to plan things out and see them through. You're good at giving directions, but people count on you most when something goes wrong on site. Your mouth and your hands are both always busy.", "say": "\"Here's how we'll split the roles. …And if there's trouble, send it my way. I'll come look right away.\"", "do": "Put in charge of a neighborhood event, you spend the day itself running around fixing broken equipment on your own.", "worry": "The more you're asked to lead, the less time you get to work quietly alone. You want others to stick to the plan, yet you yourself want to act on impulse — and you wonder if that's fair.", "karai": "The person who said \"Don't go off on your own\" is the one going off on their own the most."}, "ISTP>ESFJ": {"title": "Someone who calmly keeps everyone comfortable.", "body": "Relying on the facts and experience in front of you is the same in your temperament and your character. Beyond that, you have both sides of three things: focusing alone and enjoying being with people, cool logic and a kind heart that reads everyone's feelings, lightness and thoughtful planning. At gatherings you put everyone at ease, and when a problem comes up, you fix it without changing your expression. You're the kind of host people feel safe with.", "say": "\"Everyone got enough to drink? …Oh, that light's not working. Let me go check.\"", "do": "At a home party you serve food matched to everyone's tastes, while quietly fixing the wobbly chair.", "worry": "While looking after everyone, you lose your quiet time alone and suddenly feel drained. Torn between saying what's right and keeping the mood, you end up saying nothing.", "karai": "After taking care of everyone, the part you enjoy most is the walk home alone."}, "ISTP>ISTP": {"title": "Someone who trusts their own hands and eyes, and quietly carves their own path.", "body": "Your temperament and your character are the same combination. Checking things with your own hands, thinking them through logically, and moving freely without being tied down by rules — these have grown steadily in you since childhood. Because you know your own way so clearly, you really shine where people trust you to handle things, and in places that micromanage you, you tend to get worn out without knowing why.", "say": "\"Here, let me see that. …There. Fixed.\"", "do": "Before anyone has even opened the manual, you've already finished putting it together.", "worry": "You're not good at putting feelings into words, so people often say, \"I can't tell what you're thinking.\" The cause of your tiredness is often not you, but a place where you can't move freely.", "karai": "Someone asks \"You okay?\", you say \"Yeah,\" and that's the end of the conversation."}, "ISTP>ISFP": {"title": "Someone who adds a soft touch of feeling to steady, skilled hands.", "body": "Recharging in time alone, relying on facts, and adapting to the moment are the same in your temperament and your character. On top of that, you have both cool logic and a sense that values feelings and beauty. You use tools with precision, yet when it's time to finish, you suddenly get particular about color and texture. You can make one piece that's both easy to use and lovely to have around.", "say": "\"Strength-wise, it's fine. …But the corners would be cuter a little rounder, right?\"", "do": "You build your own shelf with measurements that fit perfectly, then pick little decorations to match the wood.", "worry": "Even when logic tells you something is right, you can't move if your heart isn't in it. When you give someone your opinion, you keep wondering whether you sounded cold.", "karai": "\"I'm not picky about it,\" says the person matching even the screw colors."}, "ISTP>ESTP": {"title": "Someone whose hands-on skill shines among people, too.", "body": "Relying on facts, deciding by logic, and moving lightly with the moment are your core, in both your temperament and your character. On top of that, you have both the focus to hone your skills alone and the energy you get from diving in among people. In a lively crowd you're the most up-for-anything one there, and on your own you quietly master your craft. Your speed has real skill behind it.", "say": "\"Okay, let's go! …Oh, let me just check the tire pressure first.\"", "do": "When trouble hits on an outing with friends, you're already moving before anyone else starts talking it over.", "worry": "Being with people is fun, but after a while you suddenly need time alone. You move so fast that people sometimes say, \"Talk to us first!\"", "karai": "Your motto is \"Less thinking, more doing\" — and then you hold a solo review meeting when you get home."}, "ISTP>ESFP": {"title": "Someone who enjoys every bit of the moment with clever hands and a bright spirit.", "body": "Relying on the facts in front of you and adapting to the moment are the same in your temperament and your character. On top of that, you have both the focus to work alone and the energy you get from being with people, plus both cool logic and a warm heart that cares about everyone's feelings. On a trip, you're the one hyping everyone up — and when the car won't start, you calmly fix it. You can show fun and dependability at the same time.", "say": "\"Wow, this place is amazing! Let's take a picture! …Huh, the tripod screw's loose. Hang on.\"", "do": "The day after playing all out with friends at a festival, you're alone at home, totally absorbed in rearranging your room.", "worry": "The day after a fun time with people, you're wiped out and don't want to talk to anyone. You hesitate between saying what you really think and keeping the fun going.", "karai": "You're the life of the party, yet somehow you end up in the corner fiddling with the sound system."}, "ISFP>INTJ": {"title": "Someone who turns the beauty their heart picks into a long-term blueprint.", "body": "Building up energy in time alone is your core, in both your temperament and your character. Beyond that, you have both sides of three things: a sense that savors what feels good right here and now and an eye that sees far ahead, choosing with your heart and deciding by logic, lightness and planning. You don't let your love for something end as a passing whim — you turn it into a path you can follow for years until it's done.", "say": "\"I really love this color scheme. …So I made a plan to redo my whole room in it by next year.\"", "do": "You've turned redecorating your room into a year-long, step-by-step plan, and you're working through it bit by bit.", "worry": "Making a plan calms you, but as you follow it, the feeling of \"I love this\" starts to fade. When people ask why you chose something by feel, you get stuck for words.", "karai": "Your \"I just kinda like it\" comes with a five-year plan attached."}, "ISFP>INTP": {"title": "Someone who digs deep into what they love with logic.", "body": "Recharging in time alone and moving at your own pace without being tied down by rules are the same in your temperament and your character. On top of that, you have both a sense that savors texture and color and a mind that thinks about unseen systems, plus both a gentle heart for feelings and calm logic. When you hear music you love, your heart moves — and at the same time, you start wondering, \"Why does this sound move me?\"", "say": "\"I love this song. …Can I take a sec to figure out why?\"", "do": "You start looking up how a little item you like was made, and before you know it you're reading about the history of its materials.", "worry": "Sometimes you overthink what you feel and can't simply enjoy it anymore. You don't share your thoughts until they're sorted, so people often assume you're not thinking about anything.", "karai": "By the time you finish explaining why it moved you, the other person is no longer moved."}, "ISFP>ENTJ": {"title": "Someone with the strength to lead and a delicate, sensitive heart.", "body": "You're a decisive leader who sets goals and pulls people forward. You also have a delicate side that treasures your own senses and quietly savors the people and beautiful things in front of you. That's why your decisions carry care for people, not just numbers. With both strength and kindness, you can move people forward.", "say": "\"The goal is end of the month — let's decide up to here today. …Before that, how about a short break, everyone?\"", "do": "After running a meeting briskly, you carefully finish the cover of the handout — and only the cover — in your favorite color.", "worry": "The more you lead from the front, the less time you have to lose yourself in what you love. When you have to speak firmly to get things moving, you keep worrying afterward whether you hurt someone.", "karai": "On a day of tough orders, the one reflecting hardest that night is the one who gave them."}, "ISFP>ENTP": {"title": "Someone who expands what they feel by talking and trying.", "body": "Adapting flexibly to the moment is your core, in both your temperament and your character. On top of that, you have both sides of three things: quietly savoring things alone and getting lively in conversation, sensing what's right in front of you and picturing new possibilities, a gentle heart for feelings and sharp logic. You read how people feel, and before you know it you've rolled the conversation in a totally new direction.", "say": "\"Hmm, that's kind of sad for them. …Oh, but what if we flipped it and did this?\"", "do": "While listening to a friend's worries, somehow you end up inventing a new game.", "worry": "The more fun you have talking, the more drained you are afterward, wanting to shut yourself away. After saying too much in a debate, you replay it at night, thinking about how the other person felt.", "karai": "You say \"Either's fine with me,\" but in your head you've already lined up three counterarguments."}, "ISFP>INFJ": {"title": "Someone who deepens kindness with quiet foresight.", "body": "Recharging in time alone and deciding with care for people's feelings are your core, in both your temperament and your character. On top of that, you have both a sense that savors this very moment and the ability to read what things will mean later, plus both easygoing lightness and calm foresight. You notice a friend's small changes right away and quietly stay by their side — while already thinking about what would make things easier for them down the road.", "say": "\"Let's take it easy today. …But let's get ready for that thing next week together, okay?\"", "do": "As you set out seasonal flowers, you've already decided what to display at this time next year.", "worry": "You think so far ahead for others that your own feelings get pushed to the back. Even on days you want to go with your mood, you end up adding plans \"for later.\"", "karai": "You'll stand by someone's worries for the next ten years, yet you haven't told anyone your own."}, "ISFP>INFP": {"title": "Someone who listens closely to the voice of the heart.", "body": "Recharging in time alone, valuing feelings, and moving at your own pace are the same in your temperament and your character. On top of that, you have both a sense that truly takes in the colors and sounds in front of you, and an imagination that pictures worlds not yet formed. A tiny flower you spot on a walk gives you a whole story. You can treasure both the beauty of what's here and the beauty of what isn't yet.", "say": "\"This sunset is lovely. …Feels like a story from some faraway land is about to begin.\"", "do": "In your favorite notebook, you take turns writing diary entries and made-up stories.", "worry": "The higher your ideals, the lonelier the gap with reality feels. There are so many things you want to treasure that you can't decide which to choose.", "karai": "In your imagination you can do anything. In real life, you agonize for an hour over calling to book a table."}, "ISFP>ENFJ": {"title": "Someone who stays close and gently gives people a push.", "body": "Deciding with care for people's feelings is your core, in both your temperament and your character. On top of that, you have both sides of three things: settling your heart alone and getting energy among people, a sense that savors the present and an eye that sees ahead, easygoing lightness and the ability to plan. You stay close to the feelings of the person in front of you, while quietly clearing a path so they can take that first step.", "say": "\"I totally get how you feel. …So let's try getting this far together by next week.\"", "do": "You drop off snacks a down friend might like — and leave having planned the next fun thing together, too.", "worry": "When you're the cheerleader for too long, you lose time to do what you love alone, and your heart wears thin. Some days your mood can't keep up with the plans you made for everyone.", "karai": "You're everyone's emotional support team, but your own calendar is completely blank."}, "ISFP>ENFP": {"title": "Someone who shares the things they love and grows them with others.", "body": "Valuing feelings and going with the flow are the same in your temperament and your character. On top of that, you have both the ability to enjoy things quietly alone and the energy you get from sharing them with others, plus both an eye for what feels good right now and an eye for new possibilities. Some days you savor your favorite café alone; other days you bring friends, and the talk of \"next, let's try that place\" goes on forever.", "say": "\"I love this place so much! Want to come with everyone next time? …Actually, maybe I want to come alone.\"", "do": "Every time you find a cute little thing you send a photo, and somehow three new plans for your next day off appear.", "worry": "On the way home after a fun time, you're thrown by how suddenly you want to be alone. New favorites keep piling up, and your heart moves on before you can dig into one.", "karai": "The very day you decide to stay home is the day you send out the most fun invitation yourself."}, "ISFP>ISTJ": {"title": "Someone who protects a soft sensitivity with solid steps.", "body": "Recharging in time alone and valuing the facts and experience in front of you are the same in your temperament and your character. On top of that, you have both a kindness that chooses with the heart and a calm that decides by logic, plus both free, light movement and the integrity to keep your word. In your precise work, little touches of care and a beautiful finish shine through. You deliver trust and comfort together.", "say": "\"I'll hand it in on time. …Oh, and I changed just the cover color to match the season.\"", "do": "You keep your household budget accurate to the last cent, and put your favorite stickers in the corners of the pages.", "worry": "On days you put being right first, you lie awake wondering whether you left someone's feelings behind. While following the rules, you realize you've been putting the things you love on hold.", "karai": "So meticulous — except for your stationery habit, which never stays on budget."}, "ISFP>ISFJ": {"title": "Someone who brings comfort to the everyday lives around them.", "body": "Recharging in time alone, valuing facts and experience, and caring about people's feelings are the same in your temperament and your character. On top of that, you have both the lightness to move with your mood and the ability to think ahead and prepare properly. Usually you support family and friends with smooth planning, and on days off you wander wherever you like. You have both the power to support others and the power to fill yourself up.", "say": "\"I got tomorrow's stuff ready too. …So today, I'm just gonna wander out for a bit.\"", "do": "You make everyone's lunches the night before, and on the day itself you enjoy a detour picked on a whim.", "worry": "The more carefully you prepare, the guiltier you feel about free, easy time. While fitting into other people's schedules, you tend to forget what you wanted to do.", "karai": "You carry spares for everything everyone else forgets — and left your own umbrella at home."}, "ISFP>ESTJ": {"title": "Someone who moves things forward firmly, with kind eyes.", "body": "Relying on the facts and experience in front of you is your core, in both your temperament and your character. On top of that, you have both sides of three things: settling your heart alone and bringing people together, kindness that reads feelings and strength that decides by logic, lightness and a knack for planning. You keep things on schedule, and still quietly check in on anyone who looks tired. You're an organizer with both firmness and warmth.", "say": "\"Deadline's Friday, no changes. …But if it's getting to be too much, tell me early, okay?\"", "do": "You make a minute-by-minute schedule for an event, and on the day people also compliment your eye for decorations.", "worry": "The clearer your instructions, the more you lie awake wondering if you said it too harshly. The longer you're the organizer, the more you miss time alone with the things you love.", "karai": "The sterner your face that day, the more likely you buy yourself something cute on the way home."}, "ISFP>ESFJ": {"title": "Someone who brings quiet thoughtfulness into the group.", "body": "Valuing facts and experience and caring about people's feelings are your core, in both your temperament and your character. On top of that, you have both the ability to spend time quietly alone and the energy you get among people, plus both lightness in the moment and the ability to think ahead and prepare. At gatherings you pay close attention so everyone feels at home, and back home you sink into your favorite music alone. That switch is what keeps you going.", "say": "\"Everyone's seat is all set. …Oh, I might sneak out a little early, though.\"", "do": "You start preparing birthday party decorations a week ahead, and afterward you take the leftover flowers home to your room.", "worry": "You love doing things for everyone, but keep it up and you suddenly want to be alone. When turning down an invitation, you overthink whether you'll let them down.", "karai": "The day after organizing the perfect get-together, you turn off every notification on your phone."}, "ISFP>ISTP": {"title": "Someone with a feeling heart and sure, skilled hands.", "body": "Recharging in time alone, relying on facts, and adapting to the moment are the same in your temperament and your character. On top of that, you have both a sense that values feelings and beauty and the power to judge calmly by logic. When something you love moves you, you can also work out with your hands how to make it even better. Your sensitivity comes with real skill.", "say": "\"This shape is beautiful. …If I shave a bit off here, it'll be easier to hold.\"", "do": "You repair your favorite old chair yourself, keeping all its worn-in charm.", "worry": "After calmly saying what's right, you replay it again and again, wondering if you hurt the person. You want to choose with your heart, but logic gets there first and you can't just be happy.", "karai": "People call you \"distant,\" but the gifts you make with those hands usually get happy tears."}, "ISFP>ISFP": {"title": "Someone who has kept growing what they love, straight and true.", "body": "Your temperament and your character are the same combination. A sense for what feels good, a gentle way of staying close to people, and the lightness to move at your own pace — these have grown in you without wavering. Because you know yourself so clearly, you bloom in places filled with things you love, and where you're rushed or dismissed, you tend to lose energy without knowing why.", "say": "\"Yeah, this one. I can't really explain why, though.\"", "do": "On an ordinary walk home, you catch the scent of the season and take the long way back.", "worry": "It takes you time to put your feelings into words, and you often end up swallowing them unsaid. The cause of your tiredness is often not you, but a place that asks you to move at a pace that doesn't fit.", "karai": "You say \"Anywhere's fine,\" yet you remember the restaurant that didn't get picked for quite a while."}, "ISFP>ESTP": {"title": "Someone who savors every bit of the moment with feeling and action.", "body": "Relying on the facts in front of you and moving lightly with the moment are your core, in both your temperament and your character. On top of that, you have both the ability to savor things quietly alone and the energy you get from diving in among people, plus both a gentle heart for feelings and the power to decide quickly by logic. On a trip, you jump right into any spot that catches your heart, and even when trouble hits, you calmly change the plan.", "say": "\"This place has such a nice vibe! Let's go in! …Oh, if it's packed, I'll check the place around back first.\"", "do": "You enjoy an outing with friends to the fullest, then back home you slowly look through the photos alone.", "worry": "Something you decided in the heat of the moment snags later: \"Did I think about how they felt?\" When the busy, noisy times go on, you suddenly feel worn out from having no time alone.", "karai": "First to make a move — and the quietest one on the way home."}, "ISFP>ESFP": {"title": "Someone who shares comfort and spreads it among people.", "body": "Valuing the facts in front of you, caring about feelings, and going with the flow are the same in your temperament and your character. On top of that, you have both the ability to enjoy things quietly alone and the energy to light up among people. In lively places you make everyone smile, and in your time alone you sink deep into what you love. You have both the power to spread fun to others and the power to savor things deeply on your own.", "say": "\"Let's all go, it'll be so fun! …And when I get home, I'll look at today's photos by myself.\"", "do": "You throw everything into celebrating a friend's birthday, and the next day you watch your favorite movies in your room all day.", "worry": "The more time you spend in fun places, the harder the tiredness hits afterward. You can't say no to invitations, so you easily run short of time alone.", "karai": "You're the one who says \"Let's hang out again!\" the most — but the next message usually comes from them."}};
var LV={"questions": [{"ax": "EI", "p": "E", "q": "Dates are more fun with friends along than with just the two of us."}, {"ax": "SN", "p": "N", "q": "I've imagined a confession or proposal down to the place and the exact words."}, {"ax": "TF", "p": "T", "q": "After a fight, I first want to sort out what actually caused it."}, {"ax": "JP", "p": "J", "q": "I like to decide where and when we're going on a date ahead of time."}, {"ax": "EI", "p": "I", "q": "When I like someone, I only talk about it with one person I trust."}, {"ax": "SN", "p": "S", "q": "What makes me fall for someone is whether I can relax around them."}, {"ax": "TF", "p": "F", "q": "I quickly notice when the person I like is even a little bit down."}, {"ax": "JP", "p": "P", "q": "I'd rather come up with surprises on the day, depending on my mood."}, {"ax": "EI", "p": "E", "q": "When I'm interested in someone, I'm the one who goes up and starts talking."}, {"ax": "SN", "p": "N", "q": "I love talking with my partner about future dreams and \"what if\" scenarios."}, {"ax": "TF", "p": "T", "q": "When my partner comes to me with a problem, I tend to offer solutions more than feelings."}, {"ax": "JP", "p": "J", "q": "I like to agree early on how often we'll keep in touch and on our ground rules."}], "types": {"INTJ": {"t": "INTJ", "name": "Owl in Love", "tag": "Star-Map Maker for Two", "one": "You draw a map of the future, even in love.", "desc": "You're very careful before you fall for someone. But once you decide, you quietly look ahead to your future together and treasure it. You may not say much, but you always put the choice that's best for your partner first. Sometimes you make a plan before you share your feelings, which can leave your partner a little unsure of where they stand.", "good": ["You never date just for fun", "You think seriously about your future together", "You can truly support your partner's dreams", "You give spot-on answers when they're stuck", "You keep cherishing the one you chose"], "care": ["You can take a very long time to fall for someone", "You answer with what's right instead of with feelings", "You tend to plan the future on your own", "Leaning on others is really hard for you", "Their \"I just feel like it\" can puzzle you"], "tip": "Before giving an answer, pause and say, \"So that's how you felt.\" Reassurance reaches them before being right does.", "best": ["INTP", "You both think about love with your heads. You give direction to their free-flowing ideas, and the conversation never runs dry."], "hard": ["ISFJ", "They show love through small, everyday kindnesses. Your future-focused love may not fill the loneliness they feel right now, so you can easily miss each other."], "words": [["Thinks long-term", 3], ["Falls slowly", 3], ["Only the one", 2], ["Bad at being babied", 2], ["Planned dates", 2], ["Wants the reason", 2], ["Needs alone time", 2], ["Devoted when serious", 2], ["Subtle affection", 1], ["Secret romantic", 1], ["Hides jealousy", 1], ["Deep talk first", 1], ["Opens up slowly", 1], ["Cheating? Never", 1], ["Solutions for problems", 1], ["Love in actions", 1], ["Patient in love", 1], ["Well-pondered confession", 1], ["Trust that lasts", 1]]}, "INTP": {"t": "INTP", "name": "Cat in Love", "tag": "Bashful Love Researcher", "one": "You see the person you like as the most fascinating mystery.", "desc": "When someone catches your interest, you want to know everything about them. You love the little discoveries in conversation and the topics only the two of you share. Until you get close, you may seem a bit aloof, but with someone you trust, you have a soft, cuddly side. Putting your feelings into words takes you a little time.", "good": ["You give your partner freedom, never control", "You're never boring to talk to", "You take a real interest in what they love", "You stay calm instead of getting emotional", "You're surprisingly affectionate once you open up"], "care": ["You forget to text, and they wonder if you've cooled off", "You overthink when asked how you feel", "You sometimes miss anniversaries", "Your logic can leave them deflated", "You go quiet when you're lost in your own world"], "tip": "Try saying even half of what you're thinking out loud. The \"I like you\" in your head won't reach them unless you put it into words.", "best": ["INTJ", "They map out where the two of you are heading, so you can let your curiosity roam freely. A pair that stays up late in deep conversation."], "hard": ["ISFP", "They want to sense feelings through mood and expressions. Your analysis and silence can easily come across as coldness."], "words": [["Studying my crush", 3], ["Cuddly on a whim", 3], ["Forgets to reply", 2], ["Loves deep talks", 2], ["A bit too logical", 2], ["Freedom first", 2], ["Shy cover-up", 2], ["Loyal underneath", 2], ["Our own topics", 1], ["Answers with logic", 1], ["Late-night talks", 1], ["Home dates are fine", 1], ["Analyzes the attraction", 1], ["Aloof at first", 1], ["My own world", 1], ["Advice as analysis", 1], ["Slow-burn love", 1], ["Thinking over texting", 1], ["Nonstop on favorites", 1]]}, "ENTJ": {"t": "ENTJ", "name": "Lion in Love", "tag": "Reliable Romance Director", "one": "You lead your future together, straight ahead.", "desc": "When you like someone, you make the first move and make the relationship clear. You lead without hesitation, from date plans to talks about the future, and you take pride in protecting your partner. You're incredibly dependable, but you sometimes decide things at your own pace and forget to ask how your partner feels.", "good": ["You decide fast and never leave them guessing", "You're the first to protect them in tough times", "You can picture your future together in detail", "You truly support your partner's growth", "You always follow through on promises"], "care": ["You run dates and life a little too much", "You can't show weakness", "Their indecision can frustrate you", "Love gets pushed back when you're busy", "Your advice can sound like orders"], "tip": "Before deciding, ask one question: \"What would you like to do?\" Your lead feels even stronger when their voice is part of it.", "best": ["ENTP", "You turn their free ideas into reality. Even your arguments are fun, an exciting pair."], "hard": ["ESFJ", "You both want to run the plans for the two of you. You decide by efficiency and they decide by feelings, so you can clash over who's in charge."], "words": [["Confesses first", 3], ["Future fully planned", 3], ["Leads the date", 2], ["Protector type", 2], ["Decide, then do", 2], ["Never shows weakness", 2], ["All-in on everything", 2], ["Thrives when relied on", 2], ["Hates dithering", 1], ["I'll book it", 1], ["Says it straight", 1], ["Proud of my partner", 1], ["Busy means \"seen\" only", 1], ["Cheers your growth", 1], ["Secretly gets lonely", 1], ["Clumsy when shy", 1], ["Walks the talk", 1], ["Efficient dates", 1], ["Grand anniversaries", 1]]}, "ENTP": {"t": "ENTP", "name": "Fox in Love", "tag": "Push-and-Pull Magician", "one": "You turn love and conversation into a new game every time.", "desc": "With jokes and bright ideas, you never let your partner get bored. A little playful teasing and a few surprises turn love into a fun puzzle. With someone you click with, you fall hard, but when rules and the same routine drag on, your attention may start to drift.", "good": ["Talking with you is just plain fun", "Your date ideas are new every time", "You enjoy hearing how your partner thinks", "You don't hold on to fights", "You believe in their potential and give them a push"], "care": ["Too much playing hard to get makes them anxious", "You dodge serious talks with jokes", "Fixed plans and rules aren't your thing", "You may win the argument but lose ground in the relationship", "You can seem easily bored"], "tip": "Just for important talks, give the jokes a rest. When you answer seriously, people trust you more than usual.", "best": ["ENTJ", "They seriously turn your bright ideas into reality. A pair that pushes each other and grows together through friendly rivalry."], "hard": ["ESFP", "They want their feelings received straight on. Your jokes and logic can feel like dodging, and that can make them lonely."], "words": [["Master of flirty games", 3], ["Falls through talk", 3], ["Lots of jokes", 2], ["Same date = boring", 2], ["Debate as a date", 2], ["Spontaneous trips", 2], ["Loves to tease", 2], ["Gets bored easily", 2], ["New-spot hunter", 1], ["Awkward when serious", 1], ["Hates being tied down", 1], ["Theorizes about love", 1], ["Last-minute plans", 1], ["Friends with exes", 1], ["Loves making you laugh", 1], ["Into smart people", 1], ["Shy about serious talks", 1], ["Love through banter", 1], ["Loves to surprise", 1]]}, "INFJ": {"t": "INFJ", "name": "Whale in Love", "tag": "Deep-Sea Lighthouse Keeper", "one": "You gently take in the feelings beneath the words.", "desc": "You notice the feelings behind someone's expressions and words faster than anyone. You're looking for someone you can connect with deep in your heart, and once you find them, you quietly care for them for a long time. Because your ideals are high, you sometimes carry hopes you can't voice and end up worn out on your own.", "good": ["You understand their feelings without being told", "You listen seriously to deep talks", "You know their good points better than they do", "You cherish the one you chose for a long time", "When they're lost, you quietly light the way"], "care": ["You project your ideal love onto your partner", "You don't say what you mean and hope they'll guess", "You suddenly close off when hurt", "You wear yourself out reading their feelings in advance", "You struggle alone, then one day just drift away"], "tip": "When you catch yourself wishing they'd just know, take it as a sign to say it. Saying it lets your depth come through.", "best": ["INFP", "You both treasure the tender parts of the heart. You scoop up their feelings, and they give you honesty in return."], "hard": ["ISTJ", "They show feelings through set habits and real actions. You may feel there's too little heart-to-heart talk, and that can get lonely."], "words": [["Reads feelings", 3], ["Believes in fate", 3], ["Heart-to-heart talks", 2], ["High ideals", 2], ["True feelings run deep", 2], ["Loyal for years", 2], ["Hopes you'll just know", 2], ["Loves writing letters", 2], ["Sensitive to my crush", 1], ["Suddenly closes off", 1], ["Finds meaning in us", 1], ["Quiet dates", 1], ["The love-advice listener", 1], ["Over-reads the room", 1], ["Dreams of the future", 1], ["Crowds are draining", 1], ["Careful with words", 1], ["Worn out from sensing", 1], ["Reads between the lines", 1]]}, "INFP": {"t": "INFP", "name": "Hedgehog in Love", "tag": "Shy Love-Letter Poet", "one": "You gently grow tender feelings with care.", "desc": "You picture the person you like in your mind again and again. You're usually reserved, but when someone accepts you as you are, you pour out deep, honest love. You're good at putting your heart into words and small gifts. But you hurt easily, and a single prickly comment can stay with you for a long time.", "good": ["You accept your partner just as they are", "You give heartfelt words and letters", "You find and treasure their small good points", "You connect deeply with people who share your values", "You truly stand by them when things are hard"], "care": ["Fear of getting hurt keeps you from getting close", "The gap between ideal love and reality gets you down", "You swallow what you want to say", "One comment can weigh on you for a long time", "Stories tend to play out in your head"], "tip": "When you're hurt, before your spines go up, say, \"That made me a little sad.\" Once you say it, they can really notice.", "best": ["INFJ", "They pick up even the feelings you can't put into words. A quiet, deep pair where you can open your heart safely."], "hard": ["ISTP", "They lend a hand through actions rather than talking about feelings. The love you want to confirm in words can look like coldness."], "words": [["Great daydreamer", 3], ["Slow to open up", 3], ["Says it in letters", 2], ["Remembers every word", 2], ["Values matter", 2], ["Secretly devoted", 2], ["Feels every love song", 2], ["Gets close slowly", 2], ["Dreams of my crush", 1], ["Easily hurt", 1], ["Confessing takes courage", 1], ["A world for two", 1], ["Just as you are", 1], ["Small gifts", 1], ["Feelings in a notebook", 1], ["Avoids fights", 1], ["Late-night overthinking", 1], ["Cries alone", 1], ["Saves your messages", 1]]}, "ENFJ": {"t": "ENFJ", "name": "Dolphin in Love", "tag": "Your Personal Cheer Squad", "one": "You want to be the biggest supporter of the one you love.", "desc": "You take your partner's dreams and worries to heart as if they were your own, and you cheer them on. You keep conversations lively and you're good at putting feelings into words, so the mood between you stays bright. But you can do so much for your partner that you put your own tiredness and true feelings last.", "good": ["You support their dreams with everything you've got", "You're good at putting feelings into words", "You get along with their friends and family", "You quickly lift them up when they're down", "You work hard to make the relationship better"], "care": ["You try too hard to change your partner", "You feel let down without the reaction you hoped for", "You get anxious when they don't rely on you", "You're slow to notice your own exhaustion", "You avoid fights and give in too much"], "tip": "If there are days you cheer, make days to be cheered on too. It's okay to say, \"Today, I want you to listen.\"", "best": ["ENFP", "You cheer on their sudden ideas and dreams with all you've got and help bring them to life. A pair full of laughter and talk of the future."], "hard": ["ESTJ", "They prefer to move things forward by rules and results rather than feelings. Your caring words can sound roundabout, so you may not mesh well."], "words": [["Always on your side", 3], ["Grows you with praise", 3], ["Says it in words", 2], ["Backs your dreams", 2], ["Loves being needed", 2], ["Long calls OK", 2], ["Anniversary surprises", 2], ["Careful not to overgive", 2], ["Friends with your friends", 1], ["Always giving advice", 1], ["Thanks every day", 1], ["Expects too much", 1], ["Puts self last", 1], ["Loves future talk", 1], ["Brightens the mood", 1], ["Wants to change you", 1], ["The date planner", 1], ["Cries along", 1], ["Listens closely", 1]]}, "ENFP": {"t": "ENFP", "name": "Otter in Love", "tag": "Scenic-Route Love Explorer", "one": "With every love, your world gets bigger.", "desc": "When you're with someone you like, places to go and things to do keep bubbling up. Every time you discover a new side of your partner, you light up, and you show it with your whole self. Your bright belief in what the two of you could be is your charm, but your feelings swing a lot, and the same routine every day isn't your strong suit.", "good": ["You keep finding your partner's good points", "Every date turns into an adventure", "You express your feelings honestly", "You can share their dreams with real excitement", "You bounce back fast when you're down"], "care": ["You start to waver once the early spark settles", "You change plans depending on your mood", "Loneliness can quickly turn into worry", "You put off practical talks", "With so much on your mind, your texting gets spotty"], "tip": "On days when the excitement quiets down, it's not the end. It's the start of something deeper. Going back to your usual spot is a fine adventure too.", "best": ["ENFJ", "They truly cheer on your dreams and ideas and give you a push. A pair whose excitement actually leads to a future."], "hard": ["ESTP", "They enjoy the thrill of the moment. The meaning and future you want to talk about can easily get brushed aside."], "words": [["All-in when in love", 3], ["Detour dates", 3], ["Feelings on my face", 2], ["Easily lonely", 2], ["Future daydreams", 2], ["Hates ruts", 2], ["Loves mutual praise", 2], ["Texting comes in waves", 2], ["Partner = best friend", 1], ["New-spot finder", 1], ["Midnight long calls", 1], ["Many reasons to love", 1], ["Plans change midway", 1], ["Feels fate easily", 1], ["Wants to hold hands", 1], ["Trips for two", 1], ["Shows you off", 1], ["Whole-body love", 1], ["Memories in photos", 1]]}, "ISTJ": {"t": "ISTJ", "name": "Beaver in Love", "tag": "Steady Nest Builder", "one": "You build a sense of safety, one kept promise at a time.", "desc": "In love and in life, you want to move forward one sure step at a time. You may not use flashy words, but you always keep your promises and firmly support your life together. Trust you've built over time doesn't waver easily. Still, sudden changes of plan or love driven by mood can leave you confused.", "good": ["You always keep promises and show up on time", "You're never flaky", "You give practical support to your life together", "You stay with the one you choose for the long run", "Your words and actions always match"], "care": ["Your affection can be too low-key", "Sudden plan changes annoy you", "Dates tend to be the same every time", "You put being right first and miss feelings", "You stay quiet and put up with things instead of speaking up"], "tip": "Once a month, add one thing that's different from usual to your steady routine. A small change makes your days together even more fun.", "best": ["ISTP", "You both talk little and show feelings through actions. They loosen up the promises you keep with their easygoing way, and you last quietly for a long time."], "hard": ["INFJ", "They want to understand the feelings beneath the words. Your sincere actions alone may not be enough, and they may ask, \"How do you really feel?\""], "words": [["Promises are sacred", 3], ["Slow and sure", 3], ["Always on time", 2], ["Classic dates", 2], ["Never cheats", 2], ["Solid future", 2], ["Love in actions", 2], ["Thrown by change", 2], ["Texts at set times", 1], ["Anniversaries in planner", 1], ["Saving for us", 1], ["No sudden plans", 1], ["Long relationships", 1], ["Too shy to say", 1], ["Shared chores", 1], ["Keeps every memento", 1], ["Trust first", 1], ["Practical gifts", 1], ["Same favorite spot", 1]]}, "ISFJ": {"t": "ISFJ", "name": "Bear in Love", "tag": "Warm Blanket Keeper", "one": "Just being near you puts people at ease.", "desc": "You're always checking whether the one you love is cold or tired. You don't do anything showy, but you quietly support them, like handing over a warm drink. You remember their tastes and habits well and you're great at making a safe place to be. But you tend to keep your own loneliness to yourself.", "good": ["You notice their health and tiredness right away", "Your quiet thoughtfulness never stops", "Being with you calms the heart", "You remember what they like", "You get better the longer you're together"], "care": ["You can't say no to things you don't like", "After giving so much, you wait for something back", "Fear of change makes you stick with how things are", "You adjust so much you lose yourself", "You hold it in until your limit, then tears suddenly come"], "tip": "When you're about to say \"I'm fine,\" check once whether you really are. Showing weakness doesn't take anything away from your warmth.", "best": ["ISFP", "Your quiet thoughtfulness fits their calm, easygoing pace. A pair whose quiet, warm moments last a long time."], "hard": ["INTJ", "They show love through long-term plans and logic. The everyday care you value can be easy for them to overlook."], "words": [["Quiet support", 3], ["Cozy home dates", 3], ["Thoughtful", 2], ["\"I'm fine\" habit", 2], ["Brings treats", 2], ["Knows your tastes", 2], ["Holds it in", 2], ["Here to stay", 2], ["\"Aren't you cold?\"", 1], ["Homemade lunches", 1], ["Can't say I'm lonely", 1], ["Waits for something back", 1], ["Wary of change", 1], ["Safety first", 1], ["Usually the listener", 1], ["Our usual spot", 1], ["Treasured keepsakes", 1], ["Shy", 1], ["Checks on your health", 1]]}, "ESTJ": {"t": "ESTJ", "name": "Elephant in Love", "tag": "Foreman of Promises", "one": "You reliably keep your days together on track.", "desc": "You like to move forward in love with clear lines. Dating, meeting up, deciding on the future: you say it clearly and follow through as promised. You're dependable, and things get done when you're around. But you can assume your way is the right way and put the plan ahead of your partner's feelings.", "good": ["You always keep your word", "Your date planning is flawless", "You think realistically about your future together", "You're reliable when trouble comes", "You make the relationship clear"], "care": ["You can push your way of doing things", "You cut off feelings talk with \"So what's the point?\"", "You're strict about broken rules", "You don't let yourself look weak", "Romantic gestures make you feel awkward"], "tip": "Before asking whether it's right, ask how your partner feels right now. It adds one more layer of kindness to your reliability.", "best": ["ESTP", "You bring planning and security to their energy and drive. A pair whose days move along at a good pace."], "hard": ["ENFJ", "They want to put feelings into words and share them. Your plans and logic can look like you're leaving their heart behind."], "words": [["Clear lines matter", 3], ["I'll handle it", 3], ["Strict about time", 2], ["Marriage by plan", 2], ["Dependable", 2], ["Bottom line first", 2], ["Shy about romance", 2], ["Open about dating", 2], ["Reservations set", 1], ["Rule follower", 1], ["Runs the budget", 1], ["Can't help being right", 1], ["Fine even when tired", 1], ["Introduces you to family", 1], ["No lateness allowed", 1], ["\"Leave it to me\"", 1], ["Birthdays on schedule", 1], ["Promises in writing", 1], ["Someone to lean on", 1]]}, "ESFJ": {"t": "ESFJ", "name": "Penguin in Love", "tag": "Guardian of Anniversaries", "one": "You carefully build up your days together, one by one.", "desc": "You put your partner at the center of your life and take good care of each day. You remember anniversaries, favorite foods and how they're feeling, and you act before they ask. The sense of security you give is unbeatable, but you can give so much that you put your own feelings last.", "good": ["You never forget anniversaries or what they like", "You're the first to notice when they feel unwell", "You get along with their family and friends", "You keep promises, so trust keeps growing", "Your life together runs smoothly with you"], "care": ["You wear yourself out giving too much", "Without a \"thank you,\" you quietly get hurt", "You almost end up managing their schedule too", "You store up complaints and let them out all at once", "You worry too much about what others think"], "tip": "Before what you want to do for them, share one thing you'd like them to do for you today.", "best": ["ESFP", "You turn the fun they bring into anniversaries and traditions. A lively pair that really lasts."], "hard": ["ENTJ", "You both want to run the plans for the two of you. You decide by feelings and they decide by efficiency, so you can clash over who's in charge."], "words": [["Remembers every anniversary", 3], ["Natural giver", 3], ["Sense of security", 2], ["Texts often", 2], ["Home cooking", 2], ["Wants a thank-you", 2], ["Partner first", 2], ["Close with your family", 1], ["Health check", 1], ["Makes our rules", 1], ["Swallows jealousy", 1], ["Cares what others think", 1], ["Thinking about marriage", 1], ["Caretaker", 1], ["Keeps promises", 1], ["Saves up complaints", 1], ["Wants to be needed", 1], ["Our shared calendar", 1]]}, "ISTP": {"t": "ISTP", "name": "Wolf in Love", "tag": "Quiet Spare-Key Maker", "one": "Few words, but you hand over trust through actions.", "desc": "Saying \"I like you\" out loud isn't easy for you. But you fix what's broken and quietly show up when they're in trouble. Like handing over a spare key, you turn trust into something real, little by little. You value your own time too, so a clingy relationship can feel a bit cramped.", "good": ["You're the most reliable person in a pinch", "You don't try to control, so you're easy to be with", "You don't say much, but you never lie", "You lend a hand without fuss", "Silence between you is never awkward"], "care": ["You say \"I like you\" so rarely that they worry", "Your texts can seem curt", "You get irritated when your alone time gets cut", "You go quiet when feelings come up", "Before you know it, they feel far away"], "tip": "Once a month is enough: say \"thank you\" and \"I like you\" in words. The meaning of your actions will come across many times more.", "best": ["ISTJ", "You both show feelings through actions more than words. You can rely on the promises they keep, and you last quietly for a long time."], "hard": ["INFP", "They want to share feelings slowly in words. Your \"eh, it's fine\" can feel like you're taking their feelings lightly."], "words": [["Shows it in actions", 3], ["No control", 3], ["Few words", 2], ["Helps quietly", 2], ["The fix-it person", 2], ["Loyal at heart", 2], ["Short replies", 2], ["Alone time needed", 1], ["No lies", 1], ["Feelings talk? Hmm", 1], ["Fine with silence", 1], ["Handy", 1], ["Dependable", 1], ["Shy", 1], ["Forgets anniversaries", 1], ["Spare key = trust", 1], ["Replies with stickers", 1], ["Your seat is shotgun", 1]]}, "ISFP": {"t": "ISFP", "name": "Panda in Love", "tag": "Painter of Everyday Moments", "one": "You paint ordinary days in gentle colors.", "desc": "You're calm and go at your own pace. But you savor ordinary time with the one you love more than anyone. Instead of words, you show your feelings through the food you shared, the views you saw and the gifts you picked. You don't like conflict and tend to laugh things off even when you're upset. Then, before anyone notices, you may have already pulled away.", "good": ["They never have to tiptoe around you", "You respect your partner's pace", "You pick gifts with great taste", "You make ordinary days feel special", "You accept your partner without judging"], "care": ["You're slow to put feelings into words", "When a fight looms, you quietly slip away", "Tightly fixed plans wear you out", "Instead of voicing complaints, you quietly drift away", "You keep putting off talks about the future"], "tip": "When something bothers you, say just one word while it's still small. It's a much kinder choice for both of you than pulling away in silence.", "best": ["ISFJ", "Their careful thoughtfulness gently wraps around your easygoing pace. A pair whose calm, cozy time keeps going."], "hard": ["INTP", "They like to sort out feelings through analysis and debate. Being asked for reasons when you just want to go with what you feel can wear you out."], "words": [["My-pace romance", 3], ["Loves ordinary days", 3], ["Gifts with taste", 2], ["Avoids conflict", 2], ["Feelings through mood", 2], ["Hates being tied down", 2], ["Lazy dates", 2], ["Sharing the view", 2], ["Food dates", 1], ["Loose plans", 1], ["Few words", 1], ["Quietly steps back", 1], ["Loves holding hands", 1], ["Naps together", 1], ["Never judges", 1], ["Meets on a whim", 1], ["Future can wait", 1], ["Shy smile", 1], ["Five-senses dates", 1]]}, "ESTP": {"t": "ESTP", "name": "Cheetah in Love", "tag": "Instant-Date Sprinter", "one": "The moment you like someone, you're off and running.", "desc": "When someone catches your eye, you go see them before you even think twice. Day trips and fun plans are decided on the spot, and you whisk your partner off to exciting times. You're great at keeping things fun through action, and being with you is never dull. But because you live in the moment, feelings talk and future promises tend to get pushed back.", "good": ["Your approach is clear and easy to read", "Being with you is never boring", "You act fast when trouble comes", "You don't dwell on little things", "You take them out for new experiences"], "care": ["You close the distance too fast in the heat of the moment", "You tend to find feelings talk \"too heavy\"", "When you get bored, your replies suddenly drop off", "Promises about the future are hard for you", "You forget things you said on a whim"], "tip": "At the end of a fun date, take one minute to ask, \"How was today?\" Knowing their feelings too makes love go deeper.", "best": ["ESTJ", "They catch your momentum with planning and security. A pair whose energy turns straight into memories."], "hard": ["ENFP", "They want to talk about what the two of you mean and where you're going. The more you enjoy the moment, the lighter your feelings may look to them."], "words": [["Instant approach", 3], ["Active dates", 3], ["Spur-of-the-moment trips", 2], ["No mind games", 2], ["Living for now", 2], ["Bored means \"seen\"", 2], ["Quick to act", 2], ["Not into heavy talk", 2], ["Sports dates", 1], ["Fired up by games", 1], ["Surprise trips", 1], ["Never dwells", 1], ["Promises on a whim", 1], ["Confident", 1], ["Brings friends along", 1], ["Quick to bounce back", 1], ["Future plans TBD", 1], ["Love through touch", 1], ["\"Free today?\"", 1]]}, "ESFP": {"t": "ESFP", "name": "Parakeet in Love", "tag": "Heart-Flutter Fireworks Artist", "one": "You turn love into an everyday celebration.", "desc": "Once you fall for someone, you go all in. Every time you meet, you prepare little surprises and fun plans that turn your time together into a festival. You show your feelings straight through words and actions, so your partner always feels loved. But the quiet moments after the excitement settles can be a little hard for you.", "good": ["Just being with you is fun", "You can say \"I like you\" straight out", "You notice and praise their small changes", "Every spontaneous date becomes a memory", "You can make them laugh when they're down"], "care": ["When the thrill fades, you worry they've cooled off", "You make promises in the moment, then struggle later", "Slow replies make your loneliness explode", "You tend to laugh fights away", "You suddenly go quiet when the future comes up"], "tip": "On quieter days, treasure the feeling of \"being together is calming.\" Quiet time is part of your memories too.", "best": ["ESFJ", "They turn your sudden ideas into anniversaries and plans that last. A pair with both fun and security."], "hard": ["ENTP", "They enjoy bringing games and debate into love. When you want feelings back, logic comes instead, and that can feel lonely."], "words": [["All-out love", 3], ["Loves surprises", 3], ["Love gives me energy", 2], ["Lonely when apart", 2], ["Spontaneous dates", 2], ["Great at praise", 2], ["Sweet and clingy", 2], ["Photos pile up", 1], ["Every day's an event", 1], ["Lots of touch", 1], ["Jealousy shows", 1], ["Loves love talk", 1], ["Falls at first sight", 1], ["Instant replies", 1], ["Future talk is hard", 1], ["Bright even in fights", 1], ["Friend-approved couple", 1], ["Easily moved to tears", 1], ["Moody", 1], ["Life of the party", 1]]}}};
var D={"NICK": {"INTJ": "Has the answer before speaking", "INTP": "Lost down a search rabbit hole", "ENTJ": "\"Fine, I'll decide\"", "ENTP": "\"But what if...\" on repeat", "INFJ": "Notices without being told", "INFP": "A movie theater in their head", "ENFJ": "Can't help taking care of people", "ENFP": "Excitement comes first", "ISTJ": "Turns it in before the deadline", "ISFJ": "Already helping before anyone asks", "ESTJ": "Makes the schedule first", "ESFJ": "Somehow always the organizer", "ISTP": "Touches it before reading the manual", "ISFP": "Picks whatever they love", "ESTP": "Moving before thinking", "ESFP": "Decides on a whim"}, "ARUARU": {"INTJ": ["Already knows the answer in meetings, but stays quiet", "Gets quietly annoyed when plans fall apart", "Would rather skip small talk and get to the point", "Works fastest on tasks they can finish alone", "Can't understand people who decide \"just because\""], "INTP": ["Starts looking something up and ends up somewhere else entirely", "Wants to ask, \"But how do we define that?\"", "Things they don't care about just won't stick", "Thinks more clearly at night", "Explanations tend to run long"], "ENTJ": ["Can't stand meetings that never decide anything", "Ends up running the show without noticing", "Hates wasted time more than anything", "The bigger the goal, the more fired up", "Can't say no when people count on them"], "ENTP": ["Says the idea out loud, then thinks about it", "Grows every conversation with \"But what if...\"", "Gets bored fast", "Debating isn't fighting, it's playing", "Downloads every new app just to try it"], "INFJ": ["Notices someone's off before they say a word", "Rarely shows their real feelings", "Needs alone time after crowds", "Can't spend time on things that feel pointless", "Everyone comes to them for advice, but they never ask for any"], "INFP": ["Rehearses conversations in their head", "Suddenly talks a lot when it's about something they love", "Practical talk wears them out", "Remembers things people said years ago", "Won't give up on what feels right inside"], "ENFJ": ["Watches everyone's faces while talking", "Can't say no when asked", "Puts themselves last", "Brings up a topic when the room goes quiet", "Feels as happy about others' growth as their own"], "ENFP": ["Conversations jump three topics at once", "So many things to do, they're stuck in traffic", "Cleans their room right before a deadline", "Gets close with people they just met", "Loses interest all at once when bored"], "ISTJ": ["Finishes plans ahead of schedule", "Bothered by people who break the rules", "Everything has its set place", "Quietly thrown off by sudden changes", "Doesn't want to change a method once it's set"], "ISFJ": ["Notices first and acts first", "Says \"I'm fine\" while holding it in", "Remembers what people like", "Doesn't want the spotlight", "Happy when people count on them"], "ESTJ": ["Settles the plan before anything else", "Vague instructions are irritating", "Strict about time", "Sees every job through to the end", "Can sound harsh with people close to them"], "ESFJ": ["Somehow ends up organizing the get-together", "Keeps an eye on everyone's health and mood", "Gets lonely after too much time alone", "Remembers anniversaries", "Wants to check that nobody dislikes them"], "ISTP": ["Touches it before reading the manual", "Reads the group chat but never replies", "Not into pointless chatter", "When something breaks, tries fixing it first", "Stops dead the moment interest runs out"], "ISFP": ["Can't choose something that doesn't click", "Their own taste over the latest trend", "Hates being rushed", "Particular about photos and how things are arranged", "Doesn't get angry, but inside won't budge"], "ESTP": ["Body moves before the brain does", "Boredom is the worst", "Reads the room in seconds", "Better at handling things on the spot than planning", "Cleanup can wait"], "ESFP": ["Makes plans on a whim", "Loves taking photos", "Feeling down? A good sleep fixes it", "Often the one who lights up the room", "Can't keep at dull tasks for long"]}, "TCOMPAT": {"INTJ": {"m": "ENTP", "why": "An idea person who brings fresh air to your strategy."}, "ENTP": {"m": "INTJ", "why": "Turns your sparks into a solid plan."}, "INTP": {"m": "ENTJ", "why": "The doer who shapes your ideas and moves them forward."}, "ENTJ": {"m": "INTP", "why": "The brains who widens your thinking with fresh views."}, "INFJ": {"m": "ENFP", "why": "Brightly draws out the feelings you keep inside."}, "ENFP": {"m": "INFJ", "why": "Quietly deepens the dreams you spread wide."}, "INFP": {"m": "ENFJ", "why": "A reassuring guide who truly cheers on your ideals."}, "ENFJ": {"m": "INFP", "why": "A sincere person who needs your kindness."}, "ISTJ": {"m": "ESTP", "why": "Brings spark and drive to your steady ways."}, "ESTP": {"m": "ISTJ", "why": "Backs up your momentum with solid ground."}, "ISFJ": {"m": "ESFP", "why": "The mood-lifter who brightens your seriousness."}, "ESFP": {"m": "ISFJ", "why": "A reassuring presence who quietly supports your fun."}, "ISTP": {"m": "ESTJ", "why": "Sets up the place where your skills can shine."}, "ESTJ": {"m": "ISTP", "why": "A calm expert you can count on when it matters."}, "ISFP": {"m": "ESFJ", "why": "Warmly supports you as you go at your own pace."}, "ESFJ": {"m": "ISFP", "why": "Easygoing and real, their honest sense of things is soothing."}}, "GAP_USE": {"IE": {"h": "充電｜内向き → 外向き に変身", "t": "ほんとうは一人で充電する人が、人と関わる力を装備した状態。人前のあとにどっと疲れるのは、気のせいじゃなく装備の重さです。予定のあとに“ひとり時間”を確保すると、回復が一気に速くなります。"}, "EI": {"h": "充電｜外向き → 内向き に変身", "t": "ほんとうは人といて充電する人が、今はひとりモード。最近なんとなく元気が出ないなら、原因は“人との時間の不足”かも。気のおけない人と会う予定をひとつ入れるだけで、驚くほど復活します。"}, "SN": {"h": "見方｜現実派 → 直感派 に変身", "t": "地に足のついた現実派が、ひらめきで動く力を獲得。アイデアが浮かんでも「ほんとに大丈夫？」と不安になるのは、素の現実感覚が生きている証拠。ひらめきを素の現実力で検算すれば最強です。"}, "NS": {"h": "見方｜直感派 → 現実派 に変身", "t": "本来ひらめき型のあなたが、現実的にふるまう力を装備。ときどき無性に“夢の話”がしたくなるのは、素の顔の呼吸です。空想の時間はサボりじゃなく、あなたの充電です。"}, "TF": {"h": "決め方｜論理派 → 共感派 に変身", "t": "本来スジで決める人が、人に合わせて受け止める力を獲得。合わせたあとに「本音を言えばよかった」とモヤモヤしやすいタイプ。大事な決断だけは、素のロジックに戻って決めると後悔しません。"}, "FT": {"h": "決め方｜共感派 → 論理派 に変身", "t": "本来は気持ちで決める人が、冷静に判断する鎧を装備。クールに見えて、内側では感情がちゃんと動いています。ときどき“好きか嫌いか”だけで選ぶと、心の疲れがすっと取れます。"}, "JP": {"h": "動き方｜計画派 → 自由派 に変身", "t": "本来は計画派なのに、流れに乗る柔軟さを獲得。自由に見えて、心のどこかで“決まっていない不安”を感じやすい人です。ざっくりでも予定を置くと、安心して楽しめます。"}, "PJ": {"h": "動き方｜自由派 → 計画派 に変身", "t": "本来は自由派なのに、段取りの力を身につけた人。きっちりこなせるのに、たまに全部投げ出したくなるのはこのせい。“予定のない日”を先にカレンダーに入れておくのがコツです。"}}, "COLOR": {"INTJ": {"name": "深い藍", "hex": "#27406B", "line": "夜明け前の藍。静かに全体を見渡す色。"}, "INTP": {"name": "アイスブルー", "hex": "#79B6D9", "line": "澄んだ氷の青。思考が透きとおる色。"}, "ENTJ": {"name": "クリムゾン", "hex": "#C8102E", "line": "燃える深紅。目標へ突き進む色。"}, "ENTP": {"name": "エレクトリックオレンジ", "hex": "#FF6A2C", "line": "火花のオレンジ。刺激を生み出す色。"}, "INFJ": {"name": "アメジスト", "hex": "#6A4C93", "line": "神秘の紫。静かな理想を秘めた色。"}, "INFP": {"name": "ラベンダー", "hex": "#B79CE0", "line": "淡い藤色。やさしく夢みる色。"}, "ENFJ": {"name": "コーラル", "hex": "#FF8364", "line": "夕日のコーラル。人を照らすあたたかな色。"}, "ENFP": {"name": "ビビッドイエロー", "hex": "#FFD23F", "line": "弾ける黄色。その場を明るくする色。"}, "ISTJ": {"name": "ディープグリーン", "hex": "#2F6B5E", "line": "落ち着いた深緑。ぶれない芯の色。"}, "ISFJ": {"name": "ソフトピーチ", "hex": "#F4C9A8", "line": "やわらかな桃色。そっと包む色。"}, "ESTJ": {"name": "ロイヤルブルー", "hex": "#2457C5", "line": "堂々のブルー。頼れる芯の色。"}, "ESFJ": {"name": "ウォームローズ", "hex": "#F77FA1", "line": "あたたかな薔薇色。みんなを和ませる色。"}, "ISTP": {"name": "ガンメタル", "hex": "#8C97A0", "line": "クールな銀。無駄のない色。"}, "ISFP": {"name": "セージグリーン", "hex": "#8FBF9F", "line": "やさしい若草。自然体でいられる色。"}, "ESTP": {"name": "ネオンレッド", "hex": "#FF3B30", "line": "躍動の赤。動くほど光る色。"}, "ESFP": {"name": "ホットピンク", "hex": "#FF2E9A", "line": "華やぐマゼンタ。主役のオーラの色。"}}, "URA": {"INTJ": "じつは、頭の中では何手も先まで読んで、もう一人で完結している。", "INTP": "じつは、「なんで？」が止まらず、夜中に関係ない調べ物で時間が溶ける。", "ENTJ": "じつは、任されないとソワソワ。仕切りたくて手がうずうずしている。", "ENTP": "じつは、思いつきを口に出してから「どうしよう」と考えはじめる。", "INFJ": "じつは、ニコニコしながら相手の本音を静かに見抜いている。", "INFP": "じつは、頭の中で壮大なストーリーが毎日上映されている。", "ENFJ": "じつは、みんなを気づかうあまり、自分のことは後回しにしがち。", "ENFP": "じつは、やりたいこと多すぎて、半分は途中で次へ移っている。", "ISTJ": "じつは、段取りを乱す人に、心の中でこっそりイラッとしている。", "ISFJ": "じつは、「大丈夫」と言いながら、いちばん我慢している。", "ESTJ": "じつは、ゆるい計画を見ると、つい口を出したくてうずうず。", "ESFJ": "じつは、嫌われてないかな…と、こっそり空気を確認している。", "ISTP": "じつは、興味ないことには無関心。好きなことには無限に集中する。", "ISFP": "じつは、マイペースに見えて、譲れない美学はかなり頑固。", "ESTP": "じつは、退屈がいちばん苦手。刺激がないと自分で作りにいく。", "ESFP": "じつは、楽しそうにしながら、場の空気をいちばん読んでいる。"}, "QUOTE": {"INTJ": ["So what's the end goal?", "There's a more efficient way to do that", "All within expectations"], "INTP": ["Well, that depends on the definition", "Let me look into it", "I get the logic. But why?"], "ENTJ": ["Bottom line:", "Who does it, and by when?", "Leave it to me. I'll decide"], "ENTP": ["Okay, but what if", "Isn't that interesting?", "Let me play devil's advocate"], "INFJ": ["What do you really want?", "I kind of knew already", "Won't that hurt them?"], "INFP": ["Is that really me?", "Let me think about it", "Isn't \"because I love it\" enough?"], "ENFJ": ["What does everyone think?", "It's okay, let's do it together", "You can do it"], "ENFP": ["That's so good!", "So I just had an idea", "Let's just try it!"], "ISTJ": ["Last time, we did it like this", "I'll confirm and get back to you", "Those are the rules"], "ISFJ": ["Are you okay? Not overdoing it?", "I'll take care of it", "If everyone's fine with it, so am I"], "ESTJ": ["Let's set the schedule first", "So what's the deadline?", "Rules are rules"], "ESFJ": ["Let's all do it together", "I brought snacks!", "Isn't that unfair to her?"], "ISTP": ["You'll see once you try", "Either way is fine", "Hand it over, I'll fix it"], "ISFP": ["It just felt nice", "I'll go at my own pace", "It's hard to put into words"], "ESTP": ["Let's just go", "Moving beats thinking", "It'll work out"], "ESFP": ["If it's fun, isn't that enough?", "How about right now?", "Let's take a photo!"]}};
var QZ={"Q": [{"ax": "EI", "p": "E", "q": "After a few weekends with no plans, I want to reach out to someone", "ex": "On Sunday night after a whole weekend at home, I'm the one texting \"Dinner next week?\""}, {"ax": "SN", "p": "S", "q": "When I start something new, I check the steps and how-to first", "ex": "With a new appliance, I read the manual or watch a how-to video before using it"}, {"ax": "TF", "p": "T", "q": "When someone comes to me with a problem, I start thinking of solutions", "ex": "While a friend vents, I'm already working out \"What if you tried this?\" in my head"}, {"ax": "JP", "p": "J", "q": "I finish my tasks before the deadline", "ex": "Work due Friday is already done by Wednesday"}, {"ax": "AT", "p": "A", "q": "Even when I fail, I can move on fairly quickly", "ex": "If I make a mistake at work, I don't carry it past that day"}, {"ax": "EI", "p": "I", "q": "I make sure to have time alone before and after seeing people", "ex": "The day after a night out, I keep my schedule empty and stay home"}, {"ax": "SN", "p": "N", "q": "When I talk, the topic keeps branching out", "ex": "We start on travel plans and somehow end up on where we want to live someday"}, {"ax": "TF", "p": "F", "q": "When someone comes to me with a problem, I take in their feelings first", "ex": "After listening, the first thing I say is \"That sounds really hard\""}, {"ax": "JP", "p": "P", "q": "When plans suddenly change, I actually enjoy it", "ex": "When I hear \"Today's plans are off,\" I get excited about what to do instead"}, {"ax": "AT", "p": "T", "q": "I keep going back over things that are already done", "ex": "After a conversation, I wonder, \"Was that the right way to say it?\""}, {"ax": "EI", "p": "E", "q": "Even at gatherings where I know few people, I start conversations", "ex": "At a party with new faces, I'm the one asking the person next to me questions"}, {"ax": "SN", "p": "S", "q": "When I talk, I include concrete numbers and facts", "ex": "I say \"We waited 40 minutes\" instead of \"It was super crowded\""}, {"ax": "TF", "p": "T", "q": "For big decisions, I weigh the pros and cons", "ex": "When moving or changing jobs, I write out the conditions and compare them"}, {"ax": "JP", "p": "J", "q": "I feel calmer when my weekend plans are set in advance", "ex": "If it's Friday night and the weekend still has no plans, I get restless"}, {"ax": "AT", "p": "A", "q": "I don't really worry about what people think of me", "ex": "If my posts get few reactions, it doesn't bother me much"}, {"ax": "EI", "p": "I", "q": "Before speaking, I sort out my thoughts in my head first", "ex": "When asked for my opinion in a meeting, I want a moment to think"}, {"ax": "SN", "p": "N", "q": "I care about \"what it all comes down to\" before the details", "ex": "During a long explanation, I want to sum it up: \"So basically...\""}, {"ax": "TF", "p": "F", "q": "When I decide, I think about how the people involved will feel", "ex": "Even if a plan is right, I drop it if it might hurt someone"}, {"ax": "JP", "p": "P", "q": "I really get going only when the deadline is close", "ex": "Work I had two weeks for, I finish in a focused push over the last three days"}, {"ax": "AT", "p": "T", "q": "I easily notice changes in people's reactions or expressions", "ex": "If a reply feels curt, I worry I've upset them"}, {"ax": "EI", "p": "E", "q": "My thoughts come together as I talk them through with someone", "ex": "When I'm torn, my answer becomes clear while I'm talking to a friend"}, {"ax": "SN", "p": "S", "q": "I trust what I've tried and checked for myself", "ex": "Even if a restaurant gets great reviews, I won't call it good until I've been"}, {"ax": "TF", "p": "T", "q": "When we disagree, I explain my reasons rather than go along", "ex": "If I'm not convinced by a plan, I say \"That would cause trouble for X\""}, {"ax": "JP", "p": "J", "q": "I decide what to buy before I go shopping", "ex": "I take a list to the supermarket and buy exactly what's on it"}, {"ax": "AT", "p": "A", "q": "I don't second-guess decisions I've made myself", "ex": "After choosing something while shopping, I don't think \"I should've gotten the other one\""}, {"ax": "EI", "p": "I", "q": "Deep talks with a few people are more fun than a big group", "ex": "I'd pick a long chat with two or three people over a party of ten"}, {"ax": "SN", "p": "N", "q": "I often imagine \"What if...\"", "ex": "On my commute, I think \"What if I weren't in this job?\""}, {"ax": "TF", "p": "F", "q": "When the mood around me is tense, I can't settle either", "ex": "If someone's in a bad mood, I can't focus on my own stuff"}, {"ax": "JP", "p": "P", "q": "For trips, I plan roughly and figure things out once I'm there", "ex": "I book only the place to stay and decide where to go based on how I feel that day"}, {"ax": "AT", "p": "T", "q": "Even after deciding, I wonder if it was really the right choice", "ex": "After ordering, I keep eyeing the other dishes on the menu"}, {"ax": "EI", "p": "E", "q": "After seeing people, I have more energy", "ex": "On the way home from three hours of talking, \"I want to talk more\" beats feeling tired"}, {"ax": "SN", "p": "S", "q": "I'm better at improving the current way than inventing a new one", "ex": "Rather than rethinking from scratch, I cut the waste from the current steps"}, {"ax": "TF", "p": "T", "q": "If I'm praised, \"reliable\" makes me happier than \"kind\"", "ex": "Hearing \"You saved me, as expected!\" makes me feel most rewarded"}, {"ax": "JP", "p": "J", "q": "I finish one thing before moving on to the next", "ex": "While I'm in the middle of a book, I don't open the next one"}, {"ax": "AT", "p": "A", "q": "Even with something new, I feel it'll work out somehow", "ex": "When I'm handed a new kind of job, excitement wins over worry"}, {"ax": "EI", "p": "I", "q": "I reply to messages when it suits me rather than right away", "ex": "Even when I see a message, I wait until I've settled down to reply"}, {"ax": "SN", "p": "N", "q": "I'd rather try a new way than stick to the usual one", "ex": "Even though I have my usual route, I try a street I don't know"}, {"ax": "TF", "p": "F", "q": "When I team up with someone, I choose by personality over ability", "ex": "I'd rather work with someone pleasant than someone who's just good at the job"}, {"ax": "JP", "p": "P", "q": "Working on several things at once suits me", "ex": "I switch back and forth between three tasks depending on my mood"}, {"ax": "AT", "p": "T", "q": "Before important moments, I want to check things again and again", "ex": "I reread an email three times before sending it"}, {"ax": "EI", "p": "E", "q": "In group conversations, I find I'm the one doing the talking", "ex": "In a group of five, I'm more often the talker than the listener"}, {"ax": "SN", "p": "S", "q": "When I learn something, I want the steps in order first", "ex": "For a new app, I'd rather learn one action at a time than get the big picture"}, {"ax": "TF", "p": "T", "q": "When I hear someone's opinion, I first wonder whether it's correct", "ex": "While a friend talks, I'm thinking, \"Is that really true?\""}, {"ax": "JP", "p": "J", "q": "I check my belongings before I leave the house", "ex": "Every time, I check my wallet, keys and phone one by one"}, {"ax": "AT", "p": "A", "q": "When I'm praised, I can simply accept it", "ex": "When someone says \"That's amazing,\" I can just say \"Thank you\""}, {"ax": "EI", "p": "E", "q": "I'm fairly excited to go to gatherings full of people I don't know", "ex": "I happily join events I'm invited to, even if I won't know anyone"}, {"ax": "SN", "p": "S", "q": "I start with the way that worked before", "ex": "When planning a trip, I follow the route and booking method that went well last time"}, {"ax": "TF", "p": "T", "q": "For important things, I set my feelings aside before deciding", "ex": "Even when I'm angry, I sleep on it before deciding"}, {"ax": "JP", "p": "J", "q": "I like writing out my to-dos and crossing them off", "ex": "I jot down my plans for the day and draw a line through each one I finish"}, {"ax": "AT", "p": "T", "q": "Even when I'm praised, I notice where I fell short", "ex": "Even when told \"That was great,\" I remember the parts that didn't go well"}, {"ax": "EI", "p": "I", "q": "After a full day of talking with people, I want time alone at night", "ex": "Even after a fun night out, I want to walk home quietly by myself"}, {"ax": "SN", "p": "N", "q": "When I hear someone's story, other ideas pop up right away", "ex": "From a friend's story, I'm already thinking \"Then you could also do X\""}, {"ax": "TF", "p": "F", "q": "When someone's in trouble, I help before taking care of my own things", "ex": "Even when I'm busy, I find myself helping a coworker"}, {"ax": "JP", "p": "P", "q": "When plans get too detailed, I actually lose motivation", "ex": "When someone makes a minute-by-minute plan, it suddenly feels like a chore"}, {"ax": "AT", "p": "A", "q": "I don't get very nervous speaking in front of people", "ex": "Even when suddenly asked for my opinion, I can speak calmly"}, {"ax": "EI", "p": "I", "q": "Texting feels easier than calling", "ex": "When I need something, I send a message rather than call"}, {"ax": "SN", "p": "N", "q": "I'm drawn to things nobody has done yet", "ex": "I'm more curious about what's coming next than what's popular now"}, {"ax": "TF", "p": "F", "q": "If I'm praised, \"kind\" makes me happier than \"reliable\"", "ex": "Hearing \"Thanks for always looking out for me\" makes me feel most rewarded"}, {"ax": "JP", "p": "P", "q": "When an idea hits, I start even if I'm not fully ready", "ex": "I start cooking a dish I'm curious about even if I'm missing a few ingredients"}, {"ax": "AT", "p": "T", "q": "My mood goes up and down quite a lot", "ex": "Within the same week, I have very upbeat days and days when I feel low"}], "TB": {"EI": {"q": "At the end of a tiring week, what recharges you on Friday night?", "a": ["Dinner with friends", "E"], "b": ["Time alone at home", "I"]}, "SN": {"q": "When you get a new job to do, what do you want to know first?", "a": ["The exact steps and past examples", "S"], "b": ["The goal and the big picture", "N"]}, "TF": {"q": "A friend is about to make a clearly wrong choice. What do you do?", "a": ["Tell them my reasons clearly", "T"], "b": ["Ask how they feel first, then think", "F"]}, "JP": {"q": "You get a week off. What do you do?", "a": ["Plan things out in advance", "J"], "b": ["Decide nothing and go with the mood each day", "P"]}, "AT": {"q": "A big presentation is tomorrow. How are you the night before?", "a": ["Trust it'll work out and go to bed early", "A"], "b": ["Keep going over my prep again and again", "T"]}}};
var COMBO={"ISTJ>INTJ": {"karai": "You play the far-sighted one, but when the unexpected hits, you're the first to freeze.", "name": "The Visionary Who Loves Precedent", "atari": ["[[今:You talk up the five-year plan]], but [[本:deep down, last year's way of doing things is what feels safest]].", "[[今:Even in a brainstorm for fresh ideas]], [[本:part of your brain is quietly opening the old files folder]]."]}, "ISTJ>INTP": {"karai": "You call yourself a free spirit, yet your desk drawers have been labeled and lined up for years.", "name": "The Lost Researcher Who Never Runs Late", "atari": ["[[今:Once you start digging into something, you can't stop]], yet [[本:your body somehow never forgets a due date]].", "[[今:You say \"eh, it'll work out\"]], then [[本:go home and lay out tomorrow's things in a neat little row]]."]}, "ISTJ>ENTJ": {"karai": "Every time someone calls you a dependable leader, you trudge home and buy yourself a sweet treat to recover.", "name": "The Backstage Pro Turned Leader", "atari": ["[[今:You run the meeting with total confidence]], while [[本:inside you're screaming \"let me be alone\" the second it ends]].", "[[今:You set big, bold goals]], but [[本:what really fires you up is knocking out the small steps one by one]]."]}, "ISTJ>ENTP": {"karai": "You sell yourself as a rule-breaker, but you memorized every rule before breaking it. Classic honor student.", "name": "The Very Orderly Contrarian", "atari": ["[[今:You kick off a debate with \"okay, but what if\"]], while [[本:secretly hoping it lands on the usual conclusion]].", "[[今:After jumping on a new project on a whim]], [[本:you lie awake at midnight listing every possible risk]]."]}, "ISTJ>INFJ": {"karai": "You say feelings matter most, but if someone's excuse for being late is \"feelings,\" they are not forgiven.", "name": "The Good Listener With a Manual", "atari": ["[[今:You nod deeply as a friend shares their worries]], while [[本:your brain is already bullet-pointing the solutions]].", "[[今:You've learned to read the room and act on it]], but [[本:what you do next still goes by the manual]]."]}, "ISTJ>INFP": {"karai": "People think you're dreamy, but you remember every cent you've ever lent, and the date.", "name": "The Dreamy Accountant", "atari": ["[[今:You lose yourself in your favorite movie's world]], yet [[本:you've already worked out the runtime and the train home]].", "[[今:The day after writing \"I want to live as myself\" in your journal]], [[本:you still take the usual route to work at the usual time]]."]}, "ISTJ>ENFJ": {"karai": "You're great at guiding people, but mess with your schedule and your smile stays while your eyes stop smiling.", "name": "The Meticulous Caretaker", "atari": ["[[今:You take on everyone's problems]] while [[本:secretly wishing you were home eating your usual dinner]].", "[[今:Your pep talks for juniors are full of heart]], and [[本:you wrote them down in advance]]."]}, "ISTJ>ENFP": {"karai": "After a day of playing the fun one, all you can handle that night is your usual dinner and your usual videos.", "name": "Excitement, Pending Paperwork", "atari": ["[[今:Right after a quick \"That sounds fun, I'm in!\"]], [[本:you go home and research the packing list and budget with a straight face]].", "[[今:You pick up new hobbies one after another]], but [[本:you read every manual from page one before starting]]."]}, "ISTJ>ISTJ": {"karai": "\"That's how we did it last time\" is your ultimate catchphrase. New ideas usually get ignored at least once.", "name": "The Unshakable Human Timetable", "atari": ["Your morning routine hasn't changed in ten years, and you even know what you'll grab at the checkout.", "Turning work in three days early is just normal to you, so last-minute people are a total mystery."]}, "ISTJ>ISFJ": {"karai": "They call you thoughtful, but every thoughtful gesture comes with a reason and a precedent.", "name": "Kindness, Running on Schedule", "atari": ["[[今:You've learned to go along and say \"sure, that's fine\"]], but [[本:your mental notebook logs it as an exception]].", "[[今:You've gotten good at handing out snacks]], yet [[本:the count and the order were planned to perfection]]."]}, "ISTJ>ESTJ": {"karai": "You look like the steady organizer, but every time you speak in front of a group, you quietly lose a year of your life.", "name": "The Craftsperson Who Does Social", "atari": ["[[今:After running the party flawlessly]], [[本:you skip the after-party, head straight home, and feel quietly satisfied]].", "[[今:You're used to giving instructions in front of people]], but [[本:every time, you wish you could just send it all by email]]."]}, "ISTJ>ESFJ": {"karai": "You're the kind party planner, but you remember exactly who bailed last minute when next year's guest list comes around.", "name": "The Thoughtful Host Who's a Craftsperson", "atari": ["[[今:You keep the birthday party lively]] while [[本:silently calculating when the cake needs to come out to stay on schedule]].", "[[今:Your group-chat replies are fast and warm]], but [[本:you reread each one three times for typos first]]."]}, "ISTJ>ISTP": {"karai": "You act like you go with the flow, but change your plans suddenly and your bad mood shows all day.", "name": "The Toolbox That Ditched the Plan", "atari": ["[[今:You think you've become a no-plans person]], yet [[本:somehow you've already looked up where the restrooms are on your trip]].", "[[今:You work by feel now]], but [[本:you can't relax until every tool is back in its spot]]."]}, "ISTJ>ISFP": {"karai": "You think you live by feel, but at your favorite café it's always the same seat, same order.", "name": "Picking Favorites by Timetable", "atari": ["[[今:You choose clothes because you love them now]], but [[本:you still check the care label and compare prices first]].", "[[今:After rearranging your room on a whim]], [[本:you quietly decide the old layout was best and put it back]]."]}, "ISTJ>ESTP": {"karai": "You look like a person of action, but your bold moves often just retrace past successes, step by step.", "name": "The Cautious Thrill-Seeker", "atari": ["[[今:You charge ahead with \"let's just try it\"]] while [[本:mentally lining up insurance and three escape routes]].", "[[今:You can say yes to last-minute plans now]], but [[本:you open your budget app at home and have a small regret session]]."]}, "ISTJ>ESFP": {"karai": "People peg you as a party lover, but deep down you'd rather rewatch the same show from episode one.", "name": "The Life of the Party Keeping the Books", "atari": ["[[今:After warming up karaoke by singing first]], [[本:you casually handle the entire bill split too]].", "[[今:The morning after \"let's just enjoy the moment!\"]], [[本:you're up thirty minutes early making up for yesterday]]."]}, "ISFJ>INTJ": {"karai": "You play the cool strategist, yet everyone's birthday is saved in your phone calendar.", "name": "The Caretaker Playing It Cool", "atari": ["[[今:That errand you logically cut]]? [[本:You end up quietly doing it for them that night]].", "[[今:In meetings you can flatly say \"this is inefficient\"]], yet [[本:you're still worrying about how they took it once you're home]]."]}, "ISFJ>INTP": {"karai": "You're great at acting uninterested in people. But we all know you leave messages on read and agonize over a reply for thirty minutes.", "name": "The Busybody Hiding Behind Logic", "atari": ["[[今:You start with \"logically speaking\"]], but [[本:you always end up siding with whoever's struggling most]].", "[[今:You can't stop researching what interests you]], but [[本:you've never once forgotten your friends' favorite foods]]."]}, "ISFJ>ENTJ": {"karai": "You wear the face of a tough leader, but you lie awake replaying every harsh word you said.", "name": "The Pushy Nurse", "atari": ["[[今:You can lead a team and press people on the numbers now]], then [[本:rush out to buy them snacks afterward]].", "[[今:The moment you declare \"I'll decide\"]], [[本:you're scanning every face for anyone who disagrees]]."]}, "ISFJ>ENTP": {"karai": "You've gotten good at running the room with clever arguments, but really you just don't want anyone to dislike you.", "name": "The Wisecracking School Nurse", "atari": ["[[今:After getting a debate going with \"okay, but what if\"]], [[本:you privately message the one person you went too hard on]].", "[[今:You've become the one who jumps on new things]], yet [[本:you're the first to notice when the miso soup at home tastes different]]."]}, "ISFJ>INFJ": {"karai": "People call you deep, but honestly, your list of worries just keeps getting longer.", "name": "Worrying All the Way Into the Future", "atari": ["[[本:It's not just your friend's worries today]] — [[今:you picture three years ahead and ache over it on your own]].", "[[今:You've started talking about ideals]], but [[本:your hands are somehow already washing the dishes in front of you]]."]}, "ISFJ>INFP": {"karai": "You play the sensitive artist, but you can't relax unless you're being useful to someone.", "name": "The Dreamer Who Forgot the Plan", "atari": ["[[今:You get absorbed in a favorite story]], but [[本:if family is late coming home, you're too restless to read]].", "[[今:You decided to go at your own pace]], yet [[本:the moment someone asks, you clear your whole schedule]]."]}, "ISFJ>ENFJ": {"karai": "The reliable-mentor role suits you now. Your biggest weakness: never telling anyone how tiring it is to be relied on.", "name": "The Unsung Helper, Now Center Stage", "atari": ["[[今:You can give pep talks in front of everyone now]], but [[本:you'd really rather be quietly pouring tea in the back]].", "[[今:Every time you take on leading the group]], [[本:you get home and sit in the dark for a while]]."]}, "ISFJ>ENFP": {"karai": "You look like you live on vibes, but when plans change suddenly, you're the first to panic inside.", "name": "The Bubbly Guardian", "atari": ["[[今:You look like you're having more fun than anyone]], yet [[本:you keep scanning for whoever's left out of the circle]].", "[[今:You planned the trip on a whim]], but [[本:the night before, you packed motion-sickness pills for everyone]]."]}, "ISFJ>ISTJ": {"karai": "You're known as the strict one, but after being tough on someone, you rehearse your excuses to them a hundred times in your head.", "name": "The Stickler Who Locked Away Their Heart", "atari": ["[[今:You can turn people down by the rules now]], but [[本:watching them walk away still stings a little]].", "[[今:At work you say \"those are the rules\" without blinking]], yet [[本:at home you change the menu every day to suit everyone]]."]}, "ISFJ>ISFJ": {"karai": "\"I'm fine\" is your catchphrase. But you say it with the same face when you're not, so nobody ever notices.", "name": "The Born Guardian Angel", "atari": ["The moment someone sneezes, you've already pulled a tissue from your bag. Hands first, thinking later.", "You remember a friend saying \"I love this\" a year ago and casually hand it over on their birthday, to their surprise."]}, "ISFJ>ESTJ": {"karai": "You look like the capable one, but really you're working this hard to hear someone say \"thank you.\"", "name": "The Soothing Type Who Runs the Show", "atari": ["[[今:You make the schedule and tell everyone what to do]], while [[本:rewording the ends of your sentences so they don't sound harsh]].", "[[今:You're in a position to say \"stick to what we agreed\"]], yet [[本:you can't help asking why someone couldn't]]."]}, "ISFJ>ESFJ": {"karai": "People mistake your inability to say no for being social, and suddenly every weekend is booked.", "name": "The Tea-Maker at a Busy Party", "atari": ["[[今:On the way home from hosting a perfect night out]], [[本:you put in earbuds and desperately reclaim some time to talk to no one]].", "[[今:You're laughing at the center of the group]], but [[本:tea with a couple of people is really more your speed]]."]}, "ISFJ>ISTP": {"karai": "You seem cool and independent, but your happiest moment is when everyone comes to you for help.", "name": "The Quiet Fix-It Person", "atari": ["[[今:You say \"I don't really care\" without much warmth]] while [[本:silently fixing your friend's broken bike]].", "[[今:You've learned the freedom of not planning]], but [[本:you know every expiration date in the fridge]]."]}, "ISFJ>ISFP": {"karai": "You declared you'd go at your own pace, but after fitting around everyone's plans, you're the organizer again.", "name": "The Free Spirit Who Still Gives It All", "atari": ["[[今:You go with your mood these days]], but [[本:when someone's in trouble, your body moves before your mood does]].", "[[今:You finally feel okay putting what you like first]], but [[本:the knickknacks you pick are usually gifts for someone]]."]}, "ISFJ>ESTP": {"karai": "You pass as bold and carefree, but one mistake can haunt you for years.", "name": "The Worrier Who Dives In Headfirst", "atari": ["[[今:Right after diving in full force]], [[本:you quietly ask, \"Was the way I said that okay?\"]]", "[[今:You wear the face of a thrill-seeker]], but [[本:your pouch is always stocked with bandages and antacids]]."]}, "ISFJ>ESFP": {"karai": "Everyone thinks you're the cheerful mood-maker, but at home you hold a solo review of everything you said today.", "name": "The Party Starter on First-Aid Duty", "atari": ["[[今:You're dancing and hyping up the room]] while [[本:arranging water and a cab for whoever drank too much]].", "[[今:You say \"tonight, whoever has the most fun wins\"]], but [[本:you can't stop thinking about tomorrow's prep you haven't done]]."]}, "INFJ>INTJ": {"karai": "You've gotten good at seeming cold, but a movie trailer alone can make you cry.", "name": "The Empath in Armor Made of Logic", "atari": ["[[今:After a meeting where you said \"let's leave feelings out of it\"]], [[本:you can't stop thinking about the person who looked close to tears]].", "[[今:You think you decide on efficiency]], but [[本:the deciding factor is always \"will this hurt them?\"]]"]}, "INFJ>INTP": {"karai": "You act uninterested in others while spending three days decoding what someone really meant by one remark.", "name": "The Researcher of Human Hearts", "atari": ["When a friend comes to you about love, [[今:you catch yourself analyzing it like a psychology paper]].", "[[今:You get so lost in thought that plans slip by]], yet [[本:for promises with people, you start preparing your heart the day before]]."]}, "INFJ>ENTJ": {"karai": "You pass as a confident leader, but a single cold look can sink you for a week.", "name": "The Commander Carrying Ideals", "atari": ["[[今:You can move people with numbers now]], but [[本:what you really want to hear is \"this work matters\"]].", "[[今:Making bold calls suits you well]], but [[本:afterward you replay it alone, checking no one got left behind]]."]}, "INFJ>ENTP": {"karai": "You throw out sarcasm, but you can't relax until you've confirmed the other person laughed.", "name": "The Secret Saint Who Loves a Debate", "atari": ["[[今:You play devil's advocate to get the debate going]] while [[本:secretly hoping it ends with everyone getting along]].", "[[今:You're chatty and light in public]], but [[本:some nights you end up searching things like \"the meaning of life\"]]."]}, "INFJ>INFJ": {"karai": "You hold it in and hold it in, then one day silently drift out of someone's life. That's the scary part.", "name": "The Quiet One Who Sees Everything", "atari": ["The moment you walk in, you know who isn't getting along, and you quietly pick your seat accordingly.", "You notice what people want before they say it, so your gifts almost never miss."]}, "INFJ>INFP": {"karai": "You think you're living freely, but every glance at your messy room brings a wave of quiet self-loathing.", "name": "The Prophet Who Lost the Plan", "atari": ["[[本:You're great at seeing what's coming]], but [[今:when you're not in the mood, nothing gets done]], so you can't catch up to the future you saw.", "[[今:You spend more time in your own world now]], but [[本:you'll notice from miles away when someone you love is off]]."]}, "INFJ>ENFJ": {"karai": "You look like you love being relied on, but you listen to everyone so thoroughly that you're wiped out every day.", "name": "Everyone's Counselor, Closed at Night", "atari": ["[[今:By day, you're everyone's go-to listener]], [[本:but at night you need notifications off and no one to talk to]].", "[[今:You're great at cheering people on]], yet [[本:you call your own worries \"no big deal\" and tell no one]]."]}, "INFJ>ENFP": {"karai": "After years of being called the cheerful one, you act cheerful even on your down days, out of sheer habit.", "name": "The Observer Disguised as Sparkle", "atari": ["[[今:You make friends with anyone in no time]], but [[本:the people allowed deep inside fit on one hand]].", "[[今:You seem to act on a whim]], but [[本:that whim has been warming in your head for days]]."]}, "INFJ>ISTJ": {"karai": "You play the rule-following model student, but you've never really bought into how the world works.", "name": "The Idealist Hiding Behind Precedent", "atari": ["[[今:You work through the set procedure step by step]] while [[本:thinking \"this could be so much better\"]].", "[[今:People see you as practical]], but [[本:you're dreaming up epic stories while staring out the train window]]."]}, "INFJ>ISFJ": {"karai": "You seem modest and gentle, but you hold the most stubborn \"this is how it should be\" of anyone.", "name": "The Down-to-Earth Dreamer", "atari": ["[[今:You calmly get through chores and favors]] while [[本:picturing your ideal life ten years from now]].", "[[今:Taking care of people comes naturally now]], and [[本:while you do, you're quietly reading their true feelings]]."]}, "INFJ>ESTJ": {"karai": "You play the high performer flawlessly, then spend your days off with the curtains shut, ignoring every message.", "name": "The Philosopher With a Planner", "atari": ["[[今:You keep the meeting perfectly on time]] while [[本:suddenly wondering what this meeting is even for]].", "[[今:You can give crisp instructions now]], but [[本:before bed you keep replaying the face of the person you were firm with]]."]}, "INFJ>ESFJ": {"karai": "You're so good at going along with everyone that you lose track of what you actually want.", "name": "The Sage at the Banquet", "atari": ["[[今:When you plan the seating for a party]], [[本:you instantly see who needs to sit apart, and arrange it]].", "[[今:You nod along at the center of the noisy circle]] while [[本:your mind wanders off to somewhere far and quiet]]."]}, "INFJ>ISTP": {"karai": "You act detached, but secretly you want just one person to truly understand you.", "name": "The Quiet, Deep Maker", "atari": ["[[今:You look like the cool one quietly working with your hands]], but [[本:you're picking up every shift in the room]].", "[[今:You act breezy, like it'll all work out]], but [[本:at night you lie awake pondering the meaning of life]]."]}, "INFJ>ISFP": {"karai": "You may call yourself a free spirit, but you still put everyone's feelings first and your own likes last.", "name": "The Foreseer Who Lives by Feel", "atari": ["[[今:You give yourself over to the music and views you love]], but [[本:you can't help thinking about the meaning underneath]].", "[[今:You've learned to enjoy the moment]], yet [[本:even mid-fun you're thinking \"this will end someday\"]]."]}, "INFJ>ESTP": {"karai": "You laugh big, but inside you're locked up like a diary no one gets to read.", "name": "The Overthinker Running on Momentum", "atari": ["[[今:After diving in on the vibe of the moment]], [[本:you spend the walk home wondering if they actually hated it]].", "[[今:People call you a doer]], but [[本:before you move, you've already predicted several ways they might react]]."]}, "INFJ>ESFP": {"karai": "After a day of lighting up the room, you need three days of hiding at home to feel like yourself again.", "name": "The Watcher on Stage", "atari": ["[[今:You hype up the room as the star]] while [[本:still spotting the person looking bored outside the circle]].", "[[今:You say \"if it's fun, who cares?\"]] while [[本:quietly wondering whether the fun means anything]]."]}, "INTJ>INTJ": {"karai": "You're so sure you're right that you skip the explaining, and people misunderstand you constantly.", "name": "Shortest Route, Always", "atari": ["You reached the conclusion long ago and are just quietly waiting for the other person to get there too.", "You plan your days off for efficiency, so friends often say, \"This isn't a trip, it's a mission.\""]}, "INTJ>INTP": {"karai": "You play the laid-back type, but nobody roasts other people's slacking harder than you.", "name": "The Strategist Letting Answers Simmer", "atari": ["[[本:You can already see the answer]], yet [[今:you keep opening more search tabs, saying \"just a little more research\"]].", "[[今:You dream of a free life without plans]], and [[本:before you know it, you're drafting a plan for not planning]]."]}, "INTJ>ENTJ": {"karai": "You nail the sociable-leader role, but small talk is secretly torture every single time.", "name": "The Strategist Sent to the Front Line", "atari": ["[[今:You can speak confidently as a leader now]], but [[本:you'd really rather hand over the slides and go home]].", "[[今:You've gotten good at rallying people]], but [[本:every time, you mutter inside, \"it'd be faster alone\"]]."]}, "INTJ>ENTP": {"karai": "You look like you're winging it, but you've already prepared answers to every possible counterargument.", "name": "The Strategically Spontaneous", "atari": ["[[今:You freely spin ideas with \"okay, but what if\"]], but [[本:even the tangents are detours toward your final conclusion]].", "[[今:You toss out new ideas one after another]], while [[本:having decided from the start you'll only act on one]]."]}, "INTJ>INFJ": {"karai": "You play the great listener, but by the third time someone repeats the same complaint, your eyes glaze over.", "name": "The Rationalist Who Learned Kindness", "atari": ["[[今:You can stand by people's feelings now]], but [[本:your head is calculating the shortest path to a solution]].", "[[今:You can say \"that must have been hard\" now]], though [[本:you can't resist adding three ideas for improvement]]."]}, "INTJ>INFP": {"karai": "You may call yourself a sensitive dreamer, but your face can't hide it when someone's being inefficient.", "name": "The Efficient Romantic", "atari": ["[[今:You've come to love talking about dreams and ideals]], but [[本:somehow they end up as a project timeline]].", "[[今:You enjoy a day off going wherever your mood takes you]], while [[本:secretly counting what you could've done with that time]]."]}, "INTJ>ENFJ": {"karai": "People adore you as a caring mentor, but honestly, you'd be happiest if everyone just figured things out themselves.", "name": "The Cheer Captain With a Battle Plan", "atari": ["[[今:You cheer on your juniors with passion]] while [[本:coolly calculating whether that's the most effective way to do it]].", "[[今:You're at the center of the group]], but [[本:you're really just observing who to pair up for the best results]]."]}, "INTJ>ENFP": {"karai": "You're great at seeming carefree, but any plan built on vibes alone gets an instant \"fail\" in your head.", "name": "The One Who Analyzes the Sparkle", "atari": ["[[今:Right after gushing \"that's amazing!\"]], [[本:you spot three weak points in the idea]].", "[[今:You play the one who jumps on every fun thing]], but [[本:you've basically run the cost-benefit math before you jump]]."]}, "INTJ>ISTJ": {"karai": "You're known as the steady, serious one, but in your head you're redesigning the entire company.", "name": "The Revolutionary Following Precedent", "atari": ["[[今:You work strictly by the set procedure]] while [[本:rewriting your improvement plan for it again and again in your head]].", "[[今:You're trusted for your practical work]], but [[本:you'd rather be sketching the big picture five years out]]."]}, "INTJ>ISFJ": {"karai": "People call you kind, but sometimes that kindness is a strategy to keep hassle to a minimum.", "name": "The Quiet Genius Strategist Who Serves", "atari": ["[[今:You take on requests with a smile]] while [[本:calmly grading them: \"what an inefficient way to ask\"]].", "[[今:You keep a low profile to fit in]], but [[本:you're itching to redo it all your way]]."]}, "INTJ>ESTJ": {"karai": "You look like a by-the-book operator, but most rules make you think, \"What's the point?\"", "name": "The Strategist Down on the Ground", "atari": ["[[今:You build detailed schedules and keep everyone moving]], but [[本:you'd rather be talking big-picture direction]].", "[[今:Giving instructions in front of people is routine now]], but [[本:you've decided lunch break is spent alone, talking to no one]]."]}, "INTJ>ESFJ": {"karai": "You're kind to everyone on the outside, but your mental notebook of snark is getting pretty thick.", "name": "Smiling Host, Secret War Room", "atari": ["[[今:You ask everyone's preferences and set up the event]], while [[本:knowing it'd be faster to decide everything yourself]].", "[[今:You send cheerful stickers in the group chat]] while [[本:already predicting who won't show]]."]}, "INTJ>ISTP": {"karai": "You pretend to wing it, but you can't sleep unless you've thought ten steps ahead.", "name": "The Tinkerer Who Tossed the Blueprint", "atari": ["[[今:You build on a whim now]], but [[本:as you go, you're mapping every step to the finish in your head]].", "[[今:You enjoy days with no plans]], but [[本:you can't help noticing when someone else's planning is sloppy]]."]}, "INTJ>ISFP": {"karai": "People say you have a soft vibe, but get you into a real debate and you're merciless.", "name": "The Theorist Armed With Taste", "atari": ["[[今:You seem to pick what you love on instinct]], but [[本:you've actually spent days reading reviews and comparison charts]].", "[[今:You can go along with people kindly now]], but [[本:inside, you're quietly correcting anything that doesn't add up]]."]}, "INTJ>ESTP": {"karai": "You're proud of being called a go-getter, but surprises are what you hate most.", "name": "The Doer Who Did the Homework", "atari": ["[[今:You look like you're going with the flow]], but [[本:you actually simulated it all the night before]].", "[[今:You can enjoy a rowdy night out now]], but [[本:on the way home you're sorting the intel from today's conversations]]."]}, "INTJ>ESFP": {"karai": "After going all-out as the life of the party, you go silent the moment you're alone, like someone flipped a switch.", "name": "The Cool Brain Behind the Party", "atari": ["[[今:You're the one having the most fun at the party]], yet [[本:part of your brain is still working backward from the last train and tomorrow's plans]].", "[[今:You laugh, \"as long as it's fun right now\"]], but [[本:you can't help wondering where that fun leads in the future]]."]}, "ISTP>INTJ": {"karai": "You talk like a strategist, but often you just want fewer annoying steps.", "name": "The Craftsperson Who Writes Plans Too", "atari": ["[[本:You'd really rather learn by touching things]], but [[今:these days you draw the full blueprint before you move]].", "[[今:The same weekend you make a five-year plan]], [[本:you impulse-buy a tool that caught your eye and wreck the schedule]]."]}, "ISTP>INTP": {"karai": "Once you've researched everything, you're satisfied, and the tool you ordered is still in its box.", "name": "The Craftsperson Who Googles First", "atari": ["[[本:You used to take things apart to find out]], but [[今:now you read reviews for three hours before you even start]].", "[[本:\"Let's just try it\" used to be your catchphrase]], but [[今:now your hands stop until the logic checks out]]."]}, "ISTP>ENTJ": {"karai": "You lead mainly because waiting on other people stresses you out more than anything.", "name": "The Lone Wolf Who Took the Lead", "atari": ["[[今:In meetings you say \"fine, I'll decide\"]], then [[本:want to slip back to working alone the moment it's over]].", "[[今:You get fired up talking team goals]], but [[本:every party invite gets a plausible-sounding excuse]]."]}, "ISTP>ENTP": {"karai": "Now that you're a smooth talker, your excuses for not doing the work have gotten smoother too.", "name": "The Quiet Craftsperson Who Can Argue", "atari": ["[[今:After livening things up with \"okay, but what if\"]], [[本:you don't want to talk to anyone on the way home]].", "[[本:You could just quietly fix it]], but [[今:now you can't help explaining the theory behind the fix]]."]}, "ISTP>INFJ": {"karai": "You seem perceptive, but some days you're quiet only because putting what you sensed into words is a hassle.", "name": "The Fix-It Person Who Learned Tact", "atari": ["[[今:You listen quietly to people's worries]] while [[本:a corner of your brain asks, \"so where's the actual fault?\"]]", "[[今:You've started reading people's feelings in advance]], but [[本:it'd be so much easier if they just said it]]."]}, "ISTP>INFP": {"karai": "You're out there \"finding yourself,\" but if you just got your hands busy, you'd find it in three days.", "name": "The Craftsperson Who Started Dreaming", "atari": ["[[本:You used to be great at practical calls]], but [[今:now some nights you freeze, wondering \"what's the point?\"]]", "[[今:You light up when talk turns to your favorite movies]], but [[本:repair videos were always more your thing]]."]}, "ISTP>ENFJ": {"karai": "Every time you're called caring, you mutter three times inside: \"It'd be faster to do it myself.\"", "name": "The Lone Wolf Who Became a Caretaker", "atari": ["[[今:You take juniors' problems to heart]] while [[本:thinking, \"just poke at it and you'll figure it out\"]].", "[[今:You coordinated everyone's schedules to plan the event]], yet [[本:you're the one who most wants to leave early]]."]}, "ISTP>ENFP": {"karai": "You pass as the high-energy one, but only your family has seen your battery-dead face.", "name": "The Quiet One Who Found Sparkle", "atari": ["[[今:You gush \"this is the best!\" about every new hobby]], but [[本:the only ones that stick are the hands-on kind]].", "[[今:You can make friends with anyone now]], but [[本:your texts still end in one word]]."]}, "ISTP>ISTJ": {"karai": "You look meticulous, but the back of your planner is covered in \"if I feel like it.\"", "name": "The Free-Spirited Maker With a Schedule", "atari": ["[[今:You hand things in neatly before the deadline]], but [[本:a last-minute burst of focus suits you better]].", "[[今:You follow the manual step by step]] while [[本:thinking every time, \"we could skip two of these\"]]."]}, "ISTP>ISFJ": {"karai": "They say you're considerate, but you're much better at fixing machines than reading the room.", "name": "The Toolbox Powered by Kindness", "atari": ["[[今:You can't say no to favors anymore]], but [[本:you'd rather just be handed the instructions and do it alone]].", "[[今:You keep an eye on everyone's health]] while [[本:writing off your own aches with \"it'll pass\"]]."]}, "ISTP>ESTJ": {"karai": "You're strict about rules now, but you used to be the one hunting for loopholes.", "name": "The Free Spirit Turned Site Manager", "atari": ["[[今:You track the team's progress in detail]], yet [[本:you want to do your own work however the mood strikes]].", "[[今:After giving brisk instructions at the morning meeting]], [[本:you spend lunch holed up alone in your car]]."]}, "ISTP>ESFJ": {"karai": "You look like everyone's caretaker, but really you're just enjoying the puzzle called logistics.", "name": "The Hidden Craftsperson Who Hosts Too", "atari": ["[[今:You nail everything from picking the venue to splitting the bill]], then [[本:slip away from the after-party]].", "[[今:You politely react with stickers in the group chat]], but [[本:honestly you think \"you saw I read it, right?\"]]"]}, "ISTP>ISTP": {"karai": "You're dependable, but ask \"How'd you do that?\" and all you get is \"I just did.\"", "name": "The Born Fixer", "atari": ["You build things without reading the instructions and somehow end up with the cleanest result.", "When you see someone struggling, your hands move before your words and you've already fixed it."]}, "ISTP>ISFP": {"karai": "You call yourself the artsy type, but you secretly read every spec sheet too.", "name": "The Craftsperson Who Picks by Taste", "atari": ["[[本:You used to choose tools by performance]], but [[今:lately you choose them by color and feel]].", "[[本:Even when you could argue back with logic]], [[今:you look at their face and let it go with \"eh, fine\"]]."]}, "ISTP>ESTP": {"karai": "The action-hero role suits you now, but part of you is waiting for a weekend when nobody invites you anywhere.", "name": "The Craftsperson in the Spotlight", "atari": ["[[今:You pack your calendar with fun plans on a whim]], but [[本:around the third one, you suddenly crave time alone]].", "[[今:Speaking to a crowd doesn't faze you anymore]], but [[本:once the toast is done, you quietly drift to a corner seat]]."]}, "ISTP>ESFP": {"karai": "You look like you're having fun, but 80% of that smile is \"an awkward silence would be worse.\"", "name": "The Craftsperson Who Can Work a Room", "atari": ["[[今:You play the mood-maker]] while [[本:thinking, \"I want to go home and get back to my project\"]].", "[[今:You react big to your friend's story]], but [[本:you already have a one-line answer to their problem]]."]}, "ISFP>INTJ": {"karai": "You act like a cool-headed decision-maker, but the deciding factor is usually \"I just like it.\"", "name": "The Sensitive Soul Who Makes Plans", "atari": ["[[今:You move things forward on efficiency and evidence]], but [[本:you will never compromise on the fonts and colors of the slides]].", "[[今:You made the perfect long-term plan]], but [[本:the moment your heart is moved, you want to scrap it all]]."]}, "ISFP>INTP": {"karai": "You call yourself logical, but your face reacts to opinions you dislike before any reasoning does.", "name": "The Free Spirit Wrapped in Logic", "atari": ["When you talk about what you love, [[今:the analysis of why you love it now comes out before the feeling]].", "[[今:You browse comparison sites just to pick one piece of furniture]], then [[本:buy the first one you fell for]]."]}, "ISFP>ENTJ": {"karai": "Wanting to look strong sometimes turns into doing an impression of a strong person.", "name": "The Sensitive Soul Turned Leader", "atari": ["[[今:You make firm calls in meetings]], yet [[本:at home a solo \"did I say too much?\" review begins]].", "[[今:You move people with goals and numbers]], but [[本:what you really care about is whether everyone feels comfortable]]."]}, "ISFP>ENTP": {"karai": "You've become the one who calls people out, but when you get seriously shot down, it stings for a week.", "name": "The Artist Who Learned to Talk Back", "atari": ["[[今:You cut in with \"okay, but what if\" in debates]], yet [[本:you replay the face of the person you out-argued all night]].", "[[今:You fire off ideas and keep the energy up]], but [[本:you'd rather take one and slowly shape it with your hands]]."]}, "ISFP>INFJ": {"karai": "After saying something cryptic, you're left figuring out what you meant too.", "name": "The Free Spirit Who Now Plans Ahead", "atari": ["[[今:You've started smoothing out people's feelings in advance]], but [[本:you'd rather just move with the mood of the moment]].", "[[今:You're filling in next month's planner]] while [[本:your heart gets stolen by \"wow, look at that sunset\"]]."]}, "ISFP>INFP": {"karai": "The more time you spend talking about ideals, the less time you spend making things with your hands like you used to.", "name": "The Here-and-Now Type Who Daydreams", "atari": ["[[本:You used to be great at enjoying what's right in front of you]], but [[今:now you tend to get lost in \"what's this all for?\"]]", "[[本:From a single flower spotted on a walk]], [[今:you somehow dream up an epic saga by the time you get home]]."]}, "ISFP>ENFJ": {"karai": "Being needed makes you so happy that you take on too much and keep putting what you love on hold.", "name": "The Loner Working Hard for Everyone", "atari": ["[[今:You take on being everyone's counselor]] while [[本:really wanting to be alone with your favorite music]].", "[[今:You throw a friend's birthday party and it's a huge hit]], [[本:yet the next day you're in bed, seeing no one]]."]}, "ISFP>ENFP": {"karai": "You seem outgoing, but you still can't message the one person you really want to invite.", "name": "The Artist Who Jumped Into the Crowd", "atari": ["[[今:You can smile and chat with strangers now]], but [[本:your earbuds on the way home are a lifeline]].", "You've always followed your heart. It's just that [[本:you used to do it alone]], and [[今:now somehow you do it with a crowd]]."]}, "ISFP>ISTJ": {"karai": "People say you're diligent, but that diligence is mostly made of not wanting to get scolded.", "name": "The Free Spirit Playing Tidy", "atari": ["[[今:Your paperwork goes in perfect and early]], yet [[本:your desk is buried in cute knickknacks you love]].", "[[今:You've learned to follow procedures]], but [[本:every time you think \"there's a lovelier way to do this\"]]."]}, "ISFP>ISFJ": {"karai": "They say you notice everything, but you've also gotten good at bottling up everything you notice.", "name": "The Free Spirit Who Got Organized", "atari": ["[[今:You remember how everyone takes their tea]], yet [[本:you still want to change your own plans on a whim]].", "[[今:You've started preparing before anyone asks]], but [[本:it's really so you never have to see yourself panic]]."]}, "ISFP>ESTJ": {"karai": "Your capable-person mask has gotten so thick that when someone asks what you like, you freeze for a second.", "name": "The Artist Put in Charge", "atari": ["[[今:You call people out when things fall behind schedule]], yet [[本:your happiest days off have no plan at all]].", "[[今:On the way home from a day of giving clear instructions]], [[本:you clutch your phone, wondering \"was I too harsh?\"]]"]}, "ISFP>ESFJ": {"karai": "You're so good at fitting in that your own tastes have wandered off on a trip somewhere.", "name": "The Free Spirit Elected Party Planner", "atari": ["[[今:You check everyone's availability and book the place]], then [[本:spend the night taking photos of the cute interior]].", "[[今:You can't leave someone sitting alone anymore]], but [[本:on days you want to be alone, you can't say so]]."]}, "ISFP>ISTP": {"karai": "You act unsentimental, but every letter you've ever received is saved in a box.", "name": "The Artist Who Learned to Be Cool", "atari": ["[[今:People think you don't show emotion]], but [[本:one second of your favorite song's intro has you close to tears]].", "[[今:You answer people's problems with logic now]], but [[本:you'd rather say \"I get it\" and feel down with them]]."]}, "ISFP>ISFP": {"karai": "You seem like you never get angry, but your mental \"never seeing them again\" list is surprisingly long.", "name": "True to What You Love", "atari": ["You keep choosing what you love over what's trendy, and your room has quietly become a tiny art museum.", "You don't say when you hate something, but your face and feet are already leaving the room."]}, "ISFP>ESTP": {"karai": "You act tough, but you've reread that slightly cold text three times.", "name": "The Sensitive Soul Turned Doer", "atari": ["[[今:You dive in on momentum now]], but [[本:after deciding, you're alone with a nervous \"is this okay?\"]]", "[[今:You can take charge with on-the-spot calls]], yet [[本:one sad face is all it takes to make you waver]]."]}, "ISFP>ESFP": {"karai": "Your cheerful persona is so established that even when you're down, people just ask, \"Doing good?\"", "name": "The Secret Introvert Who Shines on Stage", "atari": ["[[今:At parties you're practically the main event]], yet [[本:back home you head straight to bed without turning on the lights]].", "[[今:You hop on every fun thing]], but [[本:the best part was the little shop you stopped at alone on the way home]]."]}, "INFP>INTJ": {"karai": "You reach conclusions coolly, but your ideals sneak into every one of them.", "name": "The Dreamer Who Drew Up Blueprints", "atari": ["[[今:You plan rationally and execute]], but [[本:what drives you is a big dream you can't tell anyone]].", "[[今:You can calmly handle other people's opinions now]], yet [[本:you still sob at the touching scenes in movies]]."]}, "INFP>INTP": {"karai": "Acting all logical is really just armor so you don't get hurt.", "name": "The Dreamer Wrapping Feelings in Logic", "atari": ["[[今:You write a logical deep-dive on your favorite work]], but [[本:really you just want to say \"it's so precious\"]].", "[[今:You answer people's worries with analysis now]], but [[本:you're ready to cry with them, too]]."]}, "INFP>ENTJ": {"karai": "You take charge boldly, but you might be the most easily hurt person on the team.", "name": "The Dreamer Leading for an Ideal", "atari": ["[[今:You lead and deliver results]] while [[本:\"does this work even mean anything?\" plays on repeat in your head]].", "[[今:On nights after making a tough call]], [[本:you write long excuses and reflections in your journal]]."]}, "INFP>ENTP": {"karai": "Your sarcasm is just a cover for being a hopeless romantic.", "name": "The Daydreamer Who Learned to Talk Back", "atari": ["[[今:You've started enjoying a good argument]], but [[本:late at night you keep imagining how the person you went too far with felt]].", "[[今:You toss out ideas one after another]], but [[本:the dream that really matters, you've told no one]]."]}, "INFP>INFJ": {"karai": "You look put-together, but half your plans exist just to make you look put-together.", "name": "The Romantic Who Learned to Plan", "atari": ["[[今:You can read people's feelings and act on them now]], but [[本:you can never schedule your own]].", "[[今:You fill your planner neatly now]], yet [[本:the best part is the doodles in the margins]]."]}, "INFP>INFP": {"karai": "Your ideals are so high that most real-life invitations end with \"maybe next time.\"", "name": "The Dreamer Who Lives in a Movie Theater", "atari": ["In a fifteen-minute commute, you finish an entire saga in your head where the hero grows three times.", "When you find a lyric you love, that one line decides your mood for the whole day."]}, "INFP>ENFJ": {"karai": "You work hard to be needed, but when you're needed too much, you suddenly want to run from everything.", "name": "The Daydreamer Guarding Everyone's Heart", "atari": ["[[今:You've become the one who keeps the group's mood in balance]], but [[本:at home you can't keep up with caring for your own heart]].", "[[今:Encouraging words for others flow easily]], yet [[本:you can't think of a single one for yourself]]."]}, "INFP>ENFP": {"karai": "You think you've become social, but the moment you make plans, a little \"I don't want to go\" starts growing.", "name": "The Dreamer Who Stepped Outside", "atari": ["[[今:You can have fun talking with anyone now]], but [[本:there are still only about two people you're truly honest with]].", "[[今:You tell people right away about what excites you]], but [[本:the most precious excitement is still tucked in your chest]]."]}, "INFP>ISTJ": {"karai": "You play the sensible one, but your plan for after you win the lottery is weirdly detailed.", "name": "The Dreamer Who Landed in Reality", "atari": ["[[今:After neatly wrapping up your expense reports]], [[本:you secretly plot the next chapter of your novel under the desk]].", "[[今:You work by precedent]] while [[本:asking yourself every day, \"is this really right?\"]]"]}, "INFP>ISFJ": {"karai": "They call you considerate, but all the favors you couldn't refuse have your dreams stuck in traffic.", "name": "The Gentle Dreamer Who Gets Things Done", "atari": ["[[今:You remember everyone's favorite snacks and bring them in]], but [[本:you really want time to sink into your own world]].", "[[今:You quietly get through every request]] while [[本:a totally unrelated story plays out in your head]]."]}, "INFP>ESTJ": {"karai": "You look like a dependable boss, but nobody feels worse about your harsh words than you do.", "name": "The Dreamer Playing the Responsible One", "atari": ["[[今:You move people with numbers and deadlines]] while [[本:constantly wondering, \"is everyone happy?\"]]", "[[今:You manage the schedule perfectly]], yet [[本:some days one glance at the sky makes you want to drop it all]]."]}, "INFP>ESFJ": {"karai": "You say fitting in feels safe, but deep down you want to be someone special.", "name": "The Daydreamer Making Room for Everyone", "atari": ["[[今:You host the night out flawlessly]], then [[本:wonder on the train home, \"was that the real me today?\"]]", "[[今:You remember everyone's birthday]], yet [[本:you still can't recall what you really want to do]]."]}, "INFP>ISTP": {"karai": "You pass as easygoing, but that old heartbreak is still on repeat in your head.", "name": "The Daydreamer With a Cool Face", "atari": ["[[今:You calmly work through tasks now]], but [[本:while your hands move, a different story is playing in your head]].", "[[今:Because you don't show your feelings]], [[本:you start talking fast the moment your favorite artist comes up]]."]}, "INFP>ISFP": {"karai": "You've gotten good at living in the moment, but half your mind is still in \"what if\" land.", "name": "The Dreamer Who Lives by Feel", "atari": ["[[今:You pick what you love on instinct now]], but [[本:ask why and an epic tale begins]].", "[[今:Taking photos at cafés became your hobby]], but [[本:you give every single shot its own backstory]]."]}, "INFP>ESTP": {"karai": "You look like you run on momentum, but without it, your ideals are too heavy to move.", "name": "The Dreamer Turned Doer", "atari": ["[[今:You've become a \"just try it\" person]], but [[本:afterward you need time alone to figure out what it meant]].", "[[今:You go out on a whim now]], yet [[本:on the night after a fun day, you feel a little lonely somehow]]."]}, "INFP>ESFP": {"karai": "Being called fun makes you happy, but part of you sulks: \"That's not the real me.\"", "name": "The Dreamer Who Picked Up Sunshine", "atari": ["[[今:You've gotten good at livening up the room]], but [[本:on the way home you put your favorite song on repeat to find yourself again]].", "[[今:You throw yourself into fashion and events]], yet [[本:there's a notebook in your heart you show no one]]."]}, "INTP>INTJ": {"karai": "You think you've gotten decisive, but really you just decide the moment you're bored of thinking.", "name": "The Explorer Who Learned to Wrap It Up", "atari": ["[[今:You set deadlines and reach conclusions now]], but [[本:the research in the middle is the best part]].", "[[今:Everything's going to plan]], yet [[本:at midnight you find an unrelated question and lose three hours]]."]}, "INTP>INTP": {"karai": "You've figured it all out in your head, yet deadlines and replies remain untouched.", "name": "The Researcher With Endless Questions", "atari": ["You start looking up a \"but why?\" that hit you before bed, and suddenly the birds are singing.", "Mid-conversation, you get stuck on how they defined a word and miss the rest completely."]}, "INTP>ENTJ": {"karai": "You act like a leader, but you never know what to do with yourself during small talk.", "name": "The Researcher Who Picked Up the Flag", "atari": ["[[今:You lead the team and get results]], but [[本:you'd really rather dig into root causes alone]].", "[[今:You can make snap decisions in meetings now]], yet [[本:at home you re-verify the reasoning behind that call by yourself]]."]}, "INTP>ENTP": {"karai": "You think you've become a great talker, but you watch your own logic more than the other person's face.", "name": "The Talking Search Engine", "atari": ["[[本:You used to keep what you learned to yourself]], but [[今:now you can't get through a night out without giving a lecture]].", "[[今:Debating with people is fun now]], but [[本:once there are three or more, your battery starts draining fast]]."]}, "INTP>INFJ": {"karai": "You've become empathetic, but about half of it comes from observation and calculation.", "name": "The Researcher Who Studies Hearts Too", "atari": ["[[今:You've started sensing how people feel]], but [[本:you write up your findings as a paper in your head]].", "[[今:You gently stand by people with their worries]], while [[本:deep down you want to say, \"I've got three solutions, by the way\"]]."]}, "INTP>INFP": {"karai": "You say you've become sensitive, but you still start by analyzing why you got hurt. Same old you.", "name": "The Researcher Who Discovered Feelings", "atari": ["[[本:You've lived by logic]], but [[今:lately you cry reading analyses of your favorite works]].", "[[今:You want to value feelings over being right]], but [[本:you still can't help noticing the contradictions]]."]}, "INTP>ENFJ": {"karai": "Now that you look after everyone, your curiosity gets about thirty minutes a week.", "name": "The Thinker Who Started Guiding People", "atari": ["[[今:You can really be there for your juniors now]], but [[本:at home you just want to solve puzzles in silence]].", "[[今:You offer words that boost everyone's motivation]], while [[本:secretly testing how well those words work]]."]}, "INTP>ENFP": {"karai": "You seem to live on impulse, but every impulse has passed three checks beforehand.", "name": "The Logician Who Runs on Sparkle", "atari": ["[[今:You've started gushing over things you love]], but [[本:later you analyze, alone, why you gushed]].", "[[今:You enjoy meeting new people now]], yet [[本:you're more interested in the patterns of their verbal tics than in what they're saying]]."]}, "INTP>ISTJ": {"karai": "You look like a creature of routine, but you only follow precedent on days you can't be bothered to think.", "name": "The Explorer Who Picked Up Neatness", "atari": ["[[今:You run things by the manual]] while [[本:itching to rebuild the whole procedure from scratch]].", "[[今:You wake up at the same time every morning now]], but [[本:your bedtime searching is still off the rules]]."]}, "INTP>ISFJ": {"karai": "People call you kind, but honestly, you'd rather be left alone than go along with others.", "name": "The Thinker Who's Great at Caring", "atari": ["[[今:You meet requests with a smile]] while [[本:redesigning them in your head because there's a more efficient way]].", "[[今:You've started remembering people's preferences]], but [[本:the way you do it is basically a database]]."]}, "INTP>ESTJ": {"karai": "You play the responsible one, but your real talent isn't making plans. It's poking holes in them.", "name": "The Thinker Running the Floor", "atari": ["[[今:You manage schedules and keep people moving]], but [[本:on days off you'd love to read papers in your pajamas all day]].", "[[今:You tell people \"follow precedent\"]] while [[本:already spotting three holes in that precedent]]."]}, "INTP>ESFJ": {"karai": "You've gotten good at reading the room, thanks to studying it as a research subject.", "name": "The Researcher Turned Party Planner", "atari": ["[[今:You gather everyone's schedules and book the place]] while [[本:secretly working out an algorithm for the optimal date]].", "[[今:You can chat brightly with anyone now]], but [[本:what you really enjoy is digging into questions alone]]."]}, "INTP>ISTP": {"karai": "You think you're a doer now, but you still read every warning in the manual before touching anything.", "name": "The Researcher Who Got Hands-On", "atari": ["[[本:You used to just think about things]], but [[今:now if you're curious, you take it apart to check]].", "[[今:People say you've become so practical]], but [[本:even mid-task, \"why does it do that?\" never stops]]."]}, "INTP>ISFP": {"karai": "You seem easygoing, but one remark that caught your attention gets three days of analysis.", "name": "The Logician Who Chooses by Feel", "atari": ["[[今:You can pick what you love on instinct now]], but [[本:afterward you make a comparison chart to convince yourself]].", "[[今:You've learned to be there for people's feelings]], yet [[本:every so often, a contradiction in their story nags at you]]."]}, "INTP>ESTP": {"karai": "People say you're a go-getter, but that's just the backlash from years of overthinking and never moving.", "name": "The Rabbit-Hole Dweller on the Move", "atari": ["[[今:You act before you think now]], but [[本:the solo review afterward takes two hours]].", "[[今:You join in on the fun on a whim now]], but [[本:the best part is finding loopholes in the rules of the game]]."]}, "INTP>ESFP": {"karai": "Your cheerful persona is flawless, but you wrote the script alone at home after careful research.", "name": "The Logician Who Learned to Smile", "atari": ["[[今:You've become the one who livens up the room]], but [[本:on the way home you coolly analyze why the joke landed]].", "[[今:You can ride the trends and enjoy them now]], but [[本:how things become trendy interests you more]]."]}, "ESTP>INTJ": {"karai": "You stay silent like a strategist, but half that silence is \"Can we wrap this up?\"", "name": "The Daredevil With a Business Plan", "atari": ["[[今:In meetings you say \"in the long run\"]], but [[本:your feet are itching to rush out to the field right now]].", "[[今:You planned your day off perfectly, all by yourself]], yet [[本:that morning you want to flip it all with \"actually, let's hit the beach\"]]."]}, "ESTP>INTP": {"karai": "You pretend to analyze carefully, then always decide with \"Eh, sounds fun.\"", "name": "The Doer Who Overthinks", "atari": ["[[今:After three hours of reading gadget comparison articles]], [[本:you decide to buy the moment you touch one in the store]].", "[[今:You put a party invite on hold with \"I'll think about it\"]], but [[本:you're secretly the type who wants to be there first]]."]}, "ESTP>ENTJ": {"karai": "You may look like a calm commander, but the moment your competitive streak shows, the act is over.", "name": "The CEO Hopeful Who Sealed Away the Fun", "atari": ["[[今:You preach \"planning is everything\" to your team]], yet [[本:you come most alive the moment trouble hits]].", "[[今:You set goals by the year]] while [[本:thinking \"next week is next week's me's problem\"]]."]}, "ESTP>ENTP": {"karai": "You start talking like a big thinker, and three minutes later you've landed on \"Let's just try it.\"", "name": "The Hands-On Type Who Can Split Hairs", "atari": ["[[今:You started the debate with \"okay, but what if\"]], but [[本:you're dying to just test it and get the answer]].", "[[今:Halfway through passionately pitching an idea]], [[本:you're already figuring out where to buy the materials]]."]}, "ESTP>INFJ": {"karai": "You've mastered the meaningful silence, but what's inside is usually \"I'm hungry.\"", "name": "Quick Reflexes, Quiet Face", "atari": ["[[今:You nod deeply as your friend shares their problem]], while [[本:mentally lacing up your sneakers: \"so when do we move?\"]]", "[[今:Every day you read people's feelings ahead of time and tiptoe around them]], but [[本:you'd really rather just say what you think on the spot]]."]}, "ESTP>INFP": {"karai": "The sensitive persona suits you now, yet in an argument you're still the first to fire back.", "name": "The Dreamy Speed Demon", "atari": ["[[今:You were supposed to be lost in your favorite movie's world]], but [[本:you've already looked up how to get to the filming location and booked it]].", "[[今:You choose your words so you won't hurt anyone]], but [[本:honestly you're thinking, \"wouldn't it be faster to just say it?\"]]"]}, "ESTP>ENFJ": {"karai": "You look like you're doing it all for everyone, but you're the one having the most fun.", "name": "The Caretaker Who Charges In", "atari": ["[[今:You listen kindly to your juniors' worries]], but [[本:you're itching to push them with \"just try it once and you'll see\"]].", "[[今:You coordinated everyone's schedules to plan the trip]], yet [[本:you're the one itching for an unplanned detour once you're there]]."]}, "ESTP>ENFP": {"karai": "You act deeply moved, but by the next day you've forgotten the plot of the movie that moved you.", "name": "The Dreamer Who Already Pressed Go", "atari": ["[[今:You talk about dreams with \"this is so exciting!\"]], but [[本:you've already hit the sign-up button on ninety percent of them]].", "[[今:You line up comforting words for your friend's feelings]] while [[本:three solutions are already ready in your head]]."]}, "ESTP>ISTJ": {"karai": "You follow the rules only because you know breaking them is more hassle.", "name": "The Gambler Who Follows the Manual", "atari": ["[[今:You work by the manual]] while [[本:counting, \"I could skip two of these steps\"]].", "[[今:The same weekend you make a strict savings plan]], [[本:one glimpse of \"limited-time sale\" melts your willpower instantly]]."]}, "ESTP>ISFJ": {"karai": "You want to be the humble nice person, but one compliment and you're chasing the next job at double speed.", "name": "The Show-Off Working Backstage", "atari": ["[[今:You quietly take care of every favor]], but [[本:your mouth is itching to say \"look, isn't this amazing?\"]]", "[[今:You gave up your day off to fit the family's plans]], yet [[本:the second you get time alone, you're off on a drive]]."]}, "ESTP>ESTJ": {"karai": "You look organized, but your schedule exists not to be kept, but for the thrill of breaking it.", "name": "The Wild Child With a Planner", "atari": ["[[今:You tell the team \"let's hit our deadlines\"]], yet [[本:you burn brightest during the night-before crunch]].", "[[今:You're the one who made the trip itinerary]], yet [[本:you're the first to ignore it and get sucked into the food stalls]]."]}, "ESTP>ESFJ": {"karai": "You pass as nice to everyone, but with buzzkills you draw a line while still smiling.", "name": "The Considerate Risk-Taker", "atari": ["[[今:As party host you look after everyone]], but [[本:secretly you want to belt it louder than anyone at karaoke afterward]].", "[[今:You reply politely with stickers in the group chat]], but [[本:you'd really rather just send \"ok\"]]."]}, "ESTP>ISTP": {"karai": "You act like a cool lone wolf, but when nobody invites you, you quietly get lonely.", "name": "The Doer Gone Shy", "atari": ["[[今:You're content spending a day off quietly tinkering with your bike]], but [[本:part of you wants someone to say \"wow, that's cool\"]].", "[[今:You stay quiet when meeting people for the first time]], yet [[本:once you warm up, you're laughing louder than anyone]]."]}, "ESTP>ISFP": {"karai": "You pose as a laid-back artist, but the moment there's a competition, your eyes change.", "name": "The Athlete Who Runs on Taste", "atari": ["[[今:You enjoy picking out clothes you love on your own]], but [[本:you really want someone to notice them when you go out]].", "[[今:You swallow your words to put others' feelings first]], then [[本:kick pebbles on the way home thinking \"I should've said it\"]]."]}, "ESTP>ESTP": {"karai": "No one beats your drive, but someone else usually cleans up after you.", "name": "Landed Before You Could Hesitate", "atari": ["When you spot a store that looks interesting, you've opened the door and asked \"what do you recommend?\" before looking anything up.", "The more trouble hits, the sharper you get; while everyone's panicking, you've solved it and moved on."]}, "ESTP>ESFP": {"karai": "You're known as up for anything, yet when there's money to lose, you're the coolest head in the room.", "name": "Quick Reflexes Fueled by the Vibe", "atari": ["[[今:You play the one who livens things up]] while [[本:thinking \"this event could run way more efficiently\"]].", "[[今:You go all in on your friend's love story]], while [[本:itching to make them set a date: \"so when are you confessing?\"]]"]}, "ESFP>INTJ": {"karai": "You act like you see everything coming, but invite you to something fun and you toss the whole plan.", "name": "The Party Lover Wearing Cool Well", "atari": ["[[今:After stating your opinion logically]], [[本:you get home and hold a solo review: \"was I too harsh?\"]]", "[[今:Behind the serious face planning five years ahead]], [[本:you'd rather be figuring out where to dance tonight]]."]}, "ESFP>INTP": {"karai": "You call yourself logical, but your deciding factor is always \"It's cute\" or \"It looks fun.\"", "name": "The Party Crew Lost in a Rabbit Hole", "atari": ["[[今:You research what interests you alone]], but [[本:when you find something cool, you end up calling someone to tell them]].", "[[今:You insist \"logic over feelings\"]], yet [[本:you're the first to cry when the movie credits roll]]."]}, "ESFP>ENTJ": {"karai": "You may wear a capable leader's face, but your craving for praise shows more honestly than anyone's.", "name": "The Popular One Now Running the Show", "atari": ["[[今:You manage projects by the numbers]], but [[本:you're really doing it for the wrap party with the team]].", "[[今:On the night after giving someone tough feedback]], [[本:you're secretly picking out snacks to bring them]]."]}, "ESFP>ENTP": {"karai": "You pass as the quick-witted one, but after winning an argument, you keep worrying they hate you now.", "name": "The Mood-Maker Who Can Debate", "atari": ["[[今:You pick fights with \"okay, but what if\"]], but [[本:you go easy halfway because you want it to end with both of you laughing]].", "[[今:You talk up new ideas nonstop]], but [[本:your head is really full of whatever fun thing is in front of you]]."]}, "ESFP>INFJ": {"karai": "You may come off as mysterious, but you're pretty simple inside. Good food fixes any mood.", "name": "The Party Lover Lost in Thought", "atari": ["[[今:You spend your days trying to read people deeply]], but [[本:you'd rather just laugh with everyone without overthinking]].", "[[今:You decided to treasure your alone time]], yet [[本:when a weekend invite comes, you reply \"I'm in!\" in a second]]."]}, "ESFP>INFP": {"karai": "You say you've turned introverted, but drop you into a fun party and you're the loudest one in three minutes.", "name": "The Spotlight That Stayed Home", "atari": ["[[今:You're supposed to be alone in your room, lost in daydreams]], but [[本:somehow you're waiting for someone to react on social media]].", "[[今:You have more days frozen by caring too much about your feelings]], but [[本:you're really someone who wants to act on what you feel right away]]."]}, "ESFP>ENFJ": {"karai": "You play the admirable mentor, but you haven't planned a single thing for tomorrow.", "name": "The Fun-Seeker Who Became the Organizer", "atari": ["[[今:You run events with everyone's growth in mind]], yet [[本:what you're most looking forward to is the entertainment part]].", "[[今:You talk seriously about your friend's future]] while [[本:thinking, \"more importantly, where are we going this week?\"]]"]}, "ESFP>ENFP": {"karai": "You've become someone who talks about possibilities, but those possibilities mostly boil down to \"sounds fun.\"", "name": "The Fun One Who Started Daydreaming", "atari": ["[[今:You talk about grand dreams like \"someday I'll travel the world\"]], but [[本:next week's barbecue is what you're really excited for]].", "[[今:A new hobby thrilled you and you bought all the gear]], but [[本:you found a new thrill before using any of it]]."]}, "ESFP>ISTJ": {"karai": "You may think you've become sensible, but you're powerless against \"limited edition\" and \"today only.\"", "name": "The Goofball Who Got Serious", "atari": ["[[今:You take the same train every morning]] while [[本:secretly fighting the urge to hop off at some unfamiliar station]].", "[[今:You've started keeping a strict budget]], but [[本:half the receipts are \"it was fun, so it's fine\" spending]]."]}, "ESFP>ISFJ": {"karai": "You think you're low-key, but in group photos you somehow always end up dead center.", "name": "The Star Working Behind the Scenes", "atari": ["[[今:You quietly make tea for everyone at work]] while [[本:wishing a little, \"someone notice and praise me\"]].", "[[今:You put family plans first and push your own fun back]], but [[本:you really want to be the first one out the door]]."]}, "ESFP>ESTJ": {"karai": "You act organized, but in the face of a fun invite, your planner is just paper.", "name": "The Cheerful One Laying Down the Rules", "atari": ["[[今:After warning someone \"rules are rules\"]], [[本:if they look down, you carry it with you all day too]].", "[[今:You keep work running exactly to plan]] while [[本:waiting for the moment someone invites you out for an unplanned drink]]."]}, "ESFP>ESFJ": {"karai": "You call yourself a meticulous organizer, yet someone else always has to split the bill.", "name": "The Party Boss Who Learned to Plan", "atari": ["[[今:You planned the birthday party to perfection]], yet [[本:on the day you add surprise touches on the spot]].", "[[今:You're now in charge of the group's schedule]], but [[本:being the one who's invited and tags along is more fun]]."]}, "ESFP>ISTP": {"karai": "You insist you've become unsentimental, but one kitten video breaks the whole act.", "name": "The Mood-Maker Who Builds in Silence", "atari": ["[[今:You spend a day off lost in a quiet DIY project]], then [[本:snap a photo the moment it's done and send it to your friends]].", "[[今:You've learned to stay cool and not show emotion]], but [[本:inside you're riding every high and low of their reactions]]."]}, "ESFP>ISFP": {"karai": "You say you hate crowds, yet you always manage to snag presale festival tickets.", "name": "The Popular One Who Fell for Solitude", "atari": ["[[今:You meant to enjoy some alone time at your favorite café]], but [[本:you've made friends with the staff and become a regular]].", "[[今:You avoid big gatherings these days]], yet [[本:in a small group, you're the one keeping the conversation going]]."]}, "ESFP>ESTP": {"karai": "You claim to be totally chill, but get left on read and you're guessing why until bedtime.", "name": "The Mood-Maker Who Got Competitive", "atari": ["[[今:You play aggressive when there's something to win]], yet [[本:if the loser looks down, you can't help going to cheer them up]].", "[[今:You say \"let's think about what we gain\"]], but [[本:you end up prioritizing requests from people who are fun to be with]]."]}, "ESFP>ESFP": {"karai": "You're a genius at enjoying the moment, but future you is picking up the whole tab.", "name": "Born to Party", "atari": ["You reply \"I'm in!\" before even hearing the details, so your calendar is always triple-booked.", "You go all out making everyone laugh and only notice how tired you are on the way home."]}, "ENFP>INTJ": {"karai": "You play the logical one, but ask why you decided and it's \"It just felt like fate.\"", "name": "The Strategist Who Locked Up the Sparkle", "atari": ["[[今:You build your schedule for efficiency]], yet [[本:one poster you happen to see makes you want to rearrange everything]].", "[[今:You can calmly state hard facts now]], but [[本:inside you keep worrying about how the other person feels]]."]}, "ENFP>INTP": {"karai": "You say logic beats feelings, but your logic only shines when you're justifying something you love.", "name": "In Love, Down a Rabbit Hole", "atari": ["[[今:You research the things you love inside and out, alone]], and [[本:soon you know more than anyone and are dying to talk about it]].", "[[今:You find socializing a hassle]], yet [[本:the moment you meet someone on your wavelength, you talk until dawn]]."]}, "ENFP>ENTJ": {"karai": "You wear the face of a disciplined boss, but the margins of your plan are full of doodles about what to do next.", "name": "The Commander Who Put Dreams in Numbers", "atari": ["[[今:You set goals and deadlines and lead the team]], but [[本:you'd really rather everyone take off just because it sounds fun]].", "[[今:After sending tough feedback]], [[本:you keep checking your phone until they reply]]."]}, "ENFP>ENTP": {"karai": "You've started playing the tough critic, but when someone shoots down your idea, you sulk more visibly than anyone.", "name": "The Romantic in Logical Armor", "atari": ["[[今:You've become the one asking \"is there any evidence for that?\"]], yet [[本:the only evidence for your own project is \"it just clicked\"]].", "[[今:You're great at coming up with ideas]], but [[本:you'd rather choose by \"I just like it\" than by logic]]."]}, "ENFP>INFJ": {"karai": "People call you calm, except on nights your favorite star drops big news. Then you're the loudest one around.", "name": "The Talker Who Became the Listener", "atari": ["[[今:You stick to listening and sense what people really feel]], but [[本:you'd really love to spend three hours talking about what excites you]].", "[[今:Writing future plans in a notebook has become a daily habit]], but [[本:the dream changes on every page]]."]}, "ENFP>INFP": {"karai": "You call yourself an introvert, but around kindred spirits you talk so much you wear them out.", "name": "Promoter of a One-Person Film Festival", "atari": ["[[今:You've come to enjoy getting lost alone in the stories in your head]], but [[本:you're really someone whose stories feel complete only once you share them]].", "[[今:You get worn out by plans and hole up at home]], yet [[本:three days later you're desperate to see someone]]."]}, "ENFP>ENFJ": {"karai": "You look like the responsible one, but cleaning your room has been \"someday\" for about three years.", "name": "The Free Spirit Carrying Responsibility", "atari": ["[[今:You look after everyone and run the events]], but [[本:you'd really rather be the one heading out on a whim]].", "[[今:You're so reliable when juniors come to you]], yet [[本:you might be keeping your own worries to yourself]]."]}, "ENFP>ENFP": {"karai": "Nobody starts things like you do, but your closet is overflowing with gear from hobbies you abandoned.", "name": "Too Honest About What Excites You", "atari": ["You fall for new people and hobbies so fast that your camera roll looks like a different person every month.", "You're a genius at seeing the good in people, and thirty minutes after meeting someone you're saying \"this might be fate.\""]}, "ENFP>ISTJ": {"karai": "You pass as meticulous, but your planner holds more daydreams than plans.", "name": "The Daydreamer Following the Manual", "atari": ["[[今:You follow the set procedures at work]] while [[本:ten totally different projects swell up in your head]].", "[[今:You feel safe sticking to the same routine every day]], but [[本:deep down something stirs: \"is this really it?\"]]"]}, "ENFP>ISFJ": {"karai": "You seem modest and sincere, yet get on a topic you love and you talk faster and faster, unstoppable.", "name": "The Traveler in Steady Mode", "atari": ["[[今:You carefully handle the work you're given]], but [[本:you're itching to say \"it'd be more fun if we did it this way\"]].", "[[今:You put family and friends' plans first]] while [[本:imagining setting off alone for some faraway city]]."]}, "ENFP>ESTJ": {"karai": "You keep close tabs on everyone's progress, yet the deadline for your own dream keeps getting pushed back.", "name": "Writing Dreams Into the Planner", "atari": ["[[今:You lock down the team's plans]] while [[本:wanting to try much wilder ideas]].", "[[今:\"Let's be realistic\" has become your catchphrase]], but [[本:before bed you're daydreaming the next chapter of a big dream]]."]}, "ENFP>ESFJ": {"karai": "You look like the sensible organizer, but by the after-party you've given up organizing anything.", "name": "The Dreamer Turned Party Planner", "atari": ["[[今:You nail everything from picking the place to splitting the bill]], but [[本:you'd really rather invite someone on a trip with no destination]].", "[[今:You bring everyone's opinions together and keep things smooth]], while [[本:thinking \"a weirder idea would be fine too\"]]."]}, "ENFP>ISTP": {"karai": "You've become the quiet, cool type, but your inner monologue is louder than anyone's.", "name": "The Chatterbox Brain Playing Quiet", "atari": ["[[今:Calm, unemotional replies come naturally to you now]], but [[本:inside, one word from someone can toss you around all day]].", "[[今:You get lost in hands-on work alone]], and [[本:before you know it, you've named what you made and started talking to it]]."]}, "ENFP>ISFP": {"karai": "For someone who claims to be a free spirit, a weekend with zero messages hits you surprisingly hard.", "name": "The Social Butterfly Who Found Solitude", "atari": ["[[今:You spend more time alone enjoying the music and clothes you love]], but [[本:when you find something great, you have to show someone]].", "[[今:You decided to \"live in the moment\"]], yet [[本:you've just spent an hour daydreaming about ten years from now]]."]}, "ENFP>ESTP": {"karai": "You pose as a no-nonsense doer, but compliments make you visibly giddy.", "name": "The Dream-Chaser Who Got Practical", "atari": ["[[今:You make snap \"let's just move\" decisions now]], but [[本:afterward you look back wondering \"what did they think?\"]]", "[[今:You've gotten tough about competition and what's in it for you]], but [[本:you really fire up for challenges with meaning and romance]]."]}, "ENFP>ESFP": {"karai": "You're known as the fun one, but you overanalyze what all that fun meant and wear yourself out alone.", "name": "Living for Now, Dreaming of Next", "atari": ["[[今:You go all in on the event in front of you]], yet [[本:on the way home you're already planning \"next time, let's do this\"]].", "[[今:Your days are spent hopping between trendy spots]], but [[本:you really want to find places nobody knows yet]]."]}, "ENTP>INTJ": {"karai": "You look like a calm strategist, but you leave openings on purpose because you want someone to argue with you.", "name": "The Contrarian Who Made a Plan", "atari": ["[[今:You crafted a meticulous plan all by yourself]], yet [[本:the moment it's done you think, \"what if we broke it instead?\"]]", "[[今:You seem to be listening quietly in meetings]], but [[本:inside you're poking holes in everyone's points one by one]]."]}, "ENTP>INTP": {"karai": "You claim to be a quiet thinker, but with no one to talk to, you start debating yourself out loud.", "name": "The One Who Keeps Comebacks Inside", "atari": ["[[今:You spend more time thinking alone now]], but [[本:when you come up with a good argument, you're dying to throw it at someone]].", "[[今:You silently watch debates on social media]] while [[本:you've already written three long rebuttals in your head]]."]}, "ENTP>ENTJ": {"karai": "People call you decisive, but your decision is often just the most fun idea you had last night.", "name": "The Trickster in Charge", "atari": ["[[今:You set goals and deadlines and move the team]], but [[本:the most fun is the moment you flip the plan midway]].", "[[今:You run efficient meetings]], yet [[本:when small talk starts derailing things, you're the first to join in instead of stopping it]]."]}, "ENTP>ENTP": {"karai": "You're a fountain of ideas, but when it's time to execute, you've already moved to a different fountain.", "name": "The Inventor Whose Hobby Is Arguing", "atari": ["The second someone says \"that's impossible,\" you've thought of ten reasons to do it.", "Even when you totally agree, you can't resist taking the other side just to start a debate."]}, "ENTP>INFJ": {"karai": "That thoughtful silence? You're working out how to disagree without ruffling any feathers.", "name": "The Debater Who Learned Kindness", "atari": ["[[今:You read people's feelings and choose your words]], while [[本:thinking \"but that doesn't really add up, does it?\"]]", "[[今:You're quietly playing the listener]], yet [[本:when the debate heats up, you can't help leaning in]]."]}, "ENTP>INFP": {"karai": "You call yourself sensitive, but on days you lose an argument, you hold a grudge all night.", "name": "The Debate Champ Posing as a Poet", "atari": ["[[今:You savor your favorite work's world on your own]], and [[本:before you know it you're noting plot holes in a notebook]].", "[[今:You swallow your opinions so you won't hurt anyone]], then [[本:rehearse the perfect comeback in the bath at home]]."]}, "ENTP>ENFJ": {"karai": "You've settled into the nice-person role, but your occasional sharp tongue is the real you.", "name": "The Caring Prankster", "atari": ["[[今:You comfort and encourage juniors with their worries]], but [[本:you really want to say \"have you tried questioning the premise?\"]]", "[[今:You plan everything so everyone can have fun]], while [[本:sneaking in one unexpected twist]]."]}, "ENTP>ENFP": {"karai": "You pass as emotional, but after a tearjerker your review is usually \"Great screenplay.\"", "name": "The Empathetic Hair-Splitter", "atari": ["[[今:You say \"I totally get it!\" to your friend's story]] while [[本:calmly counting its contradictions in the back of your mind]].", "[[今:You look like you're running on excitement]], but [[本:you calculated how fun it'd be with logic before jumping in]]."]}, "ENTP>ISTJ": {"karai": "Under the skin of a serious, steady person, you're always drafting reforms.", "name": "The Honor Student Who Doubts the Manual", "atari": ["[[今:You work strictly by the rules]], but [[本:you're dying to ask \"who decided this rule, anyway?\"]]", "[[今:You've found comfort in following the same steps every day]], but [[本:sometimes you take a different way home for no reason, as a tiny rebellion]]."]}, "ENTP>ISFJ": {"karai": "You seem thoughtful, but you're itching to optimize even the logistics of being thoughtful.", "name": "The Rebel Who Went Quiet", "atari": ["[[今:You quietly take on what you're asked]] while [[本:three easier ways to do it pop into your head]].", "[[今:You keep a low profile to fit in]], but [[本:you really want to be first to say \"okay, but what if\" in meetings]]."]}, "ENTP>ESTJ": {"karai": "You play the rule enforcer, but for rules that don't suit you, you've got sharp excuses ready.", "name": "The Reformer Defending Precedent", "atari": ["[[今:You wrap up meetings with \"let's go with precedent\"]], but [[本:you're the one who most wants to propose breaking it]].", "[[今:You've mastered your task app]], yet [[本:you switch every time a new one comes out]]."]}, "ENTP>ESFJ": {"karai": "You're known as everyone's ally, but inside you're quietly scoring everything everyone says.", "name": "The Sharp Tongue That Reads the Room", "atari": ["[[今:As host you nod along with everyone's opinions, smiling]], while [[本:holding back the most twisted comment in the room]].", "[[今:You shift your opinions to match how people feel]], but [[本:at home you check: \"wait, that logic was off\"]]."]}, "ENTP>ISTP": {"karai": "You look like a quiet craftsman, but the moment you spot something to call out, you suddenly can't stop talking.", "name": "The Logician Who Tests in Silence", "atari": ["[[今:You work with your hands more than you argue now]], but [[本:while you work, you're debating yourself nonstop]].", "[[今:You take machines and tools apart to see how they work]], and [[本:the daydreams of \"I could mod this into something more fun\" never stop]]."]}, "ENTP>ISFP": {"karai": "You seem laid-back, but when you speak, you hit a nerve with the gentlest face.", "name": "The Gentle Cynic", "atari": ["[[今:You enjoy a life of choosing what you love by feel]], but [[本:ask why and you suddenly start explaining with theory]].", "[[今:You keep things calm so you never clash with anyone]], but [[本:just once, you'd love to start a real debate]]."]}, "ENTP>ESTP": {"karai": "You present as a doer, but nobody has ever beaten you at getting bored fast.", "name": "The Debater Who Tests Before Thinking", "atari": ["[[今:You try things before arguing about them now]], but [[本:when it works, you spend thirty minutes explaining why]].", "[[今:You act like you decided on a whim]], but [[本:you actually simulated five possible outcomes in your head]]."]}, "ENTP>ESFP": {"karai": "You pass as happy-go-lucky, but boring talk doesn't even get a polite laugh out of you.", "name": "The Schemer Hiding Behind Fun", "atari": ["[[今:You're goofing around with everyone]], yet [[本:out of nowhere you say \"wouldn't this game be more fun if we changed the rules?\"]]", "[[今:You look like you put fun first]], but [[本:you're coolly reading who to team up with for the most fun]]."]}, "ESTJ>INTJ": {"karai": "Once you realized doing it yourself was faster than delegating, you just stopped relying on anyone.", "name": "The Foreman Who Directs in Silence", "atari": ["[[今:You listen quietly in meetings]], yet [[本:on the way home you're reassigning everyone's roles in your head]].", "[[本:Where you once would've barked the orders]], [[今:now you prepare flawless materials and sit in the back row]]."]}, "ESTJ>INTP": {"karai": "You act like a free spirit, but you still get properly mad at people who show up late.", "name": "The Ex-Organizer Who Tossed the Planner", "atari": ["[[本:You're supposed to be the one who loves a plan]], but [[今:now you start researching \"do we even need this?\" until the sun goes down]].", "[[今:You turn down being the party host]], yet [[本:somehow your restaurant comparison chart is more detailed than anyone's]]."]}, "ESTJ>ENTJ": {"karai": "You love proposing new things, but someone else's new idea first gets \"Has anyone done this before?\"", "name": "Running the Floor and the Vision", "atari": ["[[今:While you talk about big dreams]], [[本:your notes are filling up with dates and names of who's responsible]].", "[[本:Your old self is the most surprised of all]] that [[今:you can now say \"let's do it precisely because it's never been done\"]]."]}, "ESTJ>ENTP": {"karai": "You call yourself a rule-breaker, but when others break the rules you set, you get pretty grumpy.", "name": "The Hall Monitor Itching to Break Rules", "atari": ["[[今:You're the one saying \"okay, but what if\" in meetings]], yet [[本:once it's decided, you track progress more seriously than anyone]].", "[[本:You used to be the one enforcing the rules]], but [[今:now finding a loophole makes you oddly happy]]."]}, "ESTJ>INFJ": {"karai": "You play the gentle listener, but the third time someone brings the same problem, you start taking minutes in your head.", "name": "The Drill Sergeant Who Reads Every Face", "atari": ["[[今:You listen and nod silently to your junior's worries]] while [[本:breaking the fix into three steps in your head]].", "[[本:You're the type who wants things black and white]], but [[今:now you read their face and push the decision to next week]]."]}, "ESTJ>INFP": {"karai": "You cherish your sensitive side, but other people's excuses still get your old strictness.", "name": "The Dreamy Planning Boss", "atari": ["[[今:On weekends you sink into your favorite stories]], but [[本:Monday morning, the planning monster suddenly wakes up]].", "[[本:\"If I say it, I do it\" used to be your creed]], but [[今:now you're practicing forgiving yourself on days you're not feeling it]]."]}, "ESTJ>ENFJ": {"karai": "You're known as caring, but you stop caring for people who won't listen pretty fast.", "name": "The Caretaker Who Presses Gently", "atari": ["[[今:Right after saying \"you okay? don't push yourself\"]], [[本:you double-check their deadline]].", "When your team reports in, you're sometimes surprised that [[今:\"great job\" comes out before the numbers]]."]}, "ESTJ>ENFP": {"karai": "You try hard to seem easygoing, but after the third change of plans, your face goes blank.", "name": "The Manager Pretending to Be Carefree", "atari": ["[[今:You act like the trip was decided on a whim]], but [[本:before leaving, you've sent everyone a packing list and meet-up time]].", "[[本:Holding back your wish to stick to the plan]], [[今:you're trying to enjoy going along with spur-of-the-moment ideas]]."]}, "ESTJ>ISTJ": {"karai": "You act reserved, but when someone runs things sloppily, you redo it all in your head.", "name": "The Team Lead Who Stopped Giving Orders", "atari": ["[[本:You tuck away your urge to lead everyone]], and [[今:now you nail your own part and quietly leave right on time]].", "When no one in the group chat will decide, [[今:you hold out on \"read\"]], and [[本:end up dropping a proposed date in the middle of the night]]."]}, "ESTJ>ISFJ": {"karai": "You look devoted, but you keep devoting yourself until they do things your way.", "name": "The Organizer Who's Great at Saying Yes", "atari": ["[[今:You take on requests with a smile]] while [[本:reworking the plan in your head: \"you could've told me sooner\"]].", "[[本:Where you'd like to say \"this is how it should be done\"]], [[今:now you think of a gentle way to say it three times before speaking]]."]}, "ESTJ>ESTJ": {"karai": "When you say \"Normally, you'd do it this way,\" \"normal\" usually means your own rules. You haven't noticed.", "name": "The Born Schedule Master", "atari": ["The moment someone mentions a trip, you've made a spreadsheet and shared the hotel and meet-up time before anyone else.", "You always do what you say, and you always remember who doesn't. No hidden sides, and proud of it."]}, "ESTJ>ESFJ": {"karai": "You say you value everyone's opinions, but somehow your original idea always wins.", "name": "The Class Rep Who Leads With a Smile", "atari": ["[[本:Before you can say \"that's wrong\"]], [[今:you now physically can't speak without slipping in a \"love that!\" first]].", "[[今:As party host you ask everyone's likes and dislikes]] while [[本:calculating the budget and timing in seconds]]."]}, "ESTJ>ISTP": {"karai": "You act like you go at your own pace, but disrupt that pace and you complain in more detail than anyone.", "name": "The Craftsperson Who Doesn't Make Plans", "atari": ["[[本:You used to plan before you moved]], but [[今:now you just get your hands going before reading the instructions]].", "[[今:On days off you fix things around your room and see no one]], yet [[本:somehow you come up with ways to improve weekday work]]."]}, "ESTJ>ISFP": {"karai": "You act like you don't fuss over things, but you're still strict with anyone who sorts the recycling wrong.", "name": "The Ex-Class President Who Wants Freedom", "atari": ["[[本:You're the type who likes things done properly]], but [[今:now you're trying to choose clothes and work just because you like them]].", "[[今:From the day you decided to take life easy]], [[本:you've somehow been drafting a plan for taking life easy]]."]}, "ESTJ>ESTP": {"karai": "Adaptability is your selling point, but when someone else changes plans on the spot, it's \"Nobody told me.\"", "name": "The One Who Runs Things on the Run", "atari": ["[[今:You've started acting first and thinking later]], yet [[本:you never skip the review session afterward]].", "[[今:Since learning that plans made on the spot often work better]], your planner has a little more white space."]}, "ESTJ>ESFP": {"karai": "You say all that matters is having fun, but when someone plans something un-fun, you critique it for real.", "name": "The Director Who Hypes the Room", "atari": ["[[今:At parties, you're the biggest hype person there]], yet [[本:you've neatly sorted out who's sharing which cab home]].", "[[本:Someone for whom results were everything]] [[今:can now end the day with \"it was fun, so it's fine\"]]."]}, "ESFJ>INTJ": {"karai": "You insist you're not driven by emotion, but if someone forgets your birthday, you hold it against them all day.", "name": "The Host Playing It Cool", "atari": ["[[今:You act like you turned down the invite for logical reasons]], but [[本:you worry about the person you turned down all night]].", "[[今:\"It's faster to do it alone\" is your catchphrase]], yet [[本:you're always the one handing out snacks to the team]]."]}, "ESFJ>INTP": {"karai": "You act detached, but you can't hide how your voice goes up a notch the moment someone needs you.", "name": "The Popular One Hiding Behind Logic", "atari": ["[[本:Before your true wish to be useful to someone kicks in]], [[今:now you find yourself thinking \"what's the point of that?\"]]", "[[今:Even when you're deep in research alone]], [[本:you reply in seconds when a friend messages for advice]]."]}, "ESFJ>ENTJ": {"karai": "You think you're being firm, but when someone disagrees, your first move is \"You're not mad, right?\"", "name": "The Big-Hearted One-Person Show", "atari": ["[[今:After giving tough instructions]], [[本:you can't stop yourself from quietly leaving snacks as a follow-up]].", "[[本:Deep down you want everyone to like you]], but [[今:now you'll play the bad guy if that's what gets results]]."]}, "ESFJ>ENTP": {"karai": "You enjoy playing the debate champ, but when you really win, you send an apology emoji afterward.", "name": "The Host Who Brings the Comebacks", "atari": ["[[今:You stir up the debate with \"okay, but what if\"]], then [[本:the moment the mood cools, you hurry to compliment everyone]].", "[[本:You're supposed to be happy with the usual place and the usual crew]], but [[今:now you're the one saying \"let's try something new\"]]."]}, "ESFJ>INFJ": {"karai": "You play the quiet one, but a group chat buzzing without you still makes you uneasy.", "name": "The Host Who Cares From Afar", "atari": ["[[今:You skip big parties]], yet [[本:you still prepare a little gift for the people who couldn't come]].", "[[本:You're someone who likes being in the middle of everyone]], but [[今:now you watch over everyone's faces from a little distance]]."]}, "ESFJ>INFP": {"karai": "You say you like being alone, but you're always waiting for someone to ask, \"How've you been?\"", "name": "The Caretaker Who Went Indoors", "atari": ["[[今:You sink into story worlds alone at home]], yet [[本:every friend's birthday is in your calendar]].", "[[今:You lie awake alone wondering \"what does being myself even mean?\"]], and [[本:by morning you're back to listening to your friends' worries]]."]}, "ESFJ>ENFJ": {"karai": "You say it's for their sake, but you're happiest when they grow into the ideal you pictured.", "name": "The Host Who Looks After Dreams Too", "atari": ["[[本:You were only supposed to listen to your friend vent]], but [[今:somehow you're planning their future with them]].", "[[本:It used to be enough to see the person in front of you smile]], but [[今:now you can see their whole potential]]."]}, "ESFJ>ENFP": {"karai": "You seem to live freely, but posts with too few likes get quietly deleted at midnight.", "name": "The Party Starter Who Forgot the Plan", "atari": ["[[今:You invite everyone on a whim with \"let's meet up now!\"]] while [[本:quietly checking everyone's last train]].", "[[今:Every time you find a new place]], [[本:you think \"would everyone like this?\" before snapping a photo]]."]}, "ESFJ>ISTJ": {"karai": "You say \"Rules are rules,\" but half those rules are really \"so nobody gets stuck.\"", "name": "The Caring One With a Poker Face", "atari": ["[[今:You seem to just calmly get through your work]], but [[本:you're the first to notice a coworker feeling down]].", "[[今:In meetings you say only what's necessary]], yet [[本:your voice suddenly brightens during break-time chat]]."]}, "ESFJ>ISFJ": {"karai": "You say you don't need to stand out, but when no one notices your thoughtfulness, you sulk a little.", "name": "The Host Who Moved Backstage", "atari": ["[[今:At the after-party you sit in the corner]], but [[本:your eyes never stop checking that no one's glass is empty]].", "[[本:You used to love thanks from a crowd]], but [[今:now one person's words can keep you going for a week]]."]}, "ESFJ>ESTJ": {"karai": "You push through with logic, but the second they look close to tears, you're ready to reverse everything.", "name": "The Host in Business Mode", "atari": ["[[今:After a meeting where you pressed people on the numbers]], [[本:you hold a solo review in the restroom: \"was I too much?\"]]", "[[今:The efficiency-first persona suits you now]], but [[本:even with someone who missed a deadline, you start with \"are you feeling okay?\"]]"]}, "ESFJ>ESFJ": {"karai": "You say it's all for everyone, but when nobody thanks you, it quietly hurts, and you remember it forever.", "name": "The Born Host", "atari": ["The moment someone says \"where should we go?\", you've got three options and their open reservations ready.", "You're great at remembering birthdays and favorite foods, and you start prepping the celebration before the person does."]}, "ESFJ>ISTP": {"karai": "You act uninterested in people, but you know the office relationship map better than anyone.", "name": "The Craftsperson Who Put Away the Charm", "atari": ["[[今:Working quietly alone feels easy now]], yet [[本:when someone's struggling, your hands go to help on their own]].", "[[今:You deliberately set aside days off to talk to no one]], yet [[本:by evening you somehow want to call someone]]."]}, "ESFJ>ISFP": {"karai": "You say you'll go with the flow, but you've already got three possible dates in mind for hanging out.", "name": "The Caring One at Their Own Pace", "atari": ["[[今:You want to live choosing only what you love]], yet [[本:when picking a gift, you research their tastes thoroughly]].", "[[今:You're starting to like the you who can say \"let's go with the mood\"]], but [[本:right after saying it, you feel a little uneasy]]."]}, "ESFJ>ESTP": {"karai": "You think you're breezy, but get left on read and you reopen the chat about three times.", "name": "The Caretaker Who Goes With the Flow", "atari": ["[[今:You jump on invites in the heat of the moment]] while [[本:keeping a side eye out for anyone about to be left behind]].", "[[今:Saying \"let's just go\" feels weirdly good]]. But [[本:once you arrive, you've ordered everyone's drinks first]]."]}, "ESFJ>ESFP": {"karai": "You say you live on vibes, but if the party fell flat, you analyze why the whole way home.", "name": "The Party Captain Who Let Go of the Plan", "atari": ["[[今:You've come to love meeting up on the day's vibe]], yet [[本:you always take photos for the people who couldn't come]].", "[[今:Days you dive into any open place without a reservation are more fun]]. But [[本:you're the first to check there are enough seats for everyone]]."]}, "ENFJ>INTJ": {"karai": "You decided to stop expecting things from people, yet you keep expecting too much and getting let down.", "name": "The Strategist Hiding Their Ideals", "atari": ["[[今:After coldly stating the hard truth]], [[本:you keep telling yourself \"it was for their own good\"]].", "[[本:You're someone who wants to encourage and lead people]], but [[今:now you'd rather craft the perfect plan alone]]."]}, "ENFJ>INTP": {"karai": "You say relationships are a hassle, but maybe you just don't have anyone to fuss over right now.", "name": "The Researcher Hiding Their Fire", "atari": ["[[今:You love time alone mulling over theories]], yet [[本:the moment someone asks for life advice, the heartfelt quotes won't stop]].", "When a friend shares their dream, [[今:\"is there any basis for that?\" comes out before any encouragement]]."]}, "ENFJ>ENTJ": {"karai": "You play the rational leader, but behind the scenes, worrying about everyone's reactions wears you out.", "name": "The Leader Who's a Little Too Fired Up", "atari": ["[[今:You press your team on the numbers]], yet [[本:in one-on-ones you draw out everyone's dreams and remember them all]].", "[[本:You're someone who wants to put feelings first]], but [[今:now you say \"so what's the bottom line?\" before they finish talking]]."]}, "ENFJ>ENTP": {"karai": "You pose as a contrarian, but one \"thank you\" and you're sincere again in seconds.", "name": "The One Who Shows Love Through Debate", "atari": ["[[今:You argue the other side on purpose to liven up the debate]], but [[本:you always wrap it up in a way everyone can accept]].", "[[今:When a junior pitches an idea, you look for holes first]], then [[本:hurry to list five good points after]]."]}, "ENFJ>INFJ": {"karai": "You think you're just watching over them, but you're on edge until they pick the path you had in mind.", "name": "The Cheer Captain Watching Quietly", "atari": ["[[本:Rather than giving a speech to a crowd]], [[今:listening to one person for three hours at a diner feels right these days]].", "[[今:Even when you notice someone struggling, you don't say anything]], but [[本:you set up an atmosphere where they'll find it easy to talk]]."]}, "ENFJ>INFP": {"karai": "You say you'll live true to yourself, but you check how \"you\" you are by other people's reactions.", "name": "The Dreamer on a Break From Caretaking", "atari": ["[[今:You decided to value your own feelings]], yet [[本:your journal ends up being all about other people's]].", "[[今:On a free day you watch a movie alone and cry]], then [[本:genuinely worry about the side characters' futures]]."]}, "ENFJ>ENFJ": {"karai": "You love the version of you who works hard for others so much that a \"no thanks\" hurts you more than them.", "name": "The Born Cheer Captain", "atari": ["You applaud your friends' smallest challenges with your whole heart, and you're close to tears before they are.", "Nobody asked, but you help a junior think through their career, and suddenly you've scheduled a meeting."]}, "ENFJ>ENFP": {"karai": "You look like a free spirit, but you keep glancing back to make sure everyone's keeping up.", "name": "The Caretaker Who Follows the Sparkle", "atari": ["[[今:You start new things on a whim]], and [[本:before long you're looking after the friend who started with you]].", "[[本:You're someone who wants to make a plan and guide everyone]], but [[今:now you change direction on every spark of inspiration]]."]}, "ENFJ>ISTJ": {"karai": "You say you keep emotions out of work, but at farewell parties you're usually the first to cry during the speech.", "name": "The Tidy One Who Put Away the Passion", "atari": ["[[今:You work calmly by the manual]], yet [[本:you secretly keep notes on how the new hires are growing]].", "[[本:You're someone who wants to talk about big ideals]], but [[今:now saying \"let's follow precedent\" feels safer]]."]}, "ENFJ>ISFJ": {"karai": "You think you're quietly supporting, but you have plenty to say about other people's big life decisions.", "name": "The Great Manager Behind the Scenes", "atari": ["[[今:You stepped down from giving pep talks in front of everyone]], yet [[本:you attach a different note for each person to the snacks you bring]].", "[[本:Rather than chasing a big dream together]], [[今:these days you care more about whether the one person in front of you is really smiling]]."]}, "ENFJ>ESTJ": {"karai": "You play the strict boss, but when someone pleads, you end up bending the rules.", "name": "Writing Ideals Into the Schedule", "atari": ["[[本:You're someone who wants to believe in people's potential]], but [[今:now you start with the deadline: \"so when can you have it done?\"]]", "[[今:You manage the team's goals by the numbers]], yet [[本:on the day you hit them, you give everyone a handwritten message]]."]}, "ENFJ>ESFJ": {"karai": "You think you're taking care of everyone, but you're taking away quite a bit of their freedom too.", "name": "The Caretaker Who Lives for Right Now", "atari": ["[[本:Instead of talking about big dreams]], [[今:now you pour everything into picking this week's dinner spot]].", "[[本:Rather than mapping out someone's future with them]], [[今:your days are busy sending \"did you eat today?\" texts]]."]}, "ENFJ>ISTP": {"karai": "You think you live unsentimentally, but feel-good videos make you cry faster than anyone.", "name": "The One Who Packed Love Into a Toolbox", "atari": ["[[今:You've stopped cheering people on with words]], yet [[本:when a friend's bike breaks, you quietly go fix it]].", "[[本:You're someone who wants to light a fire in people's hearts]], but [[今:now you find yourself saying \"either is fine\" more often]]."]}, "ENFJ>ISFP": {"karai": "You say you never meddle, but when someone you love is struggling, you dive in headfirst.", "name": "The Cheer Captain Blooming Solo", "atari": ["[[本:Since stepping down from guiding people]], [[今:you're finally enjoying time spent picking out knickknacks and music you love]].", "[[今:You don't stand in front of crowds anymore]], but [[本:you quietly give handmade things to the people you like]]."]}, "ENFJ>ESTP": {"karai": "You play it light and breezy, but bring you a serious problem and you'll still talk until dawn.", "name": "The One Who Turned Passion Into Action", "atari": ["[[今:Your body moves before any words of encouragement]], and [[本:soon you're carrying all of someone's bags]].", "[[本:You're someone who wants to move people by talking about ideals]], but [[今:now you push through with \"let's just try it\"]]."]}, "ENFJ>ESFP": {"karai": "You laugh and say fun is all that matters, but secretly you're scheming to make everyone's life a little better.", "name": "The Mood-Maker Lighting Up the Room", "atari": ["[[今:You decided to enjoy today without thinking ahead]], yet [[本:on the way home you're worrying about everyone's plans for tomorrow]].", "[[今:You make the whole party laugh]], and [[本:when someone's left out in the corner, you go sit right next to them]]."]}, "ENTJ>INTJ": {"karai": "You stay out of the spotlight not out of humility, but because you can't be bothered to explain.", "name": "The Commander Who Stays Out of Front", "atari": ["[[今:You don't say a word in the meeting]], yet [[本:by the end, it wraps up with the conclusion you prepared]].", "[[今:You say it doesn't matter who decides]], but [[本:on days your idea doesn't win, you rework your strategy on the way home]]."]}, "ENTJ>INTP": {"karai": "You say you'll go with the flow, but anything decided without you always gets a \"Why?\"", "name": "The CEO With a Decision on Hold", "atari": ["[[本:You're someone who wants to reach conclusions fast]], but [[今:now the more you research, the more options pile up and you can't decide]].", "[[今:You're happily toying with hypotheses on your own]], yet [[本:when someone rambles, you suddenly start running the conversation]]."]}, "ENTJ>ENTJ": {"karai": "When you ask \"Any thoughts?\", you're really just counting who agrees with your plan.", "name": "The Born Decision-Maker", "atari": ["When everyone's stuck choosing a lunch spot, you decide in three seconds and have ordered for the whole table.", "Working backward from goals is just normal to you; honestly, a life without a plan makes no sense to you."]}, "ENTJ>ENTP": {"karai": "You think you've become flexible, but to everyone else, you decide just as fast as ever.", "name": "The Leader Who Keeps Going Off Track", "atari": ["[[本:You're supposed to be the one who lands the conclusion]], but [[今:every time you think of something fun, you add another agenda item]].", "[[本:You made a plan to win]], but [[今:you're itching to try another strategy that came to you halfway]]."]}, "ENTJ>INFJ": {"karai": "People think you're gentle, but you quietly cut ties with anyone who doesn't make sense.", "name": "The Commander Who Leads by Sensing", "atari": ["[[今:You listen with care for how they feel]], while [[本:you've already decided where this will land]].", "[[本:You're someone who wants to step up and take command]], but [[今:now you try to lead by helping people realize things themselves]]."]}, "ENTJ>INFP": {"karai": "You say you hate conflict, but years later you still remember every match you lost, in detail.", "name": "The Ex-CEO Who Talks About Dreams", "atari": ["[[今:You tell yourself \"just do what you love\"]], yet [[本:you want to be number one even at what you love]].", "[[今:Even when you're lost in daydreams alone]], [[本:in those daydreams you're firmly leading an organization]]."]}, "ENTJ>ENFJ": {"karai": "You aim to be a leader with heart, but behind every compliment is the next target.", "name": "The Meritocrat Who Speaks From the Heart", "atari": ["[[今:While giving a speech to encourage the team]], [[本:you're already planning the next reshuffle]].", "[[本:You're someone who'd rather win with hard facts]], but [[今:now you choose words that won't kill their motivation]]."]}, "ENTJ>ENFP": {"karai": "You look like you live freely, but the moment you realize you're falling behind, you go full throttle.", "name": "Ambition Wrapped in Sparkle", "atari": ["[[今:Something you started with \"this looks fun, let's do it!\"]] [[本:somehow becomes a business plan six months later]].", "[[今:You say you decided on \"does it excite me?\"]], but [[本:behind the scenes you've calculated your odds of winning]]."]}, "ENTJ>ISTJ": {"karai": "You call yourself steady, but when a promotion opens up, your hand shoots up first.", "name": "The Ambitious One Who Follows Procedure", "atari": ["[[今:You quietly work through the set procedures]] while [[本:thinking \"if it were me, here's how I'd change this department\"]].", "[[本:You're someone who wants to announce huge goals]], but [[今:now you only say what you know you can deliver]]."]}, "ENTJ>ISFJ": {"karai": "You say you're suited to supporting roles, but nobody gets a say in how you support.", "name": "The CEO in an Apron", "atari": ["[[今:You carefully handle the chores you're asked to do]], and [[本:before long you've redesigned the whole system behind them]].", "[[今:You've started asking \"what would you like to do?\" first]], but [[本:you usually prepared the options yourself]]."]}, "ENTJ>ESTJ": {"karai": "You say you've become realistic, but inside you haven't given up on conquering the world.", "name": "The Visionary Who Went Practical", "atari": ["[[本:Instead of talking about dreams ten years out]], [[今:now you're fired up about hitting this month's numbers]].", "When you hear a new idea, [[今:you start a responsibility chart with \"so who's doing it, and when?\"]]."]}, "ENTJ>ESFJ": {"karai": "You say you value the mood in the room, but you never let go of the final say.", "name": "The Commander Who Wants to Be Liked", "atari": ["[[今:You host the party flawlessly]] while [[本:also memorizing a map of everyone's connections]].", "[[今:Every time a meeting drags on hunting for an idea that saves everyone's face]], [[本:you think your old self would've decided in five minutes]]."]}, "ENTJ>ISTP": {"karai": "You pose as a lone wolf, but tell you to build a pack and you'd draw up an org chart overnight.", "name": "The Hands-On Type Who Stopped Commanding", "atari": ["[[本:You're someone who wants to move people toward big results]], but [[今:now you're satisfied with what you can do with your own hands]].", "[[今:You've decided not to butt in]], yet [[本:when someone's working inefficiently, you silently take the tool from them]]."]}, "ENTJ>ISFP": {"karai": "You say you're not interested in competing, but your need to win hasn't faded one bit.", "name": "The Free Spirit With Ambition on Pause", "atari": ["[[今:You meant to enjoy your hobby casually]], but [[本:somehow you've become the one running the hobby group]].", "[[今:You decided not to compare yourself and cut back on social media]], yet [[本:news of a friend's promotion strangely sticks with you]]."]}, "ENTJ>ESTP": {"karai": "You look like you're winging it, but in your mind, it was all part of the plan.", "name": "The General Who Moves Before Planning", "atari": ["[[本:You're someone who wants a long-term strategy before attacking]], but [[今:now you've learned you win more by deciding on the ground]].", "[[今:Even with a game started on a whim]], [[本:before long you've made rules and are keeping score]]."]}, "ENTJ>ESFP": {"karai": "You pretend to live on vibes, but you always go after the spotlight.", "name": "The Ambitious One Who Knows How to Party", "atari": ["[[今:You look like you're having more fun than anyone at the party]], and [[本:by the end, you've been named host of the next event]].", "[[今:You now pick people to work with by \"are they fun to be around?\"]], but [[本:the ones you pick are usually great at the job too]]."]}};
var PS={"INTJ": {"catch": "The answer-before-you-speak type. You read ahead quietly and map out the path.", "overview": "By the time everyone else starts talking it over, you can already see the shape of the answer in your head. You look at things over the long run, asking “Where is this going?”, and you're good at building a route with little waste. What moves you is a reason that makes sense and the freedom to think things through and decide for yourself. You do your best work not because someone told you to, but when something feels logical. You don't talk a lot, so people sometimes see you as cool or hard to approach. But when they come to you for help, you give answers that are surprisingly on point. Plenty of people trust you for that quiet kind of reliability.", "strengths": ["You plan ahead｜You don't just look at what's in front of you. You picture six months or a year from now and act on it. You deal with trouble before it starts, so your plans hold steady.", "You think things all the way through｜You keep working on a problem until you reach an answer. You don't get swept along by other people's opinions. You check things in your own head first, so your decisions stay firm.", "You spot waste and clean it up｜You're quick to notice, “Do we even need this step?” You can rethink how things work and save everyone time and effort.", "You can keep going on your own｜Even without everyone on board, you quietly see through what you believe is right. That attitude often ends up leading others, too."], "pitfalls": ["You skip the explanation｜The answer is all connected in your head, so you tend to share only the conclusion and leave out the steps. Adding just one line about why makes you much easier to follow.", "Other people's inefficiency bugs you｜You see waste so clearly that people who go by feelings can seem to take the long way around. It helps to remember they have their own order of what matters.", "You carry it all yourself｜It feels faster to just do it yourself, so you put off asking for help. Try handing off small tasks first. Sharing the load gives you breathing room."], "relationships": "You're fine without a lot of friends. Instead, once you trust someone, the friendship tends to be long and deep. You may not say much in the group chat, but when someone asks you for advice one-on-one, you think hard and give a real answer. At work or in a club, you're the one who says the line that cuts to the heart of things when a discussion gets stuck. You get along best with people who respect your alone time and talk to you directly, without beating around the bush.", "love": "It takes you a while to fall for someone. But once you feel, “This is the one,” you're very sincere about it. Instead of flashy words, you show your feelings by working through your partner's worries with them and talking seriously about the future. You value a relationship where you both respect each other's way of thinking. Where things can go wrong: you don't put your feelings into words very often. Just saying “I'm happy” or “Thank you” out loud makes your partner feel much more secure.", "work": "You shine when the goal is clear and you're trusted to choose how to get there. You tend to be valued in roles where you research, think, and turn plans into reality. People often come to you because “talk to them and you'll see the way forward.” On the other hand, you wear out fast in workplaces full of rules no one can explain, or endless meetings that never decide anything. Just protecting time to focus can boost your results a lot.", "jobs": ["Corporate planning / business strategy", "Systems design / engineering", "Research", "Data analyst", "Architecture / urban planning"], "growth": "When you share a conclusion, try adding just one sentence about why you think so. That alone changes how much people buy in. It also helps to set aside some time each day to listen to someone all the way through without cutting in. Meeting views you don't have yourself makes your plans even stronger.", "A": "When you're Assertive, you rarely second-guess yourself, and once you decide, you go straight for it. Pushback doesn't shake you much, and you keep plans moving calmly. Your strength is sharing your ideas with confidence, even in front of others.", "T": "When you're Cautious, your thoroughness shines. You check your plans again and again for holes. The feeling that “this could be better” drives you to improve, and you raise the quality down to the small details. When you feel anxious, try writing it all down on paper. It helps."}, "INTP": {"catch": "The down-the-rabbit-hole type. You love asking “Why is that?”", "overview": "When a small question pops up, you look up and realize you've been researching it for hours. Your biggest driver is wanting to know how things work: “Why does this happen?” “Is that really true?” You'd rather think something through until it makes sense to you than just memorize the answer. Time alone recharges you, and there are always several ideas running in your head at once. People may see you as someone who moves at your own pace and is a bit of a mystery. But once they talk with you, they find you know a wide range of things and come up with interesting answers from unexpected angles. Your free-ranging ideas can change the mood when a group is stuck.", "strengths": ["You see how things work｜Even with a complicated topic, you can find the key part and sort it out. You're good at showing the skeleton of an idea: “So basically, it's this, right?”", "You don't take things for granted｜You don't decide something just because everyone says so. You check for yourself whether it's really right. That's how you catch problems others missed.", "You focus deeply on what you love｜You can get amazingly absorbed in topics that interest you. The things you look up start to connect, and often you end up knowing more than anyone.", "You stay calm and fair｜When opinions clash, you don't get carried away by emotion. You compare each side calmly. No matter who's speaking, you value the idea that makes the most sense."], "pitfalls": ["You overthink and get stuck｜You think of so many possibilities that you can't commit, in case there's a better way. Setting yourself a rough deadline makes the first step easier.", "Feelings talk is hard for you｜Logic comes naturally, so you may offer a fix when someone just wants you to understand. Starting with “That sounds really hard” helps you connect.", "Your interest jumps around｜New questions pull at you, and half-finished things pile up. Write down just one thing you've started. It helps you build a habit of finishing."], "relationships": "You'd rather go deep on a favorite topic with a few people than spend time in a big, noisy crowd. Among friends, you're the one who tosses out a small question and gets the conversation going. At work or school, people trust you as the one who says, “I looked it up,” and brings useful knowledge when they're stuck. You get along best with people who don't mind when you suddenly go quiet to think, and who say, “That's interesting!” when you share your ideas.", "love": "Love often starts with wanting to know more about someone. You get curious about how they think and what they like, and you grow closer through long talks. You value a relationship where you both stay free. Where things can go wrong: you tend to put off replying, or you don't put your feelings into words. Even a short message like “Here's what happened today” helps your partner feel secure.", "work": "You do your best where you can think at your own pace and try new things. You tend to be valued in roles like finding the cause of a problem, building systems, or coming up with new ways of doing things. On the other hand, you wear out fast with repetitive tasks that just follow set steps, or lots of reports that seem pointless. Once you know why something needs doing, you can focus amazingly well.", "jobs": ["Programmer", "Researcher", "Data scientist", "Game designer", "Technical writer"], "growth": "Try talking about what you're thinking before it's finished. Sharing it halfway can bring hints you'd never expect. It also helps to set a timer for “just 30 minutes” before you start researching something. You keep the fun of diving deep, and you can still come back to what you need to do.", "A": "When you're Assertive, you trust your ideas and say them out loud easily. You don't dwell on mistakes much, and you deepen your thinking as you try things. Your strength is jumping into new things lightly.", "T": "When you're Cautious, your care shines. You check your thinking again and again for gaps. Because of that, your answers are very precise, and people trust them. When you're unsure, try sharing what you know so far instead of waiting for perfect. It takes the pressure off."}, "ENTJ": {"catch": "The “Okay, I'll decide” type. You're the one people count on to get a stuck group moving.", "overview": "When everyone's unsure and the talk stalls, you're the one who says, “Okay, let's do this,” and points the way. Once you find a goal, you quickly lay out the steps to get there, then pull together people and resources to make it happen. What moves you is seeing growth and results. When you can feel you've moved forward, even a little, compared to yesterday, your energy keeps building. People often see you as dependable, a leader they can rely on, and you tend to end up in charge. You can sometimes seem strict, but that comes from truly wanting a good result. Many people likely watch you and think, “If I follow them, it'll be fine.”", "strengths": ["You decide and get things moving｜Even when there are too many options, you can set clear criteria and make the call. One word from you, and a stalled discussion starts moving again.", "You're great at planning steps｜You're good at breaking a big goal into what to do today and next week. Everyone knows who does what, so the team can move easily.", "You enjoy big goals｜The harder the challenge, the more fired up you get. Even things people thought were impossible, you can bring closer step by step.", "You say things clearly｜You don't leave things vague. You put what's needed into plain words. People know what's expected, so they can act with confidence."], "pitfalls": ["You expect others to keep your pace｜Your own speed becomes the standard, and you assume others can move just as fast. Asking about their situation before you ask for help gets you more support.", "You rush results and can't rest｜You love moving forward, so you tend to feel guilty about resting. Put rest into your schedule as part of the plan. That way you can keep going for the long run.", "Your words land harder than you mean｜You mean to be clear, but it can sound harsh to others. Mention one thing that went well before you point something out. It helps people take it in."], "relationships": "Among friends, you naturally take charge of planning trips and get-togethers. When the group chat stalls on “Where should we go?”, you suggest a few options and it's settled right away. At work or in a club, you're the one who brings everyone together toward a goal. You get along best with people who give you clear opinions back, or who enjoy your energy. Taking time now and then to really listen to others deepens their trust even more.", "love": "With someone you like, you tell them how you feel, straight out. You show love through action, like planning dates and cheering on your partner's goals. You value a relationship where you both help each other grow. Where things can go wrong: you jump to solutions when your partner shares a worry. Sometimes, skip the answer and just say, “I see.” That helps them feel truly at ease. When they show you their soft side, that's an important sign of trust, too.", "work": "You do great things when the goal is clear and you have room to make your own calls. You tend to be valued in roles like running projects, leading teams, and building new systems. On the other hand, you wear out fast in organizations that are slow to decide, or with long stretches of work where results are hard to see. The more results you deliver, the more you're trusted with, and the more you can do.", "jobs": ["Business owner / entrepreneur", "Project manager", "Consultant", "Sales manager", "Lawyer"], "growth": "Try making a habit of asking, “Any other thoughts?” at the end of meetings and discussions. A quiet person's idea can turn out to be the breakthrough. It also helps to keep one block of time each week free of plans. Time to pause sets up your next big step.", "A": "When you're Assertive, you decide fast and lead people with confidence, even under pressure. When something fails, you bounce back quickly and think about your next move. Your confidence gives the people around you courage.", "T": "When you're Cautious, you set high goals and still notice small risks. That steadiness shines. Your sense that “we can do better” lifts the quality of the whole team. When you're chasing perfect too hard, try counting what you've already done. It helps."}, "ENTP": {"catch": "The “But what if…” type. You love flipping the obvious on its head.", "overview": "When everyone thinks “that's just how it is,” you're the one who asks, “But what if we did it the other way?” and brings in a new angle. You love thinking up new ideas and trading opinions with people, and your ideas keep growing as you talk. What moves you is the thrill of “This could be fun.” The newer the idea, or the less clear the right answer, the more fired up you get. People often see you as quick-witted, someone they never get bored talking to. You may seem to love a good debate, but it's not about winning. You want to find a better answer together. You're the one who livens things up and gets them moving.", "strengths": ["You switch angles fast｜You can come up with many views and solutions for one problem. Even when things are stuck, you're good at finding a new path.", "Talking helps your ideas grow｜Your ideas keep growing as you talk with people. A thought that comes up in small talk can turn into a big project.", "You enjoy change｜When plans shift or something unexpected happens, you actually find it fun. You settle into new places easily and travel light.", "You're bold and quick to act｜You can talk to important people or strangers without feeling nervous. You connect people and start new things moving."], "pitfalls": ["Great at starting, not at finishing｜You're so drawn to new things that you get bored at the slow, finishing stage. Teaming up with someone who's good at wrapping up helps your ideas take shape.", "Debates get too heated｜Trading opinions is so fun that you may not notice the other person is getting tired. Asking “What do you think?” gives them a turn and keeps the talk pleasant.", "You overpack your schedule｜You say yes to one fun invitation after another, and before you know it, your hands are full. Sleep on it before you answer. It helps you choose what you really want to do."], "relationships": "You have lots of friends and can slip into any group easily. At parties and weekend hangouts, you're the one who brings up topics and gets everyone going. In group chats, too, you send random thoughts that spark more conversation. At work or school, people often count on you for new plans and ideas. You get along best with people who enjoy your ideas but also push back sometimes. The more you can enjoy a good back-and-forth, the longer the friendship lasts.", "love": "You're drawn to people who are fun to talk to and who show you worlds you don't know. When you fall for someone, you try to make your time together exciting, like planning fun dates and inviting them to new places. You value a relationship where you grow together and never get bored. Where things can go wrong: when your jokes or debates end up hurting your partner. In serious talks, try starting with a few words that show you understand how they feel. That builds trust.", "work": "You do your best where you can take on new challenges and share ideas freely. You tend to be valued in roles like launching projects, finding new solutions to problems, and getting people on board. On the other hand, you wear out fast with the same tasks every day or a place bound by lots of small rules. The more change a workplace has, the more your flexibility pays off.", "jobs": ["New business / planning roles", "Entrepreneur", "Marketer", "Advertising planner", "Journalist"], "growth": "When an idea comes to you, before you expand it, decide on just the first step and write it down. You'll see how to make it real, and it gets easier to pull off. It also helps to look back at the end of each day on one thing you finished. Small finishes add up, and they carry your ideas much further.", "A": "When you're Assertive, you're bold enough to act the moment an idea hits. You talk about your thoughts with obvious joy, even in front of others, and your power to pull people in gets stronger. Your charm is laughing off a failure and moving on.", "T": "When you're Cautious, along with your sparks of inspiration, you have the calm to check, “Will this really work?” You're tuned in to how people react, so you can adjust how you say things. When worries start piling up, try testing them one at a time. It eases your mind."}, "INFJ": {"catch": "The notices-without-being-told type. You gently catch the small shifts in people's hearts.", "overview": "You notice the tiniest changes: a look on someone's face, the tone of their voice, how long they took to text back. Imagining feelings that haven't been said out loud comes naturally to you, so people often ask, “How did you know?” Inside, you hold a quiet ideal of how things could be, and getting closer to it gives you a deep sense of purpose. You like being around people, but in a big crowd you soak up too many feelings and tire easily. That's why time alone to sort out your thoughts is a must. To others, you seem calm and a good listener, with a strong core. You may not say much, but in your head you're often thinking far ahead.", "strengths": ["You sense shifts in the mood right away｜You pick up early on the feel of a room or when someone's running low. You can quietly offer a hand before someone even asks for help.", "You really listen｜You don't cut people off. You take in what they say, feelings and all. People feel, “I can talk to this person,” and trust you with deep worries.", "You see what's coming｜You're good at picturing where things are headed from what's happening now. A small feeling that something's off can help you head off a problem early.", "You stay true to what matters｜You know clearly what values you want to protect. Even when it would be easy to go with the flow, you quietly hold on to your view."], "pitfalls": ["You carry other people's feelings too much｜Because you understand how others feel, you tend to take it on as your own. Drawing a line in your mind, like “This is their problem,” makes things a little lighter.", "You hold it in until you can't｜You don't want to make waves, so small frustrations tend to pile up. Practice saying lightly, “Something's been on my mind,” before it builds up. It protects both the relationship and you.", "Your ideals run high｜Your picture of the ideal is so clear that the gap with reality can bring you down. Make the goal smaller, like “Getting 60% done today is plenty.” It's easier to keep going."], "relationships": "You may not have many friends, but you value deep, long-lasting bonds. In a group, you often become the listener or the one people go to for advice, and they lean on you because “talking to you calms me down.” At work or in a club, you keep an eye on the overall mood and quietly support people who seem left out or are struggling. You get along best with people you can talk to honestly and slowly, and who don't find silence awkward. You feel fulfilled by how deep the talk goes, not how often you meet, so not cramming your schedule helps your friendships last.", "love": "You don't fall fast. Instead, your heart moves as you talk and think, “I like the way this person thinks.” Once someone matters to you, you notice their small changes and show deep love more through actions than words. What you want most is to feel safe enough to say what you really feel. Where things can go wrong: you imagine your partner's feelings so far ahead that you swallow your own wishes. Try putting a little of “I wish you'd pick up on this” into words. It brings you much closer.", "work": "You do your best in work that feels meaningful, where you can tell you're helping someone. The ideal is time to think alone plus a place to talk deeply with a few people. You tend to be valued for planning that meets people's needs, supporting people one-on-one, and writing or putting documents together. On the other hand, in workplaces that only chase numbers, or where chatter and meetings never stop, you can get worn out without noticing. Saving quiet time to look back, even once a week, helps you stay in good shape.", "jobs": ["Counselor / advisor", "Editor / writer", "HR / recruiting", "UX researcher", "Childcare worker / teacher"], "growth": "You tend to put others first, and your own feelings get pushed back. Before bed, try writing one line each for “something that made me happy today” and “something that bugged me a little.” Once you can name your feelings, it gets easier to share them. Also, when someone asks you for something, try pausing with “Let me think and get back to you.” That alone cuts down on taking on too much.", "A": "When you're Assertive, you trust your judgment and act calmly. You stay close to people's feelings, but when it counts, you can clearly say, “Here's what I think.” That makes you a strong person to turn to for advice.", "T": "When you're Cautious, you look back carefully at how people reacted and at what you said and did. You're especially sensitive to other people's pain, and your choice of words is very kind. If you start worrying too much, tell yourself, “I was considerate enough,” and give yourself credit."}, "INFP": {"catch": "The movie-theater-in-my-head type. You treasure being yourself and your gentle imagination.", "overview": "On the train to school or work, or on a lazy weekend afternoon, stories and “what if” scenes start playing in your head. Music, books, and scenery move you easily, and you're good at taking time to really feel what you feel. There are things inside you that you want to protect no matter what, and if something doesn't fit them, you can't get into it, even if everyone else is doing it. You're very kind to people and try to see things from their side. To others, you seem calm and modest, but once they talk with you, they find you funny, with a unique sense and humor. It's just hard for you to show it. Inside, you have rich, warm, passionate feelings.", "strengths": ["You feel things deeply｜Small moments and words move you, and you can really savor them. You notice beauty and fun that others tend to miss.", "You can stay close to someone in pain｜You can imagine how a hurting person feels as if it were your own. You accept them without judging, so just having you nearby puts people at ease.", "You express things in your own words｜You're good at giving shape to feelings, through writing, drawing, music, and more. Even hard things, you can say gently in your own way.", "You focus deeply on what you love｜When you truly love something, you lose track of time working on it. That passion turns into original work and ideas."], "pitfalls": ["You overthink and freeze｜Your imagination grows so big in your head that the first step feels heavy. Start small, like “I'll try it for just five minutes.” Your mood will naturally follow.", "You keep your real feelings tucked away｜You don't want to hurt anyone, so sometimes you never share your view. Sorting your feelings out first in a note or a text makes it easier to talk.", "You're quick to blame yourself｜Because your ideals are high and you're kind, when things go wrong you tend to think, “It's my fault.” Try saying to yourself what you'd say to a friend. It lightens your heart."], "relationships": "You'd rather have a slow, easy talk with a few people you click with than hang out in a big, loud group. You may be quiet when you first meet someone, but once you open up, you light up talking about your favorite things and show a side people don't expect. At work or school, you don't like conflict, and you often end up smoothing over tense moments. You get along best with people who don't rush you and who enjoy your sense of things and your values. With people who don't reject your differences, you can build deep trust that lasts.", "love": "You dream of a special bond like something out of a movie, and you look for someone who understands you all the way down. When you fall for someone, your love shows in small details, like listening to their favorite songs or remembering little things they said. What you want most is the comfort of being accepted as you are. Where things can go wrong: when you idealize your partner too much in your head, or worry alone because you can't say what's bothering you. Putting small feelings into words, little by little, makes the relationship more solid.", "work": "You really come alive in work that fits your values, where you can feel you're helping someone. The ideal is some freedom to choose how you work, plus time to focus alone. You tend to be valued in roles that use your sense and imagination, like writing, design, and planning. On the other hand, your motivation drops in places bound by lots of small rules, or workplaces that push competition and quotas above all. Finding one thing you love about your work makes it easier to keep going.", "jobs": ["Writer / novelist", "Illustrator / designer", "Psychology / social work roles", "Librarian", "Video creator / filmmaker"], "growth": "The key to growing is turning your rich imagination into something real, bit by bit. Try saving one idea or feeling a day in the notes app on your phone. When you read them back later, you'll see what matters to you. Also, break what you want to do into small stages, like “This week I'll just do research.” That way you can get moving without overthinking.", "A": "When you're Assertive, it's easier to trust your own sense and choices, and you bounce back fairly fast when you're down. You don't get swayed too much by what others say, and you can proudly say, “This is what I love.” That helps your work and ideas reach people.", "T": "When you're Cautious, you feel your ups and downs deeply and turn them into richer expression. You're even more thoughtful about other people's feelings. When you feel anxious, write down what you've done well and give your kindness the credit it deserves."}, "ENFJ": {"catch": "The can't-help-looking-after-you type. You bring out the best in people and warm up the room.", "overview": "When someone's in trouble, you find yourself asking, “Want some help?” before they even ask. You're good at reading people's feelings and the mood of the room. If someone in the group seems left out, you naturally talk to them and draw them in. Nothing makes you happier than seeing people grow and smile, and you're good at spotting what's great about someone and telling them. You value everyone moving in the same direction, and in school festivals or work projects, you often end up as the one pulling it together. To others, you seem bright and caring, someone who makes them feel more positive. On the flip side, you don't always notice when you're tired.", "strengths": ["You spot what's great in people and tell them｜You find strengths people haven't noticed in themselves and put them into words. That one comment can give someone confidence or a push forward.", "You bring people together｜You listen to scattered opinions and guide everyone toward a direction they can agree on. You're good at building a sense of team.", "Your words come from the heart｜You speak with passion and care, and you can move people. In speeches and explanations, too, you leave your listeners feeling more positive.", "You're quick to lend a hand｜When you notice someone struggling, you act without hesitating. That kindness and drive earn you deep trust from those around you."], "pitfalls": ["You come last｜You want so much to help that you take on one request after another. Put “time for me” on your calendar first. It keeps you from overdoing it.", "You try too hard to meet expectations｜You can sense what people expect, and you don't want to let them down, so you push yourself too far. Saying “I can't do that one” won't break their trust that easily.", "“For your own good” goes too far｜Advice you give with good intentions can feel heavy to the other person. Asking “What would help you?” first, before you act, keeps you on the same page."], "relationships": "You have lots of friends and often become the bridge between different groups. You remember birthdays and anniversaries, and you probably love planning surprises. At work or in a club, you're the one who says hi to newcomers and lightens the mood when things feel heavy. You get along best with people who thank you openly and who are there for you when you need to vent. When it's not just you supporting them, but them supporting you too, the relationship stays comfortable for a long time.", "love": "When you fall for someone, you think about them a lot and go out of your way to do things that make them smile. You take their dreams and worries seriously, and you value a relationship where you can grow together. What you want most is to share your feelings in words with each other. Where things can go wrong: when you give so much that you wear yourself out, or feel uneasy when your partner doesn't react much. Sometimes, let yourself be the one who's cared for and say openly what you'd like. It makes the relationship more equal and warm.", "work": "You do your best where you work with people and help them grow and smile. Workplaces where the team shares a goal and moves forward together suit you. You tend to be valued in roles that connect and move people, like leading, training, or coordinating. On the other hand, you burn energy fast when you're working alone and silently for long stretches, or when the people around you are at odds. You shine brightest where, along with results, you can feel the “thank you.”", "jobs": ["Teacher / instructor", "HR / training", "Career advisor", "PR / communications", "Event planner"], "growth": "Because you give so much support, it's important to keep track of how much you have left. At the end of each day, try to recall one thing you did for yourself. If there's nothing, small is fine for tomorrow, like slowly enjoying a cup of tea. Also, try making a habit of saying, “Let me check and get back to you,” when someone asks for something. It keeps you from taking on too much.", "A": "When you're Assertive, you trust your ideas and lead people without hesitating. When something goes wrong, you switch gears fast and keep things moving with your bright energy. Even in front of a crowd, you stay calm and can bring out your best freely.", "T": "When you're Cautious, you pay even closer attention to how each person reacts. Your care in choosing words so no one gets hurt is part of your charm. When you're worried about how others see you, think back on the good things you've done and let your heart rest."}, "ENFP": {"catch": "The heart-flutter-first type. You find what's exciting and spread it to everyone around you.", "overview": "A new shop, a place you've never been, an idea nobody's tried yet. When you run into something that seems fun, your eyes light up. You want to share your ideas right away, and new ones keep growing out of casual chats. You're really interested in people, too. You warm up to strangers naturally and enjoy learning what they like and how they think. You care more about “How can we make this more fun?” than about rules or set steps, so you have a way of brightening up the room. To others, you seem lively and friendly, someone who makes their world bigger. But beneath that bubbly side, you're actually sensitive to people's feelings and have a delicate side, too.", "strengths": ["Ideas pour out of you｜From one topic, you can link together lots of new ideas. Your strength is bringing unexpected angles to meetings and brainstorms.", "You hit it off with anyone｜Even with someone new, you don't put up walls, and you listen to them with real interest. You can be the hub that connects people.", "You get people fired up｜The way you light up when you talk naturally pulls others in. You're good at creating a “Maybe I'll give it a try” mood.", "You believe in people's potential｜You notice what's good in people and how they can grow, and you cheer them on from the heart. Your positive words give someone a gentle push."], "pitfalls": ["Your interest keeps jumping｜New things excite you so much that what you started tends to stall halfway. Pick just one thing you want to finish and set a small goal. It's easier to see it through.", "You overpack your schedule｜You can't say no to invitations or things you want to do, and before you know it, your calendar is full. Decide on one “nothing day” each week in advance. It gives you breathing room again.", "Detail work wears you out｜You tend to put off repetitive tasks and paperwork. Add a little fun with small tricks, like putting on music or working in short time blocks. It makes things easier to get through."], "relationships": "You have a wide circle of friends and get along with all kinds of people. You're the type to text “Want to meet up right now?” the moment the idea hits, and you're often the one planning the fun. At work or school, you're the mood-maker who brightens the room and gets the talk started when no one's speaking up. You get along best with people who enjoy hearing your ideas and who offer a healthy dose of realism. In relationships where you can share your feelings honestly, you feel most like yourself.", "love": "Love often starts with a spark, that feeling of “I have so much fun with this person.” When you fall for someone, ideas for places to go and things to do together keep popping up, and you enjoy your time with them to the fullest. What you want most is to express your feelings openly with each other and to respect each other's freedom. Where things can go wrong: when the relationship settles down and the excitement fades, or when you read too much into your partner's feelings and get anxious. Creating small joys together in everyday life helps the relationship last.", "work": "You do your best where you can try new things and use your ideas and connections. Workplaces with lots of freedom and lots of different people suit you. You tend to be valued in roles like planning, launching, sharing ideas with the world, and connecting people. On the other hand, your motivation fades with the same steps every day or strict micromanagement. Sharing tasks you find hard with people who are good at them, or handing them to tools, frees up more time for your strengths.", "jobs": ["Planning / marketing", "Advertising / copywriter", "Event / travel planner", "Entrepreneur / new business roles", "Influencer / streamer"], "growth": "The key to growing is building the power to carry your many ideas all the way to something real. When you think of something you want to do, first write the first step in one line, and start on just one thing that same day. Also, once a month, look back at what you've started and choose what to keep and what to let go. That helps you focus your energy on what matters.", "A": "When you're Assertive, you're a doer who acts on ideas without hesitating. When something fails, you switch gears fast with “Next!” and lead others with your bright energy. You fit into new places quickly and enjoy grabbing chances as they come.", "T": "When you're Cautious, under your brightness there's a careful attention to people. You watch how others react, so you can find the right words for each person. When you wear yourself out worrying, recharge with some alone time doing what you love."}, "ISTJ": {"catch": "A quiet, dependable pro who keeps every promise and follows every step.", "overview": "You're the “done-before-the-deadline” type. When you decide to do something, you see it through properly. You finish assignments the day before they're due, and you arrive a little early to meet people. You don't show off, but you never cut corners on what you're trusted with. Your decisions rest on past experience and solid facts. You trust “what worked before” over a sudden idea. You're not much of a talker, so at first you may seem a bit hard to approach. But the longer people know you, the more you become the one they think of as, “If I ask them, it'll be fine.” You do your best when you have time to focus alone.", "strengths": ["You always keep your word｜You do what you say, and you meet deadlines. All those small promises kept add up to deep trust from the people around you.", "You catch gaps and slips｜You spot right away when numbers in a document don't match or a step got skipped. You're the team's safety net, stopping mistakes before they happen.", "You keep at it, steadily｜You can calmly keep up quiet, everyday tasks like daily study or record-keeping. Before you know it, they've added up to something big.", "You stay calm when it counts｜When trouble hits, you don't panic. You check the facts first, then act. Your calm puts others at ease."], "pitfalls": ["Sudden changes wear you out｜You care a lot about plans, so last-minute changes can throw you off. Having a backup plan from the start, in case things change, makes it easier.", "Putting feelings into words is hard｜You tend to keep thanks and complaints to yourself, which can lead to misunderstandings. Just saying “That really helped,” even briefly, warms things up.", "You tend to carry it all alone｜You often feel it's more reliable to do things yourself than to ask. You don't have to shoulder everything. Handing off even part of it lightens the load a lot."], "relationships": "You may not have many friends, but you value relationships that last. You like steady friendships where nothing changes even when you haven't met in a while. At work or in a club, you follow the rules and do the job you're given properly. Lively settings wear you out if they go on too long, so you get along well with people you can talk to slowly in small groups. With people who value promises and don't rush you, trust grows naturally.", "love": "It takes you a while to fall for someone, but once your mind is made up, you're all in. Instead of saying it in words, you show love through actions, like remembering anniversaries or giving rides. You look for sincerity and a sense of safety in a partner. Where things can go wrong: not sharing your feelings can make your partner feel you're cold. Even if your texts are short, adding a quick “I had fun” makes sure your feelings get through.", "work": "You do your best where rules and steps are clear and your area of work is well defined. You're highly valued in jobs that need accuracy, or roles where things must be done right by the deadline. You feel at ease when you're trusted with checking documents or tracking progress. On the other hand, you tire easily in workplaces where the direction keeps changing, or when you're asked to improvise with no prep. When you get time to gather information in advance, your true strength comes out.", "jobs": ["Accounting / bookkeeping", "Civil servant (administration)", "Quality control", "IT systems maintenance / operations", "Pharmacist"], "growth": "Your reliability is a big asset. On top of that, try bringing in a little “something different.” For example, once a week, take a new route home or pick a place you've never tried for lunch. Small changes are plenty. Also, at the end of each day, try saying a quick thank-you to someone. Practicing putting feelings into words makes relationships a lot easier.", "A": "When you're Assertive, you trust your way of doing things and move forward without hesitating. Even when you make a mistake, you don't get more down than you need to, and you calmly think about the next step. You give others a steady impression, so you're often asked to lead.", "T": "When you're Cautious, you double- and triple-check, so you make almost no small mistakes. Because you keep asking, “Is this really okay?”, your prep is top quality. Now and then, tell yourself, “This is enough.” It takes the pressure off."}, "ISFJ": {"catch": "The caring one behind the scenes who quietly notices and acts first.", "overview": "You're the “already-on-it” type. You naturally notice when people around you need something. If drinks are running low, you refill them. If someone looks down, you check on them. You don't think of it as doing someone a favor. To you, it's just what you do. What matters to you is that the people close to you can feel safe and at ease. Once you learn someone's likes or plans, you remember them for a long time. You're modest and don't like the spotlight, but when you're gone, people realize, “That was all thanks to them.” You're good at moving things along carefully within a set routine. Quiet time to reset helps you go back to being kind and active.", "strengths": ["You think ahead for others｜You notice small changes in someone's face or voice. You offer help before anyone asks, and people are deeply grateful.", "Your work is careful and reliable｜You don't skimp on any step, and you finish things with care all the way to the end. You're someone people can trust with anything.", "You remember people｜You remember birthdays, favorite foods, and things people told you before. Those memories are how you show people they matter.", "Your calm softens the room｜Even when things are tense, your gentle words ease the strain. Just having you nearby helps people relax."], "pitfalls": ["You can't say no｜You hate letting people down, so you tend to take on too much. Pausing with “Let me check and get back to you” helps protect you.", "You don't notice when you're tired｜You put others first so much that your own rest gets pushed back. Writing “time to do nothing” into your calendar first makes it easier.", "You bottle things up｜You don't want to make waves, so you tend to hold in what's bothering you. Sharing it bit by bit with someone you trust lightens your heart."], "relationships": "With friends, you're there for them in quiet, thoughtful ways. You often end up as the supporter, like sending a message to a friend who's sick or making a packing list for a trip. At work or school, too, you can't leave someone who's struggling alone. You get along best with people who say “thank you” for your kindness. Relationships where you look out for each other last longer and feel better than ones where you're the only one being leaned on.", "love": "You pay close attention to the person you like, right down to the details. You show love through small everyday acts, like checking how they're feeling or bringing a snack they love. What you value is a calm relationship where you both feel safe together. Where things can go wrong: when you go along with your partner so much that you can't say what you really feel. Try starting with small wishes, like “Here's what I'd like.” It brings you and your partner even closer.", "work": "You do your best where you can feel you're helping people, and the steps are fairly set. Your careful service and behind-the-scenes support tend to be highly valued. You're also suited to roles helping people in need, and admin work that needs accuracy. On the other hand, highly competitive workplaces or places where harsh words fly can wear you down. Choosing a workplace where people say thank you out loud helps you work happily for a long time.", "jobs": ["Nurse", "Childcare worker", "Medical office staff", "Librarian", "General affairs / HR"], "growth": "Your kindness is something you're allowed to give yourself first. Starting today, before you say “Sure” to a request, take a breath and check your own schedule and feelings. Also, before bed, try writing down one thing you did well today. When you give yourself credit for helping others, you make room in your heart.", "A": "When you're Assertive, you support others while keeping your own pace. Even with requests, you can tell what's within your reach before you say yes. Your care comes so naturally that people feel free to lean on you without worrying.", "T": "When you're Cautious, you imagine others' feelings deeply, so your care is very fine-tuned. The kindness that makes you wonder, “Am I being a bother?” builds trust. Turning that same kindness toward yourself makes things much easier."}, "ESTJ": {"catch": "A dependable organizer who lays out the steps and moves everyone forward.", "overview": "You're the “let's-make-a-schedule-first” type. You're good at turning things into something solid. Once a trip is decided, you quickly work out the dates and budget. In group work, you assign roles. Fuzzy situations make you uneasy, and you want to make clear “who does what, by when.” You rely on solid facts and past results. You say what needs to be said, so people see you as a dependable leader. You may come across as a bit strict at times, but that comes from a sense of responsibility for making things go well. You shine brightest when you work with others and get results everyone can see.", "strengths": ["You plan ahead and set the steps｜You work backward from the goal and line up what needs doing in order. You make a clear path so others can move without getting lost.", "You decide and follow through｜Even when a discussion drags on, you sum up the key points and reach a conclusion. Once it's decided, you act right away, so things move forward.", "You see it through to the end｜You finish every job you're given. Your refusal to give up, even when it's hard, earns trust from those around you.", "You say things clearly｜You avoid vague words and get straight to the point. Your instructions and explanations are clear, so people can act easily."], "pitfalls": ["Your words can come across as harsh｜You speak frankly to save time, and some people find it blunt. Adding a quick “thanks” before you get to the point helps your message land.", "You stick to your own way｜You trust what's worked before, so you tend to push other ideas aside. Hearing someone's idea all the way through first can lead to something new.", "Rest gets pushed back｜When you can see what needs doing, you just keep going. Put “rest” on your weekend schedule as a real plan. It keeps you from wearing yourself out."], "relationships": "Among friends, you naturally take the lead, like setting dates for get-togethers and booking restaurants. You look out for people, and you help anyone in trouble with practical solutions. At work or in a club, you follow the rules and keep everything running smoothly. You get along best with people who keep their promises and speak plainly. With people who lead with their feelings, making a point of taking time to listen helps you build a good relationship.", "love": "With someone you like, you show a sincere, dependable side. You show you care through action, like planning dates and solving problems together. You want a relationship of trust, where you both keep your promises. Where things can go wrong: when your partner just wants you to listen, and you jump in with a solution. Starting with “Oh, I see” helps your feelings connect much better.", "work": "You do your best where goals and roles are clear and results are easy to see. You tend to be highly valued in roles leading a team or tracking progress. You're also good at setting up rules and improving systems. On the other hand, stress builds up in workplaces where things move forward with no clear direction, or decisions take far too long. Having even a little power to make calls lets you work freely.", "jobs": ["Sales manager", "Project management", "Store manager", "Banker", "Police officer / firefighter"], "growth": "Your drive is a big force that carries people forward. Starting today, before you share your view in a meeting or discussion, try asking the others, “What do you think?” Also, try setting aside one block of time each week with no plans. Time to pause makes your next decision even more solid.", "A": "When you're Assertive, you rarely hesitate and decide very fast. You stay confident even under pressure, so your ability to lead really comes through. You're also quick to bounce back from a failure.", "T": "When you're Cautious, you check for holes and risks in the plan ahead of time. Because you keep asking, “Is this really right?”, your plans are very polished. You also pay attention to how people react, so they trust you as a gentle leader."}, "ESFJ": {"catch": "The one who brings people together and works to keep everyone smiling.", "overview": "You're the “somehow-I'm-the-organizer-again” type. Connecting people comes naturally to you. For parties and birthday celebrations, you somehow end up handling the dates and picking the place. What matters to you is that everyone there has fun and feels comfortable. If someone's left out, you talk to them and bring up topics to warm up the room. You're sensitive to people's feelings and the mood, and you value manners and kindness. To others, you seem bright and easy to talk to, and people often come to you for advice. Hearing “thank you” is your biggest source of energy, and it makes you want to do your best again next time.", "strengths": ["You connect people｜You step in between people who've just met and find something they have in common so they can relax. When you're there, the circle grows.", "You read the room｜You notice who's tired and who wants to talk. You naturally adjust things so everyone feels comfortable.", "Your care turns into action｜You don't just feel it. You show it, with a little treat or a quick message. Your kindness stays with people.", "You pull things together and get them done｜For event prep or group duties, you sort out roles and schedules and see it through to the end. You're a caretaker people can count on."], "pitfalls": ["You worry about what people think｜You want so badly for everyone to be happy that a lukewarm reaction can make you anxious. Drawing your own line, like “I did enough,” makes it easier.", "You push yourself too hard｜You keep taking on organizer and helper roles, and sometimes you end up worn out. Now and then, try handing the role to someone else and just show up.", "You tend to avoid conflict｜You want to protect the mood, so you often swallow disagreements. Saying gently, “Here's what I think,” actually brings people closer."], "relationships": "You have lots of friends and you're often the one checking in on the group chat. You can easily reach out to people you haven't talked to in a while, and you naturally keep the circle together. At work or school, you say hi to newcomers and liven up events. You get along best with people who put their feelings into words back to you. With people who don't react much, knowing they have their own way of showing thanks helps avoid misunderstandings.", "love": "With someone you like, you stay in touch often and think about what will make them happy. You're great at anniversary surprises and home-cooked meals for them. What you value is a relationship where you share your feelings and look out for each other. Where things can go wrong: when you feel like you're the only one giving, and you get lonely. Saying openly what you'd like makes it easier for your partner to respond, and the relationship becomes more stable.", "work": "You do your best in work where you team up with others and can feel you're helping. You tend to be highly valued for building a good team mood and for thoughtful care with customers. You're often trusted with running events and coordinating, too. On the other hand, you lose energy when you work alone in silence for long stretches, or when the people at work are at odds. Choosing a workplace where people share thanks helps you shine for a long time.", "jobs": ["Hotel / hospitality staff", "Teacher", "Wedding planner", "HR / recruiting", "Care worker"], "growth": "Your warmth gives the people around you energy. Starting today, before you take on someone's request, check in with yourself: “Do I have room for this right now?” Also, try putting something on your schedule once a week that's just for your own fun. The more time you spend filling yourself up, the longer your kindness to others can last.", "A": "When you're Assertive, you don't get thrown around by people's reactions, and you can move things along by your own judgment. You can speak up with confidence, so people count on you as a leader. Your brightness stays steady and gives others a sense of security.", "T": "When you're Cautious, you imagine people's feelings in detail, and your care reaches even further. Because you think hard about “Will they like this?”, your prep is very thorough. Knowing that it comes across even when it's not perfect makes your heart lighter."}, "ISTP": {"catch": "A quiet lover of how things work, whose hands get there before the manual does.", "overview": "When you get a new gadget or app, you start poking at it before you read the manual. As an ISTP, you value learning by doing. You love knowing how things work, and your focus actually sharpens when something isn't going right. You often don't say much, so people tend to see you as cool and calm. But inside, you're quietly watching what's in front of you and always thinking about what to fix to make it better. You do your best when you're free to do things your own way, not tied down by lots of small rules. When trouble hits, you don't panic. You just get your hands moving and handle it, so people count on you when it matters. Alone time recharges you, and you can get amazingly deep into the things you love.", "strengths": ["You stay steady in a crisis｜Even when plans fall apart, you first calmly look at what's going on. You choose your next move without panicking, which puts others at ease, too.", "You learn fast with your hands｜You pick up how to use tools and software by trying them out as you go. Actually doing something is how you really understand it.", "You find waste and fix it｜You're good at noticing, “If we change this, it'll be faster.” With a small tweak to the steps or tools, you make the work a lot easier.", "You handle things on your own｜Before asking anyone, you look it up and try it yourself first. Even when you're left to work alone, you stick with it until it's done."], "pitfalls": ["Putting feelings into words is hard｜Your thinking tends to wrap up inside your head, so it may not reach the people around you. Adding just one line, like “Here's what I'm thinking,” cuts down on misunderstandings a lot.", "Once the interest fades, your hands stop｜That's because you tend to feel satisfied once you've figured out how something works. Decide in advance how far you'll take the final touches. It keeps things from being left undone.", "You suddenly pull away｜When you don't get enough alone time, you want to quietly step back. Saying “I need a little break” before you go lets the other person wait without worrying."], "relationships": "With friends, you like an easygoing distance, not too clingy. Rather than texting every day, you value getting together now and then to do something side by side. At work or in a club, you help with your hands more than your words, so people often see you as “the one to count on when things go wrong.” You get along best with people who respect your pace and don't push you to talk. When you can enjoy the same hobby together, you grow closer naturally.", "love": "Even when you like someone, you often show it through actions instead of words. Carrying something heavy, fixing something broken, looking up a place they wanted to go. Those small, thoughtful acts are how you show love. You want a relationship where you both value each other's freedom. Where things can go wrong: when your partner wants to hear “I like you” out loud. Saying what you feel now and then helps your feelings come through clearly.", "work": "You do your best in hands-on settings where you can make your own calls, and in work with results you can see. You're likely to be valued when you're trusted with troubleshooting or improving how things are done. Roles working with machines, data, or tools are a good fit, too. On the other hand, you tire easily with lots of meetings that seem pointless, or workplaces where every step is fixed by detailed rules. Once you know why something is done a certain way, it gets much easier for you to move.", "jobs": ["Engineer (mechanical / facilities)", "IT systems maintenance / infrastructure", "Mechanic / technician", "Video editor / sound crew", "Emergency response / disaster prevention"], "growth": "Your thoughts only start helping others once you say them out loud. Something you can do starting today: share just one opinion in a meeting or discussion. Also, when someone helps you, try saying, “That helped, thanks.” Even a short line steadily builds trust with people.", "A": "As an Assertive ISTP, you rarely second-guess yourself and act as soon as an idea strikes. You don't dwell much on failures and quickly switch to “Next time, I'll do it this way.” You can try new things without a second thought.", "T": "As a Cautious ISTP, you're careful to check the fine details before you act. You look back closely at what didn't work, so you don't repeat the same mistakes. Your craftsman side, with its eye for quality, really shines."}, "ISFP": {"catch": "You quietly move toward whatever your heart says it loves.", "overview": "Picking clothes, choosing a café, deciding your path in life. As an ISFP, you choose by the feeling of “I love this” before any reason. That feeling is very honest, and it truly knows what suits you. Day to day, you seem calm and modest, but inside you have a strong sense of style and things you care about. You notice changes in how people feel, and you quietly stay close to anyone who's struggling. You don't like conflict and want to get along peacefully with those around you. But when someone dismisses what you hold dear, you defend it quietly, yet firmly. You're also gifted at savoring the small comforts of everyday life, like the feel of the season, music, and textures.", "strengths": ["Your sense of style makes spaces feel good｜You notice small differences in color, sound, and how things are arranged. You're good at shaping a room or a document into something that feels nice to look at.", "Your kindness stays gently close｜You quickly notice changes in someone's face or voice. You stay by their side without pushing, so they feel safe sharing what's really on their mind.", "You stay true to yourself｜You don't get swept up by trends or what others say. You choose what fits you. Seeing you do that helps others feel it's okay to be themselves.", "You can focus on what's in front of you｜Once you start on something you love, you lose track of time. The more care you put in, the more warmth shows in the result."], "pitfalls": ["You can't say no and end up carrying it｜That's because you really don't want to hurt anyone. Instead of answering right away, ask, “Can I think about it?” The extra time lets you check what you really feel.", "Long-range plans can be hard for you｜You value how you feel right now, so faraway plans don't feel real. Breaking big plans into small pieces and putting them on your calendar one at a time makes it easier.", "You take criticism too much to heart｜That's because your feelings go into what you make. Try sorting feedback into “about the work” and “about me.” It lightens your heart."], "relationships": "You'd rather spend relaxed time with a few people you click with than hang out in a big, noisy group. You remember your friends' tastes and when they're feeling off, and you can look out for them without fuss. At work or school, you're likely to be valued as someone who softens the mood. You get along best with people who don't dismiss how you feel and who match your pace. You open up slowly, so the more time you put into a relationship, the deeper the trust grows.", "love": "When you fall for someone, it's less about words and more about the vibe and how comfortable you feel together. You're good at giving your feelings a form, like writing a letter or picking a gift that suits their taste. What you want most is to respect each other's pace and the things you each love. Where things can go wrong: when you hold in your frustrations without saying them. Saying “I felt a little lonely” while it's still small makes the relationship feel even better.", "work": "You do your best in work that uses your sense of style, or where you can feel you're helping people. In making things, design, or roles where you support people directly, your care and kindness tend to be valued. In a setting where you can work at your own pace, your focus really takes off. On the other hand, you tire easily in highly competitive workplaces or places that judge you only by numbers. If there's even one part you love, it's easier to keep going for the long run.", "jobs": ["Designer", "Hairstylist / nail artist", "Childcare worker", "Pastry chef / cook", "Veterinary nurse / pet groomer"], "growth": "What you love can be a valuable hint for the people around you, too. Something you can do starting today: jot down just one line about something good you felt that day. Your tastes and what you want to protect will start to show up clearly in words. When you feel like it, try telling someone about one of them.", "A": "As an Assertive ISFP, you trust your own sense and act on it directly. You don't worry much about what others think, and you throw yourself into what you love with confidence. You bounce back from moods quickly, and people often see you as bright.", "T": "As a Cautious ISFP, you're very sensitive to how others feel, and your care is fine-tuned. You want to make what you create even better, so you rework it again and again. That care becomes part of your deep charm."}, "ESTP": {"catch": "You step out before you overthink it and catch the flow of the moment.", "overview": "“Let's just go and see” comes out of your mouth naturally. As an ESTP, you find answers by moving, not by thinking it all through first. You jump right into new shops, events, and places you've never been, and you read the mood quickly. You talk fast with a good rhythm, and people tend to see you as someone with get-up-and-go they can rely on. You care more about what's really happening right here than about theories on paper. You enjoy the unexpected, and you're at your best in a pinch. You love being with people and hit it off with strangers right away. Your brightness and easy energy are often what gets others moving.", "strengths": ["You make split-second calls｜Even when things change, you find “what to do now” right away. You cut down on time lost to hesitation and move the team forward.", "You liven things up｜You talk with a good rhythm and naturally brighten the room. Your strength is hitting it off right away, even with people you've just met.", "You move with what's real｜You think about “how we'll actually do it” over ideal theories. You combine the tools and people you have and make things happen.", "You try without fear of failing｜Even when something doesn't work, you switch to “Next!” That lightness draws in new chances."], "pitfalls": ["You tend to put off what's ahead｜You throw yourself into what's in front of you, so far-off plans are harder to see. Taking a few minutes once a week to look over next week's schedule on your phone gives you peace of mind.", "In the moment, you say too much｜You care about keeping the talk moving, so words sometimes come out first. Just taking a breath before an important talk changes how it comes across.", "Repetitive work breaks your focus｜That's because without some stimulation, you get bored easily. Setting a time limit and turning it into a game makes it easier to finish."], "relationships": "You have lots of friends, and when someone invites you, you're quick to go. You're also great at suddenly saying, “Want to hang out now?” on a day off. At work or in a club, people count on you as the mood-maker who gets things moving. You're easygoing and straightforward, so you're good at resetting the mood when things get tangled. You get along best with people who enjoy new things with you and sometimes offer a calmer view. Relationships where neither of you holds back feel most comfortable.", "love": "When you fall for someone, you show it through action. You take the leap and ask them out, and you grow closer by going places together. You love dates where you share fun experiences, like activities or trips. What you value is being able to be yourself together. Where things can go wrong: when your partner wants a long, deep talk. Taking time now and then to calmly hear how they feel makes your bond even stronger.", "work": "You do your best in work with lots of change and quick results. In roles where you deal with people directly, like sales or on-site work, your negotiating skills and fast response tend to be valued. People also count on you to put out fires when trouble hits. On the other hand, you tire easily in jobs that just repeat the same tasks, or places where decisions take a long time. You shine brightest where you can think on the move.", "jobs": ["Sales", "Event planner", "Sports trainer", "Firefighter / police officer", "Running your own business / shop"], "growth": "Your drive gets even stronger with a little prep. Something you can do starting today: wait just 10 seconds before an important decision. In that time, think of one other option or how the other person might feel. A habit of checking one thing on tomorrow's schedule before bed also helps back up your momentum.", "A": "As an Assertive ESTP, you're full of confidence and act without hesitating. You don't worry much about how others see you, and you dive into new places one after another. You'll often find yourself naturally put in the leader's role.", "T": "As a Cautious ESTP, on top of your drive, you have the calm to watch how people react. You have a habit of looking back after you act, so you put your experience to good use in the next challenge. You're someone people can count on, with a good balance of momentum and care."}, "ESFP": {"catch": "You make right now more fun for everyone around you.", "overview": "When something fun comes up, you've already replied “I'm in!” before you even think about it. As an ESFP, you enjoy the moment to the fullest and spread that fun to everyone around you. Your face is so expressive that just talking with you lights up the room. You fit in quickly even in new places, and you often end up at the center of the group. You love seeing people happy, and you make a point of celebrating friends' birthdays and little wins. Rather than logic, you act by sensing the mood and how people feel. If someone's feeling down, you lightly get them laughing and cheer them up. People think of you as “so fun to be around,” and they naturally gather around you.", "strengths": ["You brighten the mood｜Your smiles and reactions ease even a tense room. You naturally create a feel where others find it easy to talk.", "You quickly sense how people feel｜You can tell right away whether someone's having fun or getting tired. You have the kindness to check in with them on the spot.", "You fit into new places fast｜Whether it's a new school, a new team, or a trip, you warm up to people right away. Your strength is connecting with strangers and growing the circle.", "You turn “fun” into something real｜Ideas for get-togethers and events keep popping up. When you think of one, you act right away and make memories for everyone."], "pitfalls": ["You overpack your schedule｜That's because you find it hard to say no, and you want to say yes to everything that sounds fun. Deciding on one “nothing day” each week in advance keeps you from wearing yourself out.", "Money and time slip away｜That's because you tend to put the fun of the moment first. Make a rule to sleep on it before you buy. Then only the things you really want end up in your hands.", "You tend to avoid heavy talks｜That's because you really want to keep the mood bright. Setting aside a short, separate time for important talks, apart from fun times, makes them easier to face."], "relationships": "You have lots of friends, and you're the one keeping the group chat lively. You can talk easily with anyone, so at work or school you often end up connecting people. You notice small changes in others and have the warmth to ask, “How have you been?” You get along best with people who enjoy your brightness and also listen calmly now and then. The more time you spend laughing together, the longer the relationship lasts.", "love": "When you fall for someone, it shows right away. When you want to see them or talk to them, you reach out honestly. On dates, you're great at delighting your partner with surprises and fun plans. What you value is having fun together and openly sharing your feelings. Where things can go wrong: when your partner wants to talk about the future or other things down the road. Taking time now and then to think seriously about it builds a lot of trust with your partner.", "work": "You do your best in work where you deal with people and get reactions right away. In customer service, sales, or events, your brightness and thoughtfulness tend to be valued. You're also treasured as someone who makes the team's mood better. On the other hand, you tire easily in jobs where you're alone at a computer all day, or settings full of routine tasks with little change. You do your best where you can see people smile.", "jobs": ["Customer service / sales staff", "Tour guide / travel planner", "Event staff", "Childcare worker / preschool teacher", "Entertainment industry"], "growth": "Your brightness lasts longer with a little planning ahead. Something you can do starting today: at the start of each month, write down one “thing to look forward to” and one “thing I need to do.” When you can see both, it's easy to balance them happily. Also, when you're tired, try saying honestly, “I'm going to rest today.”", "A": "As an Assertive ESFP, you express your charm freely. You don't worry too much about what others think, and you act as soon as an idea strikes. Even in front of a crowd, you can just be yourself and enjoy it.", "T": "As a Cautious ESFP, under your brightness there's careful attention to the people around you. You think hard about how others felt, so you're great at staying close to people's hearts. That kindness grows deep, trusting relationships."}};
var HN={"type": {"ISTJ": {"want": "The satisfaction of seeing things through, and the security of being trusted", "effort": "Following rules and steps, and building up without mistakes", "work": "Work with clear rules and steps, where accuracy is valued", "jobs": ["Accounting & admin", "Quality control", "Public service", "Systems operations"]}, "ISFJ": {"want": "Feeling useful to others, and a place where you feel safe", "effort": "Thinking ahead, paying attention, and supporting those around you", "work": "Work where you support people close to you and get thanked directly", "jobs": ["Nursing & caregiving", "Childcare", "General affairs", "Medical admin"]}, "INFJ": {"want": "A sense of being part of something meaningful, and relationships where you truly understand each other", "effort": "Reading people's feelings and picking up on what goes unsaid", "work": "Work where you can be part of people's growth and inner lives for the long run", "jobs": ["Counselor", "Education & training", "Editor & writer", "Human resources"]}, "INTJ": {"want": "The satisfaction of moving things with a plan you made, and time alone to think deeply", "effort": "Looking ahead, laying out the logic, and showing the shortest route", "work": "Work where you're trusted with long-term strategy and building systems", "jobs": ["Planning & strategy", "Research", "Engineer", "Consultant"]}, "ISTP": {"want": "The freedom to solve problems with your own hands and head, and time without interference", "effort": "Fixing problems calmly and quickly when they come up", "work": "Work where the results of your hands-on effort are plain to see", "jobs": ["Technician & maintenance", "Engineer", "Craftsperson", "Hands-on specialist"]}, "ISFP": {"want": "Being honest about what you love, and calm relationships", "effort": "Keeping the peace and softening the mood with your own sense of things", "work": "Work where you can use your sensitivity and go at your own pace", "jobs": ["Design", "Beauty", "Making things", "Work with animals or nature"]}, "INFP": {"want": "Being able to honor your values, and a purpose you truly care about", "effort": "Staying close to people's feelings and putting ideals into words or form", "work": "Work where you can express what you believe in", "jobs": ["Writing & creative work", "Social welfare", "Counseling", "Social-impact work"]}, "INTP": {"want": "The freedom to think things through as deeply as you like, and intellectual stimulation", "effort": "Analyzing how things work, then finding and fixing contradictions", "work": "A place where thinking itself is the job", "jobs": ["Research & development", "Programmer", "Data analysis", "Specialist roles"]}, "ESTP": {"want": "The thrill of moving and seeing results right away, and competing in the moment", "effort": "Acting without hesitation and grabbing the chance in front of you", "work": "Work where speed and action turn straight into results", "jobs": ["Sales", "Events", "Sports", "Starting a business"]}, "ESFP": {"want": "Sharing fun with people, and savoring the moment", "effort": "Brightening the room and making everyone have a good time", "work": "Work where you deal with people directly and see them smile", "jobs": ["Customer service & retail", "Entertainment", "Childcare", "Beauty"]}, "ENFP": {"want": "Exciting possibilities, and the joy of connecting with people", "effort": "Coming up with ideas and getting people on board to start something new", "work": "Work full of new projects and new people", "jobs": ["Planning & PR", "Marketing", "Education", "Creative work"]}, "ENTP": {"want": "The freedom to try new ideas, and smart debates", "effort": "Questioning the usual and finding a breakthrough from another angle", "work": "Work with lots of change, where ideas win", "jobs": ["New ventures", "Consultant", "Planning", "Starting a business"]}, "ESTJ": {"want": "The satisfaction of organizing things and moving them forward, and a role with responsibility", "effort": "Setting up the plan, bringing people together, and getting results", "work": "Work where you run an organization and see results in numbers", "jobs": ["Management", "Project management", "Sales manager", "Public administration"]}, "ESFJ": {"want": "A place where everyone gets along, and the joy of being thanked", "effort": "Connecting people and keeping things in harmony", "work": "Work where you engage with your team or community and can be the one who pulls it together", "jobs": ["HR & general affairs", "Education", "Healthcare & welfare", "Customer service lead"]}, "ENFJ": {"want": "Bringing out people's potential, and relationships built on trust", "effort": "Encouraging people and uniting the team toward a goal", "work": "Work where you grow and guide people", "jobs": ["Teacher & instructor", "HR & training", "Coach", "PR"]}, "ENTJ": {"want": "Moving people and things toward a big goal, and the freedom to make the call", "effort": "Making decisions, moving people efficiently, and getting results", "work": "Work where you have decision-making power and can aim for big results", "jobs": ["Executive & management", "Consultant", "Starting a business", "Project leader"]}}, "gap": {"IE": {"axis": "Energy", "from": "Introverted", "to": "Extraverted", "worry": ["Time with people is fun, but you're drained on the way home", "You can't say no to invitations and your schedule fills up", "People see you as cheerful, so no one notices when you're tired"], "work": "Work with both a people-facing role and time to go deep alone. Listening to people, then taking it home and shaping it carefully (counseling, editing, research).", "key": "After a day with people, take the same amount of time doing nothing. Connecting with people is your strength, but you only recharge alone.", "both": "You have both the strength to think deeply on your own (I) and the strength to move with people (E). You can act naturally in front of others, yet you can only recharge in time alone."}, "EI": {"axis": "Energy", "from": "Extraverted", "to": "Introverted", "worry": ["You want to see people, yet plans on the calendar start to feel heavy", "After a stretch of time alone, your mood sinks for no clear reason", "After a gathering you enjoyed, exhaustion suddenly hits"], "work": "Work with both time with people and time to focus alone suits you. Shaping ideas carefully and then delivering them to people, or working in a small team.", "key": "Put both \"people days\" and \"alone days\" on your calendar in advance. When only one keeps going, the other strength starts to fade.", "both": "You have both the strength to recharge through people (E) and the strength to think deeply on your own (I). Lively time and quiet time are both things you need. When either runs low, you tire easily."}, "SN": {"axis": "How you see things", "from": "Realistic", "to": "Intuitive", "worry": ["Plenty of ideas come to you, but none of them take shape", "After talking big, you suddenly worry, \"Can I really do this?\"", "The gap between ideal and reality often lets you down"], "work": "Work where you think up new things and then make them real with your own hands. Building products or services, planning improvements, crafting.", "key": "Rewrite each idea as \"one step I can take tomorrow.\" Using both imagining and checking turns ideas into reality.", "both": "You have both the strength to check the facts in front of you (S) and the strength to imagine possibilities not yet visible (N). You can expand ideas, yet you can't settle until the ground under your feet is firm."}, "NS": {"axis": "How you see things", "from": "Intuitive", "to": "Realistic", "worry": ["You get everything done properly, yet something feels unfulfilled", "Repeating the same method slowly gets boring", "When asked what you really want to do, you can't answer well"], "work": "Steady work that still leaves room to invent new ways. Planning roles that know the front line, teaching, or being trusted with improvements.", "key": "Once a week, make time to think \"if I could do anything...\" Adding imagination to your steady progress changes how your days feel.", "both": "You have both the strength to imagine possibilities (N) and the strength to build on facts (S). You can move things forward realistically, yet without time to think \"what's next?\", days can feel flat."}, "TF": {"axis": "How you decide", "from": "Thinking", "to": "Feeling", "worry": ["After agreeing to go along, you realize you actually disagreed", "You have something to say, but swallow it for fear of spoiling the mood", "You help others so much that your own matters get pushed back"], "work": "Work that asks you to support people and also make sound judgments. Counseling and support roles, HR, healthcare or education, team coordinator.", "key": "Being kind and giving your opinion can go together. Try saying it in this order: \"I understand how you feel. And here's what I think.\"", "both": "You have both the strength to reason step by step (T) and the strength to sense people's feelings (F). You can stay gently by someone's side, yet inside you're calmly asking, \"Is that really right?\""}, "FT": {"axis": "How you decide", "from": "Feeling", "to": "Thinking", "worry": ["You know the right answer, yet it takes you a long time to decide", "After giving your opinion, you keep wondering, \"Was I too harsh?\"", "Sometimes you lose track of what you really want to value"], "work": "Work where both logical thinking and understanding feelings come alive. Planning, marketing, editing, people-centered consulting.", "key": "Hesitating is a sign you hold both strengths. Just write down \"What does my heart say?\" and \"What does logic say?\" separately, and what you're torn about becomes clear.", "both": "You have both the strength to sense people's feelings (F) and the strength to reason step by step (T). You see what people with only one can't, but you also tend to get two answers inside: \"my heart says this, logic says that.\""}, "JP": {"axis": "How you act", "from": "Planning", "to": "Flexible", "worry": ["Even when you look fine, an undecided plan keeps nagging at you", "After putting things off, you blame yourself", "You're free to move as you like, yet somehow it wears you out"], "work": "Work where the big frame is set, but you can design how to get there. Project management, on-site coordination, event operations.", "key": "You don't have to decide everything. Just pick three \"things I'll do this week.\" Keep your flexibility, and simply having a view ahead will lighten you.", "both": "You have both the strength to plan ahead (J) and the strength to flex in the moment (P). You can adapt to the unexpected, yet somewhere inside you can't settle without a view of what's ahead."}, "PJ": {"axis": "How you act", "from": "Flexible", "to": "Planning", "worry": ["Things are going to plan, yet somehow it isn't fun", "Sudden changes irritate you, even when you understand why", "\"I have to do this properly\" has become your catchphrase"], "work": "Work with both moments to follow the plan and moments that need on-the-spot judgment. Sales, planning, front-line management, customer service.", "key": "Leave some time in your schedule with nothing planned, on purpose. Adding the joy of the moment to your planning makes it easier to keep going.", "both": "You have both the strength to flex in the moment (P) and the strength to plan ahead (J). You can organize things well, yet days packed with plans can start to feel suffocating."}, "AT": {"axis": "Mindset", "from": "Assertive", "to": "Cautious", "worry": ["You're doing well, yet you still feel \"it's not enough\"", "Worrying about what others think keeps you from bold steps", "You dwell on small mistakes longer than you need to"], "work": "Work that needs both caution and decisiveness. Quality or risk management, healthcare, right hand to a leader.", "key": "At the end of each day, write down three things you did today. Your care is a strength. Add a moment to remember the confidence you started with.", "both": "You have both the strength to trust yourself and move forward (A) and the strength to check carefully (T). You act with care, yet sometimes you don't show the confidence you were born with."}, "TA": {"axis": "Mindset", "from": "Cautious", "to": "Assertive", "worry": ["You look confident, so you can't share your worries with anyone", "After deciding, you go over it again and again on your own", "The more people rely on you, the harder it is to admit you're struggling"], "work": "Work with both a deciding role and a careful-checking role. Team leader, specialist, head of planning.", "key": "Tell just one person you trust, \"Honestly, I'm a little worried.\" Being careful isn't weakness. It's what makes your judgment solid.", "both": "You have both the strength to check carefully (T) and the strength to trust yourself and move forward (A). You can decide without hesitating, yet inside you're quietly asking, \"Is this really okay?\""}}, "same": {"both": "Your temperament and character are the same type. You've been able to live as the person you were born as, without forcing anything. What people see is what you are, so others find you easy to read and reassuring. A clear sense of self that doesn't waver is your strength.", "worry": ["Places where your way doesn't fit cause you strong stress", "The thinking of people unlike you can be hard to understand", "The cause of your worries is often your surroundings or relationships, not you"], "key": "When something doesn't fit, changing your place or your distance from people tends to work better than changing yourself.", "work": "If the way you work now feels right, that's your answer. When in doubt, trust your own sense."}, "letter": {"E": "Gets energy from being with people", "I": "Gets energy from time alone", "S": "Relies on facts and experience", "N": "Relies on hunches and possibilities", "T": "Decides by reasoning things through", "F": "Decides by what feels right for people", "J": "Moves ahead with a clear plan", "P": "Adapts flexibly to the situation", "AT_A": "Moves ahead trusting their own judgment", "AT_T": "Watches carefully and moves with caution"}};
var TD={"themes": {"比肩": {"who": "born", "title": "A day your true colors shine", "lines": ["Today your \"born {B}\" side is at its strongest. Go at your own pace instead of matching others.", "Today your \"I just feel it's this way\" beats other people's opinions.", "No need to put on an act today. People find the real you the easiest to talk to."], "tip": "If it's yours to decide, decide it yourself"}, "劫財": {"who": "born", "title": "A day your competitive side shows", "lines": ["You might feel like competing today. Use that drive to beat your own record, not someone else.", "If comparing yourself to someone stings, that's your born fighting spirit. It's not a bad thing.", "Today you may not want to give an inch. Hold firm only on what matters, and let the rest go with a smile."], "tip": "When you want to compare, compare with yesterday's you"}, "食神": {"who": "born", "title": "The more you enjoy, the luckier you get", "lines": ["Today it's okay to relax. Eat something delicious and your born self will perk up.", "Today, having fun works better than trying hard. Add one little treat to your plans.", "Today, just being there puts everyone at ease. Reach out to someone you get along with."], "tip": "Just for today, have the treat first"}, "傷官": {"who": "born", "title": "A day your senses are sharp", "lines": ["Your intuition is sharp today. But so are your words. Take a breath before you speak.", "Today you'll easily notice when something feels off. You're probably right. Just say it gently.", "Your sense of style shines today. In clothes or in writing, the care you put in will come through."], "tip": "Read it over once before you hit send"}, "偏財": {"who": "now", "title": "A day your circle grows", "lines": ["Today \"you now\" gets to shine. If someone invites you, just go with it.", "Detours pay off today. Try a different road or a different shop.", "Spending time with people is fun today. Send a quick note to someone you haven't talked to in a while."], "tip": "When invited, start by saying \"Sounds good\""}, "正財": {"who": "now", "title": "A day steady effort pays off", "lines": ["Today \"you now\" gets rewarded for being diligent. The plainer the task, the more it pays off later.", "A good day to get your money and time in order. Take a quick look at your receipts or schedule.", "Today people trust you for keeping your word. The smaller the promise, the more it matters."], "tip": "Take care of one small errand you've been putting off"}, "偏官": {"who": "now", "title": "A day you handle surprises well", "lines": ["Today might get hectic. But \"you now\" is at your best on days like this.", "A sudden request may come your way. You don't have to take it all on. Just the one that matters most.", "Your drive is up today. If you've been on the fence about something, take just one step forward."], "tip": "When in doubt, give it just 5 minutes"}, "正官": {"who": "now", "title": "A day your diligence gets noticed", "lines": ["Today, the skills \"you now\" worked hard for get the recognition they deserve.", "The more you follow the rules and the plan, the better today goes. Move 5 minutes earlier than usual.", "Someone will rely on you today. Once you've come through for them, give yourself some praise on the way home."], "tip": "Move 5 minutes earlier than usual"}, "偏印": {"who": "born", "title": "A day ideas come to you", "lines": ["Today your born flashes of inspiration are sharp. Jot down whatever comes to mind.", "Time alone recharges you most today. Don't pack your schedule too tight.", "Today you'll think differently from others. It's probably interesting, so share it with someone later."], "tip": "Save your ideas in your phone's notes"}, "印綬": {"who": "now", "title": "A day of learning and helping hands", "lines": ["Today people will help \"you now.\" Don't carry it all alone; it's okay to lean on others.", "New things sink in easily today. That book or video you've been curious about? Today's the day.", "Today there's a hint in what a mentor or family member says. Try asking them."], "tip": "Ask someone about one thing you don't understand"}}, "power": {"high": {"label": "Power: high", "stars": 3, "add": "Your energy is full. Do what you want to do today, today."}, "mid": {"label": "Power: medium", "stars": 2, "add": "Your energy is moderate. Your usual pace is just right today."}, "low": {"label": "Power: low", "stars": 1, "add": "Your energy is in power-saving mode. Going to bed early is today's best luck boost."}}};
